# Resources the backend does not serve at all answer "Unknown resource", and asking again every cycle spends the…
_HOPELESS_TTL_S = float(os.getenv("HUB_SNAPSHOT_HOPELESS_TTL_S", "1800"))
_hopeless: dict[str, float] = {}


def _mark_hopeless(name: str) -> None:
    _hopeless[name] = time.monotonic()


def _is_hopeless(name: str) -> bool:
    at = _hopeless.get(name)
    if at is None:
        return False
    if time.monotonic() - at < _HOPELESS_TTL_S:
        return True
    _hopeless.pop(name, None)   # the clock ran out: let one read ask again
    return False


# -------------------------------------------------------------------------- manifest…
_HELD_LIVE: dict[str, Any] = {"by_design": 0, "unrouted": [], "unmarked": 0}
_HELD_SAID = {"key": ""}


def _note_held_live(live: list[dict[str, Any]]) -> None:
    """Record why the live entries are held, and say it when it changes."""
    unrouted = sorted(str(e.get("resource") or "") for e in live if e.get("held") == "unrouted")
    by_design = sum(1 for e in live if e.get("held") == "by-design")
    # AN UNMARKED ENTRY IS COUNTED AS NEITHER.
    unmarked = len(live) - by_design - len(unrouted)
    _HELD_LIVE.update({"by_design": by_design, "unrouted": unrouted, "unmarked": unmarked})
    key = f"{by_design}|{unmarked}|{','.join(unrouted)}"
    if key == _HELD_SAID["key"]:
        return
    _HELD_SAID["key"] = key
    log.info("manifest: %d resource(s) held on the live path and never asked of the backend — "
             "%d by design, %d because nothing routes them yet (%s)%s",
             len(live), by_design, len(unrouted), ", ".join(unrouted) or "none",
             f", {unmarked} unmarked (this manifest predates the mark)" if unmarked else "")


def load_manifest() -> list[dict[str, Any]]:
    """The slice list, as derived from the registry."""
    try:
        entries = json.loads(MANIFEST_PATH.read_text())["resources"]
    except Exception as exc:  # noqa: BLE001 - reported, never fatal
        log.warning("snapshot manifest unreadable at %s: %s", MANIFEST_PATH, exc)
        return []
    # `live` is a deliberate refusal, not a gap: clinical records stay on the path where access is decided per app…
    live = [e for e in entries if e.get("mode") == "live"]
    _note_held_live(live)
    return [e for e in entries if e.get("mode") != "live"]


# -------------------------------------------------------------------------- building…
HUB_DB_TABS_REMAINING: frozenset[str] = frozenset()


def _mirror_may_answer(tab: str) -> bool:
    return tab in HUB_DB_TABS_REMAINING


def _rows_from_mirror(tab: str) -> tuple[list[dict], str | None]:
    """Rows for one tab, plus when that mirror was last filled."""
    if not _mirror_may_answer(tab):
        return [], None
    with psycopg2.connect(PG_DSN) as conn, conn.cursor(
        cursor_factory=psycopg2.extras.RealDictCursor
    ) as cur:
        cur.execute(
            """
            select data, ingested_at
              from asa_drive_sheets_rows
             where sheet_id = %s and tab_name = %s
             order by row_number
            """,
            (HUB_DB_SHEET_ID, tab),
        )
        got = cur.fetchall()
        # The second floor: a copy older than the newest fill of this workbook is a copy of a tab the backup no…
        cur.execute(
            "select max(ingested_at) from asa_drive_sheets_rows where sheet_id = %s",
            (HUB_DB_SHEET_ID,),
        )
        newest_fill = cur.fetchone()
    if not got:
        return [], None
    fill = (newest_fill or {}).get("max") if isinstance(newest_fill, dict) else None
    newest_row = max(r["ingested_at"] for r in got)
    if fill and newest_row < fill:
        return [], None
    newest = max(r["ingested_at"] for r in got)
    return [r["data"] for r in got], newest.isoformat()


def _mirror_session_verdict(token_hash: str) -> tuple[bool, str, str] | None:
    """Definitive session verdict from the PG mirror — no Apps Script spent."""
    from datetime import datetime, timezone
    try:
        with psycopg2.connect(PG_DSN) as conn, conn.cursor(
            cursor_factory=psycopg2.extras.RealDictCursor
        ) as cur:
            # STALENESS CEILING (review): a copy is only trusted while the sync that fills it is demonstrably alive…
            cur.execute(
                "select max(ingested_at) as newest from asa_drive_sheets_rows "
                "where sheet_id = %s and tab_name = 'hub_sessions'",
                (HUB_DB_SHEET_ID,),
            )
            newest = (cur.fetchone() or {}).get("newest")
            if newest is None:
                return _vouch_verdict(token_hash)
            if newest.tzinfo is None:
                newest = newest.replace(tzinfo=timezone.utc)
            age = (datetime.now(timezone.utc) - newest).total_seconds()
            if age > MIRROR_TRUST_MAX_S:
 # AND IT SAYS SO.
                global _mirror_stale_said, _mirror_blind
                _mirror_blind = True
                if time.time() - _mirror_stale_said > 3600:
                    _mirror_stale_said = time.time()
                    log.warning(
                        "session mirror cannot vouch: newest hub_sessions row for "
                        "%s is %.0fs old against a %.0fs ceiling — every token is "
                        "going to the backend instead",
                        HUB_DB_SHEET_ID[:12] + "…", age, MIRROR_TRUST_MAX_S)
                return _vouch_verdict(token_hash)
            cur.execute(
                "select data from asa_drive_sheets_rows "
                "where sheet_id = %s and tab_name = 'hub_sessions' "
                "  and data->>'token_hash' = %s",
                (HUB_DB_SHEET_ID, token_hash),
            )
            sessions = cur.fetchall()
            if not sessions:
                return _vouch_verdict(token_hash)
            now = datetime.now(timezone.utc)
            live_uid = None
            for s in sessions:
                # BE ANOTHER: an acting session is named by the backend alone, never by a copy that may still hold…
                if str(s["data"].get("acting_real_user_id") or "").strip():
                    return None
                exp = _iso(s["data"].get("expires_at"))
                if exp is not None and exp.tzinfo is None:
                    exp = exp.replace(tzinfo=timezone.utc)
                if exp and exp > now:
                    live_uid = str(s["data"].get("user_id") or "")
                    break
            if not live_uid:
                return _vouch_verdict(token_hash)
            cur.execute(
                "select data from asa_drive_sheets_rows "
                "where sheet_id = %s and tab_name = 'users' "
                "  and data->>'user_id' = %s",
                (HUB_DB_SHEET_ID, live_uid),
            )
            user = cur.fetchone()
        if not user:
            return _vouch_verdict(token_hash)
        if str(user["data"].get("active") or "").strip().lower() == "false":
            return (False, "", "")
 # THE USER ID TRAVELS OUT.
        return (True, str(user["data"].get("role") or ""), live_uid)
    except Exception as exc:  # noqa: BLE001 — mirror down: the GAS path decides
        log.warning("mirror session check unavailable: %s", exc)
        return None


# ── THE SESSIONS LIVE IN POSTGRES NOW — Python reads them straight from Postgres, and that is the whole solution.
VOUCH_TRUST_MAX_S = float(os.getenv("HUB_VOUCH_TRUST_MAX", "7200"))


def _vouch_table_ensure() -> None:
    try:
        with hub_db.connect(PG_DSN) as conn, conn.cursor() as cur:
            cur.execute(
                "create table if not exists hub_session_vouch ("
                " token_hash text primary key,"
                " role text not null default '',"
                " user_id text not null default '',"
                " seen_at timestamptz not null default now())")
    except Exception as exc:  # noqa: BLE001 — the fallback lane just stays cold
        log.warning("vouch table ensure failed: %s", exc)


def _vouch_put(token_hash: str, ok: bool, role: str, uid: str) -> None:
    """One verdict in — an upsert for a real session, a DELETE for a refusal."""
    try:
        with hub_db.connect(PG_DSN) as conn, conn.cursor() as cur:
            if ok:
                cur.execute(
                    "insert into hub_session_vouch (token_hash, role, user_id, seen_at)"
                    " values (%s, %s, %s, now())"
                    " on conflict (token_hash) do update set"
                    " role = excluded.role, user_id = excluded.user_id, seen_at = now()",
                    (token_hash, role, uid))
            else:
                cur.execute("delete from hub_session_vouch where token_hash = %s",
                            (token_hash,))
    except Exception as exc:  # noqa: BLE001 — a missed write costs one re-check
        log.warning("vouch write failed: %s", exc)


def _vouch_verdict(token_hash: str) -> tuple[bool, str, str] | None:
    """The relay's OWN Postgres session record — the photograph's understudy."""
    from datetime import datetime, timezone
    try:
        with hub_db.connect(PG_DSN) as conn, conn.cursor(
            cursor_factory=psycopg2.extras.RealDictCursor
        ) as cur:
            cur.execute(
                "select role, user_id, seen_at from hub_session_vouch"
                " where token_hash = %s", (token_hash,))
            row = cur.fetchone()
        if not row:
            return None
        seen = row["seen_at"]
        if seen.tzinfo is None:
            seen = seen.replace(tzinfo=timezone.utc)
        if (datetime.now(timezone.utc) - seen).total_seconds() > VOUCH_TRUST_MAX_S:
            return None
        return (True, str(row["role"] or ""), str(row["user_id"] or ""))
    except Exception:  # noqa: BLE001 — same PG as the mirror: nothing to add
        return None


# --------------------------------------------------------------------------- THE CONFIGURATION LANE `configLane`…
_CONFIG_LANE: dict[str, Any] = {"at": 0.0, "data": None}
_CONFIG_LANE_TTL_S = 180.0
# the lane read off asa-hub-db by Python (app/config_lane.py), never Apps Script
CONFIG_LANE_APP = "config-lane"
# a read that got nothing is asked again this soon, the last good lane standing meanwhile
_CONFIG_LANE_RETRY_S = 15.0


async def _config_lane_refresh(force: bool = False) -> None:
    """Ask Python for the platform-wide config, once, for everyone; the previous lane stands while it does not answer."""
    if not force and time.time() - float(_CONFIG_LANE["at"]) < _CONFIG_LANE_TTL_S:
        return
    try:
        got = await _backend_call(CONFIG_LANE_APP, "configLane", {}, {"is_service": True})
        env = got[2] if got is not None else {
            "status": 503, "message": f"Python did not answer ({_BACKEND_UNANSWERED.get()})"}
        if env.get("status") == 200 and isinstance(env.get("data"), dict):
            _CONFIG_LANE["data"] = env["data"]
            _CONFIG_LANE["at"] = time.time()
            # The digest worker is a process of its own and never sees this memory: the gates' part of the lane is…
            lane_gate.publish(env["data"])
        else:
            log.warning("config lane not read: %s", env.get("message") or env.get("status"))
            _CONFIG_LANE["at"] = time.time() - _CONFIG_LANE_TTL_S + _CONFIG_LANE_RETRY_S
    except Exception as exc:  # noqa: BLE001 — the previous answer stands
        log.warning("config lane refresh failed: %s", exc)
        _CONFIG_LANE["at"] = time.time() - _CONFIG_LANE_TTL_S + _CONFIG_LANE_RETRY_S


def _config_lane_for(place: str) -> dict[str, Any] | None:
    """The cached config, but ONLY for a reader standing where it was built."""
    data = _CONFIG_LANE.get("data")
    if not isinstance(data, dict):
        return None
    if str(data.get("place") or "") != str(place or ""):
        return None
    return data


async def _rows_from_python(resources: list[str]) -> dict[str, list[dict]]:
    """Shaped resources filled by their Python door for the relay's own identity (BACKEND_SLICE_DOORS); one Python
    does not answer is left out, and its slice keeps the last file it had."""
    out: dict[str, list[dict]] = {}
    for name in resources:
        app_id, door = BACKEND_SLICE_DOORS[name]
        got = await _backend_call(app_id, door, {}, {"is_service": True}, timeout=HUB_APP_PACK_TIMEOUT_S)
        env = got[2] if got is not None else None
        if env is None or env.get("status") != 200 or not isinstance(env.get("data"), list):
            log.warning("python slice %s not filled: %s", name,
                        _BACKEND_UNANSWERED.get() if env is None else f"{door} answered {env.get('status')}")
            continue
        out[name] = env["data"]
        if name == STAFF_ISSUES_RESOURCE:
            # the tracker's digest is the relay's (hr_digest: its roster, its model, its cache), laid as hr_slices does
            out[name] = await asyncio.to_thread(_staff_issues_digest, out[name])
    return out


def _staff_issues_digest(rows: list[dict]) -> list[dict]:
    """hr_slices._build's tail over Python's rows: the digest laid, its top-up started; a digest that could not run
    says so on every row, never a tracker without issues."""
    try:
        rows = hr_slices.hr_digest.attach(rows, PG_DSN)
        hr_slices.hr_digest.top_up(rows, PG_DSN)
    except Exception as exc:  # noqa: BLE001
        why = f"{type(exc).__name__}: {str(exc)[:160]}"
        for row in rows:
            row.setdefault("digest_state", "pending")
            row["digest_failed"] = why
    return rows



# ------------------------------------------------------------------ THE TURNOVER REACHES THE SCREEN — live, instead…
_event_subs: set[asyncio.Queue] = set()
_event_loop: asyncio.AbstractEventLoop | None = None
# Background tasks nobody awaits, held until they finish: the loop keeps only a weak reference to a task, so an…
_BG_TASKS: set[asyncio.Task] = set()


def _keep_task(coro: Any) -> asyncio.Task:
    task = asyncio.ensure_future(coro)
    _BG_TASKS.add(task)
    task.add_done_callback(_BG_TASKS.discard)
    return task


# THE LIVE PLANE IS asa-hub-app's (app/live_plane.py): the open streams, the slices and their index. A name this relay
# rings, a slice it marks dirty and a rebuild it asks for go there; while asa-hub-app's finish runs this relay's
# observers on its answer (front_door_finish.py), what they raise is caught here and handed back, never raised twice.
_LIVE_CAPTURE: "contextvars.ContextVar[dict[str, Any] | None]" = contextvars.ContextVar("live_capture", default=None)
_LIVE_OUT: list[tuple[str, dict[str, Any]]] = []
_LIVE_OUT_WAKE: list[Any] = []


def _live_post(path: str, body: dict[str, Any], timeout: float = 10.0) -> Any:
    """Blocking: one POST to asa-hub-app's live plane as this relay; its JSON."""
    with httpx.Client(timeout=timeout) as client:
        res = client.post(f"{HUB_APP_URL}{path}", json=body, headers={"X-Hub-Token": HUB_APP_TOKEN})
    res.raise_for_status()
    return res.json() if res.content else None


def _live_forward(path: str, body: dict[str, Any]) -> None:
    """Never raises, never waits: handed to asa-hub-app on the forwarder's own thread, the bus's names batched."""
    import threading  # noqa: PLC0415

    if not HUB_APP_TOKEN:
        return
    if not _LIVE_OUT_WAKE:
        wake = threading.Event()
        _LIVE_OUT_WAKE.append(wake)

        def drain() -> None:
            while True:
                wake.wait()
                wake.clear()
                jobs = []
                while _LIVE_OUT:
                    jobs.append(_LIVE_OUT.pop(0))
                names = [n for p, b in jobs if p == "/live/publish" for n in b["resources"]]
                rest = [(p, b) for p, b in jobs if p != "/live/publish"]
                for p, b in ([("/live/publish", {"resources": names})] if names else []) + rest:
                    try:
                        _live_post(p, b)
                    except Exception as exc:  # noqa: BLE001 - said; the next write or the rebuild clock says it again
                        log.warning("live plane: %s not told (%s)", p, type(exc).__name__)

        threading.Thread(target=drain, daemon=True, name="live-forward").start()
    _LIVE_OUT.append((path, body))
    _LIVE_OUT_WAKE[0].set()


def _publish_slice(resource: str, *, kept_copy: bool = False) -> None:
    """Tell every open stream that this resource just changed."""
    # a board's name makes every viewer's kept copy of it stale, unless a kept copy's own refresh rang (VIEWER CACHE)
    if not kept_copy:
        _viewer_cache_rang(resource)
    caught = _LIVE_CAPTURE.get()
    if caught is not None:
        caught["published"].append([resource, kept_copy])
        return
    _live_forward("/live/publish", {"resources": [{"name": resource, "kept_copy": kept_copy}]})
    loop, subs = _event_loop, list(_event_subs)
    if loop is None or not subs:
        return
    gated = resource.startswith("hotline:")

    def _fan() -> None:
        now = time.time()
        for q in subs:
            if gated and not _hotline_tag_live(q, now):
                continue
            try:
                q.put_nowait(resource)
            except asyncio.QueueFull:
                pass

    try:
        loop.call_soon_threadsafe(_fan)
    except RuntimeError:
        pass


# --------------------------------------------------------------------------- THE CHAT, WITHOUT A POLL — the chat…
_chat_subs: dict[str, set[asyncio.Queue]] = {}
_token_user: dict[str, tuple[float, str, str]] = {}
_TOKEN_USER_TTL = 12 * 3600.0

# --------------------------------------------------------------------------- THE BEAT STOPS SPENDING AN EXECUTION…

# user_id -> when this relay last let a real chatPing through for them.
_chat_beat_at: dict[str, float] = {}
# user_id -> when the browser last beat AT ALL, real execution or not.
_presence_seen: dict[str, float] = {}
# action name -> how many times a BROWSER spent an execution on it, since this process started.
_by_action: dict[str, int] = {}
# user_id -> the `at` of the newest chat event observed for them since they last told us they had read it.
_chat_dirty: dict[str, str] = {}
# How long a person may go without the sheet learning they are here.
_CHAT_BEAT_DUE_S = 4 * 60.0


def _token_user_put(token: str, user_id: str, name: str = "") -> None:
    if token and user_id:
        # The name is carried so the session-swap curtain can be drawn without an execution — it is the one thing…
        if not name:
            name = (_token_user.get(token) or (0.0, "", ""))[2]
        _token_user[token] = (time.time(), user_id, name)
        if len(_token_user) > 4000:            # a long-lived process, not a leak
            cutoff = time.time() - _TOKEN_USER_TTL
            for t, (at, _u, _n) in list(_token_user.items()):
                if at < cutoff:
                    _token_user.pop(t, None)


def _token_user_get(token: str) -> str:
    hit = _token_user.get(token)
    if not hit or time.time() - hit[0] > _TOKEN_USER_TTL:
        return ""
    return hit[1]


def _token_name_get(token: str) -> str:
    hit = _token_user.get(token)
    if not hit or time.time() - hit[0] > _TOKEN_USER_TTL:
        return ""
    return hit[2]


def _publish_chat(user_id: str, payload: str) -> None:
    """Wake this person's open tabs. Never blocks, never raises."""
    subs = list(_chat_subs.get(user_id) or ())
    for q in subs:
        try:
            q.put_nowait(payload)
        except asyncio.QueueFull:
            # A tab that cannot keep up misses THIS line and reconciles on its next read — the alternative is…
            pass


# --------------------------------------------------------------------------- THE STRIP AT THE TOP OF EVERY TAB…
_HUB_PHASE: dict[str, Any] = {"phase": "warming", "since": time.time()}
HUB_WEB_INDEX = Path(os.getenv("HUB_WEB_INDEX", "/srv/web/index.html"))
HUB_WEB_EVERY_S = 1.0
_HUB_WEB: dict[str, Any] = {"mtime": 0.0, "bundle": ""}
_HUB_BUNDLE_RE = re.compile(r"index-[A-Za-z0-9_-]+\.js")


def _hub_frame() -> str:
    frame: dict[str, Any] = {"kind": "hub", "phase": _HUB_PHASE["phase"]}
    if _HUB_WEB["bundle"]:
        frame["web"] = _HUB_WEB["bundle"]
    return json.dumps(frame)


def _hub_fan(payload: str) -> None:
    """Hand a hub frame to every open stream that draws the strip. Any thread."""
    loop = _event_loop
    if loop is None:
        return

    def _fan() -> None:
        for subs in list(_chat_subs.values()):
            for q in list(subs):
                if not getattr(q, "strip", False):
                    continue
                try:
                    q.put_nowait(payload)
                except asyncio.QueueFull:
                    pass

    try:
        loop.call_soon_threadsafe(_fan)
    except RuntimeError:
        pass


def _hub_phase(phase: str) -> None:
    """Set the phase; a change is told to every tab."""
    if _HUB_PHASE["phase"] == phase:
        if phase == "engine":
            _HUB_PHASE["since"] = time.time()
        return
    _HUB_PHASE.update(phase=phase, since=time.time())
    log.info("hub phase: %s", phase)
    _hub_fan(_hub_frame())


def _hub_full_pass_done(decided: float) -> None:
    """A full build pass ended (finished, failed or abandoned): only one that decided what to re-ask after the…"""
    if _HUB_PHASE["phase"] != "ready" and decided >= _HUB_PHASE["since"]:
        _hub_phase("ready")


def _hub_web_tick() -> None:
    """The served index.html named a different bundle: tell every tab once."""
    try:
        mtime = HUB_WEB_INDEX.stat().st_mtime
        if mtime == _HUB_WEB["mtime"]:
            return
        _HUB_WEB["mtime"] = mtime
        found = _HUB_BUNDLE_RE.search(HUB_WEB_INDEX.read_text(encoding="utf-8", errors="replace"))
    except OSError:
        return
    bundle = found.group(0) if found else ""
    before, _HUB_WEB["bundle"] = _HUB_WEB["bundle"], bundle or _HUB_WEB["bundle"]
    if bundle and before and bundle != before:
        log.info("web build changed (%s → %s)", before, bundle)
        _hub_fan(_hub_frame())


async def _hub_web_loop() -> None:
    """The web look on its own clock: one stat of our own disk a second, no network, and never held behind a…"""
    while True:
        await asyncio.sleep(HUB_WEB_EVERY_S)
        try:
            _hub_web_tick()
        except Exception as exc:  # noqa: BLE001 — the look must not die
            log.warning("web look: %s", exc)


def _relay_observe_chat(raw: bytes, content: bytes) -> None:
    """A message just landed: tell the recipient, and this sender's other tabs."""
    try:
        # THE STATED EXCEPTION, NOT AN OMISSION.
        if lane_gate.holds(lane_gate.CHAT_FRAME)["held"]:
            return
        if b"chatSend" not in raw[:4096] and b"chatReact" not in raw[:4096]:
            return
        body = urllib.parse.parse_qs(raw.decode("utf-8", "ignore")).get("body", [""])[0]
        if not body:
            return
        req = json.loads(body)
        action = str(req.get("action") or "")
        if action not in ("chatSend", "chatReact"):
            return
        env = json.loads(content)
        if env.get("status") != 200:
            return
        data = env.get("data") or {}
        # A send says whom it is FOR; a reaction is on a message whose other end only the server knows, so chatReact…
        to_user = str((req.get("payload") or {}).get("to_user") or data.get("to_user") or "")
        me = _token_user_get(str(req.get("token") or ""))
        line = json.dumps({
            "kind": action,
            "thread_key": str(data.get("thread_key") or ""),
            "from_user": me,
            "at": str(data.get("created_at") or ""),
        }, separators=(",", ":"))
        at = str(data.get("created_at") or "")
        if to_user:
            _publish_chat(to_user, line)
            # AND REMEMBER IT, for the tab that is not streaming.
            if action == "chatSend":
                _chat_dirty[to_user] = at or _iso_now()
        # The sender's OTHER tabs, so a message typed on the laptop appears on the phone.
        if me:
            _publish_chat(me, line)
    except Exception:  # noqa: BLE001 — a bonus, never a failure mode
        pass


# The four actions that call chatTouchPresence_ (Chat.gs:177, 541, 579, 603).
_CHAT_STAMPS_PRESENCE = ("chatPing", "chatOverview", "chatReact", "chatMarkRead")
# The two that establish what the SHELL's badge shows.
_CHAT_SETTLES_UNREAD = ("chatPing", "chatMarkRead")


def _relay_observe_chat_read(raw: bytes, content: bytes) -> None:
    """A real execution just answered — the relay may stop asking for one."""
    try:
        if not any(a.encode() in raw[:4096] for a in _CHAT_STAMPS_PRESENCE):
            return
        body = urllib.parse.parse_qs(raw.decode("utf-8", "ignore")).get("body", [""])[0]
        if not body:
            return
        action = str(json.loads(body).get("action") or "")
        if action not in _CHAT_STAMPS_PRESENCE:
            return
        if json.loads(content).get("status") != 200:
            return
        token = str(json.loads(body).get("token") or "")
        # an acting session stamps no presence (Chat.gs) and reads nothing for the target: their flags stay.
        if token in _acting:
            _acting_beat_at[token] = time.time()
            return
        me = _token_user_get(token)
        if not me:
            return
        _chat_beat_at[me] = time.time()
        if action in _CHAT_SETTLES_UNREAD:
            _chat_dirty.pop(me, None)
    except Exception:  # noqa: BLE001 — observation is a bonus, never a failure mode
        pass


def _iso_now() -> str:
    # `datetime` is imported per-function throughout this file, not at module level — following the local style…
    from datetime import datetime, timezone
    return datetime.now(timezone.utc).isoformat()


# Notices to people online (server/web_notices.py): judged per reader, one frame each, only to streams opened with…
_notice_who: dict[str, tuple[float, str, bool | None]] = {}
# uid -> (at, shift_requests.viewer answer), held briefly for bursts
_notice_viewers: dict[str, tuple[float, dict[str, Any]]] = {}
NOTICE_VIEWER_TTL_S = float(os.getenv("HUB_NOTICE_VIEWER_TTL_S", "120"))
NOTICES_EVERY_S = float(os.getenv("HUB_NOTICES_EVERY_S", "60"))
NOTICES_FIRST_S = float(os.getenv("HUB_NOTICES_FIRST_S", "45"))
_notices_evt: asyncio.Event | None = None


def _notice_who_put(uid: str, role: str, is_master: bool | None) -> None:
    if uid:
        _notice_who[uid] = (time.time(), str(role or ""), is_master)
        if len(_notice_who) > 4000:          # a long-lived process, not a leak
            cutoff = time.time() - _TOKEN_USER_TTL
            for u, (at, _r, _m) in list(_notice_who.items()):
                if at < cutoff:
                    _notice_who.pop(u, None)


def _notice_viewer(uid: str) -> dict[str, Any] | None:
    """The reader behind a stream, or None when no session was seen for them."""
    held = _notice_viewers.get(uid)
    if held and time.time() - held[0] < NOTICE_VIEWER_TTL_S:
        return held[1]
    seen = _notice_who.get(uid)
    if not seen:
        return None
    who = shift_requests.viewer(PG_DSN, name=_roster_name_of(uid, strict=True), role=seen[1],
                                types=_user_badges(uid), is_master=seen[2])
    who["alerts_off"] = _lane_alerts_off(uid)
    _notice_viewers[uid] = (time.time(), who)
    return who


def _publish_notice_frame(user_id: str, payload: str) -> int:
    """Hand a notice to this person's notice-reading tabs; returns how many took it."""
    took = 0
    for q in list(_chat_subs.get(user_id) or ()):
        if not getattr(q, "notices", False):
            continue
        try:
            q.put_nowait(payload)
            took += 1
        except asyncio.QueueFull:
            pass
    return took


def _notice_frames(notice: dict[str, Any], uids: list[str]) -> list[tuple[str, str]]:
    """(uid, frame) for every online reader this notice is for. Worker thread."""
    readers: list[tuple[str, dict[str, Any]]] = []
    for uid in uids:
        try:
            who = _notice_viewer(uid)
        except Exception as exc:  # noqa: BLE001 — one account's lookup never silences the rest
            log.warning("notices: the reader %s could not be resolved (%s)", uid, type(exc).__name__)
            continue
        if who is not None:
            readers.append((uid, who))
    if not readers:
        return []
    shaped = web_notices.for_viewers(PG_DSN, notice, [w for _, w in readers])
    return [(uid, json.dumps({"kind": "notice", "notice": s}, separators=(",", ":"), default=str))
            for (uid, _), s in zip(readers, shaped) if s]


# The switch (server/web_gate.py): while test mode is on (or unreadable) no frame, bell or push leaves; each notice…
_NOTICE_ACCOUNTS: dict[str, Any] = {"at": 0.0, "rows": None}
# the roles a shift notice can be for
NOTICE_ACCOUNT_ROLES = ("staff", "manager", "admin", "director")
# A copy of HUB_MASTER_ACCOUNT in apps-script/Auth.gs (the relay reads rows, it cannot ask)…
HUB_MASTER_ACCOUNT = "asatech@asalifecare.com"


def _is_master_row(row: dict[str, Any]) -> bool:
    """The one filter every account list the relay answers applies: the master account is never a row in one."""
    return str((row or {}).get("email") or "").strip().lower() == HUB_MASTER_ACCOUNT
WEB_MOCK_EVERY_S = float(os.getenv("HUB_WEB_MOCK_EVERY_S", "120"))
# How long a door that refused the last batch is left alone before it is asked again.
WEB_MOCK_BACKOFF_S = float(os.getenv("HUB_WEB_MOCK_BACKOFF_S", "1800"))
_WEB_SAID: dict[str, Any] = {"switch": None, "no_key": 0.0, "mock_last": 0.0, "mock_said": 0.0,
                             "rotated": 0.0, "released": 0.0}


def _web_switch() -> dict[str, Any]:
    """The resolved test mode from the config lane; anything missing or old reads as ON."""
    if web_gate is None:
        return {"on": True, "readable": False, "word": "unreadable",
                "why": "the web gate is not on this relay"}
    return web_gate.switch_from(_config_lane_for(""))


# the same switch holds roster writes; handed in at import, before any door runs
effective_roster.use_switch(_web_switch)
# and the same lane carries the gates the relay's own doors ask (server/lane_gate.py)
lane_gate.use_lane(lambda: _config_lane_for(""))


def _lane_app_cut() -> frozenset[str]:
    """FAIL-OPEN: the app ids Settings > My Work keeps to the master's own session (configLane `my_work_apps`)."""
    lane = _config_lane_for("")
    raw = (lane or {}).get("my_work_apps")
    if not isinstance(raw, list):
        return frozenset()
    return frozenset(str(x).strip() for x in raw if str(x or "").strip())


def _lane_app_seen() -> frozenset[str]:
    """The account ids that see the listed apps too (configLane `my_work_apps_seen`); a lane that is missing or…"""
    lane = _config_lane_for("")
    raw = (lane or {}).get("my_work_apps_seen")
    if not isinstance(raw, list):
        return frozenset()
    return frozenset(str(x).strip() for x in raw if str(x or "").strip())


def _lane_ac_writers() -> frozenset[str]:
    """The account ids App Control is shared with and May change (configLane `app_control_writers`, built by…"""
    lane = _config_lane_for("")
    raw = (lane or {}).get("app_control_writers")
    if not isinstance(raw, list):
        return frozenset()
    return frozenset(str(x).strip() for x in raw if str(x or "").strip())


def _relay_ac_writer(token: str) -> bool:
    """Is this session an account App Control is shared with and may change?"""
    hit = _auth_cache.get(str(token or "")) if token else None
    uid = str(hit[3] or "").strip() if hit and hit[1] and len(hit) > 3 else ""
    return bool(uid) and uid in _lane_ac_writers()


def _lane_world_hide() -> bool:
    """FAIL-OPEN: Settings > My Work's world switch (configLane `my_world_hide`); anything but a plain True is off."""
    lane = _config_lane_for("")
    return (lane or {}).get("my_world_hide") is True


def _lane_world_seen() -> frozenset[str]:
    """The account ids that keep their world while the switch is on (configLane `my_world_seen`); a lane that is…"""
    lane = _config_lane_for("")
    raw = (lane or {}).get("my_world_seen")
    if not isinstance(raw, list):
        return frozenset()
    return frozenset(str(x).strip() for x in raw if str(x or "").strip())


def _lane_alerts_off(uid: str) -> list[str]:
    """FAIL-OPEN: the alerts this account turned off for itself in Settings > Alerts I receive (configLane…"""
    lane = _config_lane_for("")
    raw = (lane or {}).get("alert_receive_off")
    got = raw.get(str(uid or "").strip()) if isinstance(raw, dict) and str(uid or "").strip() else None
    if not isinstance(got, list):
        return []
    return sorted({str(x).strip() for x in got if str(x or "").strip()})


def _world_withheld(uid: str, master_flag: Any) -> bool:
    """Is a world kept from this session? Never from the master's own; never from an account on the seen list."""
    if master_flag is True or not _lane_world_hide():
        return False
    return not (uid and uid in _lane_world_seen())


def _app_cut_map(block: dict[str, Any], cut: frozenset[str]) -> dict[str, Any]:
    """A copy of an app-keyed map without the cut ids; the held map is never touched."""
    return {k: v for k, v in block.items() if k not in cut} if cut else block


def _app_cut_shelf(shelf: dict[str, Any], cut: frozenset[str]) -> dict[str, Any]:
    """The shelf without the cut ids' placement and order."""
    if not cut or not isinstance(shelf, dict):
        return shelf
    out = dict(shelf)
    if isinstance(shelf.get("placement"), dict):
        out["placement"] = _app_cut_map(shelf["placement"], cut)
    if isinstance(shelf.get("order"), dict):
        out["order"] = {k: [a for a in (v or []) if a not in cut] if isinstance(v, list) else v
                        for k, v in shelf["order"].items()}
    return out


if hotline_desk is not None:
    hotline_desk.use_app_cut(_lane_app_cut)
    hotline_desk.use_app_seen(_lane_app_seen)


def _notice_accounts() -> list[dict[str, str]]:
    """Every active account a notice could be for; raises when the mirror cannot be read or is empty."""
    held = _NOTICE_ACCOUNTS.get("rows")
    if held is not None and time.time() - float(_NOTICE_ACCOUNTS["at"]) < NOTICE_VIEWER_TTL_S:
        return held
    with psycopg2.connect(PG_DSN) as conn, conn.cursor() as cur:
        cur.execute("select data from asa_drive_sheets_rows where sheet_id = %s and tab_name = 'users'",
                    (HUB_DB_SHEET_ID,))
        rows = [r[0] for r in cur.fetchall() if isinstance(r[0], dict)]
    if not rows:
        raise RuntimeError("the users copy holds no rows")
    out = []
    for r in rows:
        uid = str(r.get("user_id") or "").strip()
        role = str(r.get("role") or "").strip().lower()
        if not uid or role not in NOTICE_ACCOUNT_ROLES:
            continue
        if str(r.get("active") or "").strip().upper() in ("FALSE", "0", "NO"):
            continue
        out.append({"uid": uid, "role": role, "types": str(r.get("types") or ""),
                    "label": str(r.get("display_name") or "").strip() or uid,
                    "unlisted": "1" if _is_master_row(r) else ""})
    _NOTICE_ACCOUNTS.update({"at": time.time(), "rows": out})
    return out


def _account_viewer(acc: dict[str, str]) -> dict[str, Any]:
    """The reader behind an account, built as `_requests_viewer` builds one for a session."""
    uid = acc["uid"]
    held = _notice_viewers.get(uid)
    if held and time.time() - held[0] < NOTICE_VIEWER_TTL_S:
        return held[1]
    seen = _notice_who.get(uid)
    # an unreadable name raises rather than reading as on no roster
    who = shift_requests.viewer(PG_DSN, name=_roster_name_of(uid, strict=True),
                                role=(seen[1] if seen and seen[1] else acc["role"]),
                                types=acc["types"], is_master=seen[2] if seen else None)
    who["alerts_off"] = _lane_alerts_off(uid)
    _notice_viewers[uid] = (time.time(), who)
    return who


def _judged(notice: dict[str, Any], accounts: list[dict[str, str]]) -> list[tuple[dict[str, str], Any]]:
    """(account, copy | Unjudged | None) per account; an unbuildable reader is Unjudged, never "not theirs"."""
    readers: list[tuple[dict[str, str], dict[str, Any]]] = []
    unjudged: list[tuple[dict[str, str], Any]] = []
    for acc in accounts:
        try:
            readers.append((acc, _account_viewer(acc)))
        except Exception as exc:  # noqa: BLE001 — named below, not dropped
            unjudged.append((acc, web_notices.Unjudged(f"the reader could not be read ({type(exc).__name__})")))
    shaped = web_notices.for_viewers(PG_DSN, notice, [w for _, w in readers]) if readers else []
    return [(acc, s) for (acc, _), s in zip(readers, shaped)] + unjudged


def _unjudged_rows(channel: str, notice: dict[str, Any], unjudged: list[tuple[dict[str, str], Any]],
                   switch: dict[str, Any], held_by: str, reason: str) -> list[dict[str, Any]]:
    """The mock row naming the unjudged accounts."""
    if not unjudged:
        return []
    why = "; ".join(sorted({str(getattr(s, "why", "") or "a read failed") for _, s in unjudged}))
    stand_in = {"role": "unjudged", "title": f"{notice.get('kind')} — whether these accounts hear it "
                                              "could not be answered", "body": why}
    return web_gate.mock_rows(channel, notice, [(acc["label"], stand_in) for acc, _ in unjudged],
                              result="unjudged", held_by=held_by, reason=reason, switch=switch)


def _notice_hold(notice: dict[str, Any], switch: dict[str, Any], live: set[str]) -> dict[str, Any]:
    """Test mode on (worker thread): mock rows per wording for the bell and the pushes; the row is the delivery."""
    judged = _judged(notice, _notice_accounts())
    heard = [(acc, s) for acc, s in judged if s]
    unjudged = [(acc, s) for acc, s in judged if isinstance(s, web_notices.Unjudged)]
    held_by = web_gate.held_by_test(switch)
    rows = web_gate.mock_rows(
        web_gate.CH_NOTICE, notice, [(acc["label"], s) for acc, s in heard],
        result="held", held_by=held_by, switch=switch,
        reason=("test mode is on — nobody was shown this notice: no stream frame, no bell row, "
                "no operating-system notification, and not afterwards either"
                + (f" ({switch['why']})" if switch.get("why") else "")))
    rows += _unjudged_rows(web_gate.CH_NOTICE, notice, unjudged, switch, held_by,
                           "test mode is on, and whether these accounts would have heard it could not "
                           "be answered — a read under the question failed")
    pushed: list[tuple[str, dict[str, Any]]] = []
    if web_push is not None:
        devs = web_push.devices(PG_DSN)
        label = {acc["uid"]: acc["label"] for acc, _ in heard}
        wanted = [(acc["uid"], s) for acc, s in heard
                  if acc["uid"] in devs and web_push.wants_push({**s, "held": False},
                                                                 live=acc["uid"] in live)]
        got = web_push.deliver(PG_DSN, notice, wanted, switch=switch, devs=devs)
        pushed = got["by_state"].get(web_push.S_HELD_TEST) or []
        rows += web_gate.mock_rows(
            web_gate.CH_PUSH, notice, [(label.get(uid, uid), s) for uid, s in pushed],
            result="held", held_by=held_by, switch=switch,
            reason="test mode is on — no push left the platform, and none will: this row is its "
                   "only delivery")
    kept = web_gate.record(rows)
    return {"readers": len(heard), "devices": len(pushed), "rows": kept["added"],
            "unjudged": len(unjudged)}


def _push_mock(notice: dict[str, Any], by_state: dict[str, list], switch: dict[str, Any],
               label: dict[str, str], *, released: bool = False) -> list[dict[str, Any]]:
    """Mock rows for decided pushes: sent, held for the night, or refused."""
    rows: list[dict[str, Any]] = []
    how = {
        web_push.S_SENT: ("sent", "", "pushed to the person's device(s)"
                          + (" once the hold ended, still true" if released else "")),
        web_push.S_HELD_QUIET: ("held_quiet", f"held: the quiet window ({web_gate.quiet_words()})",
                                "looked at again from 08:00, and pushed only if still true"),
        web_push.S_FAILED: ("failed", "the push service", "no device took it; tried again while still true"),
    }
    for state, (result, held_by, reason) in how.items():
        got = by_state.get(state) or []
        if got:
            rows += web_gate.mock_rows(web_gate.CH_PUSH, notice,
                                       [(label.get(item[0], item[0]), item[1]) for item in got],
                                       result=result, held_by=held_by, reason=reason, switch=switch)
    return rows


def _notice_push(notice: dict[str, Any], live: set[str], switch: dict[str, Any]) -> dict[str, Any]:
    """Test mode off (worker thread): push to the people it must interrupt; outcome by state, or `why`."""
    vapid = web_push.keys()
    if not vapid.get("ok"):
        return {"why": vapid.get("why") or "no VAPID keys"}
    devs = web_push.devices(PG_DSN)
    if not devs:
        return {}
    accounts = [acc for acc in _notice_accounts() if acc["uid"] in devs]
    if not accounts:
        return {}
    judged = _judged(notice, accounts)
    wanted = [(acc["uid"], s) for acc, s in judged if web_push.wants_push(s, live=acc["uid"] in live)]
    # an unjudged push is a `failed` row the release beat asks about again
    unjudged = [(acc, s) for acc, s in judged if isinstance(s, web_notices.Unjudged)]
    label = {acc["uid"]: acc["label"] for acc in accounts}
    out: dict[str, Any] = {}
    if unjudged:
        deferred = web_push.defer(PG_DSN, notice, [(acc["uid"], s.why) for acc, s in unjudged])
        web_gate.record(_unjudged_rows(
            web_gate.CH_PUSH, notice, [(acc, s) for acc, s in unjudged if acc["uid"] in deferred],
            switch, "", "whether this push is owed could not be answered — asked again on the next beat"))
        out["unjudged"] = len(deferred)
    if not wanted:
        return out
    got = web_push.deliver(PG_DSN, notice, wanted, switch=switch, vapid=vapid, devs=devs,
                           switch_fn=_web_switch)
    web_gate.record(_push_mock(notice, got["by_state"], switch, label))
    out.update({k: len(v) for k, v in got["by_state"].items()})
    return out


def _push_release(switch: dict[str, Any]) -> dict[str, Any]:
    """The held and the failed pushes, judged again now. Worker thread."""
    by_uid = {acc["uid"]: acc for acc in _notice_accounts()}

    def judge(notice: dict[str, Any], uid: str) -> dict[str, Any] | None:
        acc = by_uid.get(uid)
        if acc is None:
            return None  # the account is gone or no longer active
        copy = web_notices.for_viewers(PG_DSN, notice, [_account_viewer(acc)])[0]
        if isinstance(copy, web_notices.Unjudged):
            # raised: waiting, asked again next beat
            raise RuntimeError(copy.why)
        return copy

    got = web_push.release(PG_DSN, switch=switch, judge=judge, switch_fn=_web_switch)
    label = {uid: acc["label"] for uid, acc in by_uid.items()}
    per_notice: dict[int, tuple[dict[str, Any], dict[str, list]]] = {}
    for state, items in got["by_state"].items():
        for uid, copy, notice in items:
            per_notice.setdefault(int(notice["id"]), (notice, {}))[1].setdefault(state, []).append((uid, copy))
    rows: list[dict[str, Any]] = []
    for notice, by_state in per_notice.values():
        rows += _push_mock(notice, by_state, switch, label, released=True)
    if rows:
        web_gate.record(rows)
    return {"sent": len(got["by_state"].get(web_push.S_SENT) or []),
            "failed": len(got["by_state"].get(web_push.S_FAILED) or []),
            "expired": len(got["expired"]), "waiting": got["waiting"], "why": got["why"]}


async def _notice_fan(notice: dict[str, Any]) -> None:
    if web_notices is None:
        return
    # an acting tab (Be Another) is the master, not its target, on screen: it never suppresses their push
    online = [uid for uid, subs in list(_chat_subs.items())
              if any(getattr(q, "notices", False) and not getattr(q, "acting", False) for q in subs)]
    switch = _web_switch()
    if not switch["on"] and notice.get("held"):
        # stored under test mode: held regardless of the switch now
        switch = {**switch, "on": True, "why": "it was stored while test mode was on"}
    if switch["on"]:
        # NOTHING REACHES A PERSON: no frame, and the pushes are held.
        try:
            said = await asyncio.to_thread(_notice_hold, notice, switch, set(online))
        except Exception as exc:  # noqa: BLE001 — still nobody is told; the log says the mockup missed it
            log.warning("notices: %s was held (test mode) but its mockup rows could not be written (%s)",
                        notice.get("key"), type(exc).__name__)
            return
        log.info("notices: %s held — test mode; %s reader(s) and %s device(s) written for the mockup "
                 "(%s row(s))%s", notice.get("key"), said["readers"], said["devices"], said["rows"],
                 f"; {said['unjudged']} account(s) could not be judged" if said.get("unjudged") else "")
        return
    if online:
        try:
            frames = await asyncio.to_thread(_notice_frames, notice, online)
        except Exception as exc:  # noqa: BLE001 — the bell still holds it
            log.warning("notices: %s could not be shaped for the people online (%s)",
                        notice.get("key"), type(exc).__name__)
            frames = []
        reached = sum(1 for uid, frame in frames if _publish_notice_frame(uid, frame))
        if frames:
            log.info("notices: %s reached %s of %s people online (%s it was for)",
                     notice.get("key"), reached, len(online), len(frames))
    if web_push is None:
        return
    try:
        pushed = await asyncio.to_thread(_notice_push, notice, set(online), switch)
    except Exception as exc:  # noqa: BLE001 — the bell holds it; the push outbox never claimed it
        log.warning("web push: %s could not be pushed (%s)", notice.get("key"), type(exc).__name__)
        return
    if pushed.get("why"):
        if time.time() - float(_WEB_SAID["no_key"]) > 3600:
            _WEB_SAID["no_key"] = time.time()
            log.warning("web push: nothing is pushed — %s", pushed["why"])
    elif pushed:
        log.info("web push: %s — %s", notice.get("key"),
                 ", ".join(f"{n} {state}" for state, n in sorted(pushed.items())))


async def _web_mock_handoff() -> None:
    """Hand waiting mock rows to commMockWebIngest; a row is handed only when the door names it written."""
    if web_gate is None:
        return
    now = time.time()
    if now - float(_WEB_SAID["rotated"]) > 3600:
        _WEB_SAID["rotated"] = now
        try:
            await asyncio.to_thread(web_gate.rotate)
        except Exception as exc:  # noqa: BLE001 — the files stay as they are
            log.warning("web mock: the finished days could not be zipped (%s)", type(exc).__name__)
    # back off after a refused batch
    wait = WEB_MOCK_EVERY_S if not _WEB_SAID.get("mock_refused") else WEB_MOCK_BACKOFF_S
    if now - float(_WEB_SAID["mock_last"]) < wait:
        return
    try:
        rows = await asyncio.to_thread(web_gate.pending)
    except Exception as exc:  # noqa: BLE001
        log.warning("web mock: the kept rows could not be read (%s)", type(exc).__name__)
        return
    if not rows:
        return
    _WEB_SAID["mock_last"] = now
    try:
        env = await _backend_pass(COMM_MOCK_APP, "commMockWebIngest", {"rows": rows})
    except Exception as exc:  # noqa: BLE001 — the rows stay on the disk
        env = {"status": 0, "message": f"the door could not be reached ({type(exc).__name__})"}
    try:
        said = await asyncio.to_thread(web_gate.after_handoff, env, [str(r["id"]) for r in rows])
    except Exception as exc:  # noqa: BLE001
        log.warning("web mock: the answer could not be written down (%s)", type(exc).__name__)
        return
    if said["handed"]:
        log.info("web mock: %s row(s) taken by the sheet, %s not taken", said["handed"], said["refused"])
    _WEB_SAID["mock_refused"] = not said["ok"]
    if not said["ok"] and now - float(_WEB_SAID["mock_said"]) > 1800:
        _WEB_SAID["mock_said"] = now
        waiting = await asyncio.to_thread(web_gate.waiting_count)
        log.warning("web mock: %s row(s) wait on the relay's disk — the sheet did not take them (%s)",
                    waiting, said["why"])


async def _web_beat() -> None:
    """Once a minute: log switch moves, release held pushes, hand on the mock rows."""
    switch = _web_switch()
    # a switch move re-reads every shift reader now (held cells are laid only while it holds)
    was_on = _WEB_SAID.get("roster_on")
    _WEB_SAID["roster_on"] = bool(switch["on"])
    if was_on is not None and was_on != bool(switch["on"]):
        _roster_published({"location": "every house", "cells": [], "actor": "the switch",
                           "via": "test mode " + ("on — held cells laid" if switch["on"]
                                                  else "off — held cells no longer laid")})
        _housecal_rang()
    # logged on change, digits folded so an ageing lane does not log every minute
    word = (switch["on"], switch.get("readable"), re.sub(r"\d+", "N", str(switch.get("why") or "")))
    if word != _WEB_SAID["switch"]:
        _WEB_SAID["switch"] = word
        if switch["on"]:
            log.warning("notices: test mode is ON%s — nothing reaches a person: no notice frame, "
                        "every bell answers held, no push; each notice is written for the mockup",
                        f" ({switch['why']})" if switch.get("why") else "")
        else:
            log.info("notices: test mode is off — notices and pushes deliver")
    if web_push is not None and PG_DSN and time.time() - float(_WEB_SAID.get("released") or 0) >= 30:
        _WEB_SAID["released"] = time.time()
        try:
            said = await asyncio.to_thread(_push_release, switch)
            if said["sent"] or said["failed"] or said["expired"]:
                log.info("web push: released — %s sent, %s failed, %s no longer true",
                         said["sent"], said["failed"], said["expired"])
        except Exception as exc:  # noqa: BLE001 — the held rows wait for the next beat
            log.warning("web push: the held pushes could not be looked at (%s)", type(exc).__name__)
    await _web_mock_handoff()


def _notice_fanout(notice: dict[str, Any]) -> None:
    """web_notices' listener, for a notice this relay's own clocks stored: carried to whoever is online by
    asa-hub-app's notices clock (app/notice_clock.py), which holds the streams and decides the pushes; My Inbox's kept
    copies are read again."""
    _live_forward("/live/wake", {"notice_ids": [int(notice["id"])]})
    loop = _event_loop
    if loop is None:
        return
    try:
        loop.call_soon_threadsafe(_publish_slice, MY_INBOX_EVENT)
    except RuntimeError:
        pass


def _notices_wake() -> None:
    """Run the notices' catch-up now: asa-hub-app's clock (app/notice_clock.py); thread-safe, a burst is one run."""
    loop, evt = _event_loop, _notices_evt
    if loop is None or evt is None:
        _live_forward("/live/wake", {"wake": ["notices"]})
        return
    try:
        loop.call_soon_threadsafe(evt.set)
    except RuntimeError:
        pass


async def _notices_loop() -> None:
    """Publish every event without a notice yet, each minute and on wake; its own task, apart from attendance."""
    global _notices_evt
    _notices_evt = asyncio.Event()
    await asyncio.sleep(NOTICES_FIRST_S)
    while True:
        # THE SWITCH RIDES THIS CLOCK, NOT THE BUILDER'S.
        try:
            await asyncio.wait_for(_config_lane_refresh(), timeout=45)
        except Exception as exc:  # noqa: BLE001 — the previous answer stands
            log.warning("notices: the config lane could not be refreshed (%s)", type(exc).__name__)
        if PG_DSN and web_notices is not None:
            try:
                said = await asyncio.to_thread(web_notices.catch_up, PG_DSN)
                if said.get("published") or said.get("failed") or said.get("unreadable"):
                    log.info("notices: %s published %s, %s could not be stored%s",
                             said.get("published"), said.get("by_kind") or {}, said.get("failed"),
                             (" — could not read " + "; ".join(said["unreadable"]))
                             if said.get("unreadable") else "")
            except Exception as exc:  # noqa: BLE001 — this minute is lost, the next one is not
                log.warning("notices: the catch-up failed (%s)", type(exc).__name__)
        # its own try, so a failed hand-over never costs the next catch-up
        try:
            await _web_beat()
        except Exception as exc:  # noqa: BLE001
            log.warning("notices: the web beat failed (%s)", type(exc).__name__)
        try:
            await asyncio.wait_for(_notices_evt.wait(), timeout=NOTICES_EVERY_S)
        except asyncio.TimeoutError:
            pass
        _notices_evt.clear()


def _write_atomic(path: Path, payload: dict) -> None:
    """Rename, never overwrite — a reader sees one whole version or the other."""
    caught = _LIVE_CAPTURE.get()
    if caught is not None and path.parent == OUT_DIR:
        # a slice this relay shapes for asa-hub-app, which writes it (/slices/derived): one writer of the slices
        caught["files"][path.stem] = payload
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=str(path.parent), prefix=path.name, suffix=".tmp")
    try:
        with os.fdopen(fd, "w") as fh:
            json.dump(payload, fh, separators=(",", ":"), default=str)
        # mkstemp is 0600 by design; nginx runs as its own user and has to read these.
        os.chmod(tmp, 0o644)
        os.replace(tmp, path)
        # ONE PLACE, so every writer is covered without changing a signature: the file name IS the resource name…
        try:
            if path.parent == OUT_DIR:
                _publish_slice(path.stem)
        except Exception:  # noqa: BLE001 — telling nobody must never fail a build
            pass
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def _iso(ts: str | None):
    """Parse either mirror (+00:00) or stamp (Z) timestamps; None on failure."""
    if not ts:
        return None
    try:
        from datetime import datetime
        return datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
    except ValueError:
        return None


# -------------------------------------------------------------------------- THE JSON LANE (C5) — the architecture…
BUNDLE_LANE = os.getenv("HUB_BUNDLE_LANE", "") not in ("", "0", "false", "no")
# THE DEPOSIT LIVES INSIDE THE PROJECT — a self-contained folder, so that wherever the project is carried…
BUNDLE_DIR = Path(os.getenv("HUB_BUNDLE_DIR", "/srv/bundles"))
BUNDLE_MAX_AGE_S = int(os.getenv("HUB_BUNDLE_MAX_AGE_S", "900"))
