_dirty: set[str] = set()
_dirty_at: float = 0.0
_mirror_stale_said = 0.0
# True once the mirror has been caught unable to vouch — see _token_vouched
_mirror_blind = False
_cadence_said: dict[str, float] = {}
# token -> (checked_at, ok, role, uid).
_auth_cache: dict[str, tuple[float, bool, str, str]] = {}
# token -> the stamp of the brief refusal _validate writes when the backend could not answer: while that is still…
_auth_unsure: dict[str, float] = {}
# tokens being checked right now — one check per token, not one per read
_auth_pending: set[str] = set()
# the in-flight check itself, so first-touch requests can WAIT on it briefly instead of eating a 401 the cache would…
_auth_tasks: dict[str, asyncio.Task] = {}


# token -> the backend's own `is_master` for that session, learned only from an authLogin/authMe/authBootstrap answer.
_auth_master: dict[str, bool] = {}


# --------------------------------------------------------------------------- BE ANOTHER (apps-script/BeAnother.gs)…
_acting: dict[str, tuple[float, str, str]] = {}
# master token -> the child tokens it started here: a new start or the master's sign-out ends them on the backend…
_acting_children: dict[str, set[str]] = {}
# acting token -> when a real chatPing last went through for it.
_acting_beat_at: dict[str, float] = {}


def _acting_beat_dirty(since: str | None, last: float) -> bool:
    """Whether a message waits that the acting tab has not pinged for since `last`."""
    if since is None:
        return False
    parsed = _iso(since)
    if parsed is None:
        return last == 0.0
    if parsed.tzinfo is None:
        from datetime import timezone
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.timestamp() > last
# the doors an acting session may still POST to: the audited lane, the gate, the beat, and the rebuild hint a /gas…
_BE_ANOTHER_OPEN_PATHS = frozenset({"/gas", "/auth", "/chat/beat", "/notify"})
# a stream's end, put on its queue when the session behind it is revoked
_STREAM_END = object()


def _note_session_answer(token: str, env: Any) -> None:
    """What a backend answer says about this token's acting state — the one writer of _acting."""
    if not token or not isinstance(env, dict) or env.get("status") != 200:
        return
    data = env.get("data") if isinstance(env.get("data"), dict) else {}
    block = data.get("be_another") if isinstance(data.get("be_another"), dict) else {}
    acting = block.get("acting") if isinstance(block.get("acting"), dict) else None
    if not acting or not str(acting.get("id") or "").strip():
        # a token is one session of one account for life: an answer with nobody worn is not a child
        _acting.pop(token, None)
        return
    until = _iso(str(acting.get("until") or ""))
    try:
        until_s = until.timestamp() if until is not None else time.time() + float(acting.get("expires_in_ms") or 0) / 1000.0
    except (TypeError, ValueError):
        until_s = time.time()
    real = block.get("real") if isinstance(block.get("real"), dict) else {}
    _acting[token] = (until_s, str(real.get("id") or ""), str(acting.get("id") or ""))
    if len(_acting) > 2000:                  # a long-lived process, not a leak
        for t, (u, _r, _a) in list(_acting.items()):
            if u < time.time() - 86400:
                _acting.pop(t, None)
                _acting_beat_at.pop(t, None)


def _close_streams_for(token: str) -> int:
    """End every stream this token opened (chat, notices, slice events)."""
    closed = 0
    queues = [q for subs in list(_chat_subs.values()) for q in list(subs)] + list(_event_subs)
    for q in queues:
        if getattr(q, "token", None) != token:
            continue
        try:
            while q.full():
                q.get_nowait()
            q.put_nowait(_STREAM_END)
            closed += 1
        except Exception:  # noqa: BLE001 — a stream that will not take it dies with its tab
            pass
    return closed


def _be_another_revoke(token: str) -> None:
    """Be Back: the child token is refused here at once, and its streams end."""
    _auth_cache_put(token, False, "")
    _token_user.pop(token, None)
    _token_cortex.pop(token, None)
    _acting.pop(token, None)
    _acting_beat_at.pop(token, None)
    for kids in list(_acting_children.values()):
        kids.discard(token)
    _close_streams_for(token)
    _chat_live_revoke(token)
    try:
        asyncio.get_running_loop()
    except RuntimeError:  # no running loop (a test lifting this out): the row is never born for a child anyway
        return
    _keep_task(asyncio.to_thread(_vouch_put, hashlib.sha256(token.encode()).hexdigest(), False, "", ""))


def _relay_observe_be_another(raw: bytes, content: bytes) -> None:
    """The relay just carried a Be Another start or stop — the gate learns at once."""
    try:
        if b"beAnother" not in raw[:4096]:
            return
        req = _relay_envelope(raw)
        action = str((req or {}).get("action") or "")
        if action not in ("beAnotherStart", "beAnotherStop"):
            return
        env = json.loads(content)
        if not isinstance(env, dict) or env.get("status") != 200:
            return
        data = env.get("data") if isinstance(env.get("data"), dict) else {}
        if action == "beAnotherStop":
            child = str((req or {}).get("token") or "")
            if child:
                _be_another_revoke(child)
            return
        child = str(data.get("token") or "")
        parent = str((req or {}).get("token") or "")
        user = data.get("user") if isinstance(data.get("user"), dict) else {}
        uid = str(user.get("id") or "")
        if not child or not uid or not parent or child == parent:
            return
        _note_session_answer(child, {"status": 200, "data": {"user": user, "be_another": data.get("be_another")}})
        if child not in _acting:
            return      # a start answer without its acting block is not trusted as one
        # the backend ended this master session's earlier children before minting this one
        for earlier in list(_acting_children.get(parent) or ()):
            _be_another_revoke(earlier)
        _acting_children.setdefault(parent, set()).add(child)
        _auth_cache_put(child, True, str(user.get("role") or ""), uid, is_master=False)
        _token_user_put(child, uid, str(user.get("display_name") or ""))
    except Exception:  # noqa: BLE001 — observation is a bonus, never a failure mode
        pass


def _be_another_signed_out(token: str, uid: str = "") -> None:
    """A sign-out the relay carried: a child is revoked whole, a master's children with it."""
    if token in _acting:
        _be_another_revoke(token)
        return
    kids = _acting_children.pop(token, None)
    for child in list(kids or ()):
        _be_another_revoke(child)
    if not kids and uid:
        for child, (_until, real_uid, _target) in list(_acting.items()):
            if real_uid == uid:
                _be_another_revoke(child)


def _be_another_write_refusal(method: str, path: str, token: str) -> dict[str, Any] | None:
    """The answer for a relay-direct write from an acting session, or None."""
    if str(method or "GET").upper() in ("GET", "HEAD", "OPTIONS"):
        return None
    if str(path or "") in _BE_ANOTHER_OPEN_PATHS:
        return None
    act = _acting.get(token) if token else None
    if not act:
        return None
    return {"status": 409, "code": "be_another_refused",
            "message": "Not in a switched session: this door cannot take the write. "
                       "Press Be Back to do this as yourself."}


def _auth_cache_put(token: str, ok: bool, role: str, uid: str = "", *, at: float | None = None,
                    is_master: bool | None = None) -> None:
    """Every cache write goes through here so the size guard cannot be skipped by an early return — the…"""
    uid = str(uid or "")
    if ok and not uid.strip():
        prior = _auth_cache.get(token)
        if prior and prior[1] and len(prior) > 3 and str(prior[3] or "").strip():
            uid = str(prior[3])
    stamp = time.time() if at is None else at
    # an acting session's verdict never outlives the acting session itself
    act = _acting.get(token)
    if ok and act:
        stamp = min(stamp, act[0] - AUTH_TTL_SECONDS)
    _auth_cache[token] = (stamp, ok, role, uid)
    if not ok:
        _auth_master.pop(token, None)
    elif is_master is not None:
        _auth_master[token] = bool(is_master)
    if len(_auth_cache) > 5000:
        _auth_cache.clear()
        _auth_master.clear()


@app.on_event("startup")
async def _start() -> None:
    global _event_loop
    logging.basicConfig(level=logging.INFO)
    # The builder publishes from worker threads; it needs THIS loop to hand the message to.
    _event_loop = asyncio.get_running_loop()
    # the relay's own Postgres session record (additive DDL, best-effort)
    _vouch_table_ensure()
    # a change of who reads what the relay saw before it stopped still settles Python's reads (BACKEND PER APP)
    _backend_people_take_up()
    # THE PLATFORM'S OWN SHEETS⇄POSTGRES KEEPER — the system resolves this for itself: the delta mirror lane that…
    async def _sheet_sync_keeper() -> None:
        import sys
        script = str(Path(__file__).resolve().parent / "hub_sheet_sync.py")
        env = dict(os.environ, HUB_PG_DSN=PG_DSN)
        while True:
            try:
                proc = await asyncio.create_subprocess_exec(sys.executable, script, env=env)
                log.info("sheet-sync keeper spawned (pid %s)", proc.pid)
                # woken after a change of who reads what (_sheet_sync_wake)
                _SHEET_SYNC_PROC[:] = [proc, time.time()]
                rc = await proc.wait()
                log.warning("sheet-sync keeper exited rc=%s — respawn in 60s", rc)
            except Exception as _sse:  # noqa: BLE001 — the old mirror keeps serving
                log.warning("sheet-sync keeper failed to spawn: %s", _sse)
            await asyncio.sleep(60)

    # THE SECOND LANE, ARMED — on from here, with Python taking everything.
    async def _form_digest_keeper() -> None:
        import sys
        script = str(Path(__file__).resolve().parent / "form_digest.py")
        env = dict(os.environ, HUB_PG_DSN=PG_DSN)
        while True:
            try:
                proc = await asyncio.create_subprocess_exec(sys.executable, script, env=env)
                log.info("form-digest keeper spawned (pid %s)", proc.pid)
                rc = await proc.wait()
                log.warning("form-digest keeper exited rc=%s — respawn in 60s", rc)
            except Exception as _fde:  # noqa: BLE001 — the engine's sweep stands
                log.warning("form-digest keeper failed to spawn: %s", _fde)
            await asyncio.sleep(60)

    # THE MARS PAPERS, FOUND AND READ AS THEY ARRIVE — the text kept in asa-hub-db for Clients › Medication.
    async def _mar_papers_keeper() -> None:
        import sys
        script = str(Path(__file__).resolve().parent / "mar_papers.py")
        env = dict(os.environ, HUB_PG_DSN=PG_DSN)
        while True:
            try:
                proc = await asyncio.create_subprocess_exec(sys.executable, script, env=env)
                log.info("mar-papers keeper spawned (pid %s)", proc.pid)
                rc = await proc.wait()
                log.warning("mar-papers keeper exited rc=%s — respawn in 60s", rc)
            except Exception as _mpe:  # noqa: BLE001 — the screen reads what is already kept
                log.warning("mar-papers keeper failed to spawn: %s", _mpe)
            await asyncio.sleep(60)

    # WHAT A CANDIDATE SAID ON A CALL, HEARD ONCE — Staff Candidates' preferences, kept in asa-hub-db.
    async def _call_prefs_keeper() -> None:
        import sys
        script = str(Path(__file__).resolve().parent / "call_prefs.py")
        env = dict(os.environ, HUB_PG_DSN=PG_DSN)
        while True:
            try:
                proc = await asyncio.create_subprocess_exec(sys.executable, script, env=env)
                log.info("call-prefs keeper spawned (pid %s)", proc.pid)
                rc = await proc.wait()
                log.warning("call-prefs keeper exited rc=%s — respawn in 60s", rc)
            except Exception as _cpe:  # noqa: BLE001 — the screen reads what is already kept
                log.warning("call-prefs keeper failed to spawn: %s", _cpe)
            await asyncio.sleep(60)

    # A RÉSUMÉ THAT IS A SCAN, READ ONCE BY OCR — Staff Candidates' Resume, the words kept in asa-hub-db.
    async def _resume_texts_keeper() -> None:
        import sys
        script = str(Path(__file__).resolve().parent / "resume_texts.py")
        env = dict(os.environ, HUB_PG_DSN=PG_DSN)
        while True:
            try:
                proc = await asyncio.create_subprocess_exec(sys.executable, script, env=env)
                log.info("resume-texts keeper spawned (pid %s)", proc.pid)
                rc = await proc.wait()
                log.warning("resume-texts keeper exited rc=%s — respawn in 60s", rc)
            except Exception as _rte:  # noqa: BLE001 — the screen reads what is already kept
                log.warning("resume-texts keeper failed to spawn: %s", _rte)
            await asyncio.sleep(60)

    # THE CERTIFICATES, READ HERE AS THEY ARE FILED — the reading kept in asa-hub-db for Compliance documents.
    async def _cert_reads_keeper() -> None:
        import sys
        script = str(Path(__file__).resolve().parent / "cert_reads.py")
        env = dict(os.environ, HUB_PG_DSN=PG_DSN)
        while True:
            try:
                proc = await asyncio.create_subprocess_exec(sys.executable, script, env=env)
                log.info("cert-reads keeper spawned (pid %s)", proc.pid)
                rc = await proc.wait()
                log.warning("cert-reads keeper exited rc=%s — respawn in 60s", rc)
            except Exception as _cre:  # noqa: BLE001 — the ledger keeps what was read
                log.warning("cert-reads keeper failed to spawn: %s", _cre)
            await asyncio.sleep(60)

    # the six keepers are asa-hub-worker's (server/hub_worker.py), which waits while /health says they run here
    if RELAY_KEEPERS:
        for keeper in (_sheet_sync_keeper, _form_digest_keeper, _mar_papers_keeper, _call_prefs_keeper,
                       _resume_texts_keeper, _cert_reads_keeper):
            asyncio.create_task(keeper())
    else:
        log.info("keepers: none started here — asa-hub-worker runs them (HUB_RELAY_KEEPERS=1 starts them here)")

    # THE FILES ARE DECODED BY PYTHON ALONE: form_digest above reads both ledgers with Tesseract. Apps Script's
    # digestSweep is never rung again: its Drive conversions left a "digest-tmp" Doc beside a paper at every read.
 # WHAT WE ALREADY HAVE ON OUR OWN DISK.
    _bundle_adopt_disk()
    # the slices' clock and the config lane's tick (app/live_slices.py), the strip's frames with its phase and the web
    # build (app/hub_strip.py) and the bundle loop (app/live_bundle.py) are asa-hub-app's: never started here. This
    # relay's answers say the phase _loop said one tick after every start, and its config lane is told by the app
    _hub_full_pass_done(time.time())
    # the live chat hub forgets every ref with this start: it asks its tabs for new tickets
    _keep_task(_chat_live_hello())
    # the live chat cache: its kept copies taken up, then written back as it changes
    _keep_task(_chat_cache_start())
    # the boards kept per viewer: taken up from disk, then written back as they change (VIEWER CACHE)
    _keep_task(_viewer_cache_start())
    # the chat sends kept here first: taken up again and written behind to the chat's own tables
    _keep_task(_chat_behind_start())
    # the staff beat, its watchdog row and the arriving calls are asa-hub-app's (app/clocks.py sweep_loop,
    # app/comm_calls_door.py live_tick): never started here
    # the time clock (its login plan and latch), the shift pool and every post on its beat, the full punch sheet and the
    # doors that read that memory are asa-hub-app's (app/attendance_loop.py): never started here, so nothing signs in
    # to PsiAnywhere or sends twice; the shift flow's ledger it writes is followed from disk by this relay's readers
    psi_reminders.FOLLOW_DISK[0] = True
    # every publish to a house calendar reaches every reader of a shift at once
    effective_roster.on_change(_roster_published)
    # the phone's texts (the inbox, its hand-off and the Quo pull) and the 20-second beat are asa-hub-app's
    # (app/clocks.py): never started here
    # the ear that acts on the replies the inbox kept, and its acknowledgements, are asa-hub-app's (app/clocks.py,
    # app/sms_ears.py): never started here
    # the app packs are asa-hub-app's (app/app_packs.py): its warm loop owns /srv/app-packs, never started here
    # the pharmacy's medication reports: the six-hourly sweep is asa-hub-app's (app/clocks.py house_meds_loop, under
    # the lane's folder lock); the house copy is the Postgres → sheet sync's: never started here
    if time_off is not None and PG_DSN:
        asyncio.create_task(_time_off_boot())
    # the company's notices: the catch-up, the frames, the pushes, their release and the mock rows' hand-off are
    # asa-hub-app's clock (app/notice_clock.py), never started here; a notice this relay's own clocks store is handed
    # to it to carry (_notice_fanout)
    if web_notices is not None:
        web_notices.on_publish(_notice_fanout)
        # the switch is read when a notice is stored
        web_notices.set_hold_probe(lambda: bool(_web_switch().get("on")))
        # and each kind's own situation, carried on the config lane beside the gates
        web_notices.set_situation_probe(lane_gate.notice_state)
        # ASK FOR THE SWITCH BEFORE ANYTHING CAN BE HELD BY IT: one read at start, then the lane asa-hub-app reads is
        # told here (/live-notify/told)
        asyncio.create_task(_config_lane_refresh(force=True))


def _bundle_adopt_disk() -> None:
    """Take up the bundles this service last deposited, fingerprints and all."""
    if not BUNDLE_DIR:
        return
    taken = 0
    try:
        for path in sorted(BUNDLE_DIR.glob("*.json")):
            if "~" in path.stem:
                continue
            try:
                data = json.loads(path.read_text())
            except Exception:  # noqa: BLE001 — a half-written file is not a bundle
                continue
            if not isinstance(data.get("resources"), dict):
                continue
 # A BUNDLE WITHOUT FINGERPRINTS IS STILL A BUNDLE.
            if not data.get("revs"):
                log.warning("bundle lane: %s was deposited WITHOUT fingerprints — "
                            "it will be read whole every cycle until the backend "
                            "sends them", path.stem)
            if int(data.get("reader") or 0) < BUNDLE_READER_MIN:
                continue
            key = "" if path.stem == "home" else path.stem
            _BUNDLE_HELD[key] = data
            revs = data.get("revs") or {}
 # NEVER ADOPT A LIE (measured live).
            poisoned = _bundle_poisoned_resources(data["resources"], revs)
            for resource in poisoned:
                log.warning("bundle lane: %s claims rows for %s the deposit does "
                            "not hold — the fingerprint is dropped, never adopted, "
                            "and the next cycle re-reads it", path.stem, resource)
                tab = str(resource)
                revs = {rk: rv for rk, rv in revs.items()
                        if str(rk).rsplit("::", 1)[-1] not in (
                            {e.get("sheet") for e in load_manifest()
                             if e.get("resource") == tab})}
            _BUNDLE_REVS[key] = revs
            if key == "":
                _LAST_BUNDLE.update({"at": time.time(),
                                     "built_at": str(data.get("built_at") or ""),
                                     "resources": data["resources"]})
            taken += 1
    except Exception as exc:  # noqa: BLE001 — an empty start is a valid start
        log.warning("bundle lane: could not adopt the deposit: %s", exc)
    if taken:
        log.info("bundle lane: adopted %d bundle(s) from disk — the first cycle "
                 "asks only for what moved", taken)


async def _bundle_cycle() -> None:
    """Refresh every place's bundle, once."""
    _BUNDLE_CYCLES["n"] += 1
    targets = await _bundle_targets()
    alive = {t["key"] for t in targets}
    # A LIST WALKED FROM THE TOP EVERY TIME IS A LIST WITH A TAIL NOBODY READS .
    rest = sorted([t for t in targets if t["key"] != ""], key=lambda t: t["key"])
    cursor = _BUNDLE_CURSOR.get("i") or 0
    if cursor >= len(rest):
        cursor = 0
    ordered = ([t for t in targets if t["key"] == ""]
               + rest[cursor:] + rest[:cursor])
    examined = 0
    deadline = time.monotonic() + BUNDLE_CYCLE_BUDGET_S
    for target in ordered:
        if target["key"] != "":
            # AT THE TOP, NEVER MID-TARGET: a target begun runs to completion, however long it costs, because…
            if time.monotonic() > deadline:
                _BUNDLE_BUDGET["overruns"] += 1
                _BUNDLE_BUDGET["at"] = time.time()
                log.info("bundle lane: budget spent after %d of %d target(s) — "
                         "the next cycle resumes at %s", examined, len(rest),
                         (rest[(cursor + examined) % max(1, len(rest))]["key"]
                          if rest else "home"))
                break
            examined += 1
            # WRITTEN AS WE GO, not after the loop.
            try:
                _BUNDLE_CURSOR["i"] = (cursor + examined) % max(1, len(rest))
            except Exception:  # noqa: BLE001 — a lost cursor costs a repeat, never a raise
                pass
        # IN PIECES, THEN PUT BACK TOGETHER.
        n = BUNDLE_PARTS if "world" not in target else 1
        built = None
        pieces: list[dict[str, Any]] = []
        for piece in range(n):
            got = await _bundle_build(target, piece, n)
            body_piece = _bundle_body(got)
            if body_piece is None:
                # ONE PIECE MISSING IS NO BUNDLE.
                log.warning("bundle %s: piece %d of %d did not come back — "
                            "the cycle falls back", target["key"] or "home", piece + 1, n)
                pieces = []
                break
            pieces.append(body_piece)
            built = got
            # AN OLDER BACKEND IGNORES THE SPLIT and answers with the whole thing, so asking for the second half…
            if int((got or {}).get("parts") or 1) < 2 and n > 1:
                break
        body = None
        if pieces:
            body = pieces[0]
            if len(pieces) > 1:
                joined = dict(body)
                res: dict[str, Any] = {}
                revs: dict[str, str] = {}
                carried: list[str] = []
                for pc in pieces:
                    res.update(pc.get("resources") or {})
                    revs.update(pc.get("revs") or {})
                    carried.extend(pc.get("carried") or [])
                joined["resources"], joined["revs"], joined["carried"] = res, revs, carried
                body = joined
        if body is not None:
            body = _bundle_merge(target["key"], body) or None
        if body is not None:
            if not (built or {}).get("carried"):
                _BUNDLE_FULL_OWED.discard(target["key"])
            _BUNDLE_HELD[target["key"]] = body
            _bundle_evict(alive)
            _BUNDLE_REVS[target["key"]] = body.get("revs") or {}
            read_now = len((built or {}).get("read") or {})
            carried_now = len((built or {}).get("carried") or [])
            if carried_now:
                log.info("bundle %s: %d tab(s) changed, %d carried forward",
                         target["key"] or "home", read_now, carried_now)
            # It came back with the build.
            if target["key"] == "":
                _LAST_BUNDLE.update({"at": time.time(),
                                     "built_at": str(body.get("built_at") or ""),
                                     "resources": body["resources"]})
            _bundle_deposit(target["key"], body)
        else:
            # An older backend, or a build that skipped because another was already running: read it back the way…
            await _bundle_fetch(target["key"], hold=(target["key"] == ""))
        # and the personal half of a PLACE — a world is already one person's whole workbook, so there is nothing to…
        if "world" not in target:
            await _bundle_owned(target.get("place") or "")


async def _bundle_loop() -> None:
    """The bundle's own clock."""
    # asa-hub-app's now (app/live_bundle.py): one writer of /srv/bundles
    if not SLICES_BUILT_HERE:
        return
    while True:
        await asyncio.sleep(5)
        if not BUNDLE_LANE:
            continue
        if time.time() - _LAST_BUNDLE_BUILD["at"] < BUNDLE_MIN_INTERVAL_S:
            continue
        # Stamped BEFORE the work, not after: a cycle that overruns must not let the next one start a second one…
        _LAST_BUNDLE_BUILD["at"] = time.time()
        try:
            await asyncio.wait_for(_bundle_cycle(), timeout=BUNDLE_CYCLE_TIMEOUT_S)
        except asyncio.TimeoutError:
            log.error("bundle lane: cycle exceeded %ss and was abandoned — the "
                      "previous bundles stay served", BUNDLE_CYCLE_TIMEOUT_S)
        except Exception as exc:  # noqa: BLE001 — the loop must not die
            log.exception("bundle lane: %s", exc)
        # AFTER the cycle, not before.
        await _cadence_beat('hub.bundle_cycle', BUNDLE_CYCLE_TIMEOUT_S,
                            cursor=_BUNDLE_CURSOR.get("i"),
                            cycles=_BUNDLE_CYCLES.get("n"))


async def _loop() -> None:
    """One loop serving both triggers: the debounce and the floor."""
    global _dirty, _dirty_at
    last_full = 0.0
    while True:
        await asyncio.sleep(1)
        now = time.time()
        try:
            # the slices are built by asa-hub-app's own clock (app/live_slices.py): this one keeps the config lane
            # and says the phase ready
            if not SLICES_BUILT_HERE and not last_full:
                last_full = now
                _hub_full_pass_done(now)
 # A BUILD MUST NOT BE ABLE TO HANG THE LOOP.
            elif SLICES_BUILT_HERE and _dirty and now - _dirty_at >= DEBOUNCE_SECONDS:
                due, _dirty = _dirty, set()
                await asyncio.wait_for(build_all(only=due), timeout=BUILD_TIMEOUT_S)
            elif SLICES_BUILT_HERE and now - last_full >= HEARTBEAT_SECONDS:
                last_full = now
                try:
                    await asyncio.wait_for(build_all(), timeout=BUILD_TIMEOUT_S)
                finally:
                    # a full pass that failed or was abandoned ends the strip's phase too: a backend that cannot…
                    _hub_full_pass_done(now)
            # The configuration rides the same clock, on its own TTL, so it is warm before anybody signs in rather…
            try:
                await asyncio.wait_for(_config_lane_refresh(), timeout=60)
            except Exception as exc:  # noqa: BLE001 — the previous answer stands
                log.warning("config lane tick: %s", exc)
        except asyncio.TimeoutError:
            log.error("snapshot build exceeded %ss and was abandoned — the "
                      "previous slices stay served; next tick starts fresh", BUILD_TIMEOUT_S)
        except Exception as exc:  # noqa: BLE001 - the loop must not die
            log.exception("snapshot loop: %s", exc)


@app.post("/notify")
async def notify(payload: dict[str, Any]) -> dict[str, Any]:
    """A write happened."""
    names = payload.get("resources") or ([payload["resource"]] if payload.get("resource") else [])
    accepted = _mark_dirty(names)
    return {"accepted": accepted, "rebuild_in": DEBOUNCE_SECONDS if accepted else None}


@app.post("/lanes/told")
async def lanes_told(payload: dict[str, Any]) -> dict[str, Any]:
    """What asa-hub-app's scheduling lanes (app/sched_lanes.py) wrote, told to this relay's streams and clocks: bare
    events, wakes, caches to forget, a published roster, and test mode's mockup row for roster cells it held."""
    if not SERVICE_SECRET or not hmac.compare_digest(str(payload.get("service_secret") or ""), SERVICE_SECRET):
        return {"status": 401, "message": "service identity required"}
    out: dict[str, Any] = {"status": 200}
    # the open streams are asa-hub-app's, which publishes these names itself once this answers: only the kept copies
    # are rung here
    for name in payload.get("events") or []:
        _viewer_cache_rang(str(name))
    wake = {str(w) for w in payload.get("wake") or []}
    if "notices" in wake:
        _notices_wake()
    # "attendance" and "calloff_road" wake asa-hub-app's own attendance loop (app/attendance_loop.py), never this relay
    forget = {str(f) for f in payload.get("forget") or []}
    if "estate" in forget:
        shift_requests.forget_estate()
    if "time_off" in forget and time_off is not None:
        time_off.forget()
    if isinstance(payload.get("roster"), dict):
        _roster_published(payload["roster"])
    held = payload.get("held_roster")
    if isinstance(held, dict) and web_gate is not None:
        try:
            web_gate.record(web_gate.roster_rows(
                str(held.get("location") or ""), [c for c in held.get("cells") or [] if isinstance(c, dict)],
                via=str(held.get("via") or ""), actor=str(held.get("actor") or ""), act=str(held.get("act") or ""),
                switch=held.get("switch") if isinstance(held.get("switch"), dict) else _web_switch()))
            out["held_kept"] = True
        except Exception as exc:  # noqa: BLE001 — the platform's record stands; said
            log.warning("lanes told: a held roster's mockup row was not kept (%s)", type(exc).__name__)
            out["held_kept"] = False
    if names := [str(r) for r in payload.get("resources") or []]:
        out["accepted"] = _mark_dirty(names)
    return out


@app.post("/live-notify/told")
async def live_notify_told(request: Request) -> Response:
    """What asa-hub-app's clocks tell this relay's memory (app/live_notify.py told): bare event names rung to every
    open stream, the app packs a sweep made stale, a clock of this relay's woken, the config lane it read (lane)."""
    if not HUB_APP_TOKEN or not hmac.compare_digest(request.headers.get("x-hub-token", ""), HUB_APP_TOKEN):
        return Response(status_code=401)
    try:
        body = json.loads(await request.body() or b"{}")
    except ValueError:
        body = None
    if not isinstance(body, dict):
        return Response(status_code=400)
    now = time.time()
    for name in body.get("swept") or []:
        _app_pack_swept[str(name)] = now
    # published by asa-hub-app itself once this answers: only the kept copies are rung here
    for name in body.get("rang") or []:
        _viewer_cache_rang(str(name))
    wakes = body.get("wake") or []
    if "sms-ears" in wakes:
        _sms_ears_wake()
    if "access-written" in wakes:
        # App Control changed who reaches which app (asa-hub-app's finish saw it land): the gated lanes here stop
        # trusting older copies, and every kept copy is read again
        if hotline_desk is not None:
            hotline_desk.note_access_written()
        _VIEWER_CACHE_WROTE["*"] = time.monotonic()
        _viewer_cache_marks_keep()
        _VIEWER_CACHE_DIRTY.update(_VIEWER_CACHE)
        _viewer_cache_unlink_now(sorted(_VIEWER_CACHE_DIRTY))
        _VIEWER_CACHE.clear()
    if "sheet-sync" in wakes:
        _backend_people_wake_in(BACKEND_PEOPLE_WAKE_S)
    # the config lane asa-hub-app read (app/live_slices.py): this relay's gates, switch and digest worker read it
    lane = body.get("config_lane")
    if isinstance(lane, dict):
        _CONFIG_LANE["data"] = lane
        _CONFIG_LANE["at"] = time.time()
        lane_gate.publish(lane)
    return Response(status_code=204)


def _mark_dirty(names: Any) -> list[str]:
    """Queue these manifest resources for the debounced rebuild; the names the manifest knows come back sorted."""
    global _dirty_at
    # the study's held sources have no entry, but a write to one still rebuilds it
    known = {e["resource"] for e in load_manifest()} | set(medcorr_slices.SOURCES)
    accepted = {n for n in names if n in known}
    if accepted and not SLICES_BUILT_HERE:
        # asa-hub-app's slices: its own debounce rebuilds them
        caught = _LIVE_CAPTURE.get()
        if caught is not None:
            caught["dirty"].extend(sorted(accepted))
        else:
            _live_forward("/notify", {"resources": sorted(accepted)})
    elif accepted:
        _dirty.update(accepted)
        # The clock is only WOUND, never rewound (review): a stream of notifies used to push the debounce forward…
        if not _dirty_at or time.time() - _dirty_at >= DEBOUNCE_SECONDS:
            _dirty_at = time.time()
    return sorted(accepted)



# -------------------------------------------------------------------------- traffic — the one number the resolver…
_traffic: dict[str, Any] = {"since": time.time(), "slice_reads": 0,
                            "exec_read": 0, "exec_write": 0, "exec_tool": 0,
                            "exec_auth": 0, "exec_undeclared": 0,
                            "exec_service": 0}


def _traffic_note(key: str) -> None:
    try:
        _traffic[key] = _traffic.get(key, 0) + 1
    except Exception:  # noqa: BLE001 — a counter must never be the outage
        pass


def _traffic_write_slice() -> None:
    """Publish the traffic as an ORDINARY SLICE, admin-only."""
    from datetime import datetime, timezone   # module scope has no import
    try:
        _write_atomic(OUT_DIR / "resolverHealth.json", {
            "resource": "resolverHealth",
            "built_at": datetime.now(timezone.utc).isoformat(),
            "rows": [dict(_traffic_snapshot(), id="traffic")],
        })
    except Exception as exc:  # noqa: BLE001 - a report must never be an outage
        log.warning("resolver health slice not written: %s", exc)


def _traffic_snapshot() -> dict[str, Any]:
    execs = sum(v for k, v in _traffic.items()
                if k.startswith("exec_") and isinstance(v, int)
                and k != "exec_service")
    service = int(_traffic.get("exec_service", 0))
    slices = int(_traffic.get("slice_reads", 0))
    total = execs + slices
    return {
        "window_s": round(time.time() - float(_traffic["since"])),
        "slice_reads": slices,
        "exec_reads": int(_traffic.get("exec_read", 0)),
        "exec_writes": int(_traffic.get("exec_write", 0)),
        "exec_tools": int(_traffic.get("exec_tool", 0)),
        "exec_undeclared": int(_traffic.get("exec_undeclared", 0)),
        # The snapshot builder's own heartbeat, kept OUT of the ratio.
        "exec_service": service,
        # Heartbeats the relay answered from memory instead of spending an execution on.
        "chat_beats": int(_traffic.get("chat_beats", 0)),
        # The twenty worst, ranked. This is the worklist.
        "by_action": dict(sorted(_by_action.items(), key=lambda kv: -kv[1])[:20]),
        # THE number: the share of the BROWSER's data requests that still spend an execution.
        "exec_share": round(execs / total, 3) if total else None,
        "exec_share_covers": "browser traffic only — the snapshot builder posts to Apps Script directly",
    }


@app.get("/auth")
async def auth(
    authorization: str = Header(default=""),
    original_uri: str = Header(default="", alias="X-Original-URI"),
) -> Response:
    """nginx asks this before handing over a slice."""
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    if not token:
        return Response(status_code=401)

    hit = _auth_cache.get(token)
    if hit and time.time() - hit[0] < AUTH_TTL_SECONDS:
        if not hit[1]:
            return Response(status_code=401)
        return Response(status_code=200 if _role_may_read(hit[2], original_uri) else 403)

    # Unknown or expired entry: the MIRROR answers first — a local lookup in milliseconds, no Apps Script spent, so…
    verdict = await asyncio.to_thread(_session_verdict, token)
    if verdict is not None:
        ok, role, uid = verdict
        _auth_cache_put(token, ok, role, uid)
        if not ok:
            return Response(status_code=401)
        ok = _role_may_read(role, original_uri)
        if ok and _is_slice_uri(original_uri):
            _traffic_note("slice_reads")
        return Response(status_code=200 if ok else 403)

    # The mirror cannot say (sign-in newer than its last pass, or mirror down) → the backend decides.
    if token not in _auth_pending and len(_auth_pending) < 256:
        _auth_pending.add(token)
        _auth_tasks[token] = asyncio.create_task(_validate(token))

    # FIRST-TOUCH GRACE — wait for the in-flight verdict instead of refusing what the cache would serve seconds later.
    task = _auth_tasks.get(token)
    if task is not None:
        try:
            await asyncio.wait_for(asyncio.shield(task), timeout=AUTH_GRACE_S)
        except Exception:  # noqa: BLE001 — timeout or validator hiccup: refuse for now
            pass
        hit = _auth_cache.get(token)
        if hit and time.time() - hit[0] < AUTH_TTL_SECONDS:
            if not hit[1]:
                return Response(status_code=401)
            ok2 = _role_may_read(hit[2], original_uri)
            if ok2:
                _traffic_note("slice_reads")
            return Response(status_code=200 if ok2 else 403)
    return Response(status_code=401)


# The doors behind this gate that are NOT a slice.
_NON_SLICE_DOORS = ("/snapshot/events", "/snapshot/chat-stream", "/snapshot/chat-beat",
                    "/snapshot/chat-ticket",
                    "/cortex/chat/send", "/cortex/mesh/graph", "/cortex/mesh/live",
                    "/cortex/health", "/cortex/fleet")


def _is_slice_uri(uri: str) -> bool:
    return uri.split("?", 1)[0] not in _NON_SLICE_DOORS


def _role_may_read(role: str, uri: str) -> bool:
    """Whether this role can reach the resource behind the requested file."""
    # The URI judged here is the raw request line; nginx serves the normalized one and cuts it at '#'.
    if "#" in uri or "\\" in uri:
        return False
    path = uri.split("?", 1)[0]
    if "%" in path:
        return False
 # THE NON-SLICE DOORS.
    if path in ("/digest/try", "/digest/shelf", "/digest/proposals",
                "/digest/proposals/decide", "/digest/teach"):
        return True
    if path in ("/snapshot/events", "/snapshot/chat-stream", "/snapshot/chat-beat",
                # live chat's ticket: the door itself judges the session, the acting state and the App Control row…
                "/snapshot/chat-ticket",
                "/cortex/chat/send",
 # THE PLACE DOOR (found live): the gate answered 403 to EVERY role, because "place" is not a .json and was named…
                "/snapshot/place"):
        return True
    if path in ("/cortex/mesh/graph", "/cortex/mesh/live",
                "/cortex/health", "/cortex/fleet"):
        return role == "admin"
    name = path.rsplit("/", 1)[-1]
    if name == "index.json":
        return True  # ages and error states only — no rows
    if name == "all.json":
        return True  # the bang bundle — role-filtered INSIDE /bundle below
    if not name.endswith(".json"):
        return False
    resource = name[: -len(".json")]
    for entry in load_manifest():
        if entry["resource"] == resource:
            return role in (entry.get("roles") or [])
    return False


async def _validate(token: str) -> None:
    """Ask the sign-in whether this session is real, out of everyone's way."""
    ok = False
    role = ""
    transport_failed = False
    try:
        env = await _auth_me(token)
        ok = env.get("status") == 200
        _user = ((env.get("data") or {}).get("user") or {})
        role = str(_user.get("role") or "")
        uid = str(_user.get("id") or _user.get("user_id") or "")
        is_master = bool(_user.get("is_master")) if "is_master" in _user else None
        _note_session_answer(token, env)
    except Exception as exc:  # noqa: BLE001
        transport_failed = True
        log.warning("auth check failed: %s", exc)
    finally:
        _auth_pending.discard(token)
        _auth_tasks.pop(token, None)
    if transport_failed:
        # A busy backend is not a signed-out person — but adversarial review killed the first cure, which extended…
        placeholder = time.time() - AUTH_TTL_SECONDS + 20.0
        _auth_cache_put(token, False, "", at=placeholder)
        if len(_auth_unsure) > 5000:
            _auth_unsure.clear()
        _auth_unsure[token] = placeholder
        return
    _auth_cache_put(token, ok, role, uid, is_master=is_master)
    # the verdict lands in Postgres — the relay feeds the session record it reads, and the Drive photograph is no…
    await asyncio.to_thread(
        _vouch_put, hashlib.sha256(token.encode()).hexdigest(), ok and token not in _acting, role, uid)



@app.get("/events")
async def events(authorization: str = Header(default="")) -> Response:
    """Which slice just changed, as it happens."""
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    hit = _auth_cache.get(token) if token else None
    if not hit or not hit[1] or time.time() - hit[0] >= AUTH_TTL_SECONDS:
        return Response(status_code=401)

    queue: asyncio.Queue = asyncio.Queue(maxsize=64)
    # Untagged until the Smart Comms gate opens for this session: no hotline name reaches it before then…
    queue.hotline = False  # type: ignore[attr-defined]
    queue.hotline_until = 0.0  # type: ignore[attr-defined]
    queue.hotline_auth = (authorization, token)  # type: ignore[attr-defined]
    # whose session it is, so Be Back can end it (_close_streams_for)
    queue.token = token  # type: ignore[attr-defined]
    _event_subs.add(queue)
    _keep_task(_events_tag_hotline(queue, authorization, token))
    # back online: this viewer's stale kept boards are read again before they look (VIEWER CACHE)
    _viewer_cache_online(token)

    async def stream():
        try:
            yield b": open\n\n"
            while True:
                try:
                    resource = await asyncio.wait_for(queue.get(), timeout=25)
                except asyncio.TimeoutError:
                    yield b": ping\n\n"
                    continue
                if resource is _STREAM_END:
                    break    # the session behind it was revoked (Be Back)
                yield f"data: {resource}\n\n".encode()
        finally:
            # A tab that closed, a proxy that cut the line, a reload: the subscriber goes with it, or the set grows…
            _event_subs.discard(queue)

    return StreamingResponse(
        stream(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-store",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )


@app.post("/chat/beat")
async def chat_beat(authorization: str = Header(default="")) -> Response:
    """The shell's heartbeat, answered without spending an Apps Script execution."""
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    hit = _auth_cache.get(token) if token else None
    if not hit or not hit[1] or time.time() - hit[0] >= AUTH_TTL_SECONDS:
        return Response(status_code=401)

    me = _token_user_get(token)
    if not me:
        # Never seen this token — say so rather than guess.
        return JSONResponse({"ok": False, "due": True})

    now = time.time()
    acting = token in _acting
    # an acting session (Be Another) is not the person being here
    if not acting:
        _presence_seen[me] = now
    _traffic_note("chat_beats")
    if acting:
        # THE ACTING TAB KEEPS ITS OWN CLOCK, by token: it never settles the target's flags (they are theirs), so on…
        last = _acting_beat_at.get(token, 0.0)
        dirty = _acting_beat_dirty(_chat_dirty.get(me) if me in _chat_dirty else None, last)
    else:
        last = _chat_beat_at.get(me, 0.0)
        dirty = me in _chat_dirty
    due = dirty or (now - last) >= _CHAT_BEAT_DUE_S
    return JSONResponse({
        "ok": True,
        "me": me,
        "me_name": _token_name_get(token),
        "due": bool(due),
        "dirty": bool(dirty),
        "live": any(not getattr(q, "acting", False) for q in (_chat_subs.get(me) or ())),
        "since": _chat_dirty.get(me, ""),
        # newest notice id for a polling tab; null means "ask", never "none"
        "notices": web_notices.latest_id() if web_notices is not None else None,
    })


@app.get("/chat/stream")
async def chat_stream(authorization: str = Header(default=""),
                      x_hub_notices: str = Header(default=""),
                      x_hub_strip: str = Header(default="")) -> Response:
    """Messages as they are sent, instead of a browser asking every 20 seconds."""
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    hit = _auth_cache.get(token) if token else None
    if not hit or not hit[1] or time.time() - hit[0] >= AUTH_TTL_SECONDS:
        return Response(status_code=401)

    me = _token_user_get(token)
    if not me:
        try:
            env = await _auth_me(token)
            user = ((env.get("data") or {}).get("user") or {}) if env.get("status") == 200 else {}
            me = str(user.get("id") or user.get("user_id") or "")
            if me:
                _note_session_answer(token, env)
                _token_user_put(token, me,
                                str(user.get("display_name") or user.get("name") or ""))
        except Exception:  # noqa: BLE001
            me = ""
    if not me:
        # No name, no routing.
        return Response(status_code=503)

    queue: asyncio.Queue = asyncio.Queue(maxsize=32)
    # a notice-reading tab says so; the session's role is kept for judging its reader
    queue.notices = x_hub_notices.strip() == "1"  # type: ignore[attr-defined]
    # a tab that draws the strip says so too; only it is sent hub frames
    queue.strip = x_hub_strip.strip() == "1"  # type: ignore[attr-defined]
    # whose session it is: Be Back ends it, and an acting tab never counts as the target online
    queue.token = token  # type: ignore[attr-defined]
    queue.acting = token in _acting  # type: ignore[attr-defined]
    if not queue.acting:  # type: ignore[attr-defined]
        _notice_who_put(me, str(hit[2]), _auth_master.get(token))
    _chat_subs.setdefault(me, set()).add(queue)

    async def stream():
        try:
            yield b": open\n\n"
            # the phase at once, so a reconnect never waits for the next change
            if queue.strip:  # type: ignore[attr-defined]
                yield f"data: {_hub_frame()}\n\n".encode()
            while True:
                try:
                    line = await asyncio.wait_for(queue.get(), timeout=25)
                except asyncio.TimeoutError:
                    # a tab that draws the strip is kept alive by the current hub frame: one dropped on a full queue…
                    if queue.strip:  # type: ignore[attr-defined]
                        yield f"data: {_hub_frame()}\n\n".encode()
                    else:
                        yield b": ping\n\n"
                    continue
                if line is _STREAM_END:
                    break    # the session behind it was revoked (Be Back)
                yield f"data: {line}\n\n".encode()
        finally:
            subs = _chat_subs.get(me)
            if subs is not None:
                subs.discard(queue)
                if not subs:
                    _chat_subs.pop(me, None)

    return StreamingResponse(
        stream(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-store",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )


# The host's own answer about itself, written by the host agent beside the other manifests.
HOST_STATUS_PATH = Path("/srv/manifests/host-status.json")
HOST_STATUS_MAX_AGE_S = 180


def _host_status() -> tuple[dict[str, Any] | None, float | None]:
    """(parsed status, age_s) — (None, age_s) when stale, (None, None) when the file is absent or unreadable."""
    try:
        age = round(time.time() - HOST_STATUS_PATH.stat().st_mtime, 1)
    except OSError:
        return None, None
    if age > HOST_STATUS_MAX_AGE_S:
        return None, age
    try:
        return json.loads(HOST_STATUS_PATH.read_text()), age
    except Exception:  # noqa: BLE001 — unreadable JSON is 'unknown', never green
        return None, age


# the keeper lane's vitals, cached — /health is polled by the container healthcheck, and three SELECTs per poll…
_SHEET_SYNC_HEALTH: dict[str, Any] = {"at": 0.0, "data": None}


def _sheet_sync_health() -> dict[str, Any] | None:
    """The sheets⇄Postgres keeper's own vitals — read by the Guardian card."""
    from datetime import datetime, timezone
    if time.time() - _SHEET_SYNC_HEALTH["at"] < 60:
        return _SHEET_SYNC_HEALTH["data"]
    data = None
    try:
        with psycopg2.connect(PG_DSN) as conn, conn.cursor(
            cursor_factory=psycopg2.extras.RealDictCursor
        ) as cur:
            cur.execute("select watermark, last_pass_at, last_pass_books,"
                        " last_pass_errors from hub_sheet_sync_state where id = 1")
            st = cur.fetchone() or {}
            cur.execute(
                "select count(*) filter (where last_sync_status = 'ok') as ok,"
                " count(*) filter (where last_sync_status = 'error') as err,"
                " count(*) filter (where last_sync_at > now() - interval '2 hours') as fresh_2h"
                " from asa_drive_sheets_meta")
            agg = cur.fetchone() or {}
            cur.execute(
                "select name, left(coalesce(last_sync_error, ''), 160) as error"
                " from asa_drive_sheets_meta where last_sync_status = 'error'"
                " order by last_sync_at desc limit 5")
            errs = cur.fetchall()
            cur.execute(
                "select extract(epoch from now() - max(ingested_at)) as age"
                " from asa_drive_sheets_rows"
                " where sheet_id = %s and tab_name = 'hub_sessions'",
                (HUB_DB_SHEET_ID,))
            sess = cur.fetchone() or {}
            got = hub_db.own(cur, "select count(*) as n from hub_session_vouch"
                                  " where seen_at > now() - interval '2 hours'")
            vouch = got[0] if got else {}
        pa = st.get("last_pass_at")
        if pa is not None and pa.tzinfo is None:
            pa = pa.replace(tzinfo=timezone.utc)
        data = {
            "last_pass_at": pa.isoformat() if pa else None,
            "last_pass_age_s": (round((datetime.now(timezone.utc) - pa).total_seconds())
                                if pa else None),
            "last_pass_books": int(st.get("last_pass_books") or 0),
            "last_pass_errors": int(st.get("last_pass_errors") or 0),
            "books_ok": int(agg.get("ok") or 0),
            "books_error": int(agg.get("err") or 0),
            "books_fresh_2h": int(agg.get("fresh_2h") or 0),
            "error_books": [dict(e) for e in errs],
            "session_mirror_age_s": (round(float(sess["age"]))
                                     if sess.get("age") is not None else None),
            "vouch_live_2h": int(vouch.get("n") or 0),
        }
    except Exception as exc:  # noqa: BLE001 — unknown, never green
        log.warning("sheet-sync health unavailable: %s", exc)
        data = None
    _SHEET_SYNC_HEALTH["at"] = time.time()
    _SHEET_SYNC_HEALTH["data"] = data
    return data


# the digester's vitals, cached like the keeper's — read by the Guardian
_FORM_DIGEST_HEALTH: dict[str, Any] = {"at": 0.0, "data": None}


def _form_digest_health() -> dict[str, Any] | None:
    """The digester's vitals, measured from the LEDGER itself (the engine does the work now — Digest.gs — so the…"""
    from datetime import datetime, timezone
    if time.time() - _FORM_DIGEST_HEALTH["at"] < 60:
        return _FORM_DIGEST_HEALTH["data"]
    data = None
    try:
        with psycopg2.connect(PG_DSN) as conn, conn.cursor(
            cursor_factory=psycopg2.extras.RealDictCursor
        ) as cur:
            cur.execute(
                "select data->>'Value' as v from asa_drive_sheets_rows"
                " where sheet_id = '1Y6UMJlCS5gHur52f0YrPsLSqwYlCA792I8gAiZsxsug'"
                "  and tab_name = 'Facts'"
                "  and data->>'Source' = 'switchboard:props.HUB_HOUSE_FORM_FILES_ID'"
                " order by row_number desc limit 1")
            row = cur.fetchone()
            house = str((row or {}).get("v") or "").strip()
            if not house:
                raise RuntimeError("no form_files house pointer in the mirror yet")
            cur.execute(
                "select coalesce(nullif(data->>'digest_state',''),'pending') as st,"
                " count(*) as n from asa_drive_sheets_rows"
                " where sheet_id = %s and tab_name = 'form_files'"
                " group by 1", (house,))
            counts = {r["st"]: int(r["n"]) for r in cur.fetchall()}
            cur.execute(
                "select min(data->>'createdAt') as oldest from asa_drive_sheets_rows"
                " where sheet_id = %s and tab_name = 'form_files'"
                "  and data->>'digest_state' = 'pending'", (house,))
            oldest = (cur.fetchone() or {}).get("oldest")
            cur.execute(
                "select left(coalesce(data->>'file_name',''),60) as file_name,"
                " left(coalesce(data->>'digest_error',''),160) as error"
                " from asa_drive_sheets_rows"
                " where sheet_id = %s and tab_name = 'form_files'"
                "  and data->>'digest_state' = 'error'"
                " order by row_number desc limit 5", (house,))
            errs = [dict(e) for e in cur.fetchall()]
        age = None
        if oldest:
            try:
                dt = datetime.fromisoformat(str(oldest).replace("Z", "+00:00"))
                age = round((datetime.now(timezone.utc) - dt).total_seconds())
            except Exception:  # noqa: BLE001
                age = None
        data = {"counts": counts, "oldest_pending_age_s": age,
                "error_items": errs, "engine": "Digest.gs via the service clock"}
    except Exception as exc:  # noqa: BLE001 — unknown, never green
        log.warning("form-digest health unavailable: %s", exc)
        data = None
    _FORM_DIGEST_HEALTH["at"] = time.time()
    _FORM_DIGEST_HEALTH["data"] = data
    return data


@app.get("/health")
async def health() -> dict[str, Any]:
    try:
        index = json.loads((OUT_DIR / "index.json").read_text())
    except Exception:  # noqa: BLE001
        index = {"slices": {}}
    slices = index.get("slices", {})
    host, host_age = _host_status()
    return {
        "ok": True,
        # who runs the six keepers: asa-hub-worker starts its own only once this says "worker"
        "keepers": "relay" if RELAY_KEEPERS else "worker",
        "manifest": len(load_manifest()),
        # what the number above LEAVES OUT, and why.
        "held_live": dict(_HELD_LIVE),
        # which read path is actually serving — the question "is the JSON lane on?" should never need a code read to…
        "bundle_lane": ("on" if BUNDLE_LANE else "off"),
        "bundle_dir": str(BUNDLE_DIR),
        "bundle_built_at": _LAST_BUNDLE["built_at"] or None,
        "bundle_resources": len(_LAST_BUNDLE["resources"] or {}),
        # the engine that last answered, the sweep lanes' failure streaks, and the refusals still being remembered…
        "engine_build": _ENGINE_BUILD or None,
        # the phase the tabs' strip is told (warming / engine / ready) and since when — for the Guardian and…
        "phase": _HUB_PHASE["phase"],
        "phase_since": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(_HUB_PHASE["since"])),
        "sweeps": dict(_SWEEP_FAILURES),
        # A STREAK IS NOT A DIAGNOSIS.
        "hotline": {**_HOTLINE_LAST,
                    "ever_run": _HOTLINE_LAST.get("at") is not None},
        # the hotline webhook's own door: armed or not, and its last filing
        "hotline_fast": _hotline_fast_health(),
        # live chat: counts only — refs, tickets, execs by action, the event feed to the hub
        "chat_live": _chat_live_health(),
        # the text inbox: its webhook key and the Quo pull's key in place or not, and whether the hand-off is stood…
        "quo_inbox": {**quo_inbox.health(), "pull_armed": bool(quo_pull._key())},
        # WHETHER THE PSIANYWHERE CHECK IS ARMED, AND NOTHING IT FOUND.
        "psi": (psi_anywhere.health() if psi_anywhere is not None
                else {"armed": False, "held": False, "credential": False}),
        "hopeless_adapters": sorted(_hopeless),
        "bundle": {
            "cursor": _BUNDLE_CURSOR.get("i") or 0,
            "budget_spent": {
                "count": _BUNDLE_BUDGET["overruns"],
                "age_s": (round(time.time() - _BUNDLE_BUDGET["at"], 1)
                          if _BUNDLE_BUDGET["at"] else None),
            },
        },
        "host": host,
        "host_age_s": host_age,
        "slices": len(slices),
        "failing": sorted(k for k, v in slices.items() if v.get("error")),
        "built_at": index.get("built_at"),
        "identity": "secret" if SERVICE_SECRET else ("session" if SERVICE_TOKEN else None),
        "resolver": {"declared": len(_resolver_table()), "traffic": _traffic_snapshot()},
        # the sheets⇄Postgres keeper — the Guardian's watch over the mirror
        "sheet_sync": _sheet_sync_health(),
        # the form-file digester — the Guardian's watch over the intake
        "form_digest": _form_digest_health(),
    }


# ------------------------------------------------------------------------ THE FILE FOLLOWS THE ROLE BADGE.
PLACE_BADGE_GATE = os.getenv("HUB_PLACE_BADGE_GATE", "0") == "1"
# resource -> the apps that read it, from the manifest. Filled on each /place.
_RESOURCE_APPS: dict[str, list[str]] = {}
_BADGE_RULES: dict[str, tuple[float, dict[str, list[str]]]] = {}


def _lab_open(hit: tuple) -> bool:
    """The lab's door obeys the role badge, like every app on the platform — access is decided by ROLE BADGE."""
    role = str((hit[2] if len(hit) > 2 else "") or "").lower()
    if role in ("admin", "administrator", "director", "manager"):
        return True
    uid = str((hit[3] if len(hit) > 3 else "") or "")
    rule = _badge_rules().get("digestlab")
    return bool(rule) and _badge_allows(rule, _badges_of(role, _user_badges(uid)))


def _badge_rules() -> dict[str, list[str]]:
    """appId -> the badges that may open it, from the master's own matrix."""
    hit = _BADGE_RULES.get("rules")
    if hit and time.time() - hit[0] < 60:
        return hit[1]
    out: dict[str, list[str]] = {}
    try:
        rows, _ = _rows_from_mirror("app_badge_access")
        for r in rows:
            app_id = str(r.get("app_id") or "").strip()
            if not app_id:
                continue
            out[app_id] = [b.strip().upper() for b in
                           str(r.get("badges") or "").split(",") if b.strip()]
    except Exception as exc:  # noqa: BLE001 — no matrix means no narrowing
        log.warning("badge matrix unavailable, the place file is not narrowed: %s", exc)
        return {}
    _BADGE_RULES["rules"] = (time.time(), out)
    return out


def _config_kv(tab: str) -> dict[str, str]:
    """A key/value configuration tab, read from the mirror."""
    out: dict[str, str] = {}
    try:
        rows, _ = _rows_from_mirror(tab)
        for r in rows:
            key = str(r.get("key") or "").strip()
            if key:
                out[key] = str(r.get("value") or "")
    except Exception as exc:  # noqa: BLE001 — absent config is not wrong config
        log.warning("config tab %s unavailable to the bang: %s", tab, exc)
    return out


def _ist_config_block(role: str) -> dict[str, Any] | None:
    """The relay's one IST copy — the gate's and the board's — as the bundle ships it (ist_config.bundle_block)."""
    try:
        ist_config.rules(PG_DSN)
    except Exception as exc:  # noqa: BLE001 — no copy is not a wrong copy
        log.warning("ist settings unavailable to the bundle: %s", exc)
        return None
    return ist_config.bundle_block(role)


def _shelf_rows() -> dict[str, Any]:
    """The sidebar's own shape — sections, placement and order, from the mirror."""
    out: dict[str, Any] = {"sections": [], "placement": {}, "order": {}}
    try:
        sec_rows, _ = _rows_from_mirror("app_sections")
        sections = []
        for i, r in enumerate(sec_rows):
            sid = str(r.get("section_id") or "").strip()
            if not sid:
                continue
            try:
                pos = float(r.get("position") or 0) or (i + 1)
            except (TypeError, ValueError):
                pos = i + 1
            sections.append({"id": sid, "label": str(r.get("label") or "") or sid,
                             "tint": str(r.get("tint") or "") or "blue",
                             "icon": str(r.get("icon") or ""), "position": pos})
        sections.sort(key=lambda s: s["position"])
        out["sections"] = sections

        pl_rows, _ = _rows_from_mirror("app_placement")
        ranked: dict[str, list[tuple[float, str]]] = {}
        for p, r in enumerate(pl_rows):
            app_id = str(r.get("app_id") or "").strip()
            sec_id = str(r.get("section_id") or "").strip()
            if not app_id or not sec_id:
                continue
            out["placement"][app_id] = sec_id          # last row wins
            try:
                at = float(r.get("position") or 0) or (p + 1)
            except (TypeError, ValueError):
                at = p + 1
            ranked.setdefault(sec_id, []).append((at, app_id))
        out["order"] = {k: [a for _at, a in sorted(v, key=lambda x: x[0])]
                        for k, v in ranked.items()}
    except Exception as exc:  # noqa: BLE001 — no shelf here means the live one answers
        log.warning("app shelf unavailable to the bang: %s", exc)
        return {"sections": [], "placement": {}, "order": {}}
    return out


# WHY THE VIEW CELLS TRAVEL RAW, AND ARE NOT DECODED HERE.
def _views_raw(cfg: dict[str, str], key: str) -> str:
    return str(cfg.get(key) or "")


_BUNDLE_ACCESS: dict[str, tuple[float, dict[str, list[str]]]] = {}


def _bundle_access(tab: str, key_field: str, value_field: str, upper: bool = False) -> dict[str, list[str]]:
    """One Core access matrix for the bang, read from the mirror without the drain gate."""
    hit = _BUNDLE_ACCESS.get(tab)
    if hit and time.time() - hit[0] < 60:
        return hit[1]
    out: dict[str, list[str]] = {}
    try:
        with psycopg2.connect(PG_DSN) as conn, conn.cursor() as cur:
            cur.execute(
                "select data from asa_drive_sheets_rows where sheet_id = %s and tab_name = %s order by row_number",
                (HUB_DB_SHEET_ID, tab),
            )
            rows = [r[0] for r in cur.fetchall()]
        for r in rows:
            if not isinstance(r, dict):
                continue
            key = str(r.get(key_field) or "").strip()
            if not key:
                continue
            words = [w.strip() for w in str(r.get(value_field) or "").split(",") if w.strip()]
            out[key] = [w.upper() for w in words] if upper else words
    except Exception as exc:  # noqa: BLE001 — an unread matrix is left out of the bang, never sent empty
        log.warning("bundle access %s unreadable: %s", tab, exc)
        return {}
    if out:
        _BUNDLE_ACCESS[tab] = (time.time(), out)
    return out


def _access_list(tab: str, key_field: str, value_field: str) -> dict[str, list[str]]:
    """key -> list-of-words for one access matrix tab, from the mirror."""
    out: dict[str, list[str]] = {}
    try:
        rows, _ = _rows_from_mirror(tab)
        for r in rows:
            key = str(r.get(key_field) or "").strip()
            if not key:
                continue
            out[key] = [w.strip() for w in str(r.get(value_field) or "").split(",") if w.strip()]
    except Exception as exc:  # noqa: BLE001 — an absent matrix narrows nothing
        log.warning("access matrix %s unavailable to the bang: %s", tab, exc)
    return out


def _badges_of(role: str, types: str | list[str] | None) -> set[str]:
    """What this person wears, as the matrix spells it: their badges AND their role, folded — the same fold…"""
    worn = set()
    if isinstance(types, str):
        worn |= {t.strip().upper() for t in types.split(",") if t.strip()}
    elif isinstance(types, list):
        worn |= {str(t).strip().upper() for t in types if str(t).strip()}
    if role:
        worn.add(str(role).strip().upper())
    return badge_follows.with_followed(worn)


def _badge_allows(rule: list[str] | None, worn: set[str]) -> bool:
    """No rule written is allowed — the master narrows by writing, never by omission."""
    if not rule:
        return True
    return any(b in worn for b in rule)


def _user_badges(uid: str) -> str:
    """The badge column of this person's row, from the mirror — no execution."""
    if not uid:
        return ""
    try:
        with psycopg2.connect(PG_DSN) as conn, conn.cursor(
                cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(
                "select data from asa_drive_sheets_rows "
                "where sheet_id = %s and tab_name = 'users' "
                "  and data->>'user_id' = %s limit 1",
                (HUB_DB_SHEET_ID, str(uid)),
            )
            row = cur.fetchone()
        # THE COLUMN IS `types`, and the vocabulary in it is the SAME one the matrix is written in — DIRECTOR…
        return str((row or {}).get("data", {}).get("types") or "")
    except Exception as exc:  # noqa: BLE001 — the role still answers
        log.warning("badge column unavailable for %s: %s", uid, exc)
        return ""


# uid -> (read at, the badges the hotline calendar gives them)
_CALENDAR_BADGES: dict[str, tuple[float, frozenset[str]]] = {}
# the only apps a badge worn by code opens; every other app reads the written badges alone
CALENDAR_BADGE_APPS = frozenset({"calendarbuilder", "shiftboard"})
CALENDAR_BADGES_TTL_S = float(os.getenv("HUB_CALENDAR_BADGES_TTL_S", "60"))


def _calendar_badges(uid: str) -> set[str]:
    """{'HM'} for a current ** manager, derived per read; a failed read wears nothing extra."""
    if not uid or not PG_DSN:
        return set()
    held = _CALENDAR_BADGES.get(uid)
    if held and time.time() - held[0] < CALENDAR_BADGES_TTL_S:
        return set(held[1])
    try:
        name = _roster_name_of(uid)
        worn = ({shift_requests.CALENDAR_BADGE}
                if name and shift_requests.houses_managed(PG_DSN, name) else set())
    except Exception as exc:  # noqa: BLE001 — the written badges still answer
        log.warning("calendar badge unavailable for %s (%s)", uid, type(exc).__name__)
        worn = set()
    _CALENDAR_BADGES[uid] = (time.time(), frozenset(worn))
    if len(_CALENDAR_BADGES) > 4000:          # a long-lived process, not a leak
        cutoff = time.time() - CALENDAR_BADGES_TTL_S
        for u, (at, _w) in list(_CALENDAR_BADGES.items()):
            if at < cutoff:
                _CALENDAR_BADGES.pop(u, None)
    return worn


def _apps_open(resource: str, role: str, worn: set[str],
               derived: set[str] | frozenset[str] = frozenset()) -> bool:
    """Does any app this person can open ask for this resource?"""
    rules = _badge_rules()
    apps = _RESOURCE_APPS.get(resource)
    if not apps:
        # Nothing declared.
        return True
    return any(_badge_allows(rules.get(a), (worn | derived) if a in CALENDAR_BADGE_APPS else worn)
               and _app_feeds(a, role, worn, resource) for a in apps)


# resource -> {app: page gates}, only when every page reading it is gated; None for an older manifest
_RESOURCE_GATES: dict[str, dict[str, list[str]] | None] = {}
# with an older manifest Calendar Builder keeps its old rule, so nothing widens
CALENDAR_BUILDER_APP = "calendarbuilder"


def _note_gates(entry: dict[str, Any]) -> None:
    gates = entry.get("gates")
    _RESOURCE_GATES[str(entry.get("resource") or "")] = gates if isinstance(gates, dict) else None


# a gated page's estate-wide slices go only to readers who edit every house; ungated pages follow the matrix
def _app_feeds(app: str, role: str, worn: set[str], resource: str = "") -> bool:
    """May this app hand this reader this resource?"""
    gates = _RESOURCE_GATES.get(resource)
    gated = (app == CALENDAR_BUILDER_APP) if gates is None else bool(gates.get(app))
    if not gated:
        return True
    if "no-client" in ((gates or {}).get(app) or []) \
            and str(role or "").strip().lower() not in shift_requests.CALENDAR_REFUSED_ROLES:
        return True
    return bool(worn & shift_requests.REASON_BADGES) \
        or str(role or "").strip().lower() in shift_requests.CALENDAR_EDIT_ROLES


PLACE_MEMBERS_TAB = "platform_members"
# the depot (Essencial) and its switchboard rows that move the member rows into their own house (hubTabSheet_)
ESSENCIAL_SHEET_ID = os.getenv("HUB_ESSENCIAL_SHEET_ID", "1Y6UMJlCS5gHur52f0YrPsLSqwYlCA792I8gAiZsxsug")
PLACE_MEMBERS_HOUSE = "switchboard:props.HUB_HOUSE_PLATFORM_MEMBERS_ID"
PLACE_MEMBERS_MOVED = "switchboard:moved." + PLACE_MEMBERS_TAB


def _place_members(cur: Any, rows: Callable[..., list[dict]]) -> list[dict]:
    """The member rows where they live (hubTabSheet_): the house the depot names once the tab is moved — its own tab,
    else its Data tab — else HUB_DB's tab."""
    cur.execute("select data->>'Source' as source, data->>'Value' as value from asa_drive_sheets_rows"
                " where sheet_id = %s and tab_name = 'Facts' and data->>'Source' in (%s, %s) order by row_number",
                (ESSENCIAL_SHEET_ID, PLACE_MEMBERS_HOUSE, PLACE_MEMBERS_MOVED))
    said = {str(r["source"]): str(r["value"] or "").strip() for r in cur.fetchall()}
    house = said.get(PLACE_MEMBERS_HOUSE, "")
    if house and said.get(PLACE_MEMBERS_MOVED, "").lower() in ("on", "true", "1", "yes"):
        return rows(PLACE_MEMBERS_TAB, house) or rows("Data", house)
    return rows(PLACE_MEMBERS_TAB)


def _place_reach(uid: str) -> dict[str, set[str]]:
    """Which worlds and which company faces this ACCOUNT may be handed."""
    worlds: set[str] = set()
    tenants: set[str] = set()
    # THE PEOPLE THIS ACCOUNT MAY STAND IN, and the role each of them wears.
    members: set[str] = set()
    member_roles: dict[str, str] = {}
    if not uid:
        return {"worlds": worlds, "tenants": tenants, "members": members, "roles": member_roles}
    try:
        with psycopg2.connect(PG_DSN) as conn, conn.cursor(
            cursor_factory=psycopg2.extras.RealDictCursor
        ) as cur:
            def rows(tab: str, sheet_id: str = HUB_DB_SHEET_ID) -> list[dict]:
                cur.execute(
                    "select data from asa_drive_sheets_rows "
                    "where sheet_id = %s and tab_name = %s",
                    (sheet_id, tab),
                )
                return [r["data"] for r in cur.fetchall()]

            # my own world, as My World's registry names it (never a sheet)
            worlds |= {w for w, o in _WORLD_OWNERS.items() if o == uid}
            # and the world of anybody who left their door open to me — the SAME condition World.gs enforces: an…
            members = _place_members(cur, rows)
            owned_ids = {str(m.get("member_user_id") or "") for m in members
                         if str(m.get("owner_user_id") or "") == uid
                         and str(m.get("status") or "") == "active"
                         and str(m.get("scope") or "") in ("", "work_world")}
            members |= owned_ids
            if owned_ids:
                worlds |= {w for w, o in _WORLD_OWNERS.items() if o in owned_ids}
                for u in rows("users"):
                    if str(u.get("user_id") or "") in owned_ids:
                        member_roles[str(u.get("user_id"))] = str(u.get("role") or "")
            # the company faces: home plus whatever the additive columns name
            for u in rows("users"):
                if str(u.get("user_id") or "") != uid:
                    continue
                home = str(u.get("home_tenant") or "").strip()
                if home:
                    tenants.add(home)
                for t in str(u.get("tenant_ids") or "").replace(";", ",").split(","):
                    if t.strip():
                        tenants.add(t.strip())
                break
    except Exception as exc:  # noqa: BLE001 — mirror down: no place, no bundle
        log.warning("place reach unavailable: %s", exc)
    worlds.discard("")
    members.discard("")
    return {"worlds": worlds, "tenants": tenants, "members": members, "roles": member_roles}


@app.get("/place")
async def place_bundle(
    world: str = "",
    tenant: str = "",
    member: str = "",
    tab: str = "",
    authorization: str = Header(default=""),
) -> Response:
    """THE JSON LANE, FOR THE PLACE THE CALLER IS STANDING IN."""
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    hit = _auth_cache.get(token) if token else None
    if not hit or not hit[1] or time.time() - hit[0] >= AUTH_TTL_SECONDS:
        return Response(status_code=401)
    uid = hit[3] if len(hit) > 3 else ""
    if not uid:
        return Response(status_code=404)   # cannot name the caller: no place

    # THE PERSON THE CALLER IS STANDING IN.
    visited_role = ""
    if member:
        reach = await asyncio.to_thread(_place_reach, uid)
        if member not in reach.get("members", set()):
            return Response(status_code=404)
        visited_role = str((reach.get("roles") or {}).get(member) or "")
        # a person whose role the mirror cannot name is not narrowed by guesswork — the live path stays, as…
        if not visited_role:
            return Response(status_code=404)
        name = "home.json"
    elif world:
        # a world kept from this session is a place with no bundle, as for a world never opened
        if _world_withheld(uid, _auth_master.get(token)):
            return Response(status_code=404)
        reach = await asyncio.to_thread(_place_reach, uid)
        if world not in reach["worlds"]:
            return Response(status_code=404)
        name = f"world_{world}.json"
    elif tenant:
        reach = await asyncio.to_thread(_place_reach, uid)
        if tenant not in reach["tenants"]:
            return Response(status_code=404)
        name = f"ten_{tenant}.json"
    else:
        name = "home.json"
    # a place is a file of the deposit's own folder, never one below it
    if "/" in name + (member or uid):
        return Response(status_code=404)

    # ONE TAB, FOR A SCREEN THAT CANNOT GET ITS ANSWER ANY OTHER WAY.
    if tab:
        if not re.fullmatch(r"[A-Za-z0-9_]{1,64}", tab):
            return Response(status_code=400)
        role = visited_role or (hit[2] if len(hit) > 2 else "")
        badges_worn = _badges_of(role, _user_badges(member or uid))
        badges_derived = _calendar_badges(member or uid)

        # THE PERSONAL HALF IS READ BEFORE THE GATE, because the gate is not about it (review).
        cut: dict[str, Any] | None = None
        if not world and not tenant:
            whose = member or uid
            try:
                mine = json.loads((BUNDLE_DIR / f"home~{whose}.json").read_text())
                rows_ = (mine.get("resources") or {}).get(tab)
                if isinstance(rows_, list):
                    cut = {"state": "rows", "rows": rows_, "count": len(rows_),
                           "bytes": 0, "built_at": str(mine.get("built_at") or ""),
                           "read_started_at": str(mine.get("read_started_at") or ""),
                           "unreadable": mine.get("unreadable"), "carried": None}
            except Exception:  # noqa: BLE001 — nothing of their own: the gate decides
                cut = None

        # THE SAME GATE THE WHOLE-FILE ANSWER KEEPS, asked about one resource.
        withheld_answer = Response(
            json.dumps({"place": world or tenant or "home", "resource": tab,
                        "state": "withheld", "source": "deposit"}),
            status_code=403, media_type="application/json")
        entry = next((e for e in load_manifest()
                      if str(e.get("resource") or "") == tab), None)
        if cut is None:
            if entry is None:
                return withheld_answer
            roles = entry.get("roles") or []
            if roles and role not in roles:
                return withheld_answer
            if PLACE_BADGE_GATE:
                # THE BADGE MATRIX IS ASKED WITH ITS ANSWER IN HAND (review).
                _RESOURCE_APPS[tab] = entry.get("apps") or []
                _note_gates(entry)
                if not _apps_open(tab, role, badges_worn, badges_derived):
                    return withheld_answer
            cut = await asyncio.to_thread(_deposit_tab_memo, BUNDLE_DIR / name, tab)

            # AND THE LANE THAT OWNS THE SLICE ANSWERS FOR IT — the rule the whole-file path keeps, which this…
            if cut.get("state") in ("rows", "absent", "too-large"):
                derived = bool(entry and entry.get("mode") == "derived")
                if derived or not cut.get("rows"):
                    ours = _read_slice_file(tab)
                    if ours is not None and isinstance(ours.get("rows"), list):
                        cut = {"state": "rows", "rows": ours["rows"],
                               "count": len(ours["rows"]), "bytes": 0,
                               "built_at": str(ours.get("built_at") or ""),
                               "read_started_at": str(ours.get("source_at") or ""),
                               "unreadable": None, "carried": False,
                               "source": "slice"}

        age = _deposit_age_s(str(cut.get("built_at") or ""))
        answer: dict[str, Any] = {
            "place": world or tenant or "home",
            "resource": tab,
            # WHICH FILE ACTUALLY ANSWERED.
            "source": str(cut.get("source") or "deposit"),
            "state": cut["state"],
            "built_at": cut.get("built_at") or "",
            "read_started_at": cut.get("read_started_at") or "",
            "age_s": None if age is None else round(age, 1),
            # THE LINE A SCREEN JUDGES AGE BY, sent with the answer rather than spelled again in the browser: the…
            "max_age_s": BUNDLE_MAX_AGE_S,
            "stale": None if age is None else age > BUNDLE_MAX_AGE_S,
            "bytes": cut.get("bytes") or 0,
        }
        # The books THIS build could not open, carried through: a deposit that was read with a book missing must be…
        if isinstance(cut.get("unreadable"), list):
            answer["deposit_unreadable"] = cut["unreadable"]
        # WHETHER `age_s` IS THE AGE OF THE ROWS OR ONLY OF THE BUILD.
        if isinstance(cut.get("carried"), bool):
            answer["carried"] = cut["carried"]
        if cut["state"] == "rows":
            answer["rows"] = cut["rows"]
            answer["count"] = cut["count"]
        _traffic_note("slice_reads")
        # 200 for every answer the deposit itself gave — including "I do not carry that tab", which is an answer and…
        return Response(json.dumps(answer), media_type="application/json")

    try:
        payload = json.loads((BUNDLE_DIR / name).read_text())
    except Exception:  # noqa: BLE001 — no bundle for this place yet
        return Response(status_code=404)

    # THE PERSONAL HALF RIDES ALONG at home: `home~<uid>.json` holds the rows owned by this person.
    own: dict[str, list] = {}
    if not world and not tenant:
        whose = member or uid
        try:
            mine = json.loads((BUNDLE_DIR / f"home~{whose}.json").read_text())
            for k, v in (mine.get("resources") or {}).items():
                if isinstance(v, list):
                    own[k] = v
        except Exception:  # noqa: BLE001 — nothing of their own yet
            own = {}

 # THE SAME ROLE FILTER THE SINGLE-SLICE PATH KEEPS.
    role = visited_role or (hit[2] if len(hit) > 2 else "")
 # THE BADGES TOO, NOT JUST THE ROLE (review).
    badges_worn = _badges_of(role, _user_badges(member or uid))
    badges_derived = _calendar_badges(member or uid)
    withheld: list[str] = []
    allowed: dict[str, list[str]] = {}
 # THE ONES THIS SERVICE BUILDS ITSELF (found the minute bundle started carrying them).
    mine_to_build: set[str] = set()
    _RESOURCE_APPS.clear()
    _RESOURCE_GATES.clear()
    for entry in load_manifest():
        allowed[str(entry.get("resource") or "")] = entry.get("roles") or []
        _RESOURCE_APPS[str(entry.get("resource") or "")] = entry.get("apps") or []
        _note_gates(entry)
        if entry.get("mode") == "derived":
            mine_to_build.add(str(entry.get("resource") or ""))
    out = {"built_at": payload.get("built_at") or "", "slices": {}}
    shadow: list[str] = []
    for resource, rows_ in (payload.get("resources") or {}).items():
        if not isinstance(rows_, list):
            continue
        roles = allowed.get(resource)
        # A resource the manifest does not describe is not served here.
        if roles is None or (roles and role not in roles):
            continue
        # FEED EACH APP WITH WHAT IT NEEDS — the strategy is to hand every app exactly the data it needs, and…
        if PLACE_BADGE_GATE and not _apps_open(resource, role, badges_worn, badges_derived):
            withheld.append(resource)
            continue
        if not PLACE_BADGE_GATE and not _apps_open(resource, role, badges_worn, badges_derived):
            # THE SWITCH IS OFF, SO NOTHING IS WITHHELD — but the decision is taken and written down, so the change…
            shadow.append(resource)
        out["slices"][resource] = {"rows": rows_, "built_at": out["built_at"]}
    if shadow or withheld:
        log.info("place %s (%s): %d resource(s) %s by the badge matrix — %s",
                 (world or tenant or "home"), role or "?",
                 len(withheld or shadow), "withheld" if withheld else "would be withheld",
                 ", ".join(sorted(withheld or shadow)[:10]))

    # AND NOW THE PERSONAL HALF, PAST THE GATE THAT IS NOT ABOUT IT.
    for resource, rows_ in own.items():
        out["slices"][resource] = {"rows": rows_, "built_at": out["built_at"]}

 # WHAT THE BUNDLE DOES NOT CARRY, THIS SERVICE ALREADY HAS.
    for entry in load_manifest():
        resource = str(entry.get("resource") or "")
        if not resource:
            continue
        roles = entry.get("roles") or []
        if roles and role not in roles:
            continue
        held = out["slices"].get(resource)
        mine = _read_slice_file(resource)
        if mine is None:
            continue
        # the bundle's copy stands only when this service has none
        if held is None or not held.get("rows") or resource in mine_to_build:
            out["slices"][resource] = mine
    _traffic_note("slice_reads")
    return Response(json.dumps(out), media_type="application/json")


def _read_slice_file(resource: str) -> dict[str, Any] | None:
    """One built slice off this service's own disk, or None."""
    try:
        return json.loads((OUT_DIR / f"{resource}.json").read_text())
    except Exception:  # noqa: BLE001 — never built, or being written right now
        return None


@app.post("/digest/try")
async def digest_try(request: Request, authorization: str = Header(default="")) -> dict[str, Any]:
    """THE LABORATORY — one document, both readings, and nothing moved."""
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    hit = _auth_cache.get(token) if token else None
    if not hit or not hit[1] or time.time() - hit[0] >= AUTH_TTL_SECONDS:
        return {"status": 401, "message": "sign in again"}
    if not _lab_open(hit):
        return {"status": 403, "message": "the decoder lab is for admins and managers"}

    body = await request.json() if await request.body() else {}
    file_id = str(body.get("file_id") or "").strip()
    name = str(body.get("file_name") or "document").strip()
    if not file_id:
        return {"status": 400, "message": "file_id is required"}

    # the reading itself is lab_try.py's, shared with asa-hub-worker's Try (hub_worker.py)
    def work() -> dict[str, Any]:
        import lab_try  # noqa: PLC0415
        return lab_try.read(file_id, name)

    try:
        return await asyncio.to_thread(work)
    except Exception as exc:  # noqa: BLE001 — a lab that throws says why
        log.warning("digest/try failed on %s: %s", file_id, exc)
        return {"status": 500, "message": f"{type(exc).__name__}: {str(exc)[:200]}"}


# the Decoder lab under BACKEND PER APP: its proposals, its teach and its shelf asked of Python first (its Try stays here)
DIGEST_APP = "digestlab"


async def _digest_python(action: str, payload: dict[str, Any], authorization: str, write: bool) -> dict | None:
    """The lab's door asked of Python while Settings › Back-end per app gives it the Decoder lab; None: answered here."""
    if not await _backend_wanted(DIGEST_APP):
        return None
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    raw = urllib.parse.urlencode({"body": json.dumps({"token": token, "action": action, "payload": payload})}).encode()
    if write:
        decided, _raw = await _backend_write(action, raw)
        return None if decided is None else json.loads(decided.body)
    got = await _backend_answer(action, raw)
    return None if got is None else json.loads(got[0].content)


def _digest_landed(answer: dict[str, Any]) -> dict[str, Any]:
    """The lab wrote here (Google), not in Python: Python's copy read before it is behind."""
    if isinstance(answer, dict) and answer.get("status") == 200:
        _app_pack_swept[DIGEST_APP] = time.time()
    return answer


def _lab_gate(authorization: str) -> tuple[dict | None, tuple | None]:
    """The lab's door, shared by its routes: a real session, and the badge."""
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    hit = _auth_cache.get(token) if token else None
    if not hit or not hit[1] or time.time() - hit[0] >= AUTH_TTL_SECONDS:
        return {"status": 401, "message": "sign in again"}, None
    if not _lab_open(hit):
        return {"status": 403, "message": "the decoder lab is for admins and managers"}, None
    return None, hit


@app.get("/digest/proposals")
async def digest_proposals_list(request: Request, authorization: str = Header(default="")) -> dict[str, Any]:
    """WHAT THE READINGS TAUGHT — deterministically."""
    refused, hit = _lab_gate(authorization)
    if refused:
        return refused
    scan_now = str(request.query_params.get("scan") or "") == "1"
    py = await _digest_python("digestScan" if scan_now else "digestProposals", {}, authorization, write=scan_now)
    if py is not None:
        return py

    def work() -> dict[str, Any]:
        import digest_proposals as dp
        import form_digest as fd
        _, sheets = fd._clients()
        summary = dp.scan(sheets, PG_DSN) if scan_now else None
        have = dp.existing(sheets)
        kinds = dp.known_kinds(sheets)
        _, cats = dp.read_tab(sheets, "Digest Categories")
        rows = list(have.values())
        order = {"proposed": 0, "approved": 1, "rejected": 2}
        rows.sort(key=lambda r: (order.get(r.get("status", ""), 9), r.get("created_at", "")), reverse=False)
        rows.sort(key=lambda r: order.get(r.get("status", ""), 9))
        return {"status": 200, "proposals": rows[:200],
                "kinds": sorted(kinds.keys()),
                "categories": [c.get("category") for c in cats if c.get("category")],
                "scan": summary}
    try:
        got = await asyncio.to_thread(work)
        return _digest_landed(got) if scan_now else got
    except Exception as exc:  # noqa: BLE001
        log.warning("digest/proposals failed: %s", exc)
        return {"status": 500, "message": f"{type(exc).__name__}: {str(exc)[:160]}"}


@app.post("/digest/proposals/decide")
async def digest_proposals_decide(request: Request, authorization: str = Header(default="")) -> dict[str, Any]:
    """Approve = one row in Digest Kinds (the engine reads it within ten minutes, this lane on its next pass…"""
    refused, hit = _lab_gate(authorization)
    if refused:
        return refused
    body = await request.json() if await request.body() else {}
    pid = str(body.get("id") or "").strip()
    action = str(body.get("action") or "").strip().lower()
    category = str(body.get("category") or "").strip()
    if not pid or action not in ("approve", "reject"):
        return {"status": 400, "message": "id and action (approve|reject) are required"}
    # Approving or rejecting edits the live kinds table and the live proposals tab, and can create a whole new tab…
    _decide_gate = lane_gate.holds(lane_gate.DIGEST)
    if _decide_gate["held"]:
        return lane_gate.refused(_decide_gate["why"])
    who = str((hit[3] if len(hit) > 3 else "") or "") or "lab"
    py = await _digest_python("digestDecide", {"id": pid, "action": action, "category": category}, authorization, True)
    if py is not None:
        return py

    def work() -> dict[str, Any]:
        import digest_proposals as dp
        import form_digest as fd
        _, sheets = fd._clients()
        return dp.decide(sheets, pid, action, who, category)
    try:
        return _digest_landed(await asyncio.to_thread(work))
    except Exception as exc:  # noqa: BLE001
        log.warning("digest/proposals/decide failed: %s", exc)
        return {"status": 500, "message": f"{type(exc).__name__}: {str(exc)[:160]}"}


@app.post("/digest/teach")
async def digest_teach(request: Request, authorization: str = Header(default="")) -> dict[str, Any]:
    """A PERSON CORRECTS ONE PAPER, AND THE FAMILY LEARNS."""
    refused, hit = _lab_gate(authorization)
    if refused:
        return refused
    body = await request.json() if await request.body() else {}
    ledger = str(body.get("ledger") or "client_files").strip()
    rid = str(body.get("row_id") or "").strip()
    kind = str(body.get("kind") or "").strip()
    if not rid or not kind:
        return {"status": 400, "message": "row_id and kind are required"}
    # A teach pressed during a rehearsal permanently seals a real row in a real book (`final`), and writes the words…
    _teach_gate = lane_gate.holds(lane_gate.DIGEST)
    if _teach_gate["held"]:
        return lane_gate.refused(_teach_gate["why"])
    who = str((hit[3] if len(hit) > 3 else "") or "") or "lab"
    py = await _digest_python("digestTeach", {"ledger": ledger, "row_id": rid, "kind": kind}, authorization, True)
    if py is not None:
        return py

    def work() -> dict[str, Any]:
        import json as _j
        import digest_proposals as dp
        import form_digest as fd
        if ledger not in dp.LEDGERS:
            return {"status": 400, "message": "unknown ledger"}
        _, sheets = fd._clients()
        rows = dp.rows_from_mirror(PG_DSN, ledger)
        row = next((r for r in rows if r["id"] == rid), None)
        if not row:
            return {"status": 404, "message": "row not in the mirror yet"}
        kinds = dp.known_kinds(sheets)
        prop = dp.teach(row, kind, rows, kinds, ledger)
        wrote = dp.write(sheets, [prop]) if prop else 0
        # the row itself: the kind the person chose, sealed against the retry
        led = next(L for L in fd.LEDGERS if L["tab"] == ledger)
        house = fd._house_id(led["ptr"])
        grid = sheets.spreadsheets().values().get(
            spreadsheetId=house, range=f"{ledger}!A1:BZ6000").execute().get("values") or []
        head = [str(h).strip() for h in grid[0]]
        ii, ki, ji = head.index("id"), head.index("doc_kind"), head.index("digest_json")
        for n, line in enumerate(grid[1:], start=2):
            if ii < len(line) and line[ii] == rid:
                try:
                    meta = _j.loads(line[ji] if ji < len(line) and line[ji] else "{}")
                except Exception:  # noqa: BLE001
                    meta = {}
                if not isinstance(meta, dict):
                    meta = {}
                meta.update({"taught": who, "taught_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                             "taught_kind": dp._snake(kind), "final": True})
                sheets.spreadsheets().values().batchUpdate(
                    spreadsheetId=house,
                    body={"valueInputOption": "RAW", "data": [
                        {"range": f"{ledger}!{fd._a1_col(ki + 1)}{n}", "values": [[dp._snake(kind)]]},
                        {"range": f"{ledger}!{fd._a1_col(ji + 1)}{n}", "values": [[_j.dumps(meta)]]}]}).execute()
                break
        return {"status": 200, "filed": dp._snake(kind), "proposal": prop, "written": wrote}
    try:
        return _digest_landed(await asyncio.to_thread(work))
    except Exception as exc:  # noqa: BLE001
        log.warning("digest/teach failed: %s", exc)
        return {"status": 500, "message": f"{type(exc).__name__}: {str(exc)[:160]}"}


@app.get("/digest/shelf")
async def digest_shelf(request: Request, authorization: str = Header(default="")) -> dict[str, Any]:
    """THE SHELF — everything this platform has already filed, as folders."""
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    hit = _auth_cache.get(token) if token else None
    if not hit or not hit[1] or time.time() - hit[0] >= AUTH_TTL_SECONDS:
        return {"status": 401, "message": "sign in again"}
    if not _lab_open(hit):
        return {"status": 403, "message": "the decoder lab is for admins and managers"}

    folder = str(request.query_params.get("folder") or "").strip()
    q = str(request.query_params.get("q") or "").strip().lower()
    limit = max(1, min(int(request.query_params.get("limit") or 200), 500))
    py = await _digest_python("digestShelf", {"folder": folder, "q": q, "limit": limit}, authorization, False)
    if py is not None:
        return py

    LEDGERS_UI = [
        ("client_files", "1o7opeC1GR3J5Oj7iGEgYo0EKLPmkW_paGBtE8uMx3LY", "title", "drive_id"),
        ("form_files", "19OvLdtyF0iENHcesFFm_6DyGjnqTfrjStAQJjiyh6Ww", "file_name", "file_id"),
    ]

    def work() -> dict[str, Any]:
        import json as _j
        import psycopg2.extras as _extras
        folders: dict[str, int] = {}
        special = {"· read by the decoder": 0, "· it could not read": 0, "· still owes something": 0}
        files: list[dict[str, Any]] = []
        # psycopg2.connect(PG_DSN) is how every other reader in this file opens the mirror — there is no _pg() here…
        with psycopg2.connect(PG_DSN) as conn, \
                conn.cursor(cursor_factory=_extras.RealDictCursor) as cur:
            for tab, sheet, name_col, id_col in LEDGERS_UI:
                cur.execute(
                    "select data from asa_drive_sheets_rows"
                    " where sheet_id = %s and tab_name = %s order by row_number desc",
                    (sheet, tab))
                for rec in cur.fetchall():
                    row = rec["data"] if isinstance(rec["data"], dict) else {}
                    name = str(row.get(name_col) or "")
                    if not name:
                        continue
                    state = str(row.get("digest_state") or "")
                    meta = row.get("digest_json") or ""
                    if isinstance(meta, str):
                        try:
                            meta = _j.loads(meta or "{}")
                        except Exception:  # noqa: BLE001
                            meta = {}
                    missing = (meta or {}).get("missing") or []
                    fold = str(row.get("folder") or "").strip() or (
                        "Form uploads" if tab == "form_files" else "(no folder)")
                    folders[fold] = folders.get(fold, 0) + 1
                    if state == "done":
                        special["· read by the decoder"] += 1
                    if state in ("empty", "unsupported", "stalled"):
                        special["· it could not read"] += 1
                    if missing:
                        special["· still owes something"] += 1
                    if folder:
                        keep = (fold == folder
                                or (folder == "· read by the decoder" and state == "done")
                                or (folder == "· it could not read"
                                    and state in ("empty", "unsupported", "stalled"))
                                or (folder == "· still owes something" and missing))
                        if not keep:
                            continue
                    elif not q:
                        continue
                    if q and q not in name.lower() and q not in str(row.get("person") or "").lower():
                        continue
                    if len(files) < limit:
                        files.append({
                            "id": str(row.get("id") or ""), "name": name, "folder": fold,
                            "ledger": tab, "file_id": str(row.get(id_col) or ""),
                            "doc_kind": str(row.get("doc_kind") or ""),
                            "person": str(row.get("person") or ""),
                            "state": state,
                            "confidence": str(row.get("confidence") or ""),
                            "missing": missing,
                            "decoder": str((meta or {}).get("v") or ""),
                        })
        shelf = [{"name": k, "count": v} for k, v in sorted(
            folders.items(), key=lambda kv: (-kv[1], kv[0]))]
        return {"status": 200, "folders": shelf,
                "special": [{"name": k, "count": v} for k, v in special.items()],
                "files": files, "total": sum(folders.values())}

    try:
        return await asyncio.to_thread(work)
    except Exception as exc:  # noqa: BLE001
        log.warning("digest/shelf failed: %s", exc)
        return {"status": 500, "message": f"{type(exc).__name__}: {str(exc)[:200]}"}


