@app.get("/bundle")
async def bundle(authorization: str = Header(default="")) -> Response:
    """THE BANG: the whole site's data in ONE json."""
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    hit = _auth_cache.get(token) if token else None
    if not hit or not hit[1] or time.time() - hit[0] >= AUTH_TTL_SECONDS:
        return Response(status_code=401)
    role = hit[2]
    out: dict[str, Any] = {"built_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "slices": {}}
    # THE THREE ACCESS MATRICES RIDE THE BANG — the JSON with all the information is right there and was going unused.
    master_flag = _auth_master.get(token)
    uid = str(hit[3] or "").strip() if len(hit) > 3 else ""
    app_cut = frozenset() if master_flag is True or (uid and uid in _lane_app_seen()) else _lane_app_cut()
    withhold = bool(app_cut) and master_flag is None
    access = {
        "badges": {} if withhold else _app_cut_map(
            _bundle_access("app_badge_access", "app_id", "badges", upper=True), app_cut),
        "tenants": {} if withhold else _app_cut_map(_bundle_access("app_tenant_access", "app_id", "tenants"), app_cut),
        "sections": _bundle_access("config_badge_access", "section_id", "badges"),
    }
    access = {k: v for k, v in access.items() if v}
    if access:
        out["access"] = access
    log.info("bundle access: badges=%d tenants=%d sections=%d",
             len(access.get("badges", {})), len(access.get("tenants", {})), len(access.get("sections", {})))
    # THE CONFIGURATION A SCREEN NEEDS BEFORE IT CAN DRAW.
    lane = _config_lane_for("")
    cfg = _config_kv("hiring_alerts_config")
    out["config"] = {
        "shelf": _app_cut_shelf((lane or {}).get("shelf") or _shelf_rows(),
                                app_cut if master_flag is False else frozenset()),
        "source": "backend" if lane else "mirror",
    }
    for key in ("hiringViews", "clientViews", "potClientsViews", "menuLinks", "appsBuilt"):
        if lane and isinstance(lane.get(key), dict):
            out["config"][key] = lane[key]
    if role == "admin":
        # THE CELLS, AND ONLY THE CELLS — never a stand-in for hiringAlertsGet.
        out["config"]["alertsRaw"] = {k: v for k, v in cfg.items() if not str(k).startswith("mywork_")}
    # the IST settings ride for every role: the compliance screens any role opens draw with them
    ist_block = _ist_config_block(role)
    if ist_block:
        out["config"]["ist"] = ist_block
    for entry in load_manifest():
        roles = entry.get("roles") or []
        if roles and role not in roles:
            continue
        try:
            out["slices"][entry["resource"]] = json.loads((OUT_DIR / f"{entry['resource']}.json").read_text())
        except Exception:  # noqa: BLE001 — a missing slice is simply not in the bang
            continue
    return Response(json.dumps(out), media_type="application/json")


# THE BROWSER'S /gas: doPost's own answer to an action no door takes.
RELAY_UNKNOWN_ACTION = {"status": 404, "message": "Unknown action."}


def _relay_observe_auth(raw: bytes, content: bytes) -> None:
    """The relay just carried an auth action — the GATE learns from it."""
    try:
        if b"auth" not in raw[:2048]:
            return
        body = urllib.parse.parse_qs(raw.decode("utf-8", "ignore")).get("body", [""])[0]
        if not body:
            return
        req = json.loads(body)
        action = str(req.get("action") or "")
        if action not in ("authLogin", "authMe", "authLogout", "authBootstrap"):
            return
        if action == "authLogout":
            token = str(req.get("token") or "")
            if token:
                # whose session it was, read before the refusal below forgets it
                prior = _auth_cache.get(token)
                uid = str(prior[3] or "") if prior and len(prior) > 3 else ""
                uid = uid or _token_user_get(token)
                _auth_cache_put(token, False, "")
                # the acting sessions die with the session that started them (BeAnother.gs)
                _be_another_signed_out(token, uid)
                # and its live chat connections with it
                _chat_live_revoke(token)
            return
        env = json.loads(content)
        if env.get("status") != 200:
            return
        data = env.get("data") or {}
        user = data.get("user") or {}
        token = str(data.get("token") or req.get("token") or "")
        if token and user:
            # first: whether this token is an acting session (Be Another) decides what the rest may do
            _note_session_answer(token, env)
            _auth_cache_put(token, True, str(user.get("role") or ""),
                            str(user.get("id") or user.get("user_id") or ""),
                            is_master=(bool(user.get("is_master")) if "is_master" in user else None))
            # The chat stream needs a NAME to route to, and this is where the relay learns one for free — the SPA…
            _token_user_put(token, str(user.get("id") or user.get("user_id") or ""),
                            str(user.get("display_name") or user.get("name") or ""))
    except Exception:  # noqa: BLE001 — observation is a bonus, never a failure mode
        pass


