# and on the generic lane (BE_ANOTHER_REFUSED_RESOURCES): a write here is the person's own signature
ACTING_REFUSED_RESOURCES: dict[str, str] = {
    "policyAcks": "acknowledging a policy in their name",
    "marEntries": "signing a medication record in their name",
}


def _acting_refusal(raw: bytes) -> dict[str, Any] | None:
    """beAnotherPolicyGate_ / beAnotherResourceGate_ for this envelope, whatever its size; None to carry it on."""
    if not _acting:
        return None
    env = _master_guard_envelope(raw, ("token",))
    token = str(env.get("token") or "")
    if not token or not _my_work_acting(token):
        return None
    action = str(env.get("action") or "")
    # the chat's own path answers a switched session already (_chat_python_ask), in the words the page reads
    if action in CHAT_PYTHON_ACTIONS:
        return None
    what = ACTING_REFUSED.get(action)
    if what is None and action in ("create", "update", "delete"):
        what = ACTING_REFUSED_RESOURCES.get(str(env.get("resource") or ""))
    if what is None:
        return None
    name = str((_token_user.get(token) or (0.0, "", ""))[2] or "").strip() or "another account"
    return {"status": 409, "code": "be_another_refused",
            "message": f"Not while acting as {name}: {what}. Press Be Back to do this as yourself."}


@app.post("/gas")
async def gas_relay(request: Request) -> Response:
    # a raw-JSON envelope is read as the form envelope is, as doPost reads both
    sent = await request.body()
    raw = _relay_form(sent)
    content_type = (request.headers.get("content-type") if raw is sent else None) or \
        "application/x-www-form-urlencoded;charset=UTF-8"
    action = _relay_action(raw)
    refused = _relay_app_access_refusal(raw, _auth_master, _relay_ac_writer)
    if refused is not None:
        log.info("relay: an app-access write refused — app access is the master's, shared only through App Control access")
        return Response(json.dumps(refused), media_type="application/json")
    # the master's account: its sign-in and the account writes that name it, before either backend is asked
    addr = _master_sign_in_addr(request)
    _MASTER_SIGN_IN_ADDR.set(addr)
    held = _master_sign_in_refusal(raw, addr) or _acting_refusal(raw) or await _master_account_refusal(raw)
    if held is not None:
        return Response(json.dumps(held), media_type="application/json")
    # an app's public doors, before any session is asked for: the link's own token is their gate (a file too big for
    # _relay_action is named by its opening bytes); Python's answer or its 503, never Apps Script's
    door = action if action in PUBLIC_DOOR_APPS else "" if action else _upload_action(raw)
    if door in PUBLIC_DOOR_APPS:
        public = await _public_door(door, raw)
        if public is not None:
            return public
    # Settings › Editions and a person's own are Python's alone, whatever the switch says; never Apps Script
    if action in EDITIONS_PYTHON_ACTIONS:
        return await _editions_python(action, raw)
    # and so are the JSON lane's bundles, built off asa-hub-db
    if action in BUNDLE_PYTHON_ACTIONS:
        return await _bundle_python(action, raw)
    # the Emergency Contacts directory is Python's alone (Postgres); off Python the page draws its compiled one
    if action in EMERGENCY_CONTACTS_ACTIONS:
        return await _emergency_contacts(action, raw)
    # and so are a house's medications in Locations › Supplies
    if action in LOCATION_MEDS_ACTIONS:
        return await _location_meds(action, raw)
    # and so is Staff Performance (the perf_* copies and app.edits)
    if action in PERFORMANCE_ACTIONS:
        return await _performance(action, raw)
    # and so are a client's MARS papers and their kept OCR text (Clients › Medication › Administration)
    if action in MAR_PAPERS_ACTIONS and not _relay_is_service(raw):
        return await _mar_papers(action, raw)
    # and so is the chat, in its own tables
    if action in CHAT_PYTHON_ACTIONS:
        return await _chat_python_gas(action, raw)
    # and so are Staff's HR Admin and Performance, each view's line kept beside them
    if action in STAFF_AUDITED_ACTIONS and not _relay_is_service(raw):
        return await _staff_audited(action, raw)
    # and so are Settings' last tools and the asking rhythm's verbs (hiringCadences)
    settings_door = _settings_tools_door(action, raw)
    if settings_door:
        return await _settings_tools(action, settings_door, raw)
    # and so is a Time off approval row's message from My Work, which Smart Comms in Python words and sends
    if action in MY_WORK_MESSAGE_ACTIONS:
        return await _my_work_message(action, raw)
    # and so are a Google Form's import, a signed packet form attached (a file too big for _relay_action is named by its
    # opening bytes) and the hiring walk
    if action in PYTHON_TOOL_DOORS or (not action and _upload_action(raw) == "packetUpload"):
        return await _python_tool_door(action or "packetUpload", raw)
    # and so is filing a paper: an upload too big for _relay_action is named by its opening bytes
    if action == "certDocUpload" or (not action and _app_pack_upload_envelope(raw).get("action") == "certDocUpload"):
        return await _cert_papers(raw)
    # and a file pinned to a calendar day, while Settings › Back-end gives the Calendar to Python
    if action == "calendarDayFileStore" or (not action and _upload_action(raw) == "calendarDayFileStore"):
        pinned = await _calendar_files(raw)
        if pinned is not None:
            return pinned
    # and a file stored in the Library (a Kanban card's attachment), while it gives the Kanban to Python
    if action == "libraryUpload" or (not action and _upload_action(raw) == "libraryUpload"):
        stored = await _library_upload(raw)
        if stored is not None:
            return stored
    # and a file stored in or trashed from a Drive reading room, while it gives the Audit Library to Python
    if action in ("docRoomUpload", "docRoomTrash") or (not action and _upload_action(raw) == "docRoomUpload"):
        roomed = await _doc_room_door(raw)
        if roomed is not None:
            return roomed
    # and a plan filed from the plans folder, or its sections read again, while it gives the ISP Library to Python
    # and the plans' contacts read again by the model, while Client Care's rest is Python's
    if action == "ispContactsSweep":
        swept = await _isp_contacts_door(raw)
        if swept is not None:
            return swept
    # and the AI lane test the Guardian and Smart Comms press, while the Guardian is Python's
    if action == "aiKeyStress":
        stressed = await _ai_key_stress_door(raw)
        if stressed is not None:
            return stressed
    # and the Desk's Run on Smart Comms' clock
    if action == "smartCommsRun":
        return await _smart_clock_desk_run(raw)
    # and the window ask an admin presses
    if action == "commWindowAskSweep":
        return await _comm_window_ask_door(raw)
    # and the platform's contact list an admin hands over from Settings, while the contacts sync is Python's
    if action == "peopleSyncFromPlatform" or (not action and _upload_action(raw) == "peopleSyncFromPlatform"):
        synced = await _people_sync_door(raw)
        if synced is not None:
            return synced
    # and the inbound sweep a person presses, while the opt-outs are Python's
    if action == "commsInboundSweep":
        swept = await _inbound_door(raw)
        if swept is not None:
            return swept
    if action in ("ispIntakeSweep", "ispIntakeRedo", "clientProfileIspSections"):
        intake = await _isp_intake_door(action, raw)
        if intake is not None:
            return intake
    # and an IST paper filed on its record from a house, while it gives IST Records to Python
    if action == "locationIstFile" or (not action and _upload_action(raw) == "locationIstFile"):
        filed_ist = await _ist_paper_door(raw)
        if filed_ist is not None:
            return filed_ist
    # and a family member's paper with its file (a Drive link alone goes on as the write it is)
    if action == "familyProfileDocAdd" or (not action and _app_pack_upload_envelope(raw).get("action")
                                           == "familyProfileDocAdd"):
        filed = await _family_papers(raw)
        if filed is not None:
            return filed
    # and so is a paper filed on a candidate's Hiring record, read and filed here
    if action == "candidateProfileDoor" or \
            (not action and _app_pack_upload_envelope(raw).get("action") == "candidateProfileDoor"):
        paper_env = _candidate_paper_env(raw)
        if paper_env is not None:
            return await _candidate_papers(paper_env, raw)
    if action == "hiringAlertsSet" and _editions_in_config_save(raw):
        return Response(json.dumps(EDITIONS_CONFIG_REFUSED), media_type="application/json")
    # a write Python's door decides: refused in its words or kept in Postgres
    if not action and _upload_action(raw) in BACKEND_BIG_WRITES:
        action = _upload_action(raw)
    # a generic verb on a resource Python can answer (documents) is asked of Python under its door's name
    python_door = _backend_generic_door(action, raw)
    if python_door in _BACKEND_WRITES:
        decided, raw = await _backend_write(python_door, raw)
        if decided is not None:
            return decided
    # a write that makes an app pack dirty takes its kept copy off the disk first (APP PACKS)
    _app_pack_sending(action, raw)
    # and a write to a board kept per viewer is never answered to its sender from a copy older than it (VIEWER CACHE)
    _viewer_cache_written(action, raw)
    # Scheduling, Support Requests and Transportation answer from this viewer's own kept copy while the session…
    board_ask = _viewer_cache_key(action, raw, request)
    # the name a kept read re-reads on, said to the browser: its tab holds the answer too (gasAction)
    kept_ring = {"X-Kept-Ring": _viewer_cache_ring_of(action) or ""} if board_ask else {}
    if board_ask:
        board_kept = await _viewer_cache_hit(board_ask, raw, content_type)
        if board_kept is not None:
            return Response(await _backend_editions_cut(action, board_kept), media_type="application/json",
                            headers=kept_ring)
    # a person's read, answered by Python's door
    backend = await _backend_answer(python_door, raw)
    # a sign-out sends the chat sends kept here first (WRITTEN BEHIND)
    if action in ("authLogout", "beAnotherStop"):
        _t = _relay_token(raw)
        if _t:
            await _chat_behind_flush_for(_t)
    # the sign-in (app/auth_doors.py): every hook below learns from it
    if backend is None and action in AUTH_PY_DOORS:
        backend = await _auth_py_answer(action, raw)
    # WHICH ACTIONS, NOT JUST HOW MANY.
    if not _relay_is_service(raw) and action:
        # `list` and `get` are the GENERIC verbs — the action name alone says nothing about what was read, and four…
        label = action
        if action in ("list", "get"):
            res = _relay_resource(raw)
            if res:
                label = action + ":" + res
        _by_action[label] = _by_action.get(label, 0) + 1
    if backend is None:
        # no door of Python's takes it: doPost's own answer to an action it does not know, and nothing is sent anywhere
        log.info("relay: %s answered Unknown action — no door takes it", action or _upload_action(raw) or "?")
        return Response(json.dumps(RELAY_UNKNOWN_ACTION), media_type="application/json")
    res, _asked_at = backend
    try:
        _relay_observe_auth(raw, res.content)
        _master_sign_in_observed(raw, res.content)
        _relay_observe_be_another(raw, res.content)
        _auth_py_released(action, raw, res.content)
        _relay_observe_chat(raw, res.content)
        _relay_observe_chat_read(raw, res.content)
        _chat_live_observed(raw, res.content, "gas")
        _chat_push_observed(raw, res.content)
        _relay_observe_access_write(raw, res.content)
        _relay_observe_app_pack(action, raw, res.content, python=True)
        _relay_observe_scheduling(action, res.content)
        _relay_observe_support_desk(action, res.content)
        _vehicle_calendar_rang(action, res.content)
        _staff_profiles_rang(action, res.content)
        _smart_comms_rang(action, res.content)
        _forms_rang(action, res.content)
        _support_desk_rang(action, res.content)
        _docs_rang(action, res.content, raw)
        _learning_rang(action, res.content, raw)
        _recon_rang(action, res.content, raw)
        _viewer_cache_written(action, raw, res.content)
        _edit_overlay_config_seen(action, raw, res.content)
    except Exception as exc:  # noqa: BLE001 - an observer never breaks the answer
        log.warning("relay: %s answered, an observer failed (%s)", action or "?", type(exc).__name__)
    if board_ask:
        _viewer_cache_take(board_ask, res.content)
    return Response(await _backend_editions_cut(action, res.content), media_type="application/json",
                    headers=kept_ring)


# -------------------------------------------------------------------------- the session's own words in the envelope
# the editions Settings › Editions saved, as the relay last saw them (a house photo's writer is judged by them)
_edits = edit_overlay.Overlay() if edit_overlay is not None else None


def _relay_token(raw: bytes) -> str:
    """The session token inside the form envelope, '' when absent."""
    if len(raw) > 100_000:
        return ""
    try:
        body = urllib.parse.parse_qs(raw.decode("utf-8", "ignore")).get("body", [""])[0]
        return str(json.loads(body).get("token") or "")
    except Exception:  # noqa: BLE001
        return ""


async def _token_vouched(token: str) -> bool:
    """Can the gate vouch for this session?"""
    if not token:
        return False
    hit = _auth_cache.get(token)
    if hit and time.time() - hit[0] < AUTH_TTL_SECONDS:
        return bool(hit[1])
    try:
        verdict = await asyncio.to_thread(_session_verdict, token)
    except Exception:  # noqa: BLE001
        return False
    if verdict is None:
        # "THE MIRROR SAYS NO" AND "THE MIRROR CANNOT SAY" ARE OPPOSITES, and until now both landed here as False…
        if _mirror_blind:
            return bool(token)
        return False
    ok, role, uid = verdict
    _auth_cache_put(token, ok, role, uid)
    return bool(ok)


_edit_editions_mirror: dict[str, Any] = {"at": 0.0, "value": None, "copied_at": 0.0}
EDIT_EDITIONS_HOLD_S = 20.0


def _edit_overlay_config_seen(action: str, raw: bytes, content: bytes) -> None:
    """Settings › Editions saved through the relay: the list it saved decides the overlay's editions from now."""
    if _edits is None or action not in ("editionsSet", "hiringAlertsSet"):
        return
    try:
        env = json.loads(content)
        if not isinstance(env, dict) or env.get("status") != 200:
            return
        if action == "editionsSet":
            listed = (env.get("data") or {}).get("editions")
            if not isinstance(listed, list):
                return
            said = json.dumps(listed)
        else:
            values = ((_relay_envelope(raw) or {}).get("payload") or {}).get("values")
            if not isinstance(values, dict) or edit_overlay.EDITIONS_KEY not in values:
                return
            said = str(values.get(edit_overlay.EDITIONS_KEY) or "")
        _edits.note_editions(edit_overlay.parse_editions(said), time.time())
        _edit_editions_mirror["at"] = 0.0
    except Exception:  # noqa: BLE001 - an observer never breaks the answer
        return


def _edit_overlay_editions() -> dict[str, Any] | None:
    """Blocking, FAIL-CLOSED: Settings › Editions — the save the relay saw, else the mirror's copy, else None."""
    seen, seen_at = _edits.editions_seen()
    held = _edit_editions_mirror
    if time.time() - held["at"] >= EDIT_EDITIONS_HOLD_S:
        value, copied = None, 0.0
        try:
            with psycopg2.connect(PG_DSN, connect_timeout=5) as conn, conn.cursor() as cur:
                cur.execute("select data, ingested_at from asa_drive_sheets_rows where sheet_id = %s and tab_name = %s",
                            (HUB_DB_SHEET_ID, "hiring_alerts_config"))
                rows = cur.fetchall()
            if rows:
                copied = max((r[1].timestamp() for r in rows if r[1] is not None), default=0.0)
                value = edit_overlay.parse_editions(next(
                    (str(d.get("value") or "") for d, _at in rows
                     if isinstance(d, dict) and str(d.get("key") or "").strip() == edit_overlay.EDITIONS_KEY), ""))
        except Exception as exc:  # noqa: BLE001 - no copy is not a list of nobody: the save seen, else nothing
            log.warning("edit overlay: the editions could not be read from the mirror (%s)", type(exc).__name__)
        held.update(at=time.time(), value=value, copied_at=copied)
    if seen is not None and seen_at >= float(held["copied_at"] or 0):
        return seen
    return held["value"]


async def _edit_overlay_who(token: str, action: str) -> dict[str, Any] | None:
    """FAIL-CLOSED: the author, when the relay itself can say this session makes the edit; None: its door decides."""
    authorization = f"Bearer {token}"
    actor = await _session_actor(authorization)
    if not actor:
        return None
    role, uid = str(actor[0] or "").strip().lower(), str(actor[1] or "").strip()
    name = _token_name_get(token)
    master, _unsure = await _app_pack_master(authorization)
    if master:
        return {"uid": uid, "name": name, "master": True, "any_note": True}
    if role not in edit_overlay.EDITION_ROLES or not uid:
        return None
    editions = await asyncio.to_thread(_edit_overlay_editions)
    if editions is None:
        return None
    door = edit_overlay.DOORS[action]
    app = door.get("app", "locations")
    any_note = app == "locations" and edit_overlay.holds(editions, "locations.notesAny", uid, role)
    allowed = (edit_overlay.holds(editions, door["edition"], uid, role)
               or (action == "locationNoteEdit" and any_note))
    # only a session that reads every house (or client) uncut: a narrowed one is its door's
    if not allowed or not await _app_pack_released(authorization, app):
        return None
    return {"uid": uid, "name": name, "master": False, "any_note": any_note}


# the asa-hub containers, read by the status sidecar (ops/status.py) on the backend network
HUB_STATUS_URL = (os.getenv("HUB_STATUS_URL") or "http://asa-hub-status:8090").rstrip("/")
# the env first; else a private file beside the relay code (server/.hub-status-token, gitignored, 0600)
HUB_STATUS_TOKEN = os.getenv("HUB_STATUS_TOKEN", "") or (
    (Path(__file__).with_name(".hub-status-token").read_text().strip())
    if Path(__file__).with_name(".hub-status-token").is_file() else "")
HUB_STATUS_TIMEOUT_S = 12.0


def _hub_status_unreachable(why: str) -> dict[str, Any]:
    return {"status": 503, "reason": "unreachable", "message": f"Status sidecar unreachable: {why}. No list was read."}


@app.get("/hub-lanes/hub-containers")
async def lane_hub_containers(response: Response, authorization: str = Header(default="")) -> dict[str, Any]:
    """The asa-hub containers as the status sidecar reads them — the master's read; a failure is never an empty list."""
    response.headers["Cache-Control"] = "no-store"
    if not _hotline_token(authorization):
        return {"status": 401, "reason": "session", "message": "sign in first"}
    ok, unsure = await _app_pack_master(authorization)
    if unsure:
        return {"status": 503, "reason": "unavailable", "message": f"This read could not open: {unsure}. Try again."}
    if not ok:
        return {"status": 404, "reason": "unknown", "message": "Unknown lane."}
    if not HUB_STATUS_TOKEN:
        return _hub_status_unreachable("HUB_STATUS_TOKEN is not set on the relay")
    try:
        async with httpx.AsyncClient(timeout=HUB_STATUS_TIMEOUT_S) as client:
            res = await client.get(f"{HUB_STATUS_URL}/containers", headers={"X-Hub-Status-Token": HUB_STATUS_TOKEN})
    except Exception as exc:  # noqa: BLE001
        log.warning("hub containers: the status sidecar did not answer (%s)", type(exc).__name__)
        return _hub_status_unreachable(f"it did not answer ({type(exc).__name__})")
    try:
        body = res.json()
    except ValueError:
        body = None
    rows = body.get("containers") if isinstance(body, dict) else None
    if res.status_code != 200 or not isinstance(rows, list):
        said = str(body.get("error") or "")[:160] if isinstance(body, dict) else ""
        log.warning("hub containers: the status sidecar answered %s", res.status_code)
        return _hub_status_unreachable(f"it answered {res.status_code}" + (f" ({said})" if said else ""))
    return {"status": 200, "data": {"containers": [r for r in rows if isinstance(r, dict)],
                                    "read_at": str(body.get("read_at") or ""), "cache_s": body.get("cache_s")}}


# -------------------------------------------------------------------------- analysis fallback — when the Hub's own…
ANALYZE_KEYS = [k for k in (os.getenv("LLM_API_KEY", ""), os.getenv("OPENAI_API_KEY", "")) if k]
ANALYZE_URL = os.getenv("HUB_ANALYZE_URL", "https://api.openai.com/v1/chat/completions")
ANALYZE_MODEL = os.getenv("HUB_ANALYZE_MODEL", "gpt-4o-mini")

# THE LAST DOOR HAD ONE HINGE, AND THE HINGE IS OFF.
ANALYZE_LOCAL_URL = os.getenv("HUB_ANALYZE_LOCAL_URL",
                              "http://local-cortex:8080/v1/chat/completions")
ANALYZE_LOCAL_MODEL = os.getenv("HUB_ANALYZE_LOCAL_MODEL", "qwen2.5-7b-instruct")
# The whole call's wall-clock allowance, across every door and every shape.
ANALYZE_BUDGET_S = float(os.getenv("HUB_ANALYZE_BUDGET_S", "45"))


def _analyze_upstreams(asked_model: str) -> list[dict[str, Any]]:
    """The doors to try, in order."""
    ups: list[dict[str, Any]] = []
    if ANALYZE_URL and ANALYZE_KEYS:
        ups.append({"name": "pool", "url": ANALYZE_URL,
                    "model": asked_model or ANALYZE_MODEL, "keys": ANALYZE_KEYS})
    elif ANALYZE_URL:
        # A DOOR SKIPPED FOR WANT OF A KEY IS STILL A DOOR, AND IT GETS ITS NAME SAID.
        ups.append({"name": "pool", "url": ANALYZE_URL,
                    "model": asked_model or ANALYZE_MODEL, "keys": []})
    if ANALYZE_LOCAL_URL:
        ups.append({"name": "local-cortex", "url": ANALYZE_LOCAL_URL,
                    "model": ANALYZE_LOCAL_MODEL, "keys": [""]})
    return ups


@app.post("/analyze")
async def analyze(request: Request) -> dict[str, Any]:
    """One chat completion, for the Hub, when its own provider refused."""
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}

    given = str(body.get("service_secret") or "")
    if not SERVICE_SECRET or not hmac.compare_digest(given, SERVICE_SECRET):
        log.warning("analyze: refused, bad or missing service secret")
        return {"status": 401, "message": "service identity required"}

    messages = body.get("messages")
    if not isinstance(messages, list) or not messages:
        return {"status": 400, "message": "messages: a non-empty list is required"}

    upstreams = _analyze_upstreams(str(body.get("model") or ""))
    if not upstreams:
        # Said plainly rather than answered with an empty completion: an empty answer would be written into the card…
        return {"status": 503, "message": "no model upstream configured on the server"}

    payload = {
        "temperature": float(body.get("temperature", 0)),
        "messages": messages,
    }
    # FORWARD THE SHAPE THE CALLER ASKED FOR.
    if body.get("response_format"):
        payload["response_format"] = body["response_format"]
    # THE POOL IS NOT ONE MODEL.
    attempts = [payload]
    if payload.get("response_format"):
        bare = dict(payload)
        bare.pop("response_format")
        attempts.append(bare)

    # EVERY DOOR THAT REFUSED, NAMED — not just the last one.
    refusals: list[str] = []
    # A SECOND UPSTREAM DOUBLES THE DOORS AND MUST NOT DOUBLE THE WAIT.
    deadline = time.monotonic() + ANALYZE_BUDGET_S
    for up in upstreams:
      if not up["keys"]:
        refusals.append(f"{up['name']}/{up['model']} not tried (no key configured)")
        continue
      for attempt in attempts:
        shaped = dict(attempt)
        shaped["model"] = up["model"]
        for key in up["keys"]:
            # THE BUDGET IS A BOUND, NOT A STARTING GATE.
            left = deadline - time.monotonic()
            if left <= 1.0:
                refusals.append(f"{up['name']}/{up['model']} not tried (budget spent)")
                break
            try:
                headers = {"Authorization": f"Bearer {key}"} if key else {}
                async with httpx.AsyncClient(timeout=min(90.0, left)) as client:
                    r = await client.post(up["url"], json=shaped, headers=headers)
                if r.status_code >= 400:
                    refusals.append(f"{up['name']}/{up['model']} {r.status_code}: {r.text[:100]}")
                    continue
                data = r.json()
                content = (((data.get("choices") or [{}])[0].get("message") or {})
                           .get("content"))
                if not content:
                    # A 200 that carries no completion is not an answer.
                    refusals.append(f"{up['name']}/{up['model']} empty completion")
                    continue
                log.info("analyze: answered for the Hub by %s/%s (%d chars, format=%s)",
                         up["name"], up["model"], len(content),
                         "strict" if shaped.get("response_format") else "free")
                return {"status": 200, "data": {"choices": [{"message": {"content": content}}]}}
            except Exception as exc:  # noqa: BLE001
                refusals.append(f"{up['name']}/{up['model']} {type(exc).__name__}: {str(exc)[:80]}")
                continue
    said = " | ".join(dict.fromkeys(refusals)) or "no upstream was tried"
    log.warning("analyze: nothing answered — %s", said[:600])
    return {"status": 502, "message": f"no model answered: {said[:300]}"}


# --------------------------------------------------------------------------- THE INSTANT HALF OF THE PHONE-CALL…

# The webhook's record → the lane's row.
_COMM_CALLS_ROW_MAP = (
    ("call_id", ("call_id",)),
    ("event_timestamp", ("event_at", "transcript_created", "received_at")),
    ("duration_sec", ("duration_s", "duration_sec")),
    ("participant_s", ("participants", "participant_s")),
    ("team_member_s", ("team_members", "team_member_s")),
    ("direction", ("direction",)),
    ("turns", ("turns",)),
    ("full_transcript", ("full_transcript",)),
    ("speaker_transcript", ("speaker_transcript",)),
)


def _comm_calls_row(record: dict) -> dict:
    row: dict[str, Any] = {}
    for lane_name, sources in _COMM_CALLS_ROW_MAP:
        for src in sources:
            value = record.get(src)
            if value not in (None, ""):
                row[lane_name] = value
                break
    # A DURATION IS ONE NUMBER, WHATEVER SHAPE IT ARRIVED IN.
    if row.get("duration_sec") not in (None, ""):
        try:
            row["duration_sec"] = str(int(float(row["duration_sec"])))
        except (TypeError, ValueError):
            row["duration_sec"] = ""
    # THE LINE, WHEN THE PAYLOAD NAMES USERS INSTEAD OF NUMBERS.
    import re as _re
    has_number = bool(_re.search(r"\d{10}", _re.sub(r"\D", "", str(row.get("team_member_s") or ""))))
    if not has_number and record.get("quo_number"):
        try:
            with psycopg2.connect(PG_DSN) as conn, conn.cursor() as cur:
                cur.execute(
                    "select number from public.asa_openphone_lines where id = %s",
                    (str(record["quo_number"]),))
                got = cur.fetchone()
            if got and got[0]:
                row["team_member_s"] = str(got[0])
        except Exception:  # noqa: BLE001 — no resolution is not a reason to lose the call
            pass
    # The columns the mirror carries and a live event does not: it was filed seconds ago, so no lane has processed…
    row.setdefault("processed", "")
    row.setdefault("processedbyagent", "")
    row.setdefault("processingerror", "")
    row.setdefault("_row_number", 0)
    return row


def _comm_calls_ledger_row(call_id: str) -> dict | None:
    """The ledger's row for one call, or None — the idempotency check below."""
    try:
        with hub_db.connect(PG_DSN) as conn, conn.cursor(
                cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("select call_id, state, facts, landed_at from comm_call_reads"
                        " where call_id = %s", (call_id,))
            got = cur.fetchone()
            return dict(got) if got else None
    except Exception:  # noqa: BLE001 — a database that will not answer reads as not read
        return None


@app.post("/comm-calls/transcript")
async def comm_calls_transcript(request: Request, background: BackgroundTasks) -> dict[str, Any]:
    """One transcript, read now — the webhook's half of the lane."""
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}

    given = str(body.get("service_secret") or "")
    if not SERVICE_SECRET or not hmac.compare_digest(given, SERVICE_SECRET):
        log.warning("comm calls transcript: refused, bad or missing service secret")
        return {"status": 401, "message": "service identity required"}

    record = body.get("record")
    if not isinstance(record, dict) or not str(record.get("call_id") or ""):
        return {"status": 400, "message": "record with a call_id is required"}
    if not str(record.get("full_transcript") or ""):
        # A transcript event with no words is a hang-up the model would only invent a matter for — measured on this…
        return {"status": 200, "data": {"call_id": record["call_id"],
                                        "read": 0, "why": "no words on the event"}}

    if not PG_DSN:
        return {"status": 503, "message": "no database configured on the server"}
    # EVERY DATABASE AND NETWORK CALL RUNS OFF THE LOOP.
    state = await asyncio.to_thread(comm_calls_feed.ready, PG_DSN)
    if not state["key"]:
        return {"status": 503,
                "message": "nothing may be read: " + "; ".join(state["why"])}
    if not state.get("enabled"):
        # The lane's one switch holds this door too: off, no call is read from anywhere.
        return {"status": 200, "data": {"call_id": record["call_id"], "read": 0,
                                        "why": "the switch is off"}}

    row = await asyncio.to_thread(_comm_calls_row, record)
    call_id = str(row["call_id"])
    loop = asyncio.get_running_loop()

    def post(body: dict) -> dict:
        # the lane is Python's: its post goes there
        return asyncio.run_coroutine_threadsafe(_comm_calls_python(body), loop).result()

    # ALREADY READ IS DELIVERED, NOT RE-READ.
    prior = await asyncio.to_thread(_comm_calls_ledger_row, call_id)
    if prior and (prior.get("facts") or prior.get("landed_at")):
        log.info("comm calls transcript: %s already read (%s) — delivering", call_id,
                 prior.get("state"))
        delivery = await asyncio.to_thread(comm_calls_feed.deliver, PG_DSN, post,
                                           say=lambda m: log.info("%s", m))
        return {"status": 200, "data": {"call_id": call_id, "read": 0,
                                        "already": prior.get("state"),
                                        "delivered": delivery.get("landed", 0)}}

    # THE WORK GOES BACKGROUND, THE ANSWER GOES NOW.
    background.add_task(_comm_calls_read_and_serve, row, post)
    return {"status": 200, "data": {"call_id": call_id, "accepted": True}}


async def _comm_calls_read_and_serve(row: dict, post) -> None:
    """The background half of the webhook door: read, deliver, rebuild."""
    call_id = str(row["call_id"])
    try:
        reading = await asyncio.to_thread(comm_calls_feed.reading)
        if not reading.fits(len(str(row.get("full_transcript") or ""))):
            log.info("comm calls transcript: %s too long for this door — the mirror pass files it",
                     call_id)
            return

        def read() -> dict | None:
            # Starlette awaits an async background task on the loop: the who lookup and the model read block.
            whois = comm_calls_feed.who([reading.caller_digits(row.get("participant_s"))], post)
            return comm_calls_feed.read_one(PG_DSN, row, whois, f"wh{int(time.time())}")

        got = await asyncio.to_thread(read)
        if got is None:
            log.info("comm calls transcript: %s was claimed by another worker", call_id)
        else:
            log.info("comm calls transcript: %s read on the webhook (%s, %d item(s))",
                     call_id, got["state"], len(got["items"]))
        await asyncio.to_thread(comm_calls_feed.deliver, PG_DSN, post, say=lambda m: log.info("%s", m))
        await build_all(only={"commCalls", "commWorkItems"})
    except Exception as exc:  # noqa: BLE001 — the mirror pass is the safety net
        log.warning("comm calls transcript: background pass failed for %s (%s: %s)",
                    call_id, type(exc).__name__, str(exc)[:160])


# --------------------------------------------------------------------------- THE CORTEX DOOR — the chat is brought…
CORTEX_URL = os.getenv("HUB_CORTEX_URL", "http://the old platform:4000").rstrip("/")
CORTEX_KEY = os.getenv("ASA_MASTER_KEY", "")
CORTEX_TIMEOUT = float(os.getenv("HUB_CORTEX_TIMEOUT", "120"))

# token -> (at, cortex-facing identity) — who a session belongs to, learned from one authMe on a miss, exactly as…
_token_cortex: dict[str, tuple[float, str]] = {}


async def _cortex_caller(token: str) -> str:
    """The cortex-facing identity for a Hub session token, or "" when unknown."""
    hit = _token_cortex.get(token)
    if hit and time.time() - hit[0] < AUTH_TTL_SECONDS:
        return hit[1]
    # the session's account, read off the users copy by Python
    user = await _person_photo_user(f"Bearer {token}")
    got = await _backend_call(CORTEX_APP, "cortexWho", {}, user) if user is not None else None
    env = got[2] if got is not None else None
    who = str(((env or {}).get("data") or {}).get("who") or "").strip() if (env or {}).get("status") == 200 else ""
    if not who:
        log.info("cortex: the session's account was not named by Python (%s)",
                 "no session" if user is None else _BACKEND_UNANSWERED.get() or (env or {}).get("status"))
    if who:
        _token_cortex[token] = (time.time(), who)
        if len(_token_cortex) > 4000:  # a long-lived process, not a leak
            _token_cortex.clear()
    return who


def _cortex_gate(authorization: str) -> tuple[str, dict[str, Any] | None]:
    """The session check every cortex route shares: (token, error-or-None)."""
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    hit = _auth_cache.get(token) if token else None
    if not hit or not hit[1] or time.time() - hit[0] >= AUTH_TTL_SECONDS:
        return "", {"status": 401, "message": "Authentication required."}
    if not CORTEX_KEY:
        # Said plainly, never as an empty answer: without the machine credential this server cannot vouch for…
        return "", {"status": 503, "message": "The cortex door is not configured on this server."}
    return token, None


@app.post("/cortex/chat/send")
async def cortex_chat_send(request: Request, authorization: str = Header(default="")) -> Response:
    """One Dialog3 turn for a signed-in Hub user — SSE in, SSE out."""
    token, refused = _cortex_gate(authorization)
    if refused is not None:
        return Response(content=json.dumps(refused), status_code=refused["status"],
                        media_type="application/json")
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        body = {}
    message = str((body or {}).get("message") or "").strip()[:4000]
    if not message:
        return Response(content=json.dumps({"status": 400, "message": "message required"}),
                        status_code=400, media_type="application/json")
    # The browser mints and keeps its own session id (DLG-hub-…): the cortex would generate one for a blank field…
    session_id = re.sub(r"[^A-Za-z0-9_-]", "", str((body or {}).get("session_id") or ""))[:64]
    who = await _cortex_caller(token)
    if not who:
        return Response(content=json.dumps({"status": 401, "message": "Authentication required."}),
                        status_code=401, media_type="application/json")
    log.info("cortex chat: send for %s (session %s, %d chars)",
             who, session_id or "new", len(message))

    upstream_body: dict[str, Any] = {"message": message, "user_id": who}
    if session_id:
        upstream_body["session_id"] = session_id
    client = httpx.AsyncClient(timeout=httpx.Timeout(CORTEX_TIMEOUT, connect=10.0))
    try:
        req = client.build_request("POST", f"{CORTEX_URL}/v1/cortex/dialog/send",
                                   json=upstream_body,
                                   headers={"Authorization": f"Bearer {CORTEX_KEY}"})
        upstream = await client.send(req, stream=True)
    except Exception as exc:  # noqa: BLE001
        await client.aclose()
        log.warning("cortex chat: upstream unreachable for %s: %s", who, str(exc)[:120])
        return Response(content=json.dumps({"status": 502, "message": "The cortex did not answer."}),
                        status_code=502, media_type="application/json")
    if upstream.status_code != 200:
        detail = (await upstream.aread())[:200]
        await upstream.aclose()
        await client.aclose()
        log.warning("cortex chat: upstream %s for %s: %r",
                    upstream.status_code, who, detail)
        return Response(content=json.dumps({"status": 502,
                                            "message": f"The cortex refused the turn ({upstream.status_code})."}),
                        status_code=502, media_type="application/json")

    async def stream():
        try:
            async for chunk in upstream.aiter_raw():
                yield chunk
        finally:
            await upstream.aclose()
            await client.aclose()

    return StreamingResponse(
        stream(),
        media_type="text/event-stream",
        headers={"Cache-Control": "no-store", "X-Accel-Buffering": "no"},
    )


@app.post("/cortex/chat/voice/transcribe")
async def cortex_voice_transcribe(request: Request, authorization: str = Header(default="")) -> Response:
    """One audio clip in, the transcript out (cortex voice-door kill list, item 2)."""
    token, refused = _cortex_gate(authorization)
    if refused is not None:
        return Response(content=json.dumps(refused), status_code=refused["status"],
                        media_type="application/json")
    who = await _cortex_caller(token)
    if not who:
        return Response(content=json.dumps({"status": 401, "message": "Authentication required."}),
                        status_code=401, media_type="application/json")
    body = await request.body()
    if not body:
        return Response(content=json.dumps({"status": 400, "message": "no audio in the request"}),
                        status_code=400, media_type="application/json")
    ctype = request.headers.get("content-type", "")
    if "multipart/form-data" not in ctype:
        return Response(content=json.dumps({"status": 400, "message": "multipart/form-data with an 'audio' field"}),
                        status_code=400, media_type="application/json")
    bias = "1" if request.query_params.get("bias") in ("1", "true") else ""
    url = f"{CORTEX_URL}/v1/cortex/dialog/voice/transcribe" + ("?bias=1" if bias else "")
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(CORTEX_TIMEOUT, connect=10.0)) as client:
            upstream = await client.post(url, content=body,
                                         headers={"Content-Type": ctype,
                                                  "Authorization": f"Bearer {CORTEX_KEY}"})
    except Exception as exc:  # noqa: BLE001
        log.warning("cortex voice: transcribe unreachable for %s: %s", who, str(exc)[:120])
        return Response(content=json.dumps({"status": 502, "message": "The cortex did not answer."}),
                        status_code=502, media_type="application/json")
    if upstream.status_code != 200:
        log.warning("cortex voice: transcribe upstream %s for %s", upstream.status_code, who)
        return Response(content=json.dumps({"status": 502,
                                            "message": f"The cortex refused the audio ({upstream.status_code})."}),
                        status_code=502, media_type="application/json")
    log.info("cortex voice: transcribed for %s (%d bytes)", who, len(body))
    return Response(content=upstream.content, status_code=200, media_type="application/json")


@app.post("/cortex/chat/voice/speak")
async def cortex_voice_speak(request: Request, authorization: str = Header(default="")) -> Response:
    """One reply in, its audio out (cortex voice-door kill list, item 2)."""
    token, refused = _cortex_gate(authorization)
    if refused is not None:
        return Response(content=json.dumps(refused), status_code=refused["status"],
                        media_type="application/json")
    who = await _cortex_caller(token)
    if not who:
        return Response(content=json.dumps({"status": 401, "message": "Authentication required."}),
                        status_code=401, media_type="application/json")
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        body = {}
    text = str((body or {}).get("text") or "").strip()[:4000]
    if not text:
        return Response(content=json.dumps({"status": 400, "message": "text required"}),
                        status_code=400, media_type="application/json")
    upstream_body: dict[str, Any] = {"text": text}
    for k in ("voice", "format", "message_id"):
        if (body or {}).get(k) is not None:
            upstream_body[k] = body[k]
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(CORTEX_TIMEOUT, connect=10.0)) as client:
            upstream = await client.post(f"{CORTEX_URL}/v1/cortex/dialog/voice/speak",
                                         json=upstream_body,
                                         headers={"Authorization": f"Bearer {CORTEX_KEY}"})
    except Exception as exc:  # noqa: BLE001
        log.warning("cortex voice: speak unreachable for %s: %s", who, str(exc)[:120])
        return Response(content=json.dumps({"status": 502, "message": "The cortex did not answer."}),
                        status_code=502, media_type="application/json")
    ctype = upstream.headers.get("content-type", "application/json")
    if upstream.status_code != 200 or "audio" not in ctype:
        log.warning("cortex voice: speak upstream %s for %s", upstream.status_code, who)
        return Response(content=upstream.content, status_code=502, media_type="application/json")
    log.info("cortex voice: spoke %d chars for %s", len(text), who)
    passthrough = {k: v for k, v in upstream.headers.items()
                   if k.lower() in ("x-tts-lane", "x-tts-latency-ms")}
    return Response(content=upstream.content, status_code=200, media_type=ctype,
                    headers={**passthrough, "Cache-Control": "no-store"})


async def _cortex_get(path: str, authorization: str) -> Response:
    """A read-only cortex answer, admin-only, forwarded whole."""
    token, refused = _cortex_gate(authorization)
    if refused is not None:
        return Response(content=json.dumps(refused), status_code=refused["status"],
                        media_type="application/json")
    hit = _auth_cache.get(token)
    if not hit or hit[2] != "admin":
        return Response(content=json.dumps({"status": 403, "message": "Admins only."}),
                        status_code=403, media_type="application/json")
    try:
        async with httpx.AsyncClient(timeout=20) as client:
            r = await client.get(f"{CORTEX_URL}{path}",
                                 headers={"Authorization": f"Bearer {CORTEX_KEY}"})
    except Exception as exc:  # noqa: BLE001
        log.warning("cortex mesh: %s unreachable: %s", path, str(exc)[:120])
        return Response(content=json.dumps({"status": 502, "message": "The cortex did not answer."}),
                        status_code=502, media_type="application/json")
    if r.status_code != 200:
        log.warning("cortex mesh: %s answered %s", path, r.status_code)
        return Response(content=json.dumps({"status": 502,
                                            "message": f"The cortex refused ({r.status_code})."}),
                        status_code=502, media_type="application/json")
    return Response(content=r.content, status_code=200, media_type="application/json")


# --------------------------------------------------------------------------- THE CONVERSATIONS THE CORTEX ALREADY…
CORTEX_DIALOG_MAX = 60          # dialogs listed, newest first
CORTEX_TURN_MAX = 400           # turns returned for one dialog
CORTEX_TITLE_CHARS = 90


def _cortex_dialog_list(who: str) -> list[dict[str, Any]]:
    """This person's dialogs, newest first: id, title, turns, when."""
    with psycopg2.connect(PG_DSN) as conn, conn.cursor(
        cursor_factory=psycopg2.extras.RealDictCursor
    ) as cur:
        cur.execute(
            """
            with mine as (
                select session_id, role, content, created_at, id
                  from asa_cortex_dialog_messages
                 where user_id = %s
            ),
            latest as (
                select session_id,
                       count(*)            as turns,
                       max(created_at)     as last_at,
                       min(created_at)     as first_at
                  from mine
                 group by session_id
                 order by max(created_at) desc
                 limit %s
            )
            select l.session_id, l.turns, l.last_at, l.first_at,
                   (select m.content
                      from mine m
                     where m.session_id = l.session_id and m.role = 'user'
                     order by m.id
                     limit 1) as opener
              from latest l
             order by l.last_at desc
            """,
            (who, CORTEX_DIALOG_MAX),
        )
        rows = cur.fetchall()
    out: list[dict[str, Any]] = []
    for r in rows:
        opener = " ".join(str(r["opener"] or "").split())[:CORTEX_TITLE_CHARS]
        out.append({
            "id": r["session_id"],
            "title": opener or "Conversation",
            "turns": int(r["turns"] or 0),
            "at": r["last_at"].isoformat() if r["last_at"] else "",
            "started_at": r["first_at"].isoformat() if r["first_at"] else "",
        })
    return out


def _cortex_dialog_turns(who: str, session_id: str) -> list[dict[str, Any]]:
    """The turns of ONE dialog — and only if it is this person's."""
    with psycopg2.connect(PG_DSN) as conn, conn.cursor(
        cursor_factory=psycopg2.extras.RealDictCursor
    ) as cur:
        cur.execute(
            """
            select role, content, created_at
              from asa_cortex_dialog_messages
             where user_id = %s and session_id = %s
             order by id
             limit %s
            """,
            (who, session_id, CORTEX_TURN_MAX),
        )
        rows = cur.fetchall()
    return [{
        "role": "assistant" if str(r["role"]) != "user" else "user",
        "text": str(r["content"] or ""),
        "at": r["created_at"].isoformat() if r["created_at"] else "",
    } for r in rows]


@app.get("/cortex/chat/dialogs")
async def cortex_chat_dialogs(authorization: str = Header(default="")) -> Response:
    """Every conversation this person has had with the cortex, newest first."""
    token, refused = _cortex_gate(authorization)
    if refused is not None:
        return Response(content=json.dumps(refused), status_code=refused["status"],
                        media_type="application/json")
    who = await _cortex_caller(token)
    if not who:
        return Response(content=json.dumps({"status": 401, "message": "Authentication required."}),
                        status_code=401, media_type="application/json")
    if not PG_DSN:
        return Response(content=json.dumps(
            {"status": 503, "message": "The transcript store is not configured on this server."}),
            status_code=503, media_type="application/json")
    try:
        dialogs = await asyncio.to_thread(_cortex_dialog_list, who)
    except Exception as exc:  # noqa: BLE001
        log.warning("cortex dialogs: list failed for %s: %s", who, str(exc)[:160])
        return Response(content=json.dumps(
            {"status": 502, "message": "The transcript store did not answer."}),
            status_code=502, media_type="application/json")
    return Response(content=json.dumps({"status": 200, "data": {"dialogs": dialogs}}),
                    status_code=200, media_type="application/json")


@app.get("/cortex/chat/dialogs/{session_id}")
async def cortex_chat_dialog_turns(session_id: str,
                                   authorization: str = Header(default="")) -> Response:
    """One conversation, turn by turn — this person's own, or nothing."""
    token, refused = _cortex_gate(authorization)
    if refused is not None:
        return Response(content=json.dumps(refused), status_code=refused["status"],
                        media_type="application/json")
    who = await _cortex_caller(token)
    if not who:
        return Response(content=json.dumps({"status": 401, "message": "Authentication required."}),
                        status_code=401, media_type="application/json")
    sid = re.sub(r"[^A-Za-z0-9_-]", "", str(session_id or ""))[:64]
    if not sid:
        return Response(content=json.dumps({"status": 400, "message": "Which conversation?"}),
                        status_code=400, media_type="application/json")
    if not PG_DSN:
        return Response(content=json.dumps(
            {"status": 503, "message": "The transcript store is not configured on this server."}),
            status_code=503, media_type="application/json")
    try:
        turns = await asyncio.to_thread(_cortex_dialog_turns, who, sid)
    except Exception as exc:  # noqa: BLE001
        log.warning("cortex dialogs: turns failed for %s/%s: %s", who, sid, str(exc)[:160])
        return Response(content=json.dumps(
            {"status": 502, "message": "The transcript store did not answer."}),
            status_code=502, media_type="application/json")
    # An empty list is the honest answer for "not yours" AND for "no turns" — telling those apart would say whether…
    return Response(content=json.dumps({"status": 200,
                                        "data": {"id": sid, "turns": turns}}),
                    status_code=200, media_type="application/json")


# --------------------------------------------------------------------------- THE ISP DECODER — a pure function…


def _isp_from_pdf(raw: bytes):
    """PDF bytes -> (nested decode, page-separated text)."""
    import pdf_gate
    import isp_decode as _isp
    with pdf_gate.pdf_document(raw, filetype="pdf") as doc:
        text = "\f".join(p.get_text() for p in doc)
    return _isp.parse_isp_text(text, prune=False), text


# --------------------------------------------------------------------------- THE QUO WEBHOOK — the half of the door…
def _quo_signature_ok(raw: bytes, header: str, keys: list[str]) -> bool:
    """`hmac;<version>;<timestamp>;<base64 mac>` over `<timestamp>.<body>`."""
    parts = str(header or "").split(";")
    if len(parts) < 4 or not keys:
        return False
    stamp, mac = parts[2], parts[3]
    # A field with bytes past ASCII is never a signature, and compare_digest would throw on it: an anonymous POST…
    if not (stamp.isascii() and mac.isascii()):
        return False
    try:
        signed = stamp.encode() + b"." + bytes(raw)
    except Exception:  # noqa: BLE001
        return False
    for k in keys:
        try:
            made = hmac.new(base64.b64decode(k), signed, hashlib.sha256).digest()
            if hmac.compare_digest(base64.b64encode(made), mac.encode()):
                return True
        except Exception:  # noqa: BLE001
            continue
    return False


# --------------------------------------------------------------------------- THE HOTLINE'S OWN WEBHOOK — a 5558…
QUO_HOTLINE_KEY_FILE = Path(os.getenv("QUO_HOTLINE_WEBHOOK_KEY_FILE",
                                      "/srv/secrets/quo-hotline-webhook.key"))
# Quo stamps every delivery and every retry afresh: an older stamp is a replay.
HOTLINE_FAST_FRESH_S = 300.0
# The same call inside this window is a second delivery — unless the first one gave up (`failed`), and then a…
HOTLINE_FAST_DEDUPE_S = 6 * 3600.0
# The lanes a filing writes rows into, rebuilt so the call's panel shows them.
HOTLINE_FAST_SLICES = ("supportQueue", "uiIncidents", "callOffs")
# How long a stream's Smart Comms verdict is held per session token, and so how long its tag lives; a refusal that…
HOTLINE_STREAM_GATE_TTL_S = 300.0
HOTLINE_STREAM_GATE_RETRY_S = 30.0
_HOTLINE_CALL_ID = re.compile(r"AC[0-9A-Za-z]{32}")
_quo_hotline_key_state: dict[str, Any] = {"stamp": None, "file_keys": [], "file_words": 0,
                                          "said": None, "from": None}
# call_id -> {at, stage}: filing | filed | blocked | claimed | dropped | failed
_HOTLINE_FAST: dict[str, dict[str, Any]] = {}
# token -> (checked_at, verdict open|shut|retry, held_for_s)
_HOTLINE_STREAM_GATE: dict[str, tuple[float, str, float]] = {}


def _key_fingerprint(key: str) -> str:
    return hashlib.sha256(key.encode()).hexdigest()[:8]


def _usable_quo_keys(words: list[str]) -> list[str]:
    out = []
    for word in words:
        try:
            if len(base64.b64decode(word, validate=True)) >= 16:
                out.append(word)
        except Exception:  # noqa: BLE001 - not a key; counted where it is said
            pass
    return out


def _quo_hotline_keys() -> list[str]:
    """The hotline webhook's signing key: the file while it exists, else the env."""
    state = _quo_hotline_key_state
    try:
        st = QUO_HOTLINE_KEY_FILE.stat()
        stamp: tuple[int, int] | None = (int(st.st_mtime_ns), int(st.st_size))
    except OSError:
        stamp = None
    if stamp is not None:
        source = "file"
        if stamp != state["stamp"]:
            try:
                words = QUO_HOTLINE_KEY_FILE.read_text(encoding="utf-8").split()
            except (OSError, ValueError):
                words = []
            state.update(stamp=stamp, file_words=len(words), file_keys=_usable_quo_keys(words))
        keys, offered = list(state["file_keys"]), int(state["file_words"])
    else:
        source = "env"
        state.update(stamp=None, file_keys=[], file_words=0)
        words = os.getenv("QUO_HOTLINE_WEBHOOK_KEY", "").split()
        keys, offered = _usable_quo_keys(words), len(words)
    said = (source, tuple(_key_fingerprint(k) for k in keys), offered - len(keys))
    if said != state["said"]:
        state["said"] = said
        if keys:
            log.info("quo hotline: webhook key from the %s, fingerprint %s — the fast path is armed%s",
                     source, ",".join(said[1]),
                     f" ({said[2]} unusable entry(ies) ignored)" if said[2] else "")
        elif offered:
            log.warning("quo hotline: the %s holds %s entry(ies) and no usable webhook key — "
                        "the fast path is off", source, offered)
        else:
            log.info("quo hotline: no webhook key — the fast path is off")
    state["from"] = source if keys else None
    return keys


def _quo_answer(status: int, **fields: Any) -> Response:
    return Response(content=json.dumps({"status": status, **fields}),
                    status_code=status, media_type="application/json")


def _quo_stamp_age_s(header: str, now: float) -> float | None:
    """How old the signature's millisecond stamp is; None when it has none."""
    parts = str(header or "").split(";")
    try:
        return now - int(parts[2]) / 1000.0
    except (IndexError, ValueError):
        return None


def _hotline_fast_prune(now: float) -> None:
    for cid in [c for c, e in _HOTLINE_FAST.items() if now - e["at"] >= HOTLINE_FAST_DEDUPE_S]:
        _HOTLINE_FAST.pop(cid, None)
    while len(_HOTLINE_FAST) > 5000:
        _HOTLINE_FAST.pop(next(iter(_HOTLINE_FAST)))


def _hotline_event_age_ms(event_at: str, now: float) -> int | None:
    when = hotline_desk.parse_when(event_at, "UTC") if hotline_desk is not None else None
    return round((now - when.timestamp()) * 1000) if when else None


async def _quo_hotline_event(raw: bytes, header: str) -> Response:
    """An event the hotline key signed: screened, answered at once, filed behind."""
    now = time.time()
    age = _quo_stamp_age_s(header, now)
    if age is None or abs(age) > HOTLINE_FAST_FRESH_S:
        log.warning("quo hotline: refused a stale event (%s)",
                    "no stamp" if age is None else f"stamped {age:.0f}s ago")
        return _quo_answer(401, reason="stale", message="Stale.")
    try:
        event = json.loads(raw.decode() or "{}")
    except Exception:  # noqa: BLE001
        return _quo_answer(400, message="Not JSON.")
    data = event.get("data") if isinstance(event, dict) else None
    obj = data.get("object") if isinstance(data, dict) else None
    obj = obj if isinstance(obj, dict) else {}
    call_id = str(obj.get("callId") or "")
    dialogue = obj.get("dialogue")
    turns = [{"identifier": t.get("identifier"), "userId": t.get("userId"),
              "content": t.get("content"), "start": t.get("start")}
             for t in (dialogue if isinstance(dialogue, list) else []) if isinstance(t, dict)]
    why = ""
    if not isinstance(event, dict) or event.get("type") != "call.transcript.completed":
        why = "type"
    elif not _HOTLINE_CALL_ID.fullmatch(call_id):
        why = "call_id"
    elif not turns:
        why = "no_turns"
    elif hotline_desk is None:
        why = "desk_unavailable"
    elif not hotline_desk.is_hotline(turns):
        why = "not_this_line"
    elif hotline_desk.link_names_another_line(data.get("deepLink") if isinstance(data, dict) else None):
        # The 5558's agent spoke, but the event's own (signed) link opens another number's inbox: not this desk's…
        why = "not_this_line"
    if why:
        return _quo_answer(200, ignored=why)

    _hotline_fast_prune(now)
    prior = _HOTLINE_FAST.get(call_id)
    if prior and now - prior["at"] < HOTLINE_FAST_DEDUPE_S and prior.get("stage") != "failed":
        return _quo_answer(200, duplicate=call_id)
    kept = {"call_id": call_id, "event_at": str(event.get("createdAt") or ""), "created": str(obj.get("createdAt") or ""),
            "duration": obj.get("duration"), "dialogue": turns,
            "caller_phones": hotline_desk.caller_phones(turns), "team": hotline_desk.team_phones(turns)}
    # the call is kept and filed by Python (app/hotline*)
    event_at = str(event.get("createdAt") or "")
    _HOTLINE_FAST[call_id] = {"at": now, "stage": "filing"}
    hotline_desk.overlay_put(call_id, at=event_at, duration=kept["duration"] if isinstance(
        kept["duration"], (int, float)) and not isinstance(kept["duration"], bool) else None, dialogue=turns, now=now)
    _keep_task(_hotline_python_file(kept, now, _hotline_event_age_ms(event_at, now)))
    _publish_slice("hotline:calls")
    return _quo_answer(200, accepted=call_id)


async def _hotline_keep_call(call: dict[str, Any], shadow: bool = True) -> bool:
    """A call the webhook handed over, kept in app.hotline_calls by asa-hub-app (hotlineCallKeep) under one write id
    per call, so a second delivery keeps nothing; a call Python did not keep is said, never raised."""
    write_id = "W" + hashlib.sha256(("hotline|" + call["call_id"]).encode()).hexdigest()[:24]
    try:
        got = await _backend_call("hotline", "hotlineCallKeep", call, {"is_service": True},
                                  extra={"write_id": write_id})
        env = got[2] if got is not None else None
        if env is None or env.get("status") != 200:
            log.warning("quo hotline: %s not kept in Postgres (%s)", call["call_id"],
                        _BACKEND_UNANSWERED.get() if env is None else env.get("status"))
            return False
    except Exception as exc:  # noqa: BLE001 - the filing below goes on as it did
        log.warning("quo hotline: %s not kept in Postgres (%s)", call["call_id"], type(exc).__name__)
        return False
    if shadow:
        await _hotline_shadow(call["call_id"])
    return True


async def _hotline_file_once(call_id: str, content: str, via: str, psi: dict[str, Any] | None
                             ) -> tuple[dict[str, Any] | None, bool]:
    """hotlineFile under one write id per call: (its answer, whether a missing answer may still have been kept). A
    deferral kept nothing; a timeout is asked once more under the same id, and its receipt says what was kept."""
    write_id = "W" + hashlib.sha256(("hotline-file|" + call_id).encode()).hexdigest()[:24]
    payload = {"call_id": call_id, "content": content, "via": via, "psi": psi}
    unsure = False
    for _ in (1, 2):
        try:
            got = await _backend_call(HOTLINE_APP, "hotlineFile", payload, {"is_service": True},
                                      extra={"write_id": write_id}, timeout=HUB_APP_PACK_TIMEOUT_S)
        except Exception as exc:  # noqa: BLE001 - asked again under the same id
            log.warning("hotline file: %s not answered (%s)", call_id, type(exc).__name__)
            unsure = True
            continue
        env = got[2] if got is not None else None
        if env is not None:
            return env, False
        if _BACKEND_UNANSWERED.get().startswith("it deferred"):
            return None, unsure
        unsure = True
    return None, unsure


async def _hotline_settle(call_id: str, settle: str, why: str) -> dict[str, Any]:
    """hotlineFile's settling of a call no model is asked about (no_words) or none would answer (blocked, one pass
    counted per call): its answer's data, or {} when it was not answered."""
    key = f"hotline-settle|{call_id}|{settle}" + (f"|{time.time()}" if settle == "blocked" else "")
    write_id = "W" + hashlib.sha256(key.encode()).hexdigest()[:24]
    try:
        got = await _backend_call(HOTLINE_APP, "hotlineFile", {"call_id": call_id, "settle": settle, "why": why},
                                  {"is_service": True}, extra={"write_id": write_id}, timeout=HUB_APP_PACK_TIMEOUT_S)
    except Exception as exc:  # noqa: BLE001 - the inbox pass reads it again
        log.warning("hotline file: %s not settled (%s)", call_id, type(exc).__name__)
        return {}
    env = got[2] if got is not None else None
    if env is None or env.get("status") != 200:
        log.warning("hotline file: %s not settled (%s)", call_id,
                    _BACKEND_UNANSWERED.get() if env is None else env.get("message"))
        return {}
    return env.get("data") or {}


async def _hotline_python_file(kept: dict[str, Any], accepted_at: float, event_age_ms: int | None) -> None:
    """Hotline filing on Python: the call kept, the sweep's orders asked of the model, the PSI check beside it, and
    hotlineFile files every row and page in one write. A call Python could not keep, a filing it refused, or a model
    that would not answer leaves the call to the inbox pass (hotlineInboxDue reads the Transcripts inbox on the clock);
    nothing is handed to Apps Script. Never raises."""
    call_id = kept["call_id"]
    stage = "failed"
    try:
        if not await _hotline_keep_call(kept, shadow=False):
            log.warning("hotline file: %s not kept by Python — left to the inbox pass", call_id)
            return
        psi_task = _hotline_psi_start(kept)
        psi_by = time.monotonic() + (getattr(psi_anywhere, "PSI_FAST_WAIT_S", 2.0) if psi_anywhere is not None else 0.0)
        got = await _backend_call(HOTLINE_APP, "hotlineShadowAsk", {"call_id": call_id}, {"is_service": True},
                                  timeout=HUB_APP_PACK_TIMEOUT_S)
        asked = (got[2] or {}).get("data") if got is not None and (got[2] or {}).get("status") == 200 else None
        if asked is None:
            log.warning("hotline file: %s — the orders could not be built (%s)", call_id, _BACKEND_UNANSWERED.get())
        elif not asked.get("enabled"):
            stage = "dropped"
            if hotline_desk is not None:
                hotline_desk.overlay_drop(call_id)
            return
        if asked and asked.get("no_words"):
            if (await _hotline_settle(call_id, "no_words", "")).get("state") == "nothing_to_file":
                stage = "filed"
                if hotline_desk is not None:
                    hotline_desk.overlay_stage(call_id, "filed", kinds=[], items=0)
                    hotline_desk.invalidate()
                _sheet_sync_wake()
                log.info("hotline file: %s has no words past a greeting — filed with nothing, no model asked", call_id)
            return
        content, via = (await _hotline_model(str(asked.get("ask") or ""))) if asked else ("", "no orders")
        if not content:
            stage = "blocked"
            if hotline_desk is not None:
                hotline_desk.overlay_stage(call_id, "blocked", why="The model would not answer: " + via)
            settled = await _hotline_settle(call_id, "blocked", via) if asked else {}
            if settled.get("state") == "blocked":
                _sheet_sync_wake()
                log.warning("hotline file: %s blocked — %s; left blocked after %s passes", call_id, via,
                            settled.get("tries"))
            else:
                log.warning("hotline file: %s blocked — %s; kept for the inbox pass (pass %s)", call_id, via,
                            settled.get("tries") or "?")
            return
        psi = await _psi_within(psi_task, psi_by) if psi_task is not None else None
        env, unsure = await _hotline_file_once(call_id, content, via, psi)
        if env is None:
            log.warning("hotline file: %s %s — the inbox pass reads it again", call_id,
                        "not known to be kept" if unsure else f"deferred ({_BACKEND_UNANSWERED.get()})")
            return
        data = env.get("data") or {}
        if env.get("status") != 200:
            log.warning("hotline file: %s refused %s (%s) — the inbox pass reads it again", call_id,
                        env.get("status"), str(env.get("message"))[:160])
            return
        stage = "filed"
        if hotline_desk is not None:
            told = data.get("state") == "filed"
            hotline_desk.overlay_stage(call_id, "filed", kinds=data.get("kinds") if told else None,
                                       items=data.get("items") if told else None)
            hotline_desk.invalidate()
        _mark_dirty(HOTLINE_FAST_SLICES)
        _hotline_lanes_stale()
        # its rows reach the books on the keeper's next pass, not its clock's
        _sheet_sync_wake()
        # AND OUR OWN COPY OF WHAT WAS JUST FILED: the lane houses (Hotline.gs laneMirrorAfterFiling_)
        if data.get("state") == "filed" and data.get("kinds"):
            _lane_mirror_after_filing_kick()
        log.info("hotline file: %s %s by Python (%s, %s)", call_id, data.get("state"),
                 ",".join(data.get("kinds") or []) or "no items", via)
    except Exception as exc:  # noqa: BLE001 - the call stays kept; the inbox pass reads it again
        log.warning("hotline file: %s not filed (%s)", call_id, type(exc).__name__)
    finally:
        entry = _HOTLINE_FAST.get(call_id)
        if entry is not None:
            entry["stage"] = stage
        _publish_slice("hotline:calls")


async def _hotline_python_inbox() -> None:
    """hotlineSweep's inbox pass on Python: the calls the inbox holds that nobody filed, each filed as the webhook's
    are. Never raises."""
    try:
        got = await _backend_call(HOTLINE_APP, "hotlineInboxDue", {}, {"is_service": True},
                                  timeout=HUB_APP_PACK_TIMEOUT_S)
        data = (got[2] or {}).get("data") if got is not None and (got[2] or {}).get("status") == 200 else None
        if data is None:
            log.warning("hotline inbox: not read (%s)", _BACKEND_UNANSWERED.get())
            return
        for call in data.get("calls") or []:
            await _hotline_python_file(call, time.time(), None)
    except Exception as exc:  # noqa: BLE001 - the next tick reads it again
        log.warning("hotline inbox: %s", type(exc).__name__)


# Python's own reading of every hotline call, kept beside Apps Script's filing (HUB_HOTLINE_SHADOW=0 stops it)
HOTLINE_SHADOW = os.getenv("HUB_HOTLINE_SHADOW", "1") != "0"


async def _hotline_model(text: str) -> tuple[str, str]:
    """One completion for the hotline's orders — the app's Groq keys first, then the analyze door's own upstreams:
    (content, via) or ('', why)."""
    refusals: list[str] = []
    got = await _backend_call("hotline", "hotlineShadowModel", {"text": text}, {"is_service": True},
                              timeout=HUB_APP_PACK_TIMEOUT_S)
    env = got[2] if got is not None else None
    if env is not None and env.get("status") == 200 and (env.get("data") or {}).get("content"):
        return str(env["data"]["content"]), str(env["data"].get("via") or "groq")
    refusals.append("app " + str(_BACKEND_UNANSWERED.get() if env is None else env.get("message") or env.get("status")))
    deadline = time.monotonic() + ANALYZE_BUDGET_S
    for up in _analyze_upstreams(""):
        for key in up["keys"] or []:
            left = deadline - time.monotonic()
            if left <= 1.0:
                return "", "the model's time ran out"
            try:
                headers = {"Authorization": f"Bearer {key}"} if key else {}
                async with httpx.AsyncClient(timeout=min(90.0, left)) as client:
                    r = await client.post(up["url"], headers=headers, json={
                        "model": up["model"], "temperature": 0.1, "messages": [{"role": "user", "content": text}]})
                if r.status_code >= 400:
                    refusals.append(f"{up['name']} {r.status_code}")
                    continue
                content = (((r.json().get("choices") or [{}])[0].get("message") or {}).get("content")) or ""
                if content:
                    return content, f"{up['name']}/{up['model']}"
                refusals.append(f"{up['name']} empty")
            except Exception as exc:  # noqa: BLE001 - the next upstream is asked
                refusals.append(f"{up['name']} {type(exc).__name__}")
    return "", " | ".join(refusals) or "no upstream"


async def _hotline_shadow(call_id: str) -> None:
    """Python reads a kept call as the sweep would — its orders, the model, the rows each lane would take — and keeps
    that reading beside the call (app.hotline_calls.shadow); nothing is filed. Never raises."""
    if not HOTLINE_SHADOW:
        return
    try:
        service = {"is_service": True}
        got = await _backend_call("hotline", "hotlineShadowAsk", {"call_id": call_id}, service,
                                  timeout=HUB_APP_PACK_TIMEOUT_S)
        env = got[2] if got is not None else None
        if env is None or env.get("status") != 200:
            log.warning("hotline shadow: %s not asked (%s)", call_id,
                        _BACKEND_UNANSWERED.get() if env is None else env.get("message"))
            return
        asked = env["data"]
        if not asked.get("enabled") or asked.get("no_words"):
            return
        content, via = await _hotline_model(str(asked.get("ask") or ""))
        reading: dict[str, Any] = {"via": via, "at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                                   "config_from": asked.get("config_from"), "prompt_from": asked.get("prompt_from"),
                                   "types_from": asked.get("types_from")}
        if content:
            got = await _backend_call("hotline", "hotlineShadowPlan",
                                      {"call_id": call_id, "content": content, "via": via}, service,
                                      timeout=HUB_APP_PACK_TIMEOUT_S)
            planned = got[2] if got is not None else None
            done = (planned or {}).get("data", {}) if (planned or {}).get("status") == 200 else {}
            reading["plan"] = done.get("plan")
            # every row hotlineFile would keep for the call, lane by lane — nothing of it is kept
            reading["filing"] = done.get("filing")
            if not done:
                reading["plan_refused"] = str((planned or {}).get("message") or _BACKEND_UNANSWERED.get())[:300]
            reading["answer"] = content[:20000]
        else:
            reading["blocked"] = via
        write_id = "W" + hashlib.sha256(("hotline-shadow|" + call_id).encode()).hexdigest()[:24]
        await _backend_call("hotline", "hotlineShadowKeep", {"call_id": call_id, "shadow": reading}, service,
                            extra={"write_id": write_id})
        log.info("hotline shadow: %s read by Python (%s)", call_id,
                 ",".join((reading.get("plan") or {}).get("kinds") or []) or reading.get("blocked") or "no items")
    except Exception as exc:  # noqa: BLE001 - the filing goes on as it did
        log.warning("hotline shadow: %s not read (%s)", call_id, type(exc).__name__)


def _hotline_lanes_stale() -> None:
    """A filing just wrote rows: the three sheet lanes' held copies are old, so the Hotline screen's next poll…"""
    if hotline_lanes is None:
        return
    try:
        hotline_lanes.invalidate()
    except Exception as exc:  # noqa: BLE001 - the screen's own poll carries on
        log.warning("hotline lanes: the held copies were not dropped: %s", type(exc).__name__)


async def _hotline_psi_verdict(call: dict[str, Any]) -> dict[str, Any] | None:
    """Was PsiAnywhere up when this call landed?"""
    if psi_anywhere is None or not psi_anywhere.armed():
        return None
    try:
        if not psi_anywhere.sniff(psi_anywhere.dialogue_text(call.get("dialogue"))):
            return None
        return await _psi_app_verdict()
    except Exception as exc:  # noqa: BLE001 - the call files without a verdict, as it always did
        log.warning("quo hotline: the PsiAnywhere check did not run: %s", type(exc).__name__)
        return None


async def _psi_app_verdict(force: bool = False) -> dict[str, Any] | None:
    """The PsiAnywhere verdict as asa-hub-app's POST /psi/health answers it: the check and its login run there alone
    (app/attendance_loop.py), never in this relay. None when it answered without one; raises when it was not reached."""
    if not SERVICE_SECRET:
        return None
    wait = float(getattr(psi_anywhere, "PSI_DOOR_WAIT_S", 3.0)) + 2.0
    async with httpx.AsyncClient(timeout=wait) as client:
        res = await client.post(f"{HUB_APP_URL}/psi/health",
                                json={"service_secret": SERVICE_SECRET, **({"fresh": True} if force else {})})
    env = res.json() if res.status_code == 200 else None
    if isinstance(env, dict) and env.get("status") == 200 and isinstance(env.get("data"), dict):
        return env["data"]
    return None


def _hotline_psi_start(call: dict[str, Any]) -> asyncio.Task | None:
    """Begin the check BESIDE the filing, or answer None when this call is not about PsiAnywhere."""
    if psi_anywhere is None or not psi_anywhere.armed():
        return None
    try:
        if not psi_anywhere.sniff(psi_anywhere.dialogue_text(call.get("dialogue"))):
            return None
    except Exception:  # noqa: BLE001 - a sniff that throws is not a PSI call
        return None
    return _keep_task(_hotline_psi_verdict(call))


async def _psi_within(task: asyncio.Task | None, deadline: float) -> dict[str, Any] | None:
    """The verdict if it is ready by `deadline` (a monotonic stamp), else None."""
    if task is None:
        return None
    if not task.done():
        left = deadline - time.monotonic()
        if left <= 0:
            return None
        await asyncio.wait({task}, timeout=left)
    if not task.done() or task.cancelled():
        return None
    try:
        got = task.result()
    except Exception as exc:  # noqa: BLE001 - the caller carries on without a verdict
        log.warning("psi anywhere: the check did not come back: %s", type(exc).__name__)
        return None
    return got if isinstance(got, dict) else None


def _hotline_fast_armed() -> bool:
    """Would a signed 5558 event be filed by Python as it lands?"""
    return bool(_quo_hotline_keys() and hotline_desk is not None)


def _hotline_fast_health() -> dict[str, Any]:
    """/health is public: nothing here names a call or moves when one happens."""
    return {"armed": _hotline_fast_armed()}


async def _hotline_stream_allowed(authorization: str, token: str) -> tuple[str, float]:
    """This session at the hotline doors' Smart Comms gate, held per token: (open | shut | retry, until when that…"""
    now = time.time()
    held = _HOTLINE_STREAM_GATE.get(token)
    if held and now - held[0] < held[2]:
        hit = _auth_cache.get(token)
        if held[1] != "open" or (hit and hit[1]):
            return held[1], held[0] + held[2]
    try:
        actor = await _hotline_actor(authorization)
    except Exception as exc:  # noqa: BLE001 - a gate that throws stays shut
        log.warning("hotline stream: access check failed: %s", type(exc).__name__)
        actor = {"status": 403, "reason": "unreadable"}
    if not isinstance(actor, dict):
        verdict = "open"
    elif str(actor.get("reason") or "") in ("unreadable", "stale", "session"):
        # A session refusal may be the auth cache's brief busy-backend hold on a stream that opened signed in; held…
        verdict = "retry"
    else:
        verdict = "shut"
    held_for = HOTLINE_STREAM_GATE_RETRY_S if verdict == "retry" else HOTLINE_STREAM_GATE_TTL_S
    if len(_HOTLINE_STREAM_GATE) > 5000:
        _HOTLINE_STREAM_GATE.clear()
    at = time.time()
    _HOTLINE_STREAM_GATE[token] = (at, verdict, held_for)
    return verdict, at + held_for


async def _events_tag_hotline(queue: asyncio.Queue, authorization: str, token: str) -> None:
    """Tag a stream for hotline names while its session passes the gate."""
    queue.hotline_checking = True  # type: ignore[attr-defined]
    try:
        if not token:
            return
        queue.hotline_auth = (authorization, token)  # type: ignore[attr-defined]
        while queue in _event_subs:
            verdict, until = await _hotline_stream_allowed(authorization, token)
            if verdict == "open":
                queue.hotline, queue.hotline_until = True, until  # type: ignore[attr-defined]
                try:
                    queue.put_nowait("hotline:calls")
                except asyncio.QueueFull:
                    pass
                return
            queue.hotline, queue.hotline_until = False, 0.0  # type: ignore[attr-defined]
            if verdict != "retry":
                return
            # a hair past the held refusal, so the next ask is a fresh one
            await asyncio.sleep(max(HOTLINE_STREAM_GATE_RETRY_S, until - time.time()) + 0.05)
    finally:
        queue.hotline_checking = False  # type: ignore[attr-defined]


def _hotline_tag_live(queue: Any, now: float) -> bool:
    """May this stream hear a `hotline:` name now?"""
    if getattr(queue, "hotline", False) is not True:
        return False
    auth = getattr(queue, "hotline_auth", None)
    hit = _auth_cache.get(auth[1]) if auth else None
    if float(getattr(queue, "hotline_until", 0.0) or 0.0) > now and not (hit and not hit[1]):
        return True
    queue.hotline, queue.hotline_until = False, 0.0
    if auth and not getattr(queue, "hotline_checking", False) and queue in _event_subs:
        queue.hotline_checking = True
        _keep_task(_events_tag_hotline(queue, *auth))
    return False


# --------------------------------------------------------------------------- THE MESSAGES WEBHOOK, KEPT HERE FIRST…
QUO_HANDOFF_EVERY_S = 60.0
# The relay waits this long for one batch.
QUO_HANDOFF_TIMEOUT_S = 330
# HOW LONG AN EXECUTION THIS RELAY STARTED CAN STILL BE RUNNING, written down before every post…
QUO_HANDOFF_HOLD_S = 2 * QUO_HANDOFF_TIMEOUT_S + 120
# The pull's first round waits for startup to settle.
QUO_PULL_FIRST_S = 90.0
# A refusal of the whole batch is said once per this, not once a pass.
QUO_HANDOFF_SAY_EVERY_S = 3600.0
# quoCommCallsKick_: where a transcript filed live is posted — the phone-call lane's own door, this relay's, asked
# on its own port rather than round the public domain
QUO_CALLS_KICK_URL = os.getenv("HUB_QUO_CALLS_KICK_URL", "http://127.0.0.1:8080/comm-calls/transcript")
_QUO_HANDOFF_WAKE = asyncio.Event()
_QUO_HANDOFF_SAID: dict[str, Any] = {"key": None, "at": 0.0}


def _quo_handoff_wake() -> None:
    """On the event loop only: an arrival asks for the next hand-off now."""
    _QUO_HANDOFF_WAKE.set()


async def _quo_messages_event(raw: bytes, header: str) -> Response:
    """An event the messages key signed: kept, answered, handed over later."""
    age = _quo_stamp_age_s(header, time.time())
    try:
        status, fields = await asyncio.to_thread(quo_inbox.accept_webhook, raw, age)
    except Exception as exc:  # noqa: BLE001 - nothing kept: Quo must deliver it again
        log.warning("quo inbox: an event could not be kept (%s) — answered 503 so Quo delivers it again",
                    type(exc).__name__)
        return _quo_answer(503, message="Not kept.")
    if status == 401:
        log.warning("quo inbox: refused a stale event (%s)",
                    "no stamp" if age is None else f"stamped {age:.0f}s ago")
    elif fields.get("kept") == "added":
        _quo_handoff_wake()
        # the reply ear hears it now, not at the next minute
        _sms_ears_wake()
    return _quo_answer(status, **fields)


@app.post("/quo/webhook")
async def quo_webhook(request: Request) -> Response:
    """A Quo event signed by a key the relay holds on disk: verified here, kept in the inbox, filed later."""
    raw = await request.body()
    header = request.headers.get("openphone-signature", "")
    hotline_keys = _quo_hotline_keys()
    if hotline_keys and _quo_signature_ok(raw, header, hotline_keys):
        return await _quo_hotline_event(raw, header)
    # the messages webhook's events are kept by asa-hub-app (app/clocks.py): never in this relay's inbox
    message_keys: list[str] = []
    if message_keys and _quo_signature_ok(raw, header, message_keys):
        return await _quo_messages_event(raw, header)
    # every webhook that reaches this door signs with a key held on disk: one neither file verifies is refused here
    if not (hotline_keys or message_keys):
        return Response(content=json.dumps(
            {"status": 503, "message": "The webhook keys are not readable."}),
            status_code=503, media_type="application/json")
    log.warning("quo webhook: refused an event with %s signature",
                "no" if not header else "a bad")
    return Response(content=json.dumps({"status": 401, "message": "Unverified."}),
                    status_code=401, media_type="application/json")


# -------------------------------------------------------------------------- STAFF DAILY NOTES — what the DSPs told…
try:
    import daily_notes
except Exception as _daily_import_exc:  # noqa: BLE001
    daily_notes = None  # type: ignore[assignment]
    log.warning("daily notes unavailable, their doors answer 503: %s", _daily_import_exc)

_DAILY_REASONS = ("session", "badge", "stale", "unreadable", "restricted")


def _daily_refusal(envelope: dict[str, Any]) -> dict[str, Any]:
    """A gate's refusal with its `reason`, named here when the gate did not."""
    if envelope.get("reason") in _DAILY_REASONS:
        return envelope
    status = envelope.get("status")
    if status == 401:
        reason = "session"
    elif status == 403:
        text = str(envelope.get("message") or "").lower()
        reason = ("session" if "no account" in text else "stale" if "too old" in text
                  else "unreadable" if ("could not be read" in text or "cannot be read" in text)
                  else "badge")
    else:
        reason = "unreadable"
    return {**envelope, "reason": reason}


async def _daily_book() -> dict[str, Any]:
    return await daily_notes.current_book(
        hotline_desk.sheets_client, PG_DSN, str(OUT_DIR / "clients.json"))


@app.get("/hub-lanes/hotline/daily-notes")
async def lane_hotline_daily_notes(authorization: str = Header(default="")) -> dict[str, Any]:
    """Every staff daily note, newest first, with its client, its shift and each source's health beside it."""
    gate = globals().get("_hotline_actor")
    if gate is None:
        return {"status": 503, "reason": "unreadable",
                "message": "The hotline desk gate is not loaded on this server."}
    actor = await gate(authorization)
    if isinstance(actor, dict):
        return _daily_refusal(actor)
    if daily_notes is None or hotline_desk is None:
        return {"status": 503, "reason": "unreadable",
                "message": "The daily notes reader is not loaded on this server."}
    try:
        book = await _daily_book()
    except daily_notes.BookUnavailable as exc:
        return {"status": 503, "reason": "unreadable", "message": str(exc)}
    except Exception as exc:  # noqa: BLE001
        log.warning("daily notes: book unavailable: %s", type(exc).__name__)
        return {"status": 503, "reason": "unreadable",
                "message": f"The daily notes could not be read ({type(exc).__name__})."}
    return {"status": 200, "data": book["payload"]}


@app.get("/hub-lanes/clients/daily")
async def lane_clients_daily(client: str = "", authorization: str = Header(default="")) -> dict[str, Any]:
    """The staff daily notes matched to one client, for the client's record."""
    gate = globals().get("_hotline_actor")
    if gate is None:
        return {"status": 503, "reason": "unreadable",
                "message": "The access gate is not loaded on this server."}
    # The roles are written out here, not borrowed from daily_notes: a reader that failed to import must not turn…
    actor = await gate(authorization, app_id="clients",
                       refuse_roles=("client", "guardian", "onboarding", "interviewer"),
                       app_label="Client Care")
    if isinstance(actor, dict):
        return _daily_refusal(actor)
    if daily_notes is None or hotline_desk is None:
        return {"status": 503, "reason": "unreadable",
                "message": "The daily notes reader is not loaded on this server."}
    try:
        refusal = await asyncio.to_thread(
            daily_notes.types_refusal, PG_DSN, HUB_DB_SHEET_ID, actor[1], MIRROR_TRUST_MAX_S,
            is_master=_auth_master.get(_hotline_token(authorization)))
    except Exception as exc:  # noqa: BLE001 - a check that throws stays shut
        log.warning("daily notes: types check failed: %s", type(exc).__name__)
        return {"status": 403, "reason": "unreadable",
                "message": f"The access check failed ({type(exc).__name__}), so the door stays closed."}
    if refusal is not None:
        return _daily_refusal(refusal)
    wanted = " ".join(str(client or "").split())
    if not wanted:
        return {"status": 400, "message": "Say which client: ?client=<the client's name>."}
    try:
        book = await _daily_book()
        data = daily_notes.client_view(book, wanted)
    except daily_notes.ClientNotFound:
        return {"status": 404, "message": "That client is not in the clients list."}
    except daily_notes.BookUnavailable as exc:
        return {"status": 503, "reason": "unreadable", "message": str(exc)}
    except Exception as exc:  # noqa: BLE001
        log.warning("daily notes: client view unavailable: %s", type(exc).__name__)
        return {"status": 503, "reason": "unreadable",
                "message": f"The daily notes could not be read ({type(exc).__name__})."}
    log.info("client daily notes read: %d note(s) by %s", len(data["notes"]), actor[1])
    return {"status": 200, "data": data}


@app.post("/smart-comms/rpc")
async def smart_comms_rpc(request: Request) -> Response:
    """Apps Script's rpcCall_ handing one message to Python's send door while Smart Comms' sending is Python's
    (`comms-send`): {python: true, answer: rpcCall_'s answer}; {python: false} while Apps Script still sends."""
    def said(env: dict[str, Any], code: int = 200) -> Response:
        return Response(content=json.dumps(env), status_code=code, media_type="application/json")

    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        body = {}
    got = str((body or {}).get("service_secret") or "")
    if not SERVICE_SECRET or not hmac.compare_digest(got, SERVICE_SECRET):
        return said({"status": 401, "message": "Authentication required."}, 401)
    if not await _backend_wanted(COMMS_SEND_APP):
        return said({"status": 200, "data": {"python": False}})
    method = str((body or {}).get("method") or "")
    ask = {"method": method, "params": (body or {}).get("params") if isinstance((body or {}).get("params"), dict)
           else {}, "opts": (body or {}).get("opts") if isinstance((body or {}).get("opts"), dict) else {}}
    write_id = "W" + hashlib.sha256(f"comms-rpc|{time.time_ns()}".encode()).hexdigest()[:24]
    done = await _backend_call(COMMS_SEND_APP, "commsRpc", ask, {"is_service": True}, extra={"write_id": write_id})
    env = done[2] if done is not None else None
    if env is None or env.get("status") != 200 or not isinstance(env.get("data"), dict):
        if env is None:
            _backend_settle_soon(COMMS_SEND_APP, write_id, "void")
        log.warning("smart comms rpc: %s not decided by Python (%s) — nothing sent", method,
                    _BACKEND_UNANSWERED.get() if env is None else env.get("status"))
        return said({"status": 200, "data": {"python": True, "answer": {
            "ok": False, "sent": False, "gated": False, "method": method, "error": "transport",
            "detail": "The platform's sender did not answer — nothing was sent."}}})
    _traffic_note("backend_python")
    return said({"status": 200, "data": {"python": True, "answer": env["data"]}})


@app.post("/isp/decode")
async def isp_decode(request: Request) -> Response:
    """OhioISP plan text in, the seventeen flat fields out."""
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        body = {}
    got = str((body or {}).get("service_secret") or "")
    if not SERVICE_SECRET or not hmac.compare_digest(got, SERVICE_SECRET):
        return Response(content=json.dumps({"status": 401, "message": "Authentication required."}),
                        status_code=401, media_type="application/json")
    text = str((body or {}).get("text") or "")
    pdf_b64 = str((body or {}).get("pdf_b64") or "")
    if not text and not pdf_b64:
        return Response(content=json.dumps(
            {"status": 400, "message": "Send the plan: `pdf_b64` or `text`."}),
            status_code=400, media_type="application/json")
    try:
        import isp_decode as _isp
        if pdf_b64:
            # THE BYTES COME OVER THE WIRE because the sweep has the account's hands and this process does not.
            raw = await asyncio.to_thread(base64.b64decode, pdf_b64)
            nested, text = await asyncio.to_thread(_isp_from_pdf, raw)
        else:
            nested = await asyncio.to_thread(_isp.parse_isp_text, text, prune=False)
        flat = _isp.flatten(nested)
    except Exception as exc:  # noqa: BLE001
        log.warning("isp decode failed: %s", str(exc)[:200])
        return Response(content=json.dumps(
            {"status": 500, "message": "The plan could not be read: " + str(exc)[:140]}),
            status_code=500, media_type="application/json")
    return Response(content=json.dumps({"status": 200, "data": {
        "fields": flat, "pages": text.count("\f") + 1 if text else 0,
        "chars": len(text), "raw_text": text}}),
        status_code=200, media_type="application/json")


