# --------------------------------------------------------------------------- Weather — one shared forecast for the…
_WEATHER_LAT, _WEATHER_LON = 39.9612, -82.9988  # Columbus, OH
_WEATHER_TTL = 1800.0
_weather_cache: dict[str, Any] = {"at": 0.0, "data": None}


def _weather_icon(code: int) -> str:
    """WMO weather_code → the small vocabulary the UI draws."""
    if code == 0:
        return "sun"
    if code in (1, 2):
        return "partsun"
    if code == 3:
        return "cloud"
    if code in (45, 48):
        return "fog"
    if code in (56, 57, 66, 67):
        return "sleet"
    if 51 <= code <= 65 or 80 <= code <= 82:
        return "rain"
    if 71 <= code <= 77 or code in (85, 86):
        return "snow"
    if code >= 95:
        return "storm"
    return "cloud"


@app.get("/weather")
async def weather() -> dict[str, Any]:
    now = time.time()
    if _weather_cache["data"] is not None and now - _weather_cache["at"] < _WEATHER_TTL:
        return {"status": 200, "data": _weather_cache["data"]}
    url = (
        "https://api.open-meteo.com/v1/forecast"
        f"?latitude={_WEATHER_LAT}&longitude={_WEATHER_LON}"
        "&daily=weather_code,temperature_2m_max,temperature_2m_min,"
        "precipitation_probability_max"
        "&current=temperature_2m,weather_code,relative_humidity_2m,wind_speed_10m"
        "&temperature_unit=fahrenheit&wind_speed_unit=mph"
        "&timezone=America%2FNew_York&forecast_days=16"
    )
    try:
        async with httpx.AsyncClient(timeout=12.0) as client:
            resp = await client.get(url)
            resp.raise_for_status()
            raw = resp.json()
    except Exception as exc:  # noqa: BLE001
        log.warning("weather: upstream failed (%s)", type(exc).__name__)
        if _weather_cache["data"] is not None:
            # stale is better than blank on a day-cell icon
            return {"status": 200, "data": _weather_cache["data"]}
        return {"status": 502, "message": f"forecast unavailable ({type(exc).__name__})"}
    daily = raw.get("daily") or {}
    dates = daily.get("time") or []
    codes = daily.get("weather_code") or []
    tmax = daily.get("temperature_2m_max") or []
    tmin = daily.get("temperature_2m_min") or []
    rain = daily.get("precipitation_probability_max") or []
    days = []
    for i, d in enumerate(dates):
        code = int(codes[i]) if i < len(codes) and codes[i] is not None else 3
        days.append({
            "date": str(d),
            "code": code,
            "icon": _weather_icon(code),
            "tmax": round(tmax[i]) if i < len(tmax) and tmax[i] is not None else None,
            "tmin": round(tmin[i]) if i < len(tmin) and tmin[i] is not None else None,
            "rain": int(rain[i]) if i < len(rain) and rain[i] is not None else 0,
        })
    cur = raw.get("current") or {}
    cur_code = int(cur.get("weather_code") or 3)
    data = {
        "place": "Columbus, OH",
        "now": {
            "temp": round(cur.get("temperature_2m")) if cur.get("temperature_2m") is not None else None,
            "code": cur_code,
            "icon": _weather_icon(cur_code),
            "humidity": cur.get("relative_humidity_2m"),
            "wind": round(cur.get("wind_speed_10m")) if cur.get("wind_speed_10m") is not None else None,
        },
        "days": days,
        "fetched_at": int(now),
    }
    _weather_cache["at"] = now
    _weather_cache["data"] = data
    return {"status": 200, "data": data}


# Write lanes on the person's own session; House Calendars asks one law per house (_housecal_viewer).

async def _session_actor(authorization: str) -> tuple[str, str] | None:
    """(role, uid) for a live session, or None."""
    token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
    _SESSION_ACTING.set(False)
    if not token:
        return None
    hit = _auth_cache.get(token)
    if hit and time.time() - hit[0] < AUTH_TTL_SECONDS:
        _SESSION_ACTING.set(bool(hit[1]) and _my_work_acting(token))
        return (str(hit[2]), str(hit[3]) if len(hit) > 3 else "") if hit[1] else None
    verdict = await asyncio.to_thread(_session_verdict, token)
    if verdict is None:
        return None
    ok, role, uid = verdict
    _SESSION_ACTING.set(bool(ok) and _my_work_acting(token))
    return (str(role), str(uid)) if ok else None


