@app.get("/hub-lanes/shift-handoff/candidates")
async def lane_handoff_candidates(location: str = "", col_iso: str = "", from_staff: str = "",
                                 authorization: str = Header(default="")) -> dict[str, Any]:
    """The transfer picker's names (shift_handoff.candidates), weighed as the offer will weigh them."""
    got = await _housecal_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, _actor = got
    location, col_iso = location.strip(), col_iso.strip()
    if not location or not col_iso:
        return {"status": 400, "message": "location and col_iso are required"}
    me = str(who.get("name") or "")
    giver = from_staff.strip() or me
    if not giver:
        return {"status": 403, "message": "this account is not on a roster — ask your manager"}
    refused_open = await _handoff_may_open(who, location, giver,
                                           "you can transfer your own shifts — somebody else's is "
                                           "opened by the manager of THAT house, and by nobody else")
    if refused_open:
        return refused_open
    reachable, why = await asyncio.to_thread(_reachable_names)
    try:
        # `detail` (why a coworker cannot take it) is for the house's editor only
        data = await asyncio.to_thread(shift_handoff.candidates, PG_DSN, location=location,
                                       col_iso=col_iso, giver=giver, reachable=reachable,
                                       reachable_why=why,
                                       detail=shift_requests.may_edit_calendar(who, location),
                                       offered_by=me)
    except Exception as exc:  # noqa: BLE001
        return _handoff_refusal(exc)
    return {"status": 200, "data": data}


def _jsonable(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Timestamps as strings. A datetime in a JSON body is a 500 nobody reads."""
    out = []
    for r in rows:
        out.append({k: (v.isoformat() if hasattr(v, "isoformat") else v) for k, v in r.items()})
    return out


@app.post("/hub-lanes/shift-handoff")
async def lane_handoff_offer(request: Request,
                            authorization: str = Header(default="")) -> dict[str, Any]:
    """Offer a shift to somebody else; nothing moves until all three approve. `from_staff` only for that house's manager."""
    got = await _housecal_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}
    location = str(body.get("location") or "").strip()
    col_iso = str(body.get("col_iso") or "").strip()
    to_staff = str(body.get("to_staff") or "").strip()
    if not location or not col_iso or not to_staff:
        return {"status": 400, "message": "location, col_iso and to_staff are required"}
    me = str(who.get("name") or "")
    giver = str(body.get("from_staff") or "").strip() or me
    if not giver:
        return {"status": 403, "message": "this account is not on a roster — ask your manager"}
    refused_open = await _handoff_may_open(who, location, giver,
                                           "you can only transfer your own shift — a colleague's is "
                                           "opened by the manager of that house")
    if refused_open:
        return refused_open
    reachable, _why = await asyncio.to_thread(_reachable_names)
    try:
        row = await asyncio.to_thread(
            shift_handoff.offer, PG_DSN, location=location, col_iso=col_iso,
            from_staff=giver, to_staff=to_staff, offered_by=me or f"account {actor[1]}",
            created_by=str(actor[1]), reachable=reachable)
    except Exception as exc:  # noqa: BLE001
        if isinstance(exc, shift_handoff.Refused) and exc.code in ("overlap", "time_off") \
                and not shift_requests.may_edit_calendar(who, location):
            # which commitment is in the way is for the house's editor only
            return {"status": 409, "reason": "unavailable", "data": {},
                    "message": f"{to_staff} cannot take this shift — they are not free then"}
        return _handoff_refusal(exc)
    log.info("hub-lanes: handoff %s offered %s -> %s by %s (%s)", row["id"], giver,
             row["to_staff"], actor[1], row.get("approval_why") or "")
    _notices_wake()
    _housecal_rang()
    return {"status": 200, "data": _jsonable([shift_handoff.describe(row, who)])[0]}


@app.post("/hub-lanes/shift-handoff/answer")
async def lane_handoff_answer(request: Request,
                             authorization: str = Header(default="")) -> dict[str, Any]:
    """Answer a transfer from the app, through the same function as SMS replies; the side is the session's."""
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}
    hid = str(body.get("handoff_id") or "").strip()
    word = shift_handoff.read_word(body.get("word") or body.get("answer") or "")
    if not hid or word not in ("yes", "no"):
        return {"status": 400, "message": "handoff_id and a yes or no are required"}
    try:
        row = await asyncio.to_thread(shift_handoff.handoff, PG_DSN, hid)
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"handoff unreadable ({type(exc).__name__})"}
    if not row:
        return {"status": 404, "message": "no such handoff"}
    side = shift_handoff.side_for(who, row)
    if not side:
        return {"status": 403, "message": ("that transfer is not waiting on you — only the person "
                                           "offered the shift accepts it, and its house manager "
                                           "and director each approve it")}
    try:
        res = await asyncio.to_thread(shift_handoff.answer, PG_DSN, row["id"], side=side,
                                      word=word, via="app",
                                      by=str(who.get("name") or f"account {actor[1]}"),
                                      master=who.get("is_master") is True)
    except Exception as exc:  # noqa: BLE001
        return _handoff_refusal(exc)
    log.info("hub-lanes: handoff %s %s said %s by %s -> %s", row["id"], side, word, actor[1],
             res.get("state"))
    _notices_wake()
    _housecal_rang()
    after = await _housecal_after(str(res["location"]), who)
    return {"status": 200, "data": {**_jsonable([shift_handoff.describe(res, who)])[0],
                                    "changed": bool(res.get("changed")),
                                    "computed": after["computed"]}}


@app.post("/hub-lanes/shift-handoff/withdraw")
async def lane_handoff_withdraw(request: Request,
                               authorization: str = Header(default="")) -> dict[str, Any]:
    """Withdraw a transfer; its cell, receiver and training approval are released."""
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}
    hid = str(body.get("handoff_id") or "").strip()
    if not hid:
        return {"status": 400, "message": "handoff_id is required"}
    try:
        row = await asyncio.to_thread(shift_handoff.handoff, PG_DSN, hid)
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"handoff unreadable ({type(exc).__name__})"}
    if not row:
        return {"status": 404, "message": "no such handoff"}
    if not shift_handoff.may_withdraw(who, row):
        return {"status": 403, "message": ("only the person giving the shift, and this house's "
                                           "manager and those above, withdraw a transfer")}
    name = str(who.get("name") or f"account {actor[1]}")
    try:
        res = await asyncio.to_thread(shift_handoff.withdraw, PG_DSN, row["id"], by=name)
    except Exception as exc:  # noqa: BLE001
        return _handoff_refusal(exc)
    log.info("hub-lanes: handoff %s withdrawn by %s", row["id"], actor[1])
    # a withdrawn offer is a swap that ended: its notice is derived from the row
    _notices_wake()
    _housecal_rang()
    return {"status": 200, "data": _jsonable([shift_handoff.describe(res, who)])[0]}


# Requests: gated by the session, not the app matrix (caregivers apply here); the badge question and the private…

_REQUESTS_REFUSED = "Requests is the staff's screen"


async def _requests_viewer(authorization: str) -> tuple[dict[str, Any], tuple[str, str]] | dict[str, Any]:
    """(who is reading, the session) or a refusal envelope."""
    actor = await _session_actor(authorization)
    if not actor:
        return {"status": 401, "message": "sign in first"}
    # an unreadable name is not "not on a roster"
    try:
        name = await asyncio.to_thread(_roster_name_of, actor[1], strict=True)
    except Exception as exc:  # noqa: BLE001
        log.warning("shift requests: the roster name could not be read (%s)", type(exc).__name__)
        return {"status": 502, "message": f"your roster name could not be read ({type(exc).__name__})"}
    badges = await asyncio.to_thread(_user_badges, actor[1])
    who = await asyncio.to_thread(
        shift_requests.viewer, PG_DSN, name=name, role=actor[0], types=badges,
        is_master=_auth_master.get(_hotline_token(authorization)))
    return who, actor


@app.get("/hub-lanes/shift-requests")
async def lane_shift_requests(authorization: str = Header(default="")) -> dict[str, Any]:
    """The Requests screen, whole. Every panel on it is decided here."""
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, _actor = got
    if not shift_requests.may_read_requests(who):
        return {"status": 403, "message": _REQUESTS_REFUSED}
    try:
        data = await asyncio.to_thread(shift_requests.feed, PG_DSN, who=who)
    except Exception as exc:  # noqa: BLE001
        log.warning("shift requests: the feed failed (%s)", type(exc).__name__)
        return {"status": 502, "message": f"requests unreadable ({type(exc).__name__})"}
    # the rehearsal doors' own gate, so the tab is drawn for exactly who they open to
    data["rehearsal"] = _rehearsal_refusal(authorization) is None
    return {"status": 200, "data": data}


@app.get("/hub-lanes/shift-requests/detail")
async def lane_shift_requests_detail(ref: str = "",
                                    authorization: str = Header(default="")) -> dict[str, Any]:
    """One pooled shift as the Requests panel opens it (shift_requests.shift_detail), cut for the reader."""
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, _actor = got
    if not shift_requests.may_read_requests(who):
        return {"status": 403, "message": _REQUESTS_REFUSED}
    ref = str(ref or "").strip()
    if not shift_requests.REF_RE.fullmatch(ref):
        return {"status": 400, "message": "ref is required"}
    try:
        data = await asyncio.to_thread(shift_requests.shift_detail, PG_DSN, who=who, ref=ref)
    except shift_requests.Refused as exc:
        return {"status": 404 if exc.code == "no_such_shift" else 403, "message": exc.why,
                "code": exc.code}
    except Exception as exc:  # noqa: BLE001
        log.warning("shift requests: the detail failed (%s)", type(exc).__name__)
        return {"status": 502, "message": f"this shift could not be read ({type(exc).__name__})"}
    return {"status": 200, "data": data}


@app.post("/hub-lanes/shift-requests/apply")
async def lane_shift_requests_apply(request: Request,
                                   authorization: str = Header(default="")) -> dict[str, Any]:
    """Put a name down for an open or a called-off shift."""
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}
    # THE SHIFT IS NAMED BY ITS REF WHEREVER ONE WAS GIVEN, and the row it belongs to is read out of the pool HERE.
    ref = str(body.get("ref") or "").strip()
    location = str(body.get("location") or "").strip()
    open_row = str(body.get("open_row") or "OPEN").strip()
    col_iso = str(body.get("col_iso") or "").strip()
    if ref:
        found = await asyncio.to_thread(shift_requests.by_ref, PG_DSN, ref)
        if not found:
            return {"status": 404, "message": "that shift is not open"}
        location, open_row, col_iso = found
    if not location or not col_iso:
        return {"status": 400, "message": "location and col_iso are required"}
    mine = str(who.get("name") or "")
    wanted = str(body.get("person") or "").strip()
    # THE DESK IS A HOUSE QUESTION, NEVER A ROLE ONE.
    desk = shift_requests.may_decide(who, location)
    if wanted and not desk and wanted.casefold() != mine.casefold():
        return {"status": 403, "message": "you can only apply for yourself"}
    person = wanted or mine
    if not person:
        return {"status": 403,
                "message": "this account is not on a roster — ask your manager"}
    # the road is the server's to say: this door is the app
    try:
        row = await asyncio.to_thread(
            shift_requests.apply_for, PG_DSN, location=location, open_row=open_row,
            col_iso=col_iso, person=person, via="app")
    except shift_requests.Refused as exc:
        return {"status": 409, "reason": exc.code, "message": exc.why, "data": exc.extra}
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"the application failed ({type(exc).__name__})"}
    log.info("hub-lanes: shift request %s / %s / %s by %s (%s) — %s", location, open_row,
             col_iso, person, actor[1],
             "applied" if row.get("applied") else "already applied")
    if row.get("applied"):
        _notices_wake()
        _housecal_rang()
    # a call-off's `open_row` (the caller) never rides back to an applicant
    if not shift_requests.sees_callers(who, location):
        row = {k: v for k, v in row.items() if k != "open_row"}
    return {"status": 200, "data": _jsonable([row])[0]}


@app.post("/hub-lanes/shift-requests/withdraw")
async def lane_shift_requests_withdraw(request: Request,
                                      authorization: str = Header(default="")) -> dict[str, Any]:
    """Take a name back off. The row stays on the list, as history."""
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}
    rid = str(body.get("request_id") or "").strip()
    if not rid:
        return {"status": 400, "message": "request_id is required"}
    # WITHDRAWING SOMEBODY ELSE'S APPLICATION IS THEIR HOUSE'S DESK, and the house is the ROW's, not the body's: a…
    owner = await asyncio.to_thread(shift_requests.request_row, PG_DSN, rid)
    desk = bool(owner) and shift_requests.may_decide(who, str(owner.get("location") or ""))
    try:
        row = await asyncio.to_thread(shift_requests.withdraw, PG_DSN, request_id_=rid,
                                      person="" if desk else str(who.get("name") or ""))
    except shift_requests.Refused as exc:
        return {"status": 409, "reason": exc.code, "message": exc.why}
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"the withdrawal failed ({type(exc).__name__})"}
    log.info("hub-lanes: shift request %s withdrawn (%s)", rid, actor[1])
    _notices_wake()
    _housecal_rang()
    if not shift_requests.sees_callers(who, str(row.get("location") or "")):
        row = {k: v for k, v in row.items() if k != "open_row"}
    return {"status": 200, "data": _jsonable([row])[0]}


@app.post("/hub-lanes/shift-requests/decide")
async def lane_shift_requests_decide(request: Request,
                                    authorization: str = Header(default="")) -> dict[str, Any]:
    """The house manager's word: this person takes the shift."""
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}
    ref = str(body.get("ref") or "").strip()
    location = str(body.get("location") or "").strip()
    open_row = str(body.get("open_row") or "OPEN").strip()
    col_iso = str(body.get("col_iso") or "").strip()
    person = str(body.get("person") or "").strip()
    how = "assigned" if body.get("assign") else "approved"
    if ref:
        found = await asyncio.to_thread(shift_requests.by_ref, PG_DSN, ref)
        if not found:
            return {"status": 404, "message": "that shift is not in the pool"}
        location, open_row, col_iso = found
    if not location or not col_iso or not person:
        return {"status": 400, "message": "location, col_iso and person are required"}
    if not shift_requests.may_decide(who, location):
        return {"status": 403,
                "message": ("only this house's manager decides who takes its shifts — the "
                            "hotline calendar's ** row for it, and the administrators")}
    try:
        out = await asyncio.to_thread(
            shift_requests.decide, PG_DSN, location=location, open_row=open_row,
            col_iso=col_iso, person=person, by=str(who.get("name") or actor[1]), how=how)
    except shift_requests.Refused as exc:
        return {"status": 409, "reason": exc.code, "message": exc.why, "data": exc.extra}
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"the decision failed ({type(exc).__name__})"}
    log.info("hub-lanes: shift request decided %s / %s / %s → %s (%s) by %s", location,
             open_row, col_iso, person, how, actor[1])
    _notices_wake()
    _housecal_rang()
    # the whole house rides back, as this decider may see it
    return {"status": 200, "data": {**out, **await _housecal_after(location, who)}}


@app.post("/hub-lanes/shift-requests/training")
async def lane_shift_requests_training(request: Request,
                                      authorization: str = Header(default="")) -> dict[str, Any]:
    """A house manager takes the training on or not; approve is 409 trainer_busy / trainer_unreadable without a free trainer."""
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}
    rid = str(body.get("request_id") or "").strip()
    word = "yes" if str(body.get("word") or "yes").strip().lower() in ("yes", "y", "approve") else "no"
    if not rid:
        return {"status": 400, "message": "request_id is required"}
    # THE HOUSE IS THE ROW'S.
    owner = await asyncio.to_thread(shift_requests.request_row, PG_DSN, rid)
    if not owner:
        return {"status": 404, "message": "that training approval is not waiting"}
    location = str(owner.get("location") or "")
    if not shift_requests.may_decide(who, location):
        return {"status": 403, "message": "only this house's manager may take its training on"}
    try:
        row = await asyncio.to_thread(shift_requests.approve_training, PG_DSN,
                                      request_id_=rid, by=str(who.get("name") or actor[1]),
                                      word=word, location=location)
    except shift_requests.Refused as exc:
        return {"status": 409, "reason": exc.code, "message": exc.why, "data": exc.extra}
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"the approval failed ({type(exc).__name__})"}
    trains = str((row.get("trainer") or {}).get("name") or "")
    log.info("hub-lanes: training approval %s said %s by %s%s", rid, word, actor[1],
             f" — {trains} trains" if trains else "")
    # a swap's training answer is also the swap's approval (shift_handoff.training_answered)
    swap = None
    if str(owner.get("ref") or "") == shift_requests.KIND_SWAP:
        try:
            got_swap = await asyncio.to_thread(shift_handoff.training_answered, PG_DSN, rid,
                                               who=who, word=word)
            swap = _jsonable([shift_handoff.describe(got_swap, who)])[0] if got_swap else None
        except Exception as exc:  # noqa: BLE001 — the training answer itself stands
            log.warning("hub-lanes: the swap behind training %s could not be moved on (%s)",
                        rid, type(exc).__name__)
            swap = {"unreadable": True, "why": f"the training is approved, but the transfer "
                                               f"itself could not be moved on "
                                               f"({type(exc).__name__}) — approve it on its own "
                                               f"row"}
    _notices_wake()
    _housecal_rang()
    return {"status": 200, "data": {**_jsonable([row])[0], "swap": swap}}


# The rehearsal (shift_rehearsal.py): simulated staff answers through the real doors, played in a sealed worker…

_REHEARSAL_REFUSED = ("the rehearsal is the master's alone until it is released — "
                      "it plays real people's answers, even inside its own sandbox")


def _rehearsal_refusal(authorization: str) -> dict[str, Any] | None:
    """None for the master's own session, else the refusal envelope."""
    token = _hotline_token(authorization)
    acting = bool(token) and token in _acting
    flag = _auth_master.get(token) if token else None
    if shift_rehearsal.may_drive(flag, acting=acting):
        return None
    if acting:
        return {"status": 403, "reason": "acting",
                "message": "the rehearsal is not driven while acting as another account — press "
                           "Be Back to drive it as yourself"}
    if flag is None:
        return {"status": 403, "reason": "unknown",
                "message": "this session's master check has not been made yet, so the rehearsal "
                           "stays closed — reload the page to make it"}
    return {"status": 403, "reason": "master", "message": _REHEARSAL_REFUSED}


async def _rehearsal_driver(authorization: str):
    """(the reader, the session) for a rehearsal door, or its refusal envelope."""
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    refused = _rehearsal_refusal(authorization)
    if refused is not None:
        return refused
    return got


@app.get("/hub-lanes/shift-rehearsal")
async def lane_shift_rehearsal(run: str = "", at: str = "",
                              authorization: str = Header(default="")) -> dict[str, Any]:
    """The rehearsal board, read from the sandbox: its copy of the houses, people, shifts and swaps, and what was…"""
    got = await _rehearsal_driver(authorization)
    if isinstance(got, dict):
        return got
    who, _actor = got
    try:
        data = await asyncio.to_thread(shift_rehearsal.board, PG_DSN, who=who, run=run, at=at)
    except shift_rehearsal.Refused as exc:
        return {"status": 409, "reason": exc.code, "message": exc.why}
    except shift_rehearsal.Failed as exc:
        return {"status": 502, "message": f"the rehearsal could not be read: {exc}"}
    except Exception as exc:  # noqa: BLE001
        log.warning("shift rehearsal: the board failed (%s)", type(exc).__name__)
        return {"status": 502, "message": f"the rehearsal could not be read ({type(exc).__name__})"}
    return {"status": 200, "data": _jsonable([data])[0]}


@app.post("/hub-lanes/shift-rehearsal/answer")
async def lane_shift_rehearsal_answer(request: Request,
                                     authorization: str = Header(default="")) -> dict[str, Any]:
    """One simulated answer, through the door a real one comes through, inside the sandbox."""
    got = await _rehearsal_driver(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}
    fields = {k: str(body.get(k) or "").strip() for k in
              ("run", "door", "act", "location", "open_row", "col_iso", "ref", "person",
               "request_id", "handoff_id", "to_staff", "word", "at", "decider")}
    try:
        row = await asyncio.to_thread(
            shift_rehearsal.answer, PG_DSN, driver=str(who.get("name") or actor[1]),
            door=fields["door"] or "app", act=fields["act"], run=fields["run"],
            location=fields["location"], open_row=fields["open_row"], col_iso=fields["col_iso"],
            ref=fields["ref"], person=fields["person"], request_id=fields["request_id"],
            handoff_id=fields["handoff_id"], to_staff=fields["to_staff"],
            word=fields["word"] or "yes", at=fields["at"], decider=fields["decider"], who=who)
    except shift_rehearsal.Refused as exc:
        return {"status": 409, "reason": exc.code, "message": exc.why, "data": exc.extra}
    except shift_rehearsal.Failed as exc:
        return {"status": 502, "message": f"the rehearsal failed: {exc}"}
    except Exception as exc:  # noqa: BLE001
        log.warning("shift rehearsal: the answer failed (%s)", type(exc).__name__)
        return {"status": 502, "message": f"the rehearsal failed ({type(exc).__name__})"}
    log.info("shift rehearsal: %s by the %s door — %s (%s) driven by %s, inside the sandbox",
             fields["act"], fields["door"] or "app", row.get("outcome"), row.get("code"), actor[1])
    # no real notice, calendar or reader is woken: nothing outside the sandbox changed
    return {"status": 200, "data": _jsonable([row])[0]}


@app.post("/hub-lanes/shift-rehearsal/reset")
async def lane_shift_rehearsal_reset(authorization: str = Header(default="")) -> dict[str, Any]:
    """Empty the sandbox of everything played in it and take a fresh copy of the estate."""
    got = await _rehearsal_driver(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    try:
        data = await asyncio.to_thread(shift_rehearsal.reset, PG_DSN,
                                       by=str(who.get("name") or actor[1]))
    except shift_rehearsal.Refused as exc:
        return {"status": 409, "reason": exc.code, "message": exc.why}
    except shift_rehearsal.Failed as exc:
        return {"status": 502, "message": f"the reset failed: {exc}"}
    except Exception as exc:  # noqa: BLE001
        log.warning("shift rehearsal: the reset failed (%s)", type(exc).__name__)
        return {"status": 502, "message": f"the reset failed ({type(exc).__name__})"}
    log.info("shift rehearsal: the sandbox was reset by %s (%s answer(s) cleared)", actor[1],
             data.get("cleared"))
    return {"status": 200, "data": _jsonable([data])[0]}


# The bell (web_notices.py), cut by the same reader as Requests.

@app.get("/hub-lanes/notices")
async def lane_notices(since: int = 0, limit: int = 60,
                      authorization: str = Header(default="")) -> dict[str, Any]:
    """{notices, unread, seq}; `since` returns only newer ids."""
    if web_notices is None:
        return {"status": 503, "message": "the notices lane is not on this relay"}
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    _notice_who_put(actor[1], actor[0], _auth_master.get(_hotline_token(authorization)))
    # test mode holds the bell too
    switch = _web_switch()
    held = ("test mode" + ("" if switch.get("readable") else " (unreadable, so treated as on)")
            if switch["on"] else "")
    try:
        data = await asyncio.to_thread(web_notices.inbox, PG_DSN,
                                       who={**who, "alerts_off": _lane_alerts_off(actor[1])}, uid=actor[1],
                                       since=since, limit=limit, held=held)
    except Exception as exc:  # noqa: BLE001
        log.warning("notices: the inbox could not be read (%s)", type(exc).__name__)
        return {"status": 502, "message": f"notices unreadable ({type(exc).__name__})"}
    return {"status": 200, "data": data}


@app.post("/hub-lanes/notices/read")
async def lane_notices_read(request: Request,
                           authorization: str = Header(default="")) -> dict[str, Any]:
    """Mark this account's notices read, or dismissed."""
    if web_notices is None:
        return {"status": 503, "message": "the notices lane is not on this relay"}
    actor = await _session_actor(authorization)
    if not actor:
        return {"status": 401, "message": "sign in first"}
    if not actor[1]:
        return {"status": 403, "message": "this session carries no account to keep the reads for"}
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}
    ids = body.get("ids") if isinstance(body, dict) else None
    if not isinstance(ids, list) or not ids:
        return {"status": 400, "message": "ids is required"}
    try:
        marked = await asyncio.to_thread(web_notices.mark_read, PG_DSN, uid=actor[1], ids=ids,
                                         dismiss=bool(body.get("dismiss")))
    except Exception as exc:  # noqa: BLE001
        log.warning("notices: the reads could not be written (%s)", type(exc).__name__)
        return {"status": 502, "message": f"not marked ({type(exc).__name__})"}
    return {"status": 200, "data": {"marked": marked}}


# Push devices (web_push.py): always kept for the session's account, never an id from the body.

@app.get("/hub-lanes/push/key")
async def lane_push_key(authorization: str = Header(default="")) -> dict[str, Any]:
    """{key, why} — the VAPID public key, or null and why."""
    if web_push is None:
        return {"status": 503, "message": "the push lane is not on this relay"}
    actor = await _session_actor(authorization)
    if not actor:
        return {"status": 401, "message": "sign in first"}
    got = await asyncio.to_thread(web_push.keys)
    return {"status": 200, "data": {"key": got.get("public_key") if got.get("ok") else None,
                                    "why": got.get("why") or ""}}


@app.post("/hub-lanes/push/subscribe")
async def lane_push_subscribe(request: Request,
                             authorization: str = Header(default="")) -> dict[str, Any]:
    """Keep this browser's push subscription for the signed-in account."""
    if web_push is None:
        return {"status": 503, "message": "the push lane is not on this relay"}
    actor = await _session_actor(authorization)
    if not actor:
        return {"status": 401, "message": "sign in first"}
    if not actor[1]:
        return {"status": 403, "message": "this session carries no account to keep a device for"}
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}
    sub = web_push.clean_subscription((body or {}).get("subscription") if isinstance(body, dict) else None)
    if sub is None:
        return {"status": 400, "message": "not a push subscription this relay can write to"}
    if not (await asyncio.to_thread(web_push.public_key)):
        return {"status": 409, "message": "this relay has no push keys yet, so nothing could reach the device"}
    _notice_who_put(actor[1], actor[0], _auth_master.get(_hotline_token(authorization)))
    try:
        kept = await asyncio.to_thread(web_push.subscribe, PG_DSN, uid=actor[1], role=actor[0], sub=sub,
                                       ua=str((body or {}).get("ua") or request.headers.get("user-agent") or ""))
    except Exception as exc:  # noqa: BLE001
        log.warning("web push: a device could not be kept (%s)", type(exc).__name__)
        return {"status": 502, "message": f"not kept ({type(exc).__name__})"}
    if kept.get("fresh"):
        log.info("web push: a device was kept for %s (%s device(s) on the account)", actor[1],
                 kept.get("devices"))
    return {"status": 200, "data": kept}


@app.post("/hub-lanes/push/unsubscribe")
async def lane_push_unsubscribe(request: Request,
                               authorization: str = Header(default="")) -> dict[str, Any]:
    """Let one of this account's own devices go."""
    if web_push is None:
        return {"status": 503, "message": "the push lane is not on this relay"}
    actor = await _session_actor(authorization)
    if not actor:
        return {"status": 401, "message": "sign in first"}
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "message": "invalid body"}
    endpoint = str((body or {}).get("endpoint") or "") if isinstance(body, dict) else ""
    if not endpoint.startswith("https://"):
        return {"status": 400, "message": "endpoint is required"}
    try:
        gone = await asyncio.to_thread(web_push.unsubscribe, PG_DSN, uid=actor[1], endpoint=endpoint)
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"not removed ({type(exc).__name__})"}
    return {"status": 200, "data": {"removed": gone}}


@app.get("/hub-lanes/housecal/{location}")
async def lane_housecal_grid(location: str,
                            authorization: str = Header(default="")) -> dict[str, Any]:
    """One house's grid with its arithmetic and call-off line; any staff may look, `access` says who edits."""
    got = await _housecal_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, _actor = got
    try:
        grid = await _housecal_grid_for(who, location)
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"calendar mirror unreadable ({type(exc).__name__})"}
    if grid is None:
        return {"status": 404, "message": "no calendar for that house"}
    # no ref-to-row table: a call-off's row is the caller's name
    return {"status": 200, "data": grid}


# Calendar editing moved to Calendar Builder; these closed doors answer with where the edit is made.
_HOUSECAL_EDITS_MOVED = (
    "Calendar Builder → Live no longer changes a roster — calendars are created and edited in "
    "Calendar Builder → Builder, as a draft the house's manager publishes to the workbook. "
    "Open the house there to make this change.")


def _housecal_edits_moved(location: str, col_iso: str = "") -> dict[str, Any]:
    return {"status": 410, "reason": "moved_to_builder", "message": _HOUSECAL_EDITS_MOVED,
            "data": {"path": (calendar_builder_houses.builder_link(location, col_iso)
                              if location else "")}}


@app.post("/hub-lanes/housecal/cell")
async def lane_housecal_cell(request: Request,
                            authorization: str = Header(default="")) -> dict[str, Any]:
    """A typed cell: a closed door that says where the edit is made; who may look is asked first."""
    got = await _housecal_viewer(authorization)
    if isinstance(got, dict):
        return got
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001 — the answer does not depend on it
        body = {}
    return _housecal_edits_moved(str((body or {}).get("location") or "").strip(),
                                 str((body or {}).get("col_iso") or "").strip())


async def _housecal_grid_for(who: dict[str, Any] | None,
                             location: str) -> dict[str, Any] | None:
    """One house's grid as this reader may see it (shift_requests.calendar_grid) with `access`; None without a calendar."""
    grid = await asyncio.to_thread(shift_requests.calendar_grid, PG_DSN, location, who)
    if grid is None:
        return None
    managers = await asyncio.to_thread(shift_requests.house_managers, PG_DSN)
    access = shift_requests.calendar_access(who or {}, location, managers)
    grid["access"] = {k: access[k] for k in ("view", "edit", "why", "me")}
    grid["house_manager"] = access["house_manager"]
    # whether test mode holds roster writes now, so a Give is never promised to the workbook
    grid["test_mode"] = effective_roster.test_mode_said()
    # this house's waiting transfers the reader may see; a failed read is said
    try:
        grid["handoffs"] = await asyncio.to_thread(shift_handoff.for_house, PG_DSN, location,
                                                   who or {})
        grid["handoffs_why"] = ""
    except Exception as exc:  # noqa: BLE001
        grid["handoffs"] = []
        grid["handoffs_why"] = f"the transfers waiting here could not be read ({type(exc).__name__})"
    return grid


async def _housecal_after(location: str, who: dict[str, Any] | None) -> dict[str, Any]:
    """{computed, grid} — the whole house re-read after a write; None for both means the write landed but the re-read failed."""
    try:
        grid = await _housecal_grid_for(who, location)
    except Exception as exc:  # noqa: BLE001
        log.warning("housecal: the house could not be re-read after a write (%s)",
                    type(exc).__name__)
        return {"computed": None, "grid": None}
    return {"computed": (grid or {}).get("computed"), "grid": grid}


# rung after every shift write; a bare name (screens re-read through their own gated doors), so test mode does not hold it
HOUSECAL_EVENT = "housecal"


def _housecal_rang() -> None:
    try:
        _publish_slice(HOUSECAL_EVENT)
    except Exception:  # noqa: BLE001 — telling nobody must never fail a write
        pass


# rung after a Scheduling write the engine answered 200; a bare name — every open screen re-reads its own gated board
SCHEDULING_EVENT = "scheduling"
_SCHEDULING_READS = frozenset({"schedulingBoard", "schedulingStaffShifts", "schedulingTimeOffList",
                               "schedulingBuilderRead"})


def _relay_observe_scheduling(action: str, content: bytes) -> None:
    try:
        if not action.startswith("scheduling") or action in _SCHEDULING_READS or _resolver_lane(action) == "read":
            return
        env = json.loads(content)
        if isinstance(env, dict) and env.get("status") == 200:
            try:
                _publish_slice(SCHEDULING_EVENT)
            finally:
                # Python's copy read before this landing is behind every house (BACKEND PER APP)
                _app_pack_swept[SCHEDULING_EVENT] = time.time()
    except Exception:  # noqa: BLE001 — telling nobody must never fail a write
        pass


