def _backend_generic_door(action: str, raw: bytes) -> str:
    """The Python door a generic verb names: My World's where the envelope names a world, else the resource's own
    wherever the session stands (an App Studio door for a name route() does not have); the action itself otherwise."""
    if action not in _GENERIC_VERBS:
        return action
    env = _relay_envelope(raw)
    if not isinstance(env, dict):
        return action
    # a world re-points the generic verbs at its own workbook (Main.gs doPost): My World's doors alone
    if str(env.get("world") or "").strip():
        return WORLD_GENERIC_DOORS[action]
    resource = str(env.get("resource") or "")
    door = BACKEND_GENERIC_DOORS.get((resource, action))
    if door:
        return door
    return action if resource in GS_ROUTE_NAMES else "builder" + action.title()


def _builder_payload(action: str, env: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
    """An App Studio generic door is told the resource its verb names (`_envelope`, beside the relay's other axes)."""
    if action not in BUILDER_DOORS:
        return payload
    axes = payload.get("_envelope") if isinstance(payload.get("_envelope"), dict) else {}
    return {**payload, "_envelope": {**axes, "resource": str(env.get("resource") or "")}}


def _docs_rang(action: str, content: bytes, raw: bytes = b"") -> None:
    """After a library write landed 200 (Python's or Apps Script's), Python's copy read before it is behind; never
    raises."""
    try:
        touches = (action in ("docsCreate", "docsUpdate", "docsDelete")
                   or DOCS_RESOURCE in _resolver_invalidates(action)
                   or (action in _GENERIC_VERBS and action not in ("list", "get")
                       and _relay_resource(raw) == DOCS_RESOURCE))
        if not touches:
            return
        env = json.loads(content)
        if isinstance(env, dict) and env.get("status") == 200:
            _app_pack_swept[DOCS_APP] = time.time()
    except Exception:  # noqa: BLE001 — telling nobody must never fail a write
        pass


def _sheet_resources_rang(action: str, content: bytes) -> None:
    """After Python kept a row of the widget bank or the image bank in Postgres, its slice is built again now, by
    Python, with the row in it; never raises."""
    try:
        resource = SHEET_RESOURCE_DOORS.get(action, "")
        if resource not in BACKEND_SLICE_DOORS:
            return
        env = json.loads(content)
        if isinstance(env, dict) and env.get("status") == 200:
            _mark_dirty((resource,))
    except Exception:  # noqa: BLE001 — the next pass carries it all the same
        pass


def _generic_rows_rang(action: str, content: bytes) -> None:
    """After Python kept a generic write on a tab a sheet slice (or the medication study) is read from, that slice is
    built again now with it; never raises."""
    try:
        resource = SHEET_RESOURCE_DOORS.get(action, "")
        if resource not in GENERIC_RINGS:
            return
        env = json.loads(content)
        if isinstance(env, dict) and env.get("status") == 200:
            _mark_dirty((resource,))
    except Exception:  # noqa: BLE001 — the next pass carries it all the same
        pass


async def _resource_rows_upload(app_id: str, after: float = 0.0, *, release: bool = False) -> None:
    """An app given to Python: its sheets uploaded into Postgres again (rows nothing there has touched), and its slices
    built again; given back to Apps Script (`release`): its readers beside the app read the sheet's copy again. Never
    raises."""
    try:
        if after:
            await asyncio.sleep(after)
        door = RESOURCE_UPLOAD_DOORS[app_id]
        if app_id == TIME_OFF_APP and not release:
            # the house read live under its write locks: every copy withholds the reasons
            env = await asyncio.to_thread(time_off.upload_kept, PG_DSN) if time_off is not None and PG_DSN else None
        else:
            write_id = "W" + hashlib.sha256(f"{door}|{time.time_ns()}".encode()).hexdigest()[:24]
            got = await _backend_call(app_id, door, {"release": True} if release else {}, {"is_service": True},
                                      extra={"write_id": write_id}, timeout=HUB_APP_PACK_TIMEOUT_S)
            env = got[2] if got is not None else None
        if env is None or env.get("status") != 200:
            log.warning("resource rows: %s not uploaded again (%s)", app_id,
                        _BACKEND_UNANSWERED.get() if env is None else env.get("status"))
            return
        done = env.get("data") if isinstance(env.get("data"), dict) else {}
        log.info("resource rows: %s uploaded again %s", app_id, done)
        _mark_dirty(tuple(r for r in done if r in BACKEND_SLICE_DOORS))
        if app_id in DRIVE_INTAKE and not release:
            # the files its rows link brought onto the server now that the rows are Postgres'
            _drive_intake_kick(app_id)
        if app_id == PRODUCTION_ACTIONS_APP and not release:
            # each banner's book onto the server once, so its preview reads the server's copy
            got = await _backend_call(app_id, "productionActionBooksFetch", {}, {"is_service": True},
                                      timeout=HUB_APP_PACK_TIMEOUT_S)
            log.info("production actions: books %s", (got[2] or {}).get("data") if got is not None else
                     _BACKEND_UNANSWERED.get())
    except Exception as exc:  # noqa: BLE001 - the rows Postgres holds stand
        log.warning("resource rows: %s not uploaded again (%s)", app_id, type(exc).__name__)


