def _recon_rang(action: str, content: bytes, raw: bytes = b"") -> None:
    """After a Time Reconciliation write landed 200 (Python's or Apps Script's), Python's copy read before it is
    behind; never raises."""
    try:
        touches = (action in RECON_WRITES
                   or (action in _GENERIC_VERBS and action not in ("list", "get")
                       and _relay_resource(raw) == "financeConfig")
                   or SHEET_RESOURCE_DOORS.get(action) in ("financeConfig", "time_punches", "recon_runs",
                                                           "recon_errors"))
        if not touches:
            return
        env = json.loads(content)
        if isinstance(env, dict) and env.get("status") == 200:
            _app_pack_swept[RECON_APP] = time.time()
    except Exception:  # noqa: BLE001 — telling nobody must never fail a write
        pass


# rung after an Emergency Contacts save Python kept (200, or a 409 that saved some fields): every open page reads again
EMERGENCY_CONTACTS_EVENT = "emergency-contacts"


def _emergency_contacts_rang(content: bytes) -> None:
    """Rings a bare name after a save that changed the directory; never raises."""
    try:
        env = json.loads(content)
        data = env.get("data") if isinstance(env, dict) else None
        if isinstance(env, dict) and (env.get("status") == 200 or (isinstance(data, dict) and data.get("written"))):
            _publish_slice(EMERGENCY_CONTACTS_EVENT)
    except Exception:  # noqa: BLE001 — telling nobody must never fail a write
        pass


# rebuilt on publish; `events` is left to the heartbeat (a rebuild can cost an Apps Script execution)
ROSTER_SLICES = tuple(shift_slices.RESOURCES) + tuple(comm_when_slices.RESOURCES)


def _roster_published(event: dict[str, Any]) -> None:
    """A publish landed (writer's thread): every shift reader re-reads now; the rebuild is queued on the loop."""
    shift_slices.forget()
    psi_attendance.roster_moved()
    # and the overlap law's held picture
    shift_requests.forget_estate()
    loop = _event_loop
    if loop is not None:
        loop.call_soon_threadsafe(_mark_dirty, ROSTER_SLICES)
    else:
        _mark_dirty(ROSTER_SLICES)
    log.info("roster: %d published cell(s) at %s (%s, by %s) reach every reader — the shift flow "
             "on its next beat, the Shift Board after the rebuild", len(event.get("cells") or []),
             event.get("location"), event.get("via") or "?", event.get("actor") or "?")


@app.post("/hub-lanes/housecal/move")
async def lane_housecal_move(request: Request,
                            authorization: str = Header(default="")) -> dict[str, Any]:
    """Drag and drop on House Calendars: a closed door; moving a shift is Calendar Builder's."""
    got = await _housecal_viewer(authorization)
    if isinstance(got, dict):
        return got
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001 — the answer does not depend on it
        body = {}
    dst = (body or {}).get("to") or {}
    return _housecal_edits_moved(str((body or {}).get("location") or "").strip(),
                                 str(dst.get("col_iso") or "").strip())


# Calendar Builder lanes: the houses (calendar_builder_houses, drafts published through the one writer) and the…

_BUILDER_EDIT_REFUSED = ("only this house's manager builds its calendar — the hotline "
                         "calendar's ** row for it — and directors, team leads and "
                         "administrators")
_BUILDER_ALL_REFUSED = ("the master grid changes every house at once, so it is for the badges "
                        "that edit every house — directors, team leads and administrators; a "
                        "house manager builds their own houses under House calendars")


async def _builder_viewer(authorization: str) -> tuple[dict[str, Any], tuple[str, str]] | dict[str, Any]:
    """(who, session) for a Calendar Builder door, or its refusal."""
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    if not shift_requests.may_view_calendars(who):
        return {"status": 403,
                "message": ("The Builder is the house managers' screen — your own shifts "
                            "are on Calendar Builder → Requests")}
    return who, actor


async def _builder_master(authorization: str) -> tuple[dict[str, Any], tuple[str, str]] | dict[str, Any]:
    got = await _builder_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    if not shift_requests.edits_every_house(who):
        return {"status": 403, "message": _BUILDER_ALL_REFUSED}
    return who, actor


async def _builder_house(authorization: str, location: str
                         ) -> tuple[dict[str, Any], tuple[str, str]] | dict[str, Any]:
    """The reader, when they build THIS house's calendar — else the refusal."""
    got = await _builder_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, actor = got
    if not location:
        return {"status": 400, "message": "name the house"}
    if not shift_requests.may_edit_calendar(who, location):
        return {"status": 403, "message": _BUILDER_EDIT_REFUSED}
    return who, actor


def _builder_name(who: dict[str, Any], actor: tuple[str, str]) -> str:
    """The name a Builder act is written down under — the roster name, else the account."""
    return str(who.get("name") or actor[1])


async def _builder_grid_for(who: dict[str, Any], location: str) -> dict[str, Any] | None:
    """One house as this reader is building it, with `access`."""
    grid = await asyncio.to_thread(calendar_builder_houses.draft_grid, PG_DSN, location, who)
    if grid is None:
        return None
    managers = await asyncio.to_thread(shift_requests.house_managers, PG_DSN)
    access = shift_requests.calendar_access(who, location, managers)
    grid["access"] = {k: access[k] for k in ("view", "edit", "why", "me")}
    grid["house_manager"] = access["house_manager"]
    return grid


async def _builder_after(location: str, who: dict[str, Any]) -> dict[str, Any]:
    """{grid} — the house re-read after a write; `grid: None` when only the re-read failed."""
    try:
        return {"grid": await _builder_grid_for(who, location)}
    except Exception as exc:  # noqa: BLE001
        log.warning("calendar-builder: the house could not be re-read after a write (%s)",
                    type(exc).__name__)
        return {"grid": None}


def _builder_refusal(exc: Exception) -> dict[str, Any]:
    """Every refusal a Builder act can meet, as the envelope the screen reads."""
    if isinstance(exc, house_cal_live.Occupied):
        return {"status": 409, "reason": "occupied", "message": str(exc),
                "data": {"employee": exc.employee, "col_iso": exc.col_iso, "value": exc.value}}
    if isinstance(exc, house_cal_live.OpenShiftCell):
        return {"status": 409, "reason": "open_shift", "message": str(exc)}
    if isinstance(exc, shift_requests.Refused):
        return {"status": 409, "reason": exc.code, "message": exc.why, "data": exc.extra}
    if isinstance(exc, house_cal_live.WorkbookRefused):
        return {"status": 409, "reason": exc.code, "message": exc.why,
                "data": {"blocked": exc.blocked}}
    if isinstance(exc, LookupError):
        return {"status": 404, "message": str(exc)}
    if isinstance(exc, ValueError):
        return {"status": 400, "message": str(exc)}
    return {"status": 502, "message": f"the calendar could not be changed ({type(exc).__name__})"}


async def _builder_body(request: Request) -> dict[str, Any] | None:
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return None
    return body if isinstance(body, dict) else None


@app.get("/hub-lanes/calendar-builder/houses")
async def lane_cal_builder_houses(authorization: str = Header(default="")) -> dict[str, Any]:
    """The houses this reader builds, or why none."""
    got = await _builder_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, _actor = got

    def _read() -> tuple[list[dict[str, Any]], dict[str, int]]:
        calendar_builder_houses.ensure_tables(PG_DSN)
        with psycopg2.connect(PG_DSN) as conn, conn.cursor(
                cursor_factory=psycopg2.extras.RealDictCursor) as live:
            live.execute("SELECT location, grid, updated_at FROM asa_house_calendar_live "
                         "ORDER BY location")
            rows = list(live.fetchall())
        # the drafts are the relay's own table: asa-hub-db once moved, read by the rail's own reader
        with hub_db.connect(PG_DSN) as conn, conn.cursor() as cur:
            counts = calendar_builder_houses.draft_counts_in(cur)
        return rows, counts

    try:
        rows, counts = await asyncio.to_thread(_read)
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"the house calendars are unreadable ({type(exc).__name__})"}
    managers = await asyncio.to_thread(shift_requests.house_managers, PG_DSN)
    houses = []
    for r in rows:
        location = str(r.get("location") or "")
        access = shift_requests.calendar_access(who, location, managers)
        if not access["edit"]:
            continue
        g = r.get("grid") or {}
        if isinstance(g, str):
            try:
                g = json.loads(g)
            except Exception:  # noqa: BLE001
                g = {}
        houses.append({"location": location,
                       "staff": sum(1 for row in g.get("rows", []) or []
                                    if not house_cal_live.not_a_person(
                                        (row or {}).get("employee"), location)),
                       "updated_at": str(r.get("updated_at") or ""),
                       "may_edit": True, "drafts": counts.get(location, 0),
                       "manager": access["house_manager"]["name"],
                       "managers": access["house_manager"]["names"]})
    if not houses:
        why = ("You manage no house, so there is no calendar here for you to build — a house's "
               "manager (the hotline calendar's ** row for it) and directors, team leads and "
               "administrators build calendars")
        if not managers.get("readable"):
            reason = managers.get("why") or "no reason given"
            why += (f"; who manages each house could not be read ({reason}), so a house "
                    f"manager is not recognised until it can")
        return {"status": 403, "message": why}
    return {"status": 200, "data": {
        "houses": houses, "me": str(who.get("name") or ""),
        "edits_every_house": shift_requests.edits_every_house(who),
        "managers_readable": bool(managers.get("readable")),
        "managers_why": str(managers.get("why") or "")}}


@app.get("/hub-lanes/calendar-builder/house")
async def lane_cal_builder_house(location: str = "",
                                authorization: str = Header(default="")) -> dict[str, Any]:
    """One house with its draft laid on and every total recomputed."""
    location = location.strip()
    got = await _builder_house(authorization, location)
    if isinstance(got, dict):
        return got
    who, _actor = got
    try:
        grid = await _builder_grid_for(who, location)
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"the house calendar is unreadable ({type(exc).__name__})"}
    if grid is None:
        return {"status": 404, "message": "no calendar for that house"}
    return {"status": 200, "data": grid}


@app.get("/hub-lanes/calendar-builder/staff")
async def lane_cal_builder_staff(authorization: str = Header(default="")) -> dict[str, Any]:
    """Everybody a house manager may place; the Builder takes a new name from here only."""
    got = await _builder_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, _actor = got
    if not (shift_requests.edits_every_house(who) or who.get("manages")):
        return {"status": 403, "message": _BUILDER_EDIT_REFUSED}
    try:
        return {"status": 200, "data": await asyncio.to_thread(
            calendar_builder_houses.staff_directory, PG_DSN)}
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"the staff list is unreadable ({type(exc).__name__})"}


@app.get("/hub-lanes/calendar-builder/house-history")
async def lane_cal_builder_history(location: str = "", employee: str = "", col_iso: str = "",
                                  authorization: str = Header(default="")) -> dict[str, Any]:
    """One cell's history, newest first."""
    location = location.strip()
    got = await _builder_house(authorization, location)
    if isinstance(got, dict):
        return got
    if not employee.strip() or not col_iso.strip():
        return {"status": 400, "message": "employee and col_iso are required"}
    try:
        # a call-off's note is its reason: only the badges that read reasons
        rows = await asyncio.to_thread(calendar_builder_houses.history, PG_DSN, location,
                                       employee.strip(), col_iso.strip(),
                                       sees_reasons=bool(got[0].get("sees_reasons")))
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"the history is unreadable ({type(exc).__name__})"}
    return {"status": 200, "data": {"history": rows}}


# a fixed list, never a label the body can invent
_BUILDER_CELL_VIA = frozenset({"cell", "times", "delete", "add"})


@app.post("/hub-lanes/calendar-builder/house/cell")
async def lane_cal_builder_house_cell(request: Request,
                                     authorization: str = Header(default="")) -> dict[str, Any]:
    """Draft one cell; `start`/`end` become the estate's code here, refused if it would read as other hours."""
    body = await _builder_body(request)
    if body is None:
        return {"status": 400, "message": "invalid body"}
    location = str(body.get("location") or "").strip()
    got = await _builder_house(authorization, location)
    if isinstance(got, dict):
        return got
    who, actor = got
    employee = str(body.get("employee") or "").strip()
    col_iso = str(body.get("col_iso") or "").strip()
    if not employee or not col_iso:
        return {"status": 400, "message": "employee and col_iso are required"}
    via = str(body.get("via") or "cell").strip()
    via = via if via in _BUILDER_CELL_VIA else "cell"
    try:
        if body.get("start") not in (None, "") or body.get("end") not in (None, ""):
            value = calendar_builder_houses.value_from_times(
                body.get("start"), body.get("end"), keep_star=bool(body.get("keep_star")))
            via = "times" if via == "cell" else via
        else:
            value = str(body.get("value") if body.get("value") is not None else "")
        admits = await asyncio.to_thread(calendar_builder_houses.admits, PG_DSN)
        out = await asyncio.to_thread(
            calendar_builder_houses.stage_cell, PG_DSN, location=location, employee=employee,
            col_iso=col_iso, value=value, actor=_builder_name(who, actor),
            note=str(body.get("note") or ""), via=via, admits=admits)
    except Exception as exc:  # noqa: BLE001 — every refusal said in its own words
        return _builder_refusal(exc)
    if out.get("changed"):
        log.info("calendar-builder: draft %s / %s / %s %r (was %r) by %s", location,
                 out["employee"], col_iso, out["value"], out["was"], actor[1])
        _housecal_rang()
    return {"status": 200, "data": {**out, **await _builder_after(location, who)}}


@app.post("/hub-lanes/calendar-builder/house/move")
async def lane_cal_builder_house_move(request: Request,
                                     authorization: str = Header(default="")) -> dict[str, Any]:
    """Move a shift as one draft act (both cells or neither); `swap`, `replace` and `value` as the panel sends them."""
    body = await _builder_body(request)
    if body is None:
        return {"status": 400, "message": "invalid body"}
    location = str(body.get("location") or "").strip()
    got = await _builder_house(authorization, location)
    if isinstance(got, dict):
        return got
    who, actor = got
    src, dst = body.get("from") or {}, body.get("to") or {}
    src_emp, src_iso = str(src.get("employee") or "").strip(), str(src.get("col_iso") or "").strip()
    dst_emp, dst_iso = str(dst.get("employee") or "").strip(), str(dst.get("col_iso") or "").strip()
    if not src_emp or not src_iso or not dst_emp or not dst_iso:
        return {"status": 400, "message": "from and to are required"}
    swap = bool(body.get("swap"))
    try:
        value = None
        if body.get("start") not in (None, "") or body.get("end") not in (None, ""):
            value = calendar_builder_houses.value_from_times(
                body.get("start"), body.get("end"), keep_star=bool(body.get("keep_star")))
        elif body.get("value") is not None:
            value = str(body.get("value"))
        admits = await asyncio.to_thread(calendar_builder_houses.admits, PG_DSN)
        out = await asyncio.to_thread(
            calendar_builder_houses.stage_move, PG_DSN, location=location,
            src_employee=src_emp, src_iso=src_iso, dst_employee=dst_emp, dst_iso=dst_iso,
            actor=_builder_name(who, actor), swap=swap,
            replace=bool(body.get("replace")) and not swap, value=value,
            note=str(body.get("note") or ""), admits=admits)
    except Exception as exc:  # noqa: BLE001
        return _builder_refusal(exc)
    log.info("calendar-builder: draft %s %s / %s %s → %s %s by %s",
             "swap" if swap else "move", location, src_emp, src_iso, dst_emp, dst_iso, actor[1])
    _housecal_rang()
    return {"status": 200, "data": {**out, **await _builder_after(location, who)}}


@app.post("/hub-lanes/calendar-builder/house/request-off")
async def lane_cal_builder_request_off(request: Request,
                                      authorization: str = Header(default="")) -> dict[str, Any]:
    """Request Off as a draft: R/O, the shift moved to the first free OPEN row."""
    body = await _builder_body(request)
    if body is None:
        return {"status": 400, "message": "invalid body"}
    location = str(body.get("location") or "").strip()
    got = await _builder_house(authorization, location)
    if isinstance(got, dict):
        return got
    who, actor = got
    try:
        out = await asyncio.to_thread(
            calendar_builder_houses.request_off, PG_DSN, location=location,
            employee=str(body.get("employee") or ""), col_iso=str(body.get("col_iso") or ""),
            actor=_builder_name(who, actor), note=str(body.get("note") or ""))
    except Exception as exc:  # noqa: BLE001
        return _builder_refusal(exc)
    _housecal_rang()
