@app.post("/hub-lanes/calendar-builder/house/publish")
async def lane_cal_builder_house_publish(request: Request,
                                        authorization: str = Header(default="")) -> dict[str, Any]:
    """Publish one house's draft through the one fail-closed writer; 409 with the cells, nothing half-lands."""
    body = await _builder_body(request)
    if body is None:
        return {"status": 400, "message": "invalid body"}
    location = str(body.get("location") or "").strip()
    got = await _builder_house(authorization, location)
    if isinstance(got, dict):
        return got
    who, actor = got
    try:
        out = await asyncio.to_thread(calendar_builder_houses.publish_house, PG_DSN,
                                      location=location, actor=_builder_name(who, actor))
    except Exception as exc:  # noqa: BLE001
        if not isinstance(exc, (shift_requests.Refused, house_cal_live.WorkbookRefused,
                                LookupError, ValueError)):
            log.warning("calendar-builder: publish of %s failed (%s)", location,
                        type(exc).__name__)
        return _builder_refusal(exc)
    if out.get("test_mode"):
        log.info("calendar-builder: %s published in TEST MODE — %d cell(s) recorded on the "
                 "platform, the workbook was NOT written (%d already there), by %s", location,
                 out.get("written", 0), out.get("already", 0), actor[1])
    else:
        log.info("calendar-builder: %s published — %d cell(s) written, %d already there, "
                 "%d row(s) added, by %s", location, out.get("written", 0), out.get("already", 0),
                 len(out.get("rows_added") or []), actor[1])
    # a publish may have raised a training approval
    _notices_wake()
    _housecal_rang()
    return {"status": 200, "data": {**out, **await _builder_after(location, who)}}


