# passes one hand-over of rows may take on Python before the rows still handed back answer as the door's budget did
BACKEND_ROW_PASSES = 6
# what openShiftCovered and recruitTell answer for a row their execution never started
COVERED_LATE = {"state": "not_yet", "why": "this execution spent its time on the rows before it; the relay offers it "
                                           "again"}
RECRUIT_LATE = {"state": "failed", "why": COVERED_LATE["why"]}


async def _backend_pass(app_id: str, action: str, payload: dict[str, Any]) -> dict[str, Any]:
    """One write of a relay-rung Smart Comms door on Python; its answer, or a 503 saying why there was none."""
    write_id = "W" + hashlib.sha256(f"{app_id}|{time.time_ns()}".encode()).hexdigest()[:24]
    got = await _backend_call(app_id, action, payload, {"is_service": True}, extra={"write_id": write_id},
                              timeout=HUB_APP_PACK_TIMEOUT_S)
    if got is None:
        _backend_settle_soon(app_id, write_id, "void")
        return {"status": 503, "message": f"Python did not answer ({_BACKEND_UNANSWERED.get()})"}
    _traffic_note("backend_python")
    return got[2]


async def _backend_row_passes(app_id: str, action: str, rows: list[dict], late: dict[str, str]) -> dict[str, Any]:
    """A door that answers one result per row on Python (openShiftCovered, recruitTell), pass after pass while it hands
    rows back; the results together, a row no pass started answered as the door's own budget answered it."""
    said: dict[str, Any] = {"results": [], "counts": {}, "dial": ""}
    left = rows
    for _ in range(BACKEND_ROW_PASSES):
        env = await _backend_pass(app_id, action, {"rows": left})
        if env.get("status") != 200:
            if not said["results"]:
                return env
            break
        data = env.get("data") or {}
        said["results"] += data.get("results") or []
        for k, n in (data.get("counts") or {}).items():
            said["counts"][k] = said["counts"].get(k, 0) + int(n or 0)
        said["dial"] = data.get("dial") or said["dial"]
        left = data.get("left") or []
        if not left:
            return {"status": 200, "data": said}
    for r in left:
        said["results"].append({"id": str((r or {}).get("id") or ""), "count": "", **late})
        said["counts"][late["state"]] = said["counts"].get(late["state"], 0) + 1
    return {"status": 200, "data": said}


async def _open_shift_covered_post() -> None:
    """Hand owed "covered" follow-ups to openShiftCovered; what the door did not say stays owed."""
    import open_shift_covered  # noqa: PLC0415 — lazy, so the in-container suites need no new module
    try:
        noted = await asyncio.to_thread(open_shift_covered.note_from_pool, PG_DSN)
        rows = await asyncio.to_thread(open_shift_covered.owed, PG_DSN)
    except Exception as exc:  # noqa: BLE001
        log.warning("open shift covered: the owed fills could not be read (%s)", type(exc).__name__)
        return
    if noted:
        log.info("open shift covered: %s fill(s) the claims road left, noted", noted)
    if not rows:
        return
    failure = ""
    said: dict[str, Any] = {}
    try:
        env = await _backend_row_passes(OPEN_SHIFT_COVERED_APP, "openShiftCovered", rows, COVERED_LATE)
        if (env or {}).get("status") != 200:
            failure = f"the door refused: {str((env or {}).get('message') or env)[:160]}"
        else:
            said = (env or {}).get("data") or {}
    except Exception as exc:  # noqa: BLE001
        failure = f"the door could not be reached ({type(exc).__name__})"
    try:
        wrote = await asyncio.to_thread(open_shift_covered.mark, PG_DSN, rows, said, failure=failure)
    except Exception as exc:  # noqa: BLE001
        log.warning("open shift covered: the ledger could not be written (%s)", type(exc).__name__)
        return
    counts = (said or {}).get("counts") or {}
    log.info("open shift covered: %s fill(s) offered → %s%s", len(rows),
             ", ".join(f"{n} {k}" for k, n in sorted(counts.items())) or "no answer per row",
             f" — {failure}" if failure else f" ({wrote} written down)")


_CALLOFF_ROAD_LOCK: asyncio.Lock | None = None


async def _calloff_calendar_python(rows: list[dict[str, Any]]) -> dict[str, Any]:
    """callOffFromCalendar on Python (app/comm_call_off_form_writes.py): pass after pass while it hands call-offs back,
    the rows each pass filed together; a ref no pass reached is not named, so it stays owed."""
    said: list[dict[str, Any]] = []
    test_mode: Any = None
    left = rows
    env: dict[str, Any] = {}
    for _ in range(COMM_LANE_PASSES):
        env = await _backend_pass(COMM_CALL_OFF_FORM_APP, "callOffFromCalendar", {"rows": left})
        if env.get("status") != 200:
            break
        data = env.get("data") or {}
        said += data.get("rows") or []
        test_mode = data.get("test_mode") if test_mode is None else test_mode
        left = data.get("left") or []
        if not left:
            break
    if not said:
        return env
    return {"status": 200, "data": {"rows": said, "test_mode": bool(test_mode)}}


async def _calloff_road_post() -> None:
    """Hand owed Builder call-offs to callOffFromCalendar; what the door did not file stays owed."""
    global _CALLOFF_ROAD_LOCK
    if not PG_DSN:
        return
    import calloff_road  # noqa: PLC0415 — lazy, so the in-container suites need no new module
    import house_directory  # noqa: PLC0415
    if _CALLOFF_ROAD_LOCK is None:
        _CALLOFF_ROAD_LOCK = asyncio.Lock()
    if _CALLOFF_ROAD_LOCK.locked():
        return                     # a press and the beat at once: one post is enough
    async with _CALLOFF_ROAD_LOCK:
        try:
            rows = await asyncio.to_thread(calloff_road.owed, PG_DSN)
        except Exception as exc:  # noqa: BLE001
            log.warning("call-off road: the owed call-offs could not be read (%s)",
                        type(exc).__name__)
            return
        if not rows:
            return
        try:
            managers = (await asyncio.to_thread(shift_requests.house_managers, PG_DSN)).get("by_code") or {}
        except Exception:  # noqa: BLE001 — the door names no manager rather than a guess
            managers = {}
        payload = [calloff_road.payload(
            r, managers.get(house_directory.code_of(r["location"])
                            or str(r["location"]).strip().upper())) for r in rows]
        failure = ""
        env: Any = None
        try:
            env = await _calloff_calendar_python(payload)
        except Exception as exc:  # noqa: BLE001
            failure = f"the door could not be reached ({type(exc).__name__})"
        try:
            said = await asyncio.to_thread(calloff_road.mark, PG_DSN, rows, env, failure=failure)
        except Exception as exc:  # noqa: BLE001
            log.warning("call-off road: the answers could not be written down (%s)",
                        type(exc).__name__)
            return
        if said["told"]:
            log.info("call-off road: %s Calendar Builder call-off(s) recorded by Python "
                     "(what each message did is on Requests)", said["told"])
        if said["owed"]:
            reason = failure or str((env or {}).get("message") or "") or "not named as filed"
            log.warning("call-off road: %s call-off(s) still owed — %s", said["owed"], reason[:200])


async def _recruit_book_post() -> None:
    """The recruit book pass: JSON copy first, changed tabs to recruitBookIngest, owed texts to recruitTell."""
    import recruit_book  # noqa: PLC0415 — lazy, so the in-container suites need no new module
    if not recruit_book.due_pass(time.time()):
        return
    try:
        synced = await asyncio.to_thread(recruit_book.sync, time.time())
    except Exception as exc:  # noqa: BLE001
        log.warning("recruit book: the copy could not be written (%s)", type(exc).__name__)
        return
    if not synced.get("read"):
        log.info("recruit book: their book could not be read — %s (the copy that stands is kept)",
                 str(synced.get("why") or "")[:200])
    moved = bool(synced.get("changed"))
    # only tabs the house is not proved to hold, never an empty one
    try:
        offers = await asyncio.to_thread(recruit_book.house_offer, time.time())
    except Exception as exc:  # noqa: BLE001
        log.warning("recruit book: the house offer could not be read (%s)", type(exc).__name__)
        offers = []
    for offer in offers:
        failure = ""
        said: dict[str, Any] = {}
        try:
            env = await _backend_pass(COMM_RECRUIT_APP, "recruitBookIngest", offer)
            if (env or {}).get("status") != 200:
                failure = f"the door refused: {str((env or {}).get('message') or env)[:160]}"
            else:
                said = (env or {}).get("data") or {}
        except Exception as exc:  # noqa: BLE001
            failure = f"the door could not be reached ({type(exc).__name__})"
        try:
            state = await asyncio.to_thread(recruit_book.house_mark, offer, said, failure, time.time())
        except Exception as exc:  # noqa: BLE001
            log.warning("recruit book: the house answer could not be written (%s)", type(exc).__name__)
            continue
        moved = True
        log.info("recruit book: %s → %s (%s rows)%s", offer.get("tab"), state, len(offer.get("rows") or []),
                 f" — {failure or said.get('why')}" if state != "written" else "")
    # THE TEXTS.
    try:
        offer = await asyncio.to_thread(recruit_book.pending, time.time())
    except Exception as exc:  # noqa: BLE001
        log.warning("recruit book: the owed texts could not be planned (%s)", type(exc).__name__)
        offer = {"rows": []}
    rows = offer.get("rows") or []
    if rows:
        failure = ""
        said = {}
        try:
            env = await _backend_row_passes(COMM_RECRUIT_APP, "recruitTell", recruit_book.door_rows(rows),
                                            RECRUIT_LATE)
            if (env or {}).get("status") != 200:
                failure = f"the door refused: {str((env or {}).get('message') or env)[:160]}"
            else:
                said = (env or {}).get("data") or {}
        except Exception as exc:  # noqa: BLE001
            failure = f"the door could not be reached ({type(exc).__name__})"
        try:
            counts = await asyncio.to_thread(recruit_book.mark, rows, said if not failure else None,
                                             failure, time.time())
        except Exception as exc:  # noqa: BLE001
            log.warning("recruit book: the answers could not be written (%s)", type(exc).__name__)
            counts = {}
        moved = True
        log.info("recruit book: %s text(s) offered → %s%s", len(rows),
                 ", ".join(f"{n} {k}" for k, n in sorted(counts.items())) or "no answer per row",
                 f" — {failure}" if failure else "")
    if moved:
        try:
            await build_all(only=set(recruit_book.RESOURCES))
        except Exception as exc:  # noqa: BLE001 — the next full build carries it
            log.warning("recruit book: the page file could not be rebuilt (%s)", type(exc).__name__)


async def _psi_reminders_post() -> None:
    """THE SHIFT FLOW, HANDED TO THE DOOR (the ask before every shift and its repeats, the house manager told of…"""
    credential = ({"service_secret": SERVICE_SECRET} if SERVICE_SECRET
                  else {"token": SERVICE_TOKEN})
    for _post in range(max(1, psi_reminders.POSTS_PER_BEAT)):
        try:
            offer = await asyncio.to_thread(psi_reminders.pending, time.time())
        except Exception as exc:  # noqa: BLE001
            log.warning("psi reminders: the owed rows could not be read (%s)", type(exc).__name__)
            return
        if not offer:
            return
        try:
            env_rem = await _staff_door("staffShiftReminder", {"rows": offer["rows"]}, credential)
        except Exception as exc:  # noqa: BLE001
            await asyncio.to_thread(psi_reminders.post_failed, time.time())
            log.warning("psi reminders: the door could not be reached (%s) — the rows stay owed",
                        type(exc).__name__)
            return
        if (env_rem or {}).get("status") != 200:
            await asyncio.to_thread(psi_reminders.post_failed, time.time())
            log.warning("psi reminders refused: %s — the rows stay owed",
                        str((env_rem or {}).get("message") or env_rem)[:160])
            return
        said = (env_rem or {}).get("data") or {}
        # the dial as the door said it: a rehearsed ask is re-offered only once it moves
        shift_handoff.note_dial(said.get("dial"), said.get("test_mode"))
        counts = await asyncio.to_thread(psi_reminders.posted, offer["ids"], said, time.time())
        log.info("psi reminders: %s row(s) offered → %s", len(offer["ids"]),
                 ", ".join(f"{n} {k}" for k, n in sorted(counts.items())) or "no answer per row")


async def _broadcast_python_carry() -> None:
    """commBroadcastQuietCarry_ on Python: once the quiet window is over, each broadcast it held is carried, one write
    each, under the relay's own identity. Never raises."""
    try:
        got = await _backend_call(BROADCAST_APP, "staffBroadcastHeld", {}, {"is_service": True})
        data = (got[2] or {}).get("data") if got is not None and (got[2] or {}).get("status") == 200 else None
        if data is None:
            log.warning("broadcast carry: the held ones were not read (%s)", _BACKEND_UNANSWERED.get())
            return
        for bid in data.get("ids") or []:
            write_id = "W" + hashlib.sha256(f"broadcast-carry|{bid}|{time.time()}".encode()).hexdigest()[:24]
            got = await _backend_call(BROADCAST_APP, "staffBroadcastCarry", {"id": bid}, {"is_service": True},
                                      extra={"write_id": write_id}, timeout=HUB_APP_PACK_TIMEOUT_S)
            env = got[2] if got is not None else None
            if not env or env.get("status") != 200:
                log.warning("broadcast carry: %s not carried (%s)", bid,
                            str((env or {}).get("message") or _BACKEND_UNANSWERED.get())[:160])
                continue
            said = env.get("data") or {}
            log.info("broadcast carry: %s %s — %s", bid, said.get("state"), str(said.get("why") or "")[:200])
            if said.get("state") != "kept":
                _smart_comms_rang("staffBroadcastCarry", b'{"status":200}')
    except Exception as exc:  # noqa: BLE001 - the clock's next tick asks again
        log.warning("broadcast carry: %s", type(exc).__name__)


