# the event situations, the credential reminders and the digests (app/smart_clock.py tells them)
SMART_CLOCK_APP = "smart-clock"
# how often the events are looked at (Apps Script's hiring sweep, which carried them, swept every few minutes), and
# the reminders and digests (its six-hour cache); a row's own hours wake them in between (app/smart_clock.py)
SMART_CLOCK_EVERY_S = 120.0
SMART_CLOCK_REMIND_EVERY_S = 6 * 3600.0
SMART_CLOCK_PASSES = 30
_SMART_CLOCK: dict[str, Any] = {"at": 0.0, "reminded": 0.0, "task": None, "unread": []}
SMART_CLOCK_UNREAD = {"status": 503, "message": "Smart Comms could not be asked just now. Try again in a moment."}


async def _smart_clock_run(reminders: bool) -> dict[str, Any] | None:
    """One turn of Smart Comms' clock on Python: the look (smartClockDue), then its plans carried pass by pass
    (smartClockSend); what it found and told, None when Python did not answer the look."""
    got = await _backend_call(SMART_CLOCK_APP, "smartClockDue", {"reminders": reminders}, {"is_service": True},
                              timeout=HUB_APP_PACK_TIMEOUT_S)
    read = got[2] if got is not None else None
    if not read or read.get("status") != 200 or not isinstance(read.get("data"), dict):
        log.warning("smart clock: not read (%s)",
                    str((read or {}).get("message") or _BACKEND_UNANSWERED.get())[:160])
        return None
    data = read["data"]
    plans = data.pop("plans", None) or []
    told: dict[str, Any] = {"plans": len(plans), "told": 0, "rehearsed": 0, "sms": 0, "email": 0,
                            "deduplicated": 0, "lost": 0, "would": 0, "failed": []}
    for _ in range(SMART_CLOCK_PASSES):
        if not plans:
            break
        write_id = "W" + hashlib.sha256(f"smart-clock|{time.time_ns()}".encode()).hexdigest()[:24]
        kept = await _backend_call(SMART_CLOCK_APP, "smartClockSend", {"plans": plans}, {"is_service": True},
                                   extra={"write_id": write_id}, timeout=HUB_APP_PACK_TIMEOUT_S)
        env = kept[2] if kept is not None else None
        if not env or env.get("status") != 200:
            if kept is None:
                _backend_settle_soon(SMART_CLOCK_APP, write_id, "void")
            told["left"] = len(plans)
            log.warning("smart clock: a pass did not land (%s)",
                        str((env or {}).get("message") or _BACKEND_UNANSWERED.get())[:160])
            break
        out = env.get("data") or {}
        for k in ("told", "rehearsed", "sms", "email", "deduplicated", "lost"):
            told[k] += int(out.get(k) or 0)
        told["would"] += len(out.get("would") or [])
        told["failed"] = (told["failed"] + list(out.get("failed") or []))[:20]
        plans = out.get("left") or []
    data["sent"] = told
    _traffic_note("backend_python")
    return data


async def _smart_clock_turn(reminders: bool) -> None:
    """A turn on the fast clock; never raises."""
    try:
        got = await _smart_clock_run(reminders)
        if got is None:
            return
        if (got.get("reminders") or {}).get("situations") is not None:
            _SMART_CLOCK["reminded"] = time.time()
        sent = got.get("sent") or {}
        # a subject that could not be read is said when it starts or stops failing, not every turn
        unread = (got.get("events") or {}).get("unread") or []
        if sent.get("plans") or unread != _SMART_CLOCK.get("unread"):
            _SMART_CLOCK["unread"] = unread
            log.info("smart clock: %s", json.dumps(got, separators=(",", ":"), default=str)[:400])
    except Exception as exc:  # noqa: BLE001 - the clock's next tick asks again
        log.warning("smart clock: %s", type(exc).__name__)


def _smart_clock_kick() -> None:
    """Starts a turn when one is due and none is running: the events every SMART_CLOCK_EVERY_S, the reminders and
    digests every SMART_CLOCK_REMIND_EVERY_S."""
    now = time.time()
    task = _SMART_CLOCK["task"]
    if (task is not None and not task.done()) or now - _SMART_CLOCK["at"] < SMART_CLOCK_EVERY_S:
        return
    _SMART_CLOCK["at"] = now
    remind = now - _SMART_CLOCK["reminded"] >= SMART_CLOCK_REMIND_EVERY_S
    _SMART_CLOCK["task"] = asyncio.create_task(_smart_clock_turn(remind))


async def _smart_clock_desk_run(raw: bytes) -> Response:
    """smartCommsRun (the Desk's Run, an admin's): one whole turn of the clock now, events first."""
    def said(env: dict[str, Any]) -> Response:
        return Response(json.dumps(env), media_type="application/json")

    env = _relay_envelope(raw)
    if not isinstance(env, dict):
        return said({"status": 400, "message": "The request could not be read."})
    token = str(env.get("token") or "")
    actor = await _session_actor(f"Bearer {token}") if token and not _relay_is_service(raw) else None
    if not actor or str(actor[0] or "").strip().lower() != "admin":
        return said({"status": 403, "message": "Requires an admin account"})
    task = _SMART_CLOCK["task"]
    if task is not None and not task.done():
        await asyncio.wait({task}, timeout=HUB_APP_PACK_TIMEOUT_S)
    got = await _smart_clock_run(True)
    if got is None:
        return said(SMART_CLOCK_UNREAD)
    _SMART_CLOCK["reminded"] = time.time()
    body = json.dumps({"status": 200, "data": got}, default=str)
    _smart_comms_rang("smartCommsRun", body.encode())
    return Response(body, media_type="application/json")


# the clock riders — the lane mirrors (and their rewrite after a hotline filing), the pattern scan, the call-off form's
# crossing — and the automatic inbound pass, each Python's on this relay's clock
LANE_MIRROR_APP = "lane-mirror"
DUP_SCAN_APP = "dup-scan"
CALL_OFF_FORM_SWEEP_APP = "call-off-form-sweep"
# in the hiring sweep's order: each rider's look, and its write; every look keeps its own throttle (the script cache's
# keys, app.clock_sweeps_state), so the fast beat asks every CLOCK_SWEEPS_EVERY_S
CLOCK_SWEEPS: tuple[tuple[str, str, str], ...] = (
    (LANE_MIRROR_APP, "laneMirrorDue", "laneMirrorSweep"), (DUP_SCAN_APP, "dupScanDue", "dupScanSweep"),
    (CALL_OFF_FORM_SWEEP_APP, "callOffFormDue", "callOffFormSweep"))
CLOCK_SWEEPS_EVERY_S = 120.0
_CLOCK_SWEEPS: dict[str, Any] = {"at": 0.0, "task": None, "after": None, "again": False}


async def _clock_sweep_python(app_id: str, look: str, sweep: str) -> dict[str, Any] | None:
    """One rider on Python: its look, then — when it says something is due — its write handed the look's answer, again
    with what a pass hands back (`left`, and the count so far) until nothing is left; the last write's answer, None
    when nothing was due or Python did not answer."""
    got = await _backend_call(app_id, look, {}, {"is_service": True}, timeout=BACKEND_PREPARE_TIMEOUT_S)
    read = got[2] if got is not None else None
    data = read.get("data") if read and read.get("status") == 200 and isinstance(read.get("data"), dict) else None
    if data is None:
        log.warning("clock riders: %s not read (%s)", look,
                    str((read or {}).get("message") or _BACKEND_UNANSWERED.get())[:160])
        return None
    if not data.get("due"):
        return None
    payload: dict[str, Any] = {"prepared": data}
    env: dict[str, Any] = {}
    for _ in range(COMM_LANE_PASSES):
        env = await _backend_pass(app_id, sweep, payload)
        if env.get("status") != 200:
            log.warning("clock riders: %s did not land (%s)", sweep, str(env.get("message") or env.get("status"))[:160])
            return None
        env.pop("_write", None)
        out = env.get("data") or {}
        if not out.get("left"):
            break
        payload = {"prepared": {**data, "plans": out["left"]}, "out": out.get("out")}
    return env


async def _clock_sweeps_turn() -> None:
    """The riders in the hiring sweep's order; the attendance rows the call-off form hands back pressed through Staff
    attendance's own lane (staffAttendancePunch). Never raises."""
    credential = ({"service_secret": SERVICE_SECRET} if SERVICE_SECRET else {"token": SERVICE_TOKEN})
    for app_id, look, sweep in CLOCK_SWEEPS:
        try:
            env = await _clock_sweep_python(app_id, look, sweep)
            data = (env or {}).get("data") or {}
            if not env:
                continue
            log.info("clock riders: %s %s", sweep, json.dumps({k: v for k, v in data.items() if k != "handed"},
                                                              separators=(",", ":"), default=str)[:300])
            for hand in data.get("handed") or []:
                if hand.get("action") != "staffAttendancePunch":
                    continue
                said = await _staff_door("staffAttendancePunch", hand.get("payload") or {}, credential)
                log.info("clock riders: the form's late and no-show rows → %s",
                         json.dumps((said or {}).get("data") or (said or {}).get("message"), default=str)[:200])
        except Exception as exc:  # noqa: BLE001 - the next turn asks again
            log.warning("clock riders: %s (%s)", sweep, type(exc).__name__)


def _clock_sweeps_kick() -> None:
    """Starts a turn when one is due and none is running."""
    now = time.time()
    task = _CLOCK_SWEEPS["task"]
    if (task is not None and not task.done()) or now - _CLOCK_SWEEPS["at"] < CLOCK_SWEEPS_EVERY_S:
        return
    _CLOCK_SWEEPS["at"] = now
    _CLOCK_SWEEPS["task"] = asyncio.create_task(_clock_sweeps_turn())


async def _lane_mirror_after_filing() -> None:
    """laneMirrorAfterFiling_ on Python: what a hotline filing just wrote, mirrored into the three houses at once —
    again when another filing landed meanwhile. Never raises."""
    while True:
        _CLOCK_SWEEPS["again"] = False
        try:
            env = await _backend_pass(LANE_MIRROR_APP, "laneMirrorAfterFiling", {})
            if env.get("status") != 200:
                log.warning("lane mirror after filing: %s", str(env.get("message") or env.get("status"))[:160])
            elif (env.get("data") or {}).get("rewrites"):
                log.info("lane mirror after filing: %s rewritten", ",".join(env["data"]["rewrites"]))
        except Exception as exc:  # noqa: BLE001 - the clock's next turn catches up
            log.warning("lane mirror after filing: %s", type(exc).__name__)
        if not _CLOCK_SWEEPS["again"]:
            return


def _lane_mirror_after_filing_kick() -> None:
    task = _CLOCK_SWEEPS["after"]
    if task is not None and not task.done():
        _CLOCK_SWEEPS["again"] = True
        return
    _CLOCK_SWEEPS["after"] = asyncio.create_task(_lane_mirror_after_filing())


# one window-ask sweep's passes together, as Apps Script's COMM_WINDOW_ASK_BUDGET_MS held them
COMM_WINDOW_ASK_BUDGET_S = 60.0


async def _comm_window_ask_door(raw: bytes) -> Response:
    """commWindowAskSweep (an admin's, or the service's) while the window ask is Python's: the look
    (commWindowAskPlan), then its plans kept pass by pass (commWindowAskKeep) inside the sweep's own budget; the
    sweep's answer."""
    def said(env: dict[str, Any]) -> Response:
        return Response(json.dumps(env, default=str), media_type="application/json")

    env = _relay_envelope(raw)
    if not isinstance(env, dict):
        return said({"status": 400, "message": "The request could not be read."})
    if not _relay_is_service(raw):
        token = str(env.get("token") or "")
        actor = await _session_actor(f"Bearer {token}") if token else None
        if not actor or str(actor[0] or "").strip().lower() != "admin":
            return said({"status": 403, "message": "Requires an admin or manager account"})
    payload = env.get("payload") if isinstance(env.get("payload"), dict) else {}
    force = payload.get("force") is True or str(payload.get("force")) == "true"
    got = await _backend_call(COMM_WINDOW_ASK_APP, "commWindowAskPlan", {"force": force}, {"is_service": True},
                              timeout=HUB_APP_PACK_TIMEOUT_S)
    read = got[2] if got is not None else None
    if not read or read.get("status") != 200 or not isinstance(read.get("data"), dict):
        return said({"status": 503, "message": "The window ask could not be asked just now. Try again in a moment."})
    plan = read["data"]
    if not plan.pop("due", False):
        return said({"status": 200, "data": plan})
    plans, tally, first = plan.get("plans") or [], {}, True
    started = time.monotonic()
    while True:
        last = time.monotonic() - started > COMM_WINDOW_ASK_BUDGET_S
        kept = await _backend_pass(COMM_WINDOW_ASK_APP, "commWindowAskKeep",
                                   {"run": plan.get("run"), "plans": plans, "first": first,
                                    "stamp": plan.get("stamp") is True, "last": last, "tally": tally})
        if kept.get("status") != 200:
            return said(kept)
        out = kept.get("data") or {}
        first = False
        plans, tally = out.pop("left", None) or [], out.pop("tally", None) or tally
        if not plans or last:
            return said({"status": 200, "data": out})


async def _app_release_noticed(action: str, payload: Any) -> None:
    """An App Control save that landed, handed to Python: the badges each rule now holds and the app's own words.
    Never raises."""
    caught = _LIVE_CAPTURE.get()
    if caught is not None:
        # asa-hub-app's finish hands it to Python itself (app/live_finish.py)
        caught["released"].append([action, payload])
        return
    try:
        p = payload if isinstance(payload, dict) else {}
        if action == "appBadgeAccessSet":
            app_id = str(p.get("app_id") or "").strip()
            rules = {app_id: p.get("badges")} if app_id else {}
            meta = {app_id: p.get("app_meta")} if app_id and isinstance(p.get("app_meta"), dict) else {}
        elif action == "appAccessSetBulk":
            rules = p.get("rules") if isinstance(p.get("rules"), dict) else {}
            meta = p.get("app_meta") if isinstance(p.get("app_meta"), dict) else {}
        else:
            return
        if not rules:
            return
        meta = {a: {"name": str((m or {}).get("name") or ""), "tagline": str((m or {}).get("tagline") or "")}
                for a, m in meta.items() if isinstance(m, dict)}
        write_id = "W" + hashlib.sha256(f"app-release|{time.time_ns()}".encode()).hexdigest()[:24]
        got = await _backend_call("app-release", "appReleaseNoticed", {"rules": rules, "meta": meta},
                                  {"is_service": True}, extra={"write_id": write_id}, timeout=HUB_APP_PACK_TIMEOUT_S)
        env = got[2] if got is not None else None
        if not env or env.get("status") != 200:
            log.warning("app release: the save was not told to Python (%s)",
                        str((env or {}).get("message") or _BACKEND_UNANSWERED.get())[:160])
            return
        log.info("app release: %s", json.dumps(env.get("data") or {}, separators=(",", ":"))[:300])
    except Exception as exc:  # noqa: BLE001 - the clock's pass carries what is owed
        log.warning("app release: %s", type(exc).__name__)


