@app.post("/hub-lanes/house-supplies/meds/preview")
async def lane_house_meds_preview(request: Request, response: Response,
                                 authorization: str = Header(default="")) -> dict[str, Any]:
    """One dropped file: parsed once, judged, staged when new — and every verdict that needs no person recorded…"""
    _meds_no_store(response)
    got = await _meds_reader(authorization, writer=True)
    if isinstance(got, dict):
        return got
    who, session, _scope = got
    # THE BODY IS BOUNDED BEFORE IT IS HELD: a report's base64 and its name, never more — read in chunks and refused…
    cap = house_meds.MAX_BYTES * 4 // 3 + 64 * 1024
    too_big = {"status": 413, "reason": "request",
               "message": "The file is larger than 5 MB — not a pharmacy report. Nothing was kept."}
    declared = str(request.headers.get("content-length") or "").strip()
    if declared.isdigit() and int(declared) > cap:
        return too_big
    held = bytearray()
    async for chunk in request.stream():
        held += chunk
        if len(held) > cap:
            return too_big
    try:
        body = json.loads(bytes(held))
        raw = base64.b64decode(str((body or {}).get("b64") or ""), validate=True)
    except Exception:  # noqa: BLE001
        return {"status": 400, "reason": "request", "message": "Send {name, size, b64} — one file per request."}
    name = str((body or {}).get("name") or "")
    if not raw:
        return {"status": 400, "reason": "request", "message": "The file arrived empty."}
    try:
        data = await asyncio.to_thread(house_meds.preview_upload, MEDS_DSN, name=name, data=raw,
                                       actor=_meds_actor(who, session))
    except Exception as exc:  # noqa: BLE001
        log.warning("house meds: the preview failed (%s)", type(exc).__name__)
        return {"status": 503, "reason": "unreadable",
                "message": f"The file could not be judged ({type(exc).__name__}). Nothing was imported."}
    log.info("house meds: a file was dropped by %s → %s", session[1], data.get("verdict"))
    return {"status": 200, "data": data}


@app.post("/hub-lanes/house-supplies/meds/folder")
async def lane_house_meds_folder(response: Response,
                                authorization: str = Header(default="")) -> dict[str, Any]:
    """Read the Drive folder: what is on file is skipped without a download, at most a batch of new files is…"""
    _meds_no_store(response)
    got = await _meds_reader(authorization, writer=True)
    if isinstance(got, dict):
        return got
    who, session, _scope = got
    try:
        data = await asyncio.to_thread(house_meds.folder_read, MEDS_DSN, actor=_meds_actor(who, session))
    except Exception as exc:  # noqa: BLE001
        log.warning("house meds: the folder read failed (%s)", type(exc).__name__)
        return {"status": 503, "reason": "unreadable",
                "message": f"The folder could not be read ({type(exc).__name__})."}
    if data.get("busy"):
        return {"status": 409, "reason": "busy", "message": f"The folder is being read by {data.get('by')}.",
                "data": data}
    if data.get("error"):
        return {"status": 502, "reason": "unreadable", "message": f"The folder could not be read — {data['error']}.",
                "data": data}
    log.info("house meds: folder read by %s — %s listed, %s on file, %s downloaded, %s remaining",
             session[1], data.get("listed"), data.get("known"), data.get("downloaded"), data.get("remaining"))
    return {"status": 200, "data": data}


@app.post("/hub-lanes/house-supplies/meds/commit")
async def lane_house_meds_commit(request: Request, response: Response,
                                authorization: str = Header(default="")) -> dict[str, Any]:
    """Import the staged files named — by stage id, never a line: the rows come only from the relay's own staging."""
    _meds_no_store(response)
    got = await _meds_reader(authorization, writer=True)
    if isinstance(got, dict):
        return got
    who, session, _scope = got
    try:
        body = await request.json()
        staged = [str(s) for s in ((body or {}).get("staged") or []) if str(s).strip()][:200]
    except Exception:  # noqa: BLE001
        return {"status": 400, "reason": "request", "message": "Send {staged: [stage ids]}."}
    if not staged:
        return {"status": 400, "reason": "request", "message": "Nothing was named to import."}
    actor = _meds_actor(who, session)
    py = await _meds_python("houseMedsCommit", {"scope": _scope, "stage_ids": staged[:50], "actor_uid": actor["uid"],
                                                "actor_label": actor["label"]}, session, write=True,
                            answers=frozenset({200, 400, 403}))
    if py is not None:
        log.info("house meds: commit by %s (Python) → %s", session[1], (py.get("data") or {}).get("counts"))
        return py
    try:
        data = await asyncio.to_thread(house_meds.commit, MEDS_DSN, staged, actor=actor)
    except Exception as exc:  # noqa: BLE001
        log.warning("house meds: the commit failed (%s)", type(exc).__name__)
        return {"status": 503, "reason": "unreadable",
                "message": f"The import could not be written ({type(exc).__name__})."}
    log.info("house meds: commit by %s → %s", session[1], data.get("counts"))
    _house_meds_wake()
    return {"status": 200, "data": data}


@app.post("/hub-lanes/house-supplies/meds/match")
async def lane_house_meds_match(request: Request, response: Response,
                               authorization: str = Header(default="")) -> dict[str, Any]:
    """A person's match of a PatID to a client (or to another PatID of the same person)."""
    _meds_no_store(response)
    got = await _meds_reader(authorization, writer=True)
    if isinstance(got, dict):
        return got
    who, session, _scope = got
    try:
        body = await request.json() or {}
    except Exception:  # noqa: BLE001
        return {"status": 400, "reason": "request", "message": "Send {patid, client_key}."}
    py = await _meds_python("houseMedsMatch", {"scope": _scope, "patid": str(body.get("patid") or "")[:40],
                                               "client_key": str(body.get("client_key") or "")[:120],
                                               "same_as": str(body.get("same_as") or "")[:40],
                                               "by": _meds_actor(who, session)["label"]}, session, write=True,
                            answers=frozenset({200, 400, 403, 404}))
    if py is not None:
        return py
    try:
        data = await asyncio.to_thread(house_meds.match, MEDS_DSN, patid=str(body.get("patid") or ""),
                                       client_key=str(body.get("client_key") or ""),
                                       same_as=str(body.get("same_as") or ""),
                                       by=_meds_actor(who, session)["label"])
    except LookupError:
        return {"status": 404, "reason": "missing", "message": "No such PatID."}
    except ValueError as exc:
        return {"status": 400, "reason": "request", "message": str(exc)}
    except Exception as exc:  # noqa: BLE001
        log.warning("house meds: the match failed (%s)", type(exc).__name__)
        return {"status": 503, "reason": "unreadable",
                "message": f"The match could not be written ({type(exc).__name__})."}
    _house_meds_wake()
    return {"status": 200, "data": data}


_HOUSE_MEDS_NOW = asyncio.Event()


def _house_meds_wake() -> None:
    """A commit or a match owes the house copy a pass: sooner than the beat."""
    try:
        _HOUSE_MEDS_NOW.set()
    except Exception:  # noqa: BLE001
        pass


async def _house_meds_loop() -> None:
    """THE LANE'S OWN BEAT."""
    if not MEDS_DSN:
        log.warning("house meds: HUB_HOUSE_MEDS_DSN is not set — the lane's tables are asa-hub-db's; its beat is off")
        return
    try:
        await asyncio.to_thread(house_meds.prepare, MEDS_DSN)
    except Exception as exc:  # noqa: BLE001 — the doors build it on first read
        log.warning("house meds: the lane could not be prepared (%s)", type(exc).__name__)
    while True:
        try:
            await asyncio.wait_for(_HOUSE_MEDS_NOW.wait(), timeout=60)
        except asyncio.TimeoutError:
            pass
        _HOUSE_MEDS_NOW.clear()
        try:
            if await asyncio.to_thread(house_meds.sweep_due, MEDS_DSN):
                said = await asyncio.to_thread(house_meds.sweep, MEDS_DSN)
                read = said.get("read") or {}
                log.info("house meds: sweep — %s listed, %s on file, %s imported%s", read.get("listed"),
                         read.get("known"), len(said.get("imported") or []),
                         f" — {read.get('error')}" if read.get("error") else "")
        except Exception as exc:  # noqa: BLE001
            log.warning("house meds: the sweep failed (%s)", type(exc).__name__)
        # the pharmacy's reports are Postgres' record (app.hub_med_*): the ASA Data books follow when the Postgres →
        # sheet sync does


# the app packs' clocks (APP PACKS, below): fresh, the ceiling nothing older is served past, and the warm pass's beat
APP_PACK_FRESH_S = max(60.0, float(os.getenv("HUB_APP_PACK_FRESH_S", "2400")))
APP_PACK_CEILING_S = max(APP_PACK_FRESH_S, float(os.getenv("HUB_APP_PACK_CEILING_S", "14400")))
APP_PACK_WARM_EVERY_S = max(60.0, float(os.getenv("HUB_APP_PACK_WARM_EVERY_S", "600")))
# the bounded background refill: every this long, on the housekeeping lane and within its slots, the packs of keys a…
APP_PACK_REFILL_S = max(60.0, float(os.getenv("HUB_BACKGROUND_REFILL_S", "180")))
APP_PACK_RECENT_S = max(APP_PACK_REFILL_S, float(os.getenv("HUB_BACKGROUND_RECENT_S", "1800")))
# where the filled packs are kept across restarts: a volume of their own, mounted into this relay alone — never a…
APP_PACK_DEFAULT_DIR = "/srv/app-packs"
APP_PACK_DIR = os.getenv("HUB_APP_PACK_DIR", APP_PACK_DEFAULT_DIR).strip()


# -------------------------------------------------------------------------- LIVE CHAT (server/chat_live.py): the…
_CHAT_KEY = chat_live.derive_key(SERVICE_SECRET) if chat_live is not None else ""
_chat_refs = chat_live.Registry() if chat_live is not None else None
_chat_unsettled = chat_live.Unsettled() if chat_live is not None else None
_chat_feed = chat_live.Feed(_CHAT_KEY) if chat_live is not None else None
# its own slots: chat and /gas never starve each other
_chat_live_slots = asyncio.Semaphore(chat_live.EXEC_CONCURRENCY if chat_live is not None else 1)
_chat_live_by_action: dict[str, int] = {}
_CHAT_LIVE_DOWN = {"status": 503, "reason": "unavailable", "message": "Live chat is not available on this server."}
_CHAT_LIVE_ACTING = {"status": 409, "code": "be_another_refused", "reason": "acting",
                     "message": "Chat is off while acting as someone else. Press Be Back to chat as yourself."}
_CHAT_LIVE_VISIT = "Live chat answers the signed-in account only; it is not opened inside a visit."
# Its own list, not My Inbox's.
_CHAT_LIVE_ROLES_REFUSED = ("onboarding", "interviewer")
_CHAT_LIVE_UNNARROWED = {"status": 503, "reason": "narrowing",
                         "message": "Live chat is not open to this account yet: the chat that shows it only its own "
                                    "people has not been published."}
_CHAT_LIVE_NOT_LISTED = {"status": 404, "reason": "circle", "message": "Not found."}


def _chat_live_fold_rows() -> list[dict[str, Any]]:
    """The Core users copy, for the accounts folded onto one person (Chat.gs chatPeopleIndex_)."""
    with psycopg2.connect(PG_DSN, connect_timeout=5) as conn, conn.cursor() as cur:
        cur.execute("select data from asa_drive_sheets_rows where sheet_id = %s and tab_name = 'users'",
                    (HUB_DB_SHEET_ID,))
        return [r[0] for r in cur.fetchall() if isinstance(r[0], dict)]


_chat_fold = chat_live.FoldCache(_chat_live_fold_rows) if chat_live is not None else None


def _chat_live_answer(env: dict[str, Any], http: int | None = None) -> JSONResponse:
    return JSONResponse(env, status_code=int(http or env.get("status") or 200),
                        headers={"Cache-Control": "no-store"})


def _chat_live_emit(event: dict[str, Any], tries: int = 1) -> None:
    """Hand one event to the hub, out of everyone's way; nothing without a loop or a key."""
    if _chat_feed is None or not _chat_feed.enabled:
        return
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return
    _keep_task(_chat_feed.send(event, tries=tries))


def _chat_live_revoke(token: str) -> None:
    """A session that ended: its refs are forgotten here and the hub closes their connections."""
    if _chat_refs is None or not token:
        return
    refs = _chat_refs.revoke_token(token)
    if refs:
        _chat_live_emit({"kind": "revoke", "refs": refs}, tries=chat_live.REVOKE_TRIES)


def _chat_live_ended(token: str) -> bool:
    """A session live chat must stop carrying: acting as someone else now, or known here as signed out."""
    if _my_work_acting(token):
        return True
    hit = _auth_cache.get(token)
    if hit is None or hit[1]:
        return False
    return _auth_unsure.get(token) != hit[0]


def _chat_live_observed(raw: bytes, content: bytes, source: str) -> None:
    """A chat write that landed outside the hub (a /gas answer, a ledger delivery): the hub nudges both ends."""
    _chat_cache_observed(raw, content)
    if chat_live is None or _chat_feed is None or not _chat_feed.enabled or b"chat" not in raw[:4096]:
        return
    try:
        event = chat_live.observed_event(raw, content, token_user=_token_user_get, held=False, source=source)
        if event is None:
            return
        if event["kind"] == "nudge":
            event["held"] = bool(lane_gate.holds(lane_gate.CHAT_FRAME)["held"])
    except Exception:  # noqa: BLE001 - observation, never a failure mode
        return
    _chat_live_emit(event)


def _chat_live_unanswered(raw: bytes, delays: tuple[float, ...]) -> None:
    """A /gas send answered `accepted` without its receipt: the row lands after the answer, and nothing else…"""
    _chat_cache_observed(raw, None)
    if chat_live is None or _chat_feed is None or not _chat_feed.enabled or not delays or b"chat" not in raw[:4096]:
        return
    try:
        event = chat_live.unanswered_event(raw, token_user=_token_user_get, source="gas")
    except Exception:  # noqa: BLE001 - observation, never a failure mode
        return
    if event is None:
        return

    async def later() -> None:
        waited = 0.0
        for at in sorted(delays):
            await asyncio.sleep(max(0.0, at - waited))
            waited = max(waited, at)
            try:
                held = bool(lane_gate.holds(lane_gate.CHAT_FRAME)["held"])
            except Exception:  # noqa: BLE001 - a gate that cannot answer holds
                held = True
            await _chat_feed.send({**event, "held": held})

    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return
    _keep_task(later())


async def _chat_live_hello() -> None:
    """After a start the hub's tabs hold refs this process never minted: they are asked to re-ticket."""
    if _chat_feed is None or not _chat_feed.enabled:
        return
    for wait in (5.0, 30.0, 120.0):
        await asyncio.sleep(wait)
        if await _chat_feed.send({"kind": "hello"}):
            return


def _chat_live_health() -> dict[str, Any]:
    if chat_live is None or _chat_refs is None:
        return {"loaded": False}
    return {"loaded": True, "keyed": bool(_CHAT_KEY), **_chat_refs.counts(),
            "unsettled": len(_chat_unsettled) if _chat_unsettled is not None else 0,
            "by_action": dict(_chat_live_by_action),
            "feed": _chat_feed.health() if _chat_feed is not None else None,
            "folds_unreadable": _chat_fold.unreadable if _chat_fold is not None else "",
            "cache": _chat_cache_health(), "behind": _chat_behind_health()}


# THE CHAT IS PYTHON'S (app/chat.py, its own tables in asa-hub-db): every chat action — live chat's, the chat page's
# and the shell's heartbeat — is answered there, as the session the relay verified, and never by Apps Script.
CHAT_APP = "chat"
CHAT_PYTHON_ACTIONS = frozenset({"chatOverview", "chatMessages", "chatSend", "chatReact", "chatMarkRead", "chatPing"})
_CHAT_PYTHON_WRITES = frozenset({"chatSend", "chatReact", "chatMarkRead"})
CHAT_PYTHON_TIMEOUT_S = float(os.getenv("HUB_CHAT_PYTHON_TIMEOUT_S", "8"))
_CHAT_UNREAD = {"status": 503, "message": "The chat could not be read just now. Try again in a moment."}
_CHAT_UNSENT = {"status": 503, "message": "The chat could not be reached just now, and nothing was sent. "
                                          "Try again in a moment."}
_CHAT_AWAY = {"status": 409, "message": "The chat is read from your own workspace — not on a visit, in a world or at "
                                        "another place."}
_CHAT_SERVICE = {"status": 403, "message": "A service session does not chat."}


async def _chat_python_ask(env: dict[str, Any], payload: dict[str, Any],
                           timeout: float = CHAT_PYTHON_TIMEOUT_S) -> tuple[dict[str, Any] | None, str]:
    """(envelope, '') from Python; (None, why) when a write was asked and not answered, so it may still have landed
    (its write id settles it)."""
    action = str(env.get("action") or "")
    write = action in _CHAT_PYTHON_WRITES
    token = str(env.get("token") or "")
    authorization = f"Bearer {token}"
    actor = await _session_actor(authorization) if token else None
    if not actor or not str(actor[1] or ""):
        return {"status": 401, "message": "Authentication required."}, ""
    # a switched session reads the person's conversations as Chat.gs let it, and writes nothing in them
    switched = _my_work_acting(token)
    if switched and write:
        return dict(_CHAT_LIVE_ACTING), ""
    if any(str(env.get(k) or "").strip() for k in ("member", "world", "tenant")):
        return dict(_CHAT_AWAY), ""
    master, unsure = await _app_pack_master(authorization)
    if unsure:
        return {"status": 503, "message": f"The chat could not open: the master check could not be made ({unsure})."}, ""
    uid = str(actor[1])
    _token_user_put(token, uid)
    user = {"uid": uid, "role": str(actor[0] or "").strip().lower(), "is_master": bool(master)}
    if switched:
        # it leaves no line and stamps no presence: it is not the person at a keyboard
        user["unlogged"] = True
    wid = str(env.get("write_id") or "") if write else ""
    got = await _backend_call(CHAT_APP, action, payload, user, extra={"write_id": wid} if wid else None,
                              timeout=max(1.0, min(CHAT_PYTHON_TIMEOUT_S, timeout)))
    if got is not None:
        _traffic_note("backend_python")
        return got[2], ""
    # _backend_call has said why in the log; it is never handed to Apps Script
    why = _BACKEND_UNANSWERED.get() or "no answer"
    if write and not why.startswith("it deferred"):
        return None, why
    return dict(_CHAT_UNSENT if write else _CHAT_UNREAD), ""


async def _chat_python_gas(action: str, raw: bytes) -> Response:
    """A chat action from /gas (the chat page, the shell's heartbeat), answered by Python, then told everywhere an
    Apps Script answer was: the stream, live chat and the push."""
    def said(env: dict[str, Any]) -> Response:
        return Response(json.dumps(env), media_type="application/json")

    env = _relay_envelope(raw)
    if not isinstance(env, dict):
        return said({"status": 400, "message": "The request could not be read."})
    if _relay_is_service(raw):
        return said(dict(_CHAT_SERVICE))
    payload = chat_live.clean_payload(action, env.get("payload")) if chat_live is not None else {}
    if "reason" in payload:
        return said(payload)
    if action in _CHAT_PYTHON_WRITES and not re.fullmatch(r"[A-Za-z0-9_.:\-]{8,80}", str(env.get("write_id") or "")):
        env["write_id"] = "W" + hashlib.sha256(raw + str(time.time_ns()).encode()).hexdigest()[:24]
        raw = urllib.parse.urlencode({"body": json.dumps(env)}).encode()
    answer, _why = await _chat_python_ask(env, payload)
    if answer is None:
        # sent, outcome unknown: both ends are nudged to read again, as for a send Apps Script left unanswered
        _chat_push_unanswered(raw, echo=False)
        _chat_live_unanswered(raw, chat_live.UNANSWERED_NUDGE_S if chat_live is not None else ())
        return said({"status": 200, "data": {"accepted": True, "confirmed": False}})
    content = json.dumps(answer).encode()
    if answer.get("status") == 200:
        _relay_observe_chat(raw, content)
        _relay_observe_chat_read(raw, content)
        _chat_live_observed(raw, content, "gas")
        _chat_push_observed(raw, content)
    if action in _CHAT_BEHIND_READS:
        content = _chat_behind_gas_read(raw, content)
    return Response(content, media_type="application/json")


async def _chat_live_post(raw: bytes, timeout: float) -> tuple[str, bytes]:
    """One chat action asked of Python on live chat's own slots: (json | connect | timeout | error, body)."""
    began = time.monotonic()
    try:
        await asyncio.wait_for(_chat_live_slots.acquire(), timeout=max(0.1, timeout))
    except asyncio.TimeoutError:
        return "connect", b""        # never left the machine
    left = timeout - (time.monotonic() - began)
    if left < chat_live.MIN_POST_S:
        _chat_live_slots.release()
        return "connect", b""        # the wait spent the budget: it never left either
    try:
        env = _relay_envelope(raw) or {}
        payload = env.get("payload") if isinstance(env.get("payload"), dict) else {}
        answer, _why = await asyncio.wait_for(_chat_python_ask(env, payload, left), timeout=left)
    except asyncio.TimeoutError:
        return "timeout", b""
    except Exception:  # noqa: BLE001 - it left, and nobody knows how it ended
        return "error", b""
    finally:
        _chat_live_slots.release()
    if answer is None:
        return "timeout", b""        # a write Python may have kept: its write id settles it
    return "json", json.dumps(answer).encode()


async def _chat_live_whoami(authorization: str, token: str) -> tuple[str, str] | None:
    """(uid, role): the gate's own memory first, then one sign-in check, as /chat/stream asks it."""
    actor = await _session_actor(authorization)
    uid = _token_user_get(token) or (str(actor[1] or "") if actor else "")
    if actor and uid:
        return uid, str(actor[0] or "")
    try:
        env = await _auth_me(token)
    except Exception:  # noqa: BLE001
        return None
    user = ((env.get("data") or {}).get("user") or {}) if env.get("status") == 200 else {}
    uid = str(user.get("id") or user.get("user_id") or "")
    if not uid:
        return None
    # the acting table first: a switched session learned here is refused as one
    _note_session_answer(token, env)
    role = str(user.get("role") or "")
    _auth_cache_put(token, True, role, uid,
                    is_master=(bool(user.get("is_master")) if "is_master" in user else None))
    _token_user_put(token, uid, str(user.get("display_name") or user.get("name") or ""))
    return uid, role


def _chat_live_rail_kept(ref: str, answer: dict[str, Any]) -> dict[str, Any]:
    """A narrowed ref's rail, carried only as Chat.gs marked it; the ids it names are kept for the ref."""
    if "reason" in answer or answer.get("status") != 200:
        return answer
    got = chat_live.narrow_overview(answer.get("data"))
    if got is None:
        _chat_refs.set_listed(ref, None)
        return dict(_CHAT_LIVE_UNNARROWED)
    _chat_refs.set_listed(ref, got[1])
    return {**answer, "data": got[0]}


async def _chat_live_narrowed_exec(req: dict[str, Any], entry: dict[str, Any], raw: bytes,
                                   write_id: str) -> dict[str, Any]:
    """A client's or a guardian's action: nothing leaves for a person its last marked rail did not name, and a…"""
    ref, action = req["ref"], req["action"]
    if action != "chatOverview" and _chat_refs.listed(ref) is None:
        first_raw = chat_live.form(chat_live.envelope(entry["token"], entry["tenant"], "chatOverview", {}))
        first = _chat_live_rail_kept(ref, await _chat_live_run(ref, entry, "chatOverview", {}, first_raw))
        if "reason" in first or first.get("status") != 200:
            return first
    if action != "chatOverview":
        who = chat_live.person_in(action, req["payload"])
        if who and who not in (_chat_refs.listed(ref) or frozenset()):
            return dict(_CHAT_LIVE_NOT_LISTED)
    answer = await _chat_live_run(ref, entry, action, req["payload"], raw, write_id)
    return _chat_live_rail_kept(ref, answer) if action == "chatOverview" else answer


async def _chat_live_body(request: Request) -> dict[str, Any] | None:
    try:
        raw = await request.body()
        body = json.loads(raw) if raw.strip() else {}
    except Exception:  # noqa: BLE001
        return None
    return body if isinstance(body, dict) else None


@app.post("/chat/ticket")
async def chat_ticket(request: Request, member: str = "", authorization: str = Header(default=""),
                      x_hub_tenant: str = Header(default="")) -> Response:
    """A ticket the live chat hub redeems within a minute; the session token stays in this process."""
    if chat_live is None or _chat_refs is None or _chat_fold is None:
        return _chat_live_answer(dict(_CHAT_LIVE_DOWN))
    token = _hotline_token(authorization)
    if not token:
        return _chat_live_answer(chat_live.refusal(401, "session", "sign in first"))
    body = await _chat_live_body(request)
    if body is None:
        return _chat_live_answer(chat_live.refusal(400, "body", "The body could not be read."))
    if str(member or "").strip() or chat_live.has_refused_field(body, dict(request.query_params)):
        return _chat_live_answer(chat_live.refusal(400, "member", _CHAT_LIVE_VISIT))
    if _my_work_acting(token):
        return _chat_live_answer(dict(_CHAT_LIVE_ACTING))
    who = await _chat_live_whoami(authorization, token)
    if who is None:
        return _chat_live_answer(chat_live.refusal(401, "session", "This session could not be confirmed."))
    if _my_work_acting(token):
        return _chat_live_answer(dict(_CHAT_LIVE_ACTING))
    uid = who[0]
    unsure = await _my_work_learn_master(authorization)
    gate = await _hotline_actor(authorization, app_id=chat_live.APP_ID, refuse_roles=_CHAT_LIVE_ROLES_REFUSED,
                                app_label=chat_live.APP_LABEL, floor=False)
    if isinstance(gate, dict):
        if unsure:
            return _chat_live_answer(chat_live.refusal(
                503, "unavailable", f"Live chat could not open: the master check could not be made ({unsure})."))
        refused = _daily_refusal(gate)
        status = int(refused.get("status") or 403)
        return _chat_live_answer(chat_live.refusal(status if status in (401, 403) else 403,
                                                   str(refused.get("reason") or "badge"),
                                                   str(refused.get("message") or "Live chat is not open to you.")))
    tenant = str(x_hub_tenant or "").strip()
    if not chat_live.TENANT_RE.fullmatch(tenant):
        return _chat_live_answer(chat_live.refusal(400, "tenant", "That place cannot be read."))
    person, folds = await asyncio.to_thread(_chat_fold.identity, uid)
    # a session vouched without a sign-in check (the mirror, after a relay restart) has no name here: the users copy…
    name = _token_name_get(token) or await asyncio.to_thread(_chat_fold.name_of, uid)
    ident = {"account_id": uid, "person_id": person or uid, "fold_ids": folds or [uid],
             "name": name, "is_master": _auth_master.get(token) is True,
             "narrowed": chat_live.narrowed(who[1], gate[0])}
    ticket = _chat_refs.mint(token, tenant, ident)
    return _chat_live_answer({"status": 200, "data": {"ticket": ticket, "expires_in": int(chat_live.TICKET_TTL_S)}})


@app.post("/chat/ticket/redeem")
async def chat_ticket_redeem(request: Request, x_hub_chat_key: str = Header(default="")) -> Response:
    """The hub's: a ticket's ref and whose it is. Never the session token."""
    if chat_live is None or _chat_refs is None:
        return _chat_live_answer(dict(_CHAT_LIVE_DOWN))
    if not chat_live.key_ok(x_hub_chat_key, _CHAT_KEY):
        return _chat_live_answer(chat_live.refusal(401, "key", "This door is the live chat hub's."))
    body = await _chat_live_body(request)
    if body is None:
        return _chat_live_answer(chat_live.refusal(400, "body", "The body could not be read."))
    got = _chat_refs.redeem(str(body.get("ticket") or ""))
    if got is None:
        return _chat_live_answer(chat_live.refusal(401, "ticket", "That ticket is expired, used up or unknown."))
    entry = _chat_refs.lookup(got["ref"])
    if entry is None:
        return _chat_live_answer(chat_live.refusal(401, "ref_unknown", "That session is not known here."))
    if _my_work_acting(entry["token"]):
        _chat_live_revoke(entry["token"])
        return _chat_live_answer(dict(_CHAT_LIVE_ACTING))
    _chat_push_seen(got.get("fold_ids"))
    return _chat_live_answer({"status": 200, "data": got})


@app.post("/chat/exec")
async def chat_exec(request: Request, x_hub_chat_key: str = Header(default="")) -> Response:
    """The hub's: one chat action as the ref's session, in the ref's tenant — never a visit, never the ledger."""
    if chat_live is None or _chat_refs is None or _chat_unsettled is None:
        return _chat_live_answer(dict(_CHAT_LIVE_DOWN), http=200)
    if not chat_live.key_ok(x_hub_chat_key, _CHAT_KEY):
        return _chat_live_answer(chat_live.refusal(401, "key", "This door is the live chat hub's."))
    body = await _chat_live_body(request)
    req = chat_live.exec_request(body) if body is not None else chat_live.refusal(400, "body", "Unreadable body.")
    if "reason" in req:
        return _chat_live_answer(req, http=200)
    entry = _chat_refs.lookup(req["ref"])
    if entry is None:
        return _chat_live_answer(chat_live.refusal(
            401, "ref_unknown", "This live chat session is not known here; ask for a new ticket."), http=200)
    token = entry["token"]
    if _my_work_acting(token):
        _chat_live_revoke(token)
        return _chat_live_answer(dict(_CHAT_LIVE_ACTING), http=200)
    action = req["action"]
    ident = entry["ident"]
    _chat_push_seen(ident.get("fold_ids"))
    write_id = (chat_live.write_id_for(str(ident.get("account_id") or ""), req["client_id"])
                if action in chat_live.WRITES else "")
    raw = chat_live.form(chat_live.envelope(token, entry["tenant"], action, req["payload"], write_id))
    if action == "chatSend" and not ident.get("narrowed"):
        # kept here first: answered now, told to both ends now, written behind (WRITTEN BEHIND)
        kept = await _chat_behind_keep(token=token, tenant=entry["tenant"], uid=str(ident.get("account_id") or ""),
                                       role="", is_master=bool(ident.get("is_master")), payload=req["payload"],
                                       write_id=write_id, client_id=req["client_id"], source="hub",
                                       name=str(ident.get("name") or ""))
        if kept is not None:
            return _chat_live_answer({**kept, "frame_held": _chat_frame_held()}, http=200)
    if ident.get("narrowed"):
        answer = await _chat_live_narrowed_exec(req, entry, raw, write_id)
    else:
        answer = await _chat_live_run(req["ref"], entry, action, req["payload"], raw, write_id)
    if action == "chatSend":
        _chat_behind_learn(write_id, str(ident.get("account_id") or ""), answer)
    if action in chat_live.WRITES:
        _chat_cache_wrote(action, ident, entry["tenant"], req["payload"], answer)
    # a cached answer ran nothing: no clock moves on it
    if "reason" not in answer and not answer.get("cached"):
        content = json.dumps(answer).encode()
        if answer.get("status") == 200:
            # the SSE tabs still on the old chat hear of it, and the beat's clocks move, as for a /gas answer
            _relay_observe_chat(raw, content)
            _relay_observe_chat_read(raw, content)
            _chat_push_observed(raw, content, ident)
        elif answer.get("status") == 401:
            _chat_live_revoke(token)
            answer = {**answer, "reason": "revoked"}
    try:
        held = bool(lane_gate.holds(lane_gate.CHAT_FRAME)["held"])
    except Exception:  # noqa: BLE001 - a gate that cannot answer holds
        held = True
    return _chat_live_answer({**answer, "frame_held": held}, http=200)


@app.post("/chat/refs")
async def chat_refs(request: Request, x_hub_chat_key: str = Header(default="")) -> Response:
    """The hub's: which refs its connections hold are no longer sessions here."""
    if chat_live is None or _chat_refs is None:
        return _chat_live_answer(dict(_CHAT_LIVE_DOWN), http=200)
    if not chat_live.key_ok(x_hub_chat_key, _CHAT_KEY):
        return _chat_live_answer(chat_live.refusal(401, "key", "This door is the live chat hub's."))
    body = await _chat_live_body(request)
    if body is None:
        return _chat_live_answer(chat_live.refusal(400, "body", "The body could not be read."))
    verdict = chat_live.check_refs(_chat_refs, body.get("refs"), _chat_live_ended)
    _chat_push_listed(body.get("refs"), verdict)
    return _chat_live_answer({"status": 200, "data": verdict})


@app.post("/chat/gate")
async def chat_gate(x_hub_chat_key: str = Header(default="")) -> Response:
    """The hub's: the frame gate as this process holds it now, asked before words reach the other end ahead of…"""
    if chat_live is None:
        return _chat_live_answer(dict(_CHAT_LIVE_DOWN), http=200)
    if not chat_live.key_ok(x_hub_chat_key, _CHAT_KEY):
        return _chat_live_answer(chat_live.refusal(401, "key", "This door is the live chat hub's."))
    try:
        held = bool(lane_gate.holds(lane_gate.CHAT_FRAME)["held"])
    except Exception:  # noqa: BLE001 - a gate that cannot answer holds
        held = True
    return _chat_live_answer({"status": 200, "frame_held": held}, http=200)


# THE CACHE (chat_live.ChatCache).
CHAT_CACHE_DIR = os.getenv("HUB_CHAT_CACHE_DIR", "/srv/app-packs/chat").strip()
CHAT_CACHE_FLUSH_S = 1.0
CHAT_CACHE_EXPIRE_EVERY = 60
# reads behind a cached answer at once, on live chat's own slots: a send never queues behind more than these
CHAT_CACHE_REFRESHES = 2
_chat_cache = chat_live.ChatCache() if chat_live is not None else None
# slot -> reads of it on their way
_chat_cache_busy: dict[tuple[str, ...], int] = {}
_chat_cache_refresh_slots = asyncio.Semaphore(CHAT_CACHE_REFRESHES)
_chat_cache_said: dict[str, Any] = {"refreshes": 0, "refresh_failed": 0, "last_failed": "", "disk": "not started",
                                    "written": 0, "removed": 0, "disk_failed": 0, "disk_last_failed": ""}


def _chat_cache_health() -> dict[str, Any] | None:
    if _chat_cache is None:
        return None
    return {**_chat_cache.counts(), **_chat_cache_said, "reading": len(_chat_cache_busy)}


def _chat_cache_hold(slot: tuple[str, ...] | None, step: int) -> None:
    if slot is None:
        return
    held = _chat_cache_busy.get(slot, 0) + step
    if held > 0:
        _chat_cache_busy[slot] = held
    else:
        _chat_cache_busy.pop(slot, None)


def _chat_cache_ids(ident: dict[str, Any]) -> frozenset[str]:
    """The ids a session is: its person, its account, and every account folded onto that person."""
    return frozenset(str(i) for i in (ident.get("person_id"), ident.get("account_id"), *(ident.get("fold_ids") or ()))
                     if i)


def _chat_cache_place(tenant: Any, uid: str, is_master: bool) -> str | None:
    """The place whose chat a session in this tenant reads (Tenant.gs tenantResolve_): the one it names, else the…"""
    named = str(tenant or "").strip()
    if named:
        return named
    if is_master:
        return ""
    return _chat_fold.home_of(uid) if _chat_fold is not None and uid else None


def _chat_cache_view(ident: dict[str, Any], tenant: Any, action: str,
                     payload: dict[str, Any]) -> dict[str, Any] | None:
    """The slot a read is, and as whom: {slot, ids, narrowed}; None for one the cache does not carry."""
    if _chat_cache is None or _chat_fold is None or action not in chat_live.CACHE_READS:
        return None
    uid, person = str(ident.get("account_id") or ""), str(ident.get("person_id") or "")
    place = _chat_cache_place(tenant, uid, bool(ident.get("is_master")))
    if place is None or not uid or not person:
        return None
    ids = _chat_cache_ids(ident)
    if action == "chatMessages":
        key = chat_live.pair_key(person, _chat_fold.peek_person(str(payload.get("with_user") or "")))
        return {"slot": ("t", place, key), "ids": ids, "narrowed": False} if key else None
    narrowed = bool(ident.get("narrowed"))
    return {"slot": ("o", place, person, uid if narrowed else ""), "ids": ids, "narrowed": narrowed}


def _chat_cache_took(view: dict[str, Any] | None, payload: dict[str, Any], answer: dict[str, Any],
                     began: float) -> None:
    """Apps Script's answer to a read, into the cache: a whole thread or a rail fills its slot, a refusal drops…"""
    if _chat_cache is None or view is None or "reason" in answer:
        return
    slot = view["slot"]
    if answer.get("status") != 200:
        _chat_cache.drop(slot)
        return
    data = answer.get("data")
    if slot[0] == "t":
        if payload.get("after") and not (isinstance(data, dict) and data.get("reset") is True):
            return
        got = _chat_cache.fill_thread(slot[1], slot[2], view["ids"], data, began)
    else:
        got = _chat_cache.fill_rail(slot[1], slot[2], slot[3], data, began, view["narrowed"])
    if got == "wrong":
        _chat_cache.drop(slot)


async def _chat_live_run(ref: str, entry: dict[str, Any], action: str, payload: dict[str, Any], raw: bytes,
                         write_id: str = "") -> dict[str, Any]:
    """One chat action for the exec door."""
    view = None
    if _chat_cache is not None and action in chat_live.CACHE_READS:
        try:
            if _chat_fold is not None and _chat_fold.stale():
                await asyncio.to_thread(_chat_fold.index)
            view = _chat_cache_view(entry["ident"], entry["tenant"], action, payload)
        except Exception:  # noqa: BLE001 - the cache is a shortcut, never the way
            view = None
    if view is not None:
        slot = view["slot"]
        hit = (_chat_cache.thread(slot[1], slot[2], view["ids"], str(payload.get("after") or "")) if slot[0] == "t"
               else _chat_cache.rail(slot[1], slot[2], slot[3]))
        if hit is not None:
            _chat_cache_reread(view, ref, entry, action, payload)
            return {"status": 200, "data": hit, "cached": True}
    _chat_live_by_action[action] = _chat_live_by_action.get(action, 0) + 1
    slot = view["slot"] if view is not None else None
    _chat_cache_hold(slot, 1)
    began = time.monotonic()
    try:
        answer = await chat_live.run_exec(_chat_live_post, raw, action, write_id=write_id, unsettled=_chat_unsettled)
    finally:
        _chat_cache_hold(slot, -1)
    if view is not None:
        try:
            _chat_cache_took(view, payload, answer, began)
            data = answer.get("data") if isinstance(answer.get("data"), dict) else {}
            if (slot[0] == "t" and payload.get("after") and answer.get("status") == 200 and "reason" not in answer
                    and data.get("reset") is not True):
                # a cursor the cache could not answer: the whole thread read behind it, so the next read is instant
                _chat_cache_reread(view, ref, entry, action, payload, force=True)
        except Exception:  # noqa: BLE001
            _chat_cache.forget_all()
    if action in _CHAT_BEHIND_READS:
        # what Apps Script does not carry yet of the sends kept here first (never into the cache: filled above)
        ident = entry["ident"]
        uid = str(ident.get("account_id") or "")
        answer = _chat_behind_overlaid(action, answer, person=str(ident.get("person_id") or ""),
                                       ids=_chat_cache_ids(ident), with_user=str(payload.get("with_user") or ""),
                                       place=_chat_cache_place(entry["tenant"], uid, bool(ident.get("is_master"))))
    return answer


def _chat_cache_reread(view: dict[str, Any], ref: str, entry: dict[str, Any], action: str, payload: dict[str, Any],
                       *, force: bool = False) -> None:
    """The slot read again from Apps Script behind an answer, as the session that asked: one read per slot at a…"""
    slot = view["slot"]
    if _chat_cache is None or _chat_cache_busy.get(slot) or not (force or _chat_cache.needs_refresh(slot)):
        return
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return
    _chat_cache_hold(slot, 1)
    _keep_task(_chat_cache_read_again(view, ref, entry["token"], action,
                                      {k: v for k, v in payload.items() if k != "after"}))


async def _chat_cache_read_again(view: dict[str, Any], ref: str, token: str, action: str,
                                 payload: dict[str, Any]) -> None:
    """One read behind an answer, on its own few slots."""
    slot = view["slot"]
    try:
        async with _chat_cache_refresh_slots:
            entry = _chat_refs.peek(ref) if _chat_refs is not None else None
            if entry is None or entry["token"] != token or _my_work_acting(token):
                return
            raw = chat_live.form(chat_live.envelope(token, entry["tenant"], action, payload))
            _chat_live_by_action[action] = _chat_live_by_action.get(action, 0) + 1
            _chat_cache_said["refreshes"] += 1
            began = time.monotonic()
            answer = await chat_live.run_exec(_chat_live_post, raw, action, unsettled=_chat_unsettled)
            entry = _chat_refs.peek(ref)
            if entry is None or entry["token"] != token or _my_work_acting(token):
                return
            if "reason" in answer:
                _chat_cache_said["refresh_failed"] += 1
                return
            if answer.get("status") == 200:
                # a real execution: the beat's clocks move as for any answer
                _relay_observe_chat_read(raw, json.dumps(answer).encode())
            _chat_cache_took(view, payload, answer, began)
    except Exception as exc:  # noqa: BLE001 - a read behind an answer is never a failure mode
        _chat_cache_said["refresh_failed"] += 1
        _chat_cache_said["last_failed"] = type(exc).__name__
    finally:
        _chat_cache_hold(slot, -1)


def _chat_cache_forget_write(action: str, key: str, person: str, other: str, payload: dict[str, Any],
                             settle_s: float) -> None:
    if _chat_cache is None:
        return
    if action == "chatReact":
        _chat_cache.forget_message(str(payload.get("message_id") or ""), settle_s)
    elif action == "chatSend":
        _chat_cache.forget(keys=(key,), people=(person, other), settle_s=settle_s)
    else:
        _chat_cache.forget(keys=(key,), people=(person,), settle_s=settle_s)


def _chat_cache_write(action: str, place: str | None, ids: frozenset[str], person: str, name: str,
                      payload: dict[str, Any], answer: dict[str, Any]) -> None:
    """A chat write as the cache must see it."""
    if _chat_cache is None or _chat_fold is None:
        return
    other = _chat_fold.peek_person(chat_live.person_in(action, payload)) if action != "chatReact" else ""
    key = chat_live.pair_key(person, other) if other else ""
    reason = str(answer.get("reason") or "")
    if reason:
        if reason in ("unconfirmed", "unreachable"):
            _chat_cache_forget_write(action, key, person, other, payload, chat_live.SETTLE_S)
        return
    if answer.get("status") != 200:
        _chat_cache_forget_write(action, key, person, other, payload, 0.0)
        return
    data = answer.get("data") if isinstance(answer.get("data"), dict) else {}
    if action == "chatSend":
        answered = str(data.get("thread_key") or "")
        if not data.get("id") or not data.get("created_at") or not answered:
            _chat_cache_forget_write(action, key, person, other, payload, chat_live.SETTLE_S)
            return
        _chat_cache.sent(place, answered, ids, {"id": data.get("id"), "created_at": data.get("created_at"),
                                                "from_name": name, "body": payload.get("body")},
                         expected_key=key, sender_person=person, to_person=other)
    elif action == "chatReact":
        if not isinstance(data.get("reactions"), dict) or not data.get("to_user"):
            _chat_cache_forget_write(action, key, person, other, payload, chat_live.SETTLE_S)
            return
        key = chat_live.pair_key(person, _chat_fold.peek_person(str(data.get("to_user"))))
        _chat_cache.reacted(place, key, ids, str(data.get("message_id") or payload.get("message_id") or ""),
                            data.get("reactions"))
    else:
        _chat_cache.read(place, key, ids, chat_live.iso_at(time.time()), reader_person=person)


def _chat_cache_wrote(action: str, ident: dict[str, Any], tenant: Any, payload: dict[str, Any],
                      answer: dict[str, Any]) -> None:
    """A write the exec door carried, as its session (_chat_cache_write). Never raises."""
    if _chat_cache is None:
        return
    try:
        uid = str(ident.get("account_id") or "")
        _chat_cache_write(action, _chat_cache_place(tenant, uid, bool(ident.get("is_master"))), _chat_cache_ids(ident),
                          str(ident.get("person_id") or ""), str(ident.get("name") or ""), payload, answer)
    except Exception:  # noqa: BLE001 - a write the cache could not follow leaves nothing it may have changed
        _chat_cache.forget_all()


def _chat_cache_blind(action: str, payload: dict[str, Any], answer: dict[str, Any]) -> None:
    """A chat write by a session the relay cannot place (unknown here, acting as someone else, or visiting)…"""
    data = answer.get("data") if isinstance(answer.get("data"), dict) else {}
    settle = chat_live.SETTLE_S if "reason" in answer or (answer.get("status") == 200 and not data) else 0.0
    if action == "chatReact":
        _chat_cache.forget_message(str(payload.get("message_id") or ""), settle)
        named = str(data.get("to_user") or "")
    else:
        named = chat_live.person_in(action, payload)
    if named:
        _chat_cache.forget_person(_chat_fold.peek_person(named), settle)


def _chat_cache_observed(raw: bytes, content: bytes | None) -> None:
    """A chat answer that passed through /gas or the write ledger (None: a write that left and did not answer)."""
    if _chat_cache is None or _chat_fold is None or b"chat" not in raw[:4096]:
        return
    req = chat_live.chat_envelope(raw)
    action = str(req.get("action") or "")
    if action not in chat_live.CACHE_READS and action not in chat_live.WRITES:
        return
    try:
        answer = {"reason": "unconfirmed"} if content is None else json.loads(content)
    except (ValueError, UnicodeDecodeError, TypeError):
        answer = None
    if not isinstance(answer, dict):
        if action in chat_live.WRITES:
            _chat_cache.forget_all()
        return
    try:
        payload = req.get("payload") if isinstance(req.get("payload"), dict) else {}
        token = str(req.get("token") or "")
        uid = _token_user_get(token)
        own = (bool(uid) and _chat_fold.known() and not _my_work_acting(token)
               and not str(req.get("member") or "").strip() and not str(req.get("world") or "").strip())
        if not own:
            if action in chat_live.WRITES:
                _chat_cache_blind(action, payload, answer)
            return
        person, folds = _chat_fold.peek_identity(uid)
        ident = {"account_id": uid, "person_id": person, "fold_ids": folds, "is_master": _auth_master.get(token) is True}
        if action in chat_live.CACHE_READS:
            data = answer.get("data")
            ident["narrowed"] = (action == "chatOverview" and isinstance(data, dict)
                                 and isinstance(data.get("circle"), dict))
            _chat_cache_took(_chat_cache_view(ident, req.get("tenant"), action, payload), payload, answer,
                             time.monotonic() - chat_live.CACHE_GAS_READ_S)
            return
        _chat_cache_write(action, _chat_cache_place(req.get("tenant"), uid, ident["is_master"]),
                          _chat_cache_ids(ident), person, _token_name_get(token) or _chat_fold.peek_name(uid),
                          payload, answer)
    except Exception:  # noqa: BLE001 - observation, never a failure mode; what it may have touched goes
        _chat_cache.forget_all()


def _chat_cache_dir_state(where: str | None = None) -> "tuple[Path | None, str]":
    """(the folder the cache is kept in, '') — or (None, why there is none): unset, inside the served snapshot…"""
    wanted = CHAT_CACHE_DIR if where is None else where
    if not wanted:
        return None, "unset"
    try:
        folder = Path(wanted).resolve()
        for root, why in ((Path(OUT_DIR).resolve(), "inside the served snapshot tree"),
                          (Path(BUNDLE_DIR).resolve(), "inside the bundle deposit")):
            if folder == root or root in folder.parents:
                return None, why
        packs = os.getenv("HUB_APP_PACK_DIR", "/srv/app-packs").strip()
        if packs and folder == Path(packs).resolve():
            return None, "the app packs' own folder"
        if not folder.is_dir():
            if not folder.parent.is_dir():
                return None, "missing"
            folder.mkdir(mode=0o700)
        os.chmod(folder, 0o700)
    except (OSError, RuntimeError):
        return None, "unreadable"
    return folder, ""


def _chat_cache_disk_read(folder: Path) -> tuple[list[tuple[str, Any]], list[str]]:
    """(each kept file's name and body, the names to remove: a write torn by a stop, a file that cannot be read)."""
    found: list[tuple[str, Any]] = []
    drop: list[str] = []
    for path in sorted(folder.iterdir()):
        if chat_live.CACHE_TEMP_RE.fullmatch(path.name):
            drop.append(path.name)
        elif chat_live.CACHE_FILE_RE.fullmatch(path.name):
            try:
                found.append((path.name, json.loads(path.read_text(encoding="utf-8"))))
            except Exception:  # noqa: BLE001 - not taken up, and removed
                drop.append(path.name)
    return found, drop


def _chat_cache_disk_write(folder: Path, jobs: list[tuple[str, str | None]]) -> None:
    """Each kept file written whole beside itself and renamed over it (0600, mkstemp's own mode, which the rename…"""
    for name, text in jobs:
        temp = ""
        try:
            if text is None:
                (folder / name).unlink(missing_ok=True)
                _chat_cache_said["removed"] += 1
                continue
            fd, temp = tempfile.mkstemp(dir=folder, prefix=f".{name}.", suffix=".tmp")
            with os.fdopen(fd, "w", encoding="utf-8") as out:
                out.write(text)
            os.replace(temp, folder / name)
            temp = ""
            _chat_cache_said["written"] += 1
        except Exception as exc:  # noqa: BLE001
            _chat_cache_said["disk_failed"] += 1
            _chat_cache_said["disk_last_failed"] = type(exc).__name__
        finally:
            if temp:
                try:
                    os.unlink(temp)
                except OSError:
                    pass


async def _chat_cache_start() -> None:
    """After a start the kept copies are taken up (each read again the first time it is served); from then on the…"""
    if _chat_cache is None:
        return
    folder = None
    try:
        folder, why = await asyncio.to_thread(_chat_cache_dir_state)
        _chat_cache_said["disk"] = why or "kept"
        if folder is not None:
            found, drop = await asyncio.to_thread(_chat_cache_disk_read, folder)
            drop += [name for name, body in found if not _chat_cache.adopt(name, body)]
            if drop:
                await asyncio.to_thread(_chat_cache_disk_write, folder, [(name, None) for name in drop])
    except Exception as exc:  # noqa: BLE001 - a folder that cannot be read starts cold, in memory
        folder = None
        _chat_cache_said["disk"] = "unreadable"
        _chat_cache_said["disk_last_failed"] = type(exc).__name__
    beat = 0
    while True:
        await asyncio.sleep(CHAT_CACHE_FLUSH_S)
        beat += 1
        try:
            if beat % CHAT_CACHE_EXPIRE_EVERY == 0:
                _chat_cache.expire()
            jobs = _chat_cache.take_dirty()
            if folder is not None and jobs:
                await asyncio.to_thread(_chat_cache_disk_write, folder, jobs)
        except Exception as exc:  # noqa: BLE001
            _chat_cache_said["disk_failed"] += 1
            _chat_cache_said["disk_last_failed"] = type(exc).__name__


# -------------------------------------------------------------------------- WRITTEN BEHIND (chat_live.Behind): a…
CHAT_BEHIND_DIR = os.getenv("HUB_CHAT_BEHIND_DIR", "/srv/app-packs/chat-behind").strip()
# a sign-out waits this long for the session's kept sends to land while its token still works
CHAT_BEHIND_LOGOUT_WAIT_S = 100.0
_CHAT_BEHIND_READS = ("chatMessages", "chatOverview", "chatPing")
_chat_behind = chat_live.Behind() if chat_live is not None else None
_chat_behind_where: dict[str, Any] = {"folder": None, "disk": "not started"}
_chat_behind_lanes: dict[str, Any] = {}
_chat_behind_said: dict[str, Any] = {"written": 0, "disk_failed": 0, "disk_last_failed": "", "restored": 0,
                                     "unreadable": 0, "lane_failed": 0}


def _chat_frame_held() -> bool:
    try:
        return bool(lane_gate.holds(lane_gate.CHAT_FRAME)["held"])
    except Exception:  # noqa: BLE001 - a gate that cannot answer holds
        return True


def _chat_behind_health() -> dict[str, Any] | None:
    if _chat_behind is None:
        return None
    return {**_chat_behind.counts(), **_chat_behind_said, "disk": _chat_behind_where["disk"],
            "lanes": sum(1 for task in _chat_behind_lanes.values() if not task.done())}


def _chat_behind_disk_write(folder: Path, name: str, body: dict[str, Any]) -> bool:
    """One file written whole beside itself, flushed, and renamed over it (0600, mkstemp's own mode)."""
    temp = ""
    try:
        fd, temp = tempfile.mkstemp(dir=folder, prefix=f".{name}.", suffix=".tmp")
        with os.fdopen(fd, "w", encoding="utf-8") as out:
            out.write(json.dumps(body, separators=(",", ":")))
            out.flush()
            os.fsync(out.fileno())
        os.replace(temp, folder / name)
        temp = ""
        _chat_behind_said["written"] += 1
        return True
    except Exception as exc:  # noqa: BLE001
        _chat_behind_said["disk_failed"] += 1
        _chat_behind_said["disk_last_failed"] = type(exc).__name__
        return False
    finally:
        if temp:
            try:
                os.unlink(temp)
            except OSError:
                pass


def _chat_behind_disk_remove(name: str) -> None:
    folder = _chat_behind_where.get("folder")
    if folder is None or not name:
        return
    try:
        (folder / name).unlink(missing_ok=True)
    except OSError as exc:
        _chat_behind_said["disk_failed"] += 1
        _chat_behind_said["disk_last_failed"] = type(exc).__name__


def _chat_behind_disk_read(folder: Path) -> tuple[list[dict[str, Any]], list[str], dict[str, Any]]:
    """(each kept send, the torn writes to remove, the kept state)."""
    found: list[dict[str, Any]] = []
    torn: list[str] = []
    state: dict[str, Any] = {}
    for path in sorted(folder.iterdir()):
        name = path.name
        if name == chat_live.BEHIND_STATE_FILE:
            try:
                got = json.loads(path.read_text(encoding="utf-8"))
                state = got if isinstance(got, dict) else {}
            except Exception:  # noqa: BLE001 - no state is the state before any proof
                state = {}
        elif chat_live.BEHIND_TEMP_RE.fullmatch(name) or (name.startswith(f".{chat_live.BEHIND_STATE_FILE}.")
                                                          and name.endswith(".tmp")):
            torn.append(name)
        elif chat_live.BEHIND_FILE_RE.fullmatch(name):
            try:
                body = json.loads(path.read_text(encoding="utf-8"))
            except Exception:  # noqa: BLE001
                body = None
            if chat_live.behind_valid(body) and body.get("file") == name:
                found.append(body)
            else:
                _chat_behind_said["unreadable"] += 1
    return found, torn, state


def _chat_behind_state_save() -> None:
    folder = _chat_behind_where.get("folder")
    if folder is not None and _chat_behind is not None:
        _chat_behind_disk_write(folder, chat_live.BEHIND_STATE_FILE, {"on": _chat_behind.on, "why": _chat_behind.why})


def _chat_behind_answer(entry: dict[str, Any]) -> dict[str, Any]:
    """A kept send's answer: the receipt Apps Script will give it, now."""
    return {"status": 200, "data": {"id": entry["id"], "created_at": entry["created_at"],
                                    "thread_key": entry["thread_key"], "emailed": False, "kept": True},
            "behind": True}


def _chat_behind_learn(write_id: str, uid: str, answer: Any) -> None:
    """A send Apps Script answered itself: whether it files a row under the id the relay would give it."""
    if _chat_behind is None or not write_id or not uid or not isinstance(answer, dict):
        return
    if answer.get("status") != 200 or "reason" in answer or answer.get("behind"):
        return
    data = answer.get("data") if isinstance(answer.get("data"), dict) else {}
    got = str(data.get("id") or "")
    if not got or data.get("deduplicated"):
        return
    proven = got == chat_live.message_id_for(write_id, uid)
    why = ("Apps Script files a send under the id the relay gives it" if proven
           else "Apps Script filed a send under another id than the relay gives it")
    if _chat_behind.learn(proven, why):
        log.info("live chat: sends are %s", "kept here first from now on" if proven else "no longer kept here first")
        try:
            asyncio.get_running_loop()
        except RuntimeError:
            return
        _keep_task(asyncio.to_thread(_chat_behind_state_save))


def _chat_behind_publish(user_ids: Any, words: str, fact: str | None) -> None:
    """A kept send's line to these accounts' streams: the words to their own tabs, only the fact (or nothing) to…"""
    for uid in dict.fromkeys(str(u) for u in user_ids or () if u):
        for queue in list(_chat_subs.get(uid) or ()):
            line = fact if getattr(queue, "acting", False) else words
            if not line:
                continue
            try:
                queue.put_nowait(line)
            except asyncio.QueueFull:
                pass


def _chat_behind_fact(entry: dict[str, Any]) -> str:
    return json.dumps({"kind": "chatSend", "thread_key": entry["thread_key"], "from_user": entry["from_account"],
                       "at": entry["created_at"]}, separators=(",", ":"))


def _chat_behind_told(entry: dict[str, Any]) -> None:
    """Both ends hear a kept send at once: the chat stream's line with the words (while the chat gate lets a…"""
    try:
        held = _chat_frame_held()
        fact = _chat_behind_fact(entry)
        if not held:
            _chat_behind_publish(entry["to_ids"], chat_live.behind_line(entry, mine=False), fact)
            for uid in entry["to_ids"]:
                _chat_dirty[uid] = entry["created_at"]
        _chat_behind_publish(entry["from_ids"], chat_live.behind_line(entry, mine=True), fact)
        if entry["source"] != "hub":
            _chat_live_emit(chat_live.behind_event(entry, held=held))
            # a hub that does not know `sent` still reads the thread on a nudge
            _chat_live_emit({"kind": "nudge", "action": "chatSend", "thread_key": entry["thread_key"],
                             "from": entry["from_account"], "to": [entry["to_user"]], "held": held,
                             "source": "behind"})
        _chat_push_observed(entry["raw"].encode("ascii"), json.dumps(_chat_behind_answer(entry)).encode(),
                            {"account_id": entry["from_account"], "person_id": entry["from_person"],
                             "name": entry["from_name"]})
    except Exception:  # noqa: BLE001 - telling is a bonus; the send is kept either way
        pass


def _chat_behind_patch(entry: dict[str, Any]) -> None:
    """The cache carries the kept send, and nothing fills what it touches from Apps Script until it lands."""
    if _chat_cache is None:
        return
    try:
        _chat_cache.sent("", entry["thread_key"], entry["from_ids"],
                         {"id": entry["id"], "created_at": entry["created_at"], "from_name": entry["from_name"],
                          "body": entry["body"]},
                         expected_key=entry["thread_key"], sender_person=entry["from_person"],
                         to_person=entry["to_person"])
    except Exception:  # noqa: BLE001 - a patch the cache could not make leaves nothing it may have changed
        _chat_cache.forget_all()
    _chat_cache.pin(keys=(entry["thread_key"],), people=(entry["from_person"], entry["to_person"]))


def _chat_behind_unpin(entry: dict[str, Any], *, forget: bool) -> None:
    if _chat_cache is None:
        return
    people = (entry["from_person"], entry["to_person"])
    _chat_cache.unpin(keys=(entry["thread_key"],), people=people)
    if forget:
        _chat_cache.forget(keys=(entry["thread_key"],), people=people)


async def _chat_behind_keep(*, token: str, tenant: str, uid: str, role: str, is_master: bool, payload: dict[str, Any],
                            write_id: str, client_id: str, source: str, name: str) -> dict[str, Any] | None:
    """The send kept here first and told to both ends, answered with its receipt; None when it goes to Apps…"""
    if _chat_behind is None or _chat_fold is None or not write_id or not uid or not token:
        return None
    held = _chat_behind.held(write_id)
    if held is not None:
        return _chat_behind_answer(held)
    folder = _chat_behind_where.get("folder")
    body = str(payload.get("body") or "").strip()
    to_user = str(payload.get("to_user") or "").strip()
    if _chat_behind.on and folder is not None and _chat_fold.stale():
        await asyncio.to_thread(_chat_fold.index)
    person, folds = _chat_fold.peek_identity(uid)
    to_person, to_ids = _chat_fold.peek_identity(to_user)
    why = chat_live.behind_refusal(
        on=_chat_behind.on and folder is not None, acting=_my_work_acting(token),
        place=_chat_cache_place(tenant, uid, is_master),
        sender_narrowed=True if chat_live.narrowed(role) else _chat_fold.peek_narrowed(uid),
        to_narrowed=_chat_fold.peek_narrowed(to_user), sender_person=person, to_person=to_person,
        room=_chat_behind.room())
    # Chat.gs keeps 4000 of JavaScript's characters: a longer one goes to it, so the row says what was answered
    if not why and (not body or not to_user or "|" in to_user or len(body.encode("utf-16-le")) > 8000):
        why = "body"
    if why:
        _chat_behind.note_not_kept(why)
        return None
    wall = time.time()
    at = chat_live.iso_at(wall)
    raw = chat_live.form(chat_live.envelope(token, tenant, "chatSend", {"to_user": to_user, "body": body, "at": at},
                                            write_id))
    entry = chat_live.behind_entry(write_id=write_id, account_id=uid, person_id=person, ids=folds, name=name,
                                   to_user=to_user, to_person=to_person, to_ids=to_ids, body=body,
                                   client_id=client_id or ("b" + write_id), source=source, raw=raw, created_at=at,
                                   wall=wall)
    entry["file"] = f"{time.time_ns():020d}.{hashlib.sha256(write_id.encode()).hexdigest()[:16]}.behind.json"
    if not await asyncio.to_thread(_chat_behind_disk_write, folder, entry["file"], entry):
        _chat_behind.note_not_kept("disk")
        return None
    twin = _chat_behind.held(write_id)
    if twin is not None:
        # the same write kept meanwhile by another ask: one file, one row
        await asyncio.to_thread(_chat_behind_disk_remove, entry["file"])
        return _chat_behind_answer(twin)
    _chat_behind.add(entry)
    _chat_behind_patch(entry)
    _chat_behind_told(entry)
    _chat_behind_wake(entry["from_person"])
    return _chat_behind_answer(entry)


def _chat_behind_wake(person: str) -> None:
    """This sender's lane runs, if it is not running already."""
    running = _chat_behind_lanes.get(person)
    if running is not None and not running.done():
        return
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return
    _chat_behind_lanes[person] = asyncio.ensure_future(_chat_behind_lane(person))


async def _chat_behind_lane(person: str) -> None:
    """One sender's kept sends to Apps Script, oldest first and one at a time, on live chat's own slots, until…"""
    tries = 0
    while _chat_behind is not None:
        entry = _chat_behind.next_for(person)
        if entry is None:
            return
        try:
            if time.time() - float(entry["accepted_at"]) > chat_live.BEHIND_MAX_AGE_S:
                _chat_behind_refused(entry, "Apps Script did not take it within a day.", how="given_up")
                tries = 0
                continue
            wait = float(entry.get("hold_until") or 0) - time.time()
            if wait > 0:
                await asyncio.sleep(min(wait, chat_live.SETTLE_S))
                continue
            entry["sent_at"] = time.time()
            folder = _chat_behind_where.get("folder")
            if folder is not None:
                await asyncio.to_thread(_chat_behind_disk_write, folder, entry["file"], entry)
            _chat_live_by_action["chatSend"] = _chat_live_by_action.get("chatSend", 0) + 1
            answer = await chat_live.run_exec(_chat_live_post, entry["raw"].encode("ascii"), "chatSend",
                                              write_id=entry["write_id"], unsettled=_chat_unsettled)
            how, why = chat_live.behind_outcome(entry, answer)
            if how == "retry":
                tries += 1
                after = (float(answer.get("retry_after_s") or 0) if answer.get("reason") == "unconfirmed" else 0.0)
                entry["hold_until"] = time.time() + max(
                    after, chat_live.BEHIND_BACKOFF_S[min(tries - 1, len(chat_live.BEHIND_BACKOFF_S) - 1)])
                continue
            tries = 0
            if how == "landed":
                _chat_behind_landed(entry, answer)
            elif how == "moved":
                _chat_behind_moved(entry)
            else:
                _chat_behind_refused(entry, why)
        except Exception as exc:  # noqa: BLE001 - the lane never dies with a send in it
            _chat_behind_said["lane_failed"] += 1
            _chat_behind_said["disk_last_failed"] = type(exc).__name__
            entry["hold_until"] = time.time() + chat_live.BEHIND_BACKOFF_S[-1]


def _chat_behind_landed(entry: dict[str, Any], answer: dict[str, Any]) -> None:
    """The row is there, under the id both ends were given."""
    _chat_behind.landed(entry["write_id"])
    _chat_behind_disk_remove(entry.get("file") or "")
    data = answer.get("data") if isinstance(answer.get("data"), dict) else {}
    filed = str(data.get("thread_key") or "")
    moved_pair = bool(filed) and filed != entry["thread_key"]
    _chat_behind_unpin(entry, forget=moved_pair)
    if moved_pair and _chat_cache is not None:
        # the sheet filed it under another pair (its folds and the relay's differ): both ends read it again
        _chat_cache.forget(keys=(filed,))
        _chat_behind_nudge(entry)


def _chat_behind_moved(entry: dict[str, Any]) -> None:
    """Filed, but under another id (or none said): Apps Script does not name rows by their write id now."""
    _chat_behind.drop(entry["write_id"], how="moved")
    _chat_behind_disk_remove(entry.get("file") or "")
    if _chat_behind.learn(False, "a kept send was filed under another id than the relay gave it"):
        log.warning("live chat: a kept send was filed under another id; sends are no longer kept here first")
        _chat_behind_state_save()
    _chat_behind_unpin(entry, forget=True)
    _chat_behind_take_back(entry)
    _chat_live_emit({**chat_live.behind_refused_event(entry, ""), "moved": True})
    _chat_behind_nudge(entry)


def _chat_behind_refused(entry: dict[str, Any], why: str, how: str = "refused") -> None:
    """Apps Script will not file it (or never took it): the line goes at the recipient's end, the sender's shows…"""
    _chat_behind.drop(entry["write_id"], how=how)
    _chat_behind_disk_remove(entry.get("file") or "")
    _chat_behind_unpin(entry, forget=True)
    log.warning("live chat: a kept send was not filed by Apps Script (%s)", how)
    _chat_behind_take_back(entry)
    _chat_behind_publish(entry["from_ids"], json.dumps({
        "kind": "write_refused", "resource": "Your chat message", "action": "chatSend", "why": why,
        "at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}), None)
    _chat_live_emit(chat_live.behind_refused_event(entry, why))


def _chat_behind_take_back(entry: dict[str, Any]) -> None:
    """The line a kept send drew goes from the streams' tabs: the sender's always, the recipient's only where the…"""
    gone = chat_live.behind_gone_line(entry)
    if not _chat_frame_held():
        _chat_behind_publish(entry["to_ids"], gone, None)
    _chat_behind_publish(entry["from_ids"], gone, None)


def _chat_behind_nudge(entry: dict[str, Any]) -> None:
    """Both ends read the thread again (the chat stream's fact, and the hub's nudge)."""
    held = _chat_frame_held()
    fact = _chat_behind_fact(entry)
    if not held:
        _chat_behind_publish(entry["to_ids"], fact, fact)
    _chat_behind_publish(entry["from_ids"], fact, fact)
    _chat_live_emit({"kind": "nudge", "action": "chatSend", "thread_key": "", "from": entry["from_account"],
                     "to": [entry["to_user"]], "held": held, "source": "behind"})


def _chat_behind_overlaid(action: str, answer: Any, *, person: str, ids: frozenset[str], with_user: str,
                          place: str | None) -> Any:
    """A read Apps Script answered, with the kept sends it does not carry yet."""
    if (_chat_behind is None or not _chat_behind.any() or place != "" or not person or not isinstance(answer, dict)
            or answer.get("status") != 200 or "reason" in answer):
        return answer
    data = answer.get("data")
    if action == "chatMessages":
        other = _chat_fold.peek_person(with_user) if _chat_fold is not None else with_user
        key = chat_live.pair_key(person, other)
        got = chat_live.overlay_messages(data, key, ids, _chat_behind.touching_thread(key)) if key else data
    elif action == "chatOverview":
        got = chat_live.overlay_rail(data, person, _chat_behind.touching((person,)))
    elif action == "chatPing":
        got = chat_live.overlay_ping(data, person, _chat_behind.touching((person,)))
    else:
        return answer
    return answer if got is data else {**answer, "data": got}


def _chat_behind_gas_read(raw: bytes, content: bytes) -> bytes:
    """A chat read /gas carried, with the kept sends it does not carry yet — for a session the relay knows by its…"""
    if _chat_behind is None or not _chat_behind.any() or b"chat" not in raw[:4096] or _chat_fold is None:
        return content
    try:
        req = chat_live.chat_envelope(raw)
        action = str(req.get("action") or "")
        if action not in _CHAT_BEHIND_READS:
            return content
        token = str(req.get("token") or "")
        uid = _token_user_get(token)
        if (not uid or not _chat_fold.known() or _my_work_acting(token) or str(req.get("member") or "").strip()
                or str(req.get("world") or "").strip()):
            return content
        answer = json.loads(content)
        person, folds = _chat_fold.peek_identity(uid)
        payload = req.get("payload") if isinstance(req.get("payload"), dict) else {}
        got = _chat_behind_overlaid(action, answer, person=person,
                                    ids=_chat_cache_ids({"account_id": uid, "person_id": person, "fold_ids": folds}),
                                    with_user=str(payload.get("with_user") or ""),
                                    place=_chat_cache_place(req.get("tenant"), uid, _auth_master.get(token) is True))
        return content if got is answer else json.dumps(got).encode()
    except Exception:  # noqa: BLE001 - the answer as Apps Script gave it
        return content


def _chat_behind_waiting_for(token: str) -> list[dict[str, Any]]:
    """This session's kept sends still waiting for Apps Script."""
    if _chat_behind is None or not token:
        return []
    return [e for e in _chat_behind.waiting_entries() if _relay_token(e["raw"].encode("ascii")) == token]


async def _chat_behind_flush_for(token: str) -> None:
    """A sign-out: this session's kept sends are delivered first, while its token still works."""
    waiting = _chat_behind_waiting_for(token)
    if not waiting:
        return
    for entry in waiting:
        if not _chat_unsettled.busy(entry["write_id"]) and _chat_unsettled.wait_left(entry["write_id"]) <= 0:
            entry["hold_until"] = 0.0
        _chat_behind_wake(entry["from_person"])
    deadline = time.monotonic() + CHAT_BEHIND_LOGOUT_WAIT_S
    while _chat_behind_waiting_for(token) and time.monotonic() < deadline:
        await asyncio.sleep(0.5)


async def _chat_behind_start() -> None:
    """After a start: the kept sends taken up again, each held off what it touches in the cache, and their lanes…"""
    if _chat_behind is None:
        return
    try:
        folder, why = await asyncio.to_thread(_chat_cache_dir_state, CHAT_BEHIND_DIR)
        _chat_behind_where.update(folder=folder, disk=why or "kept")
        if folder is None:
            return
        found, torn, state = await asyncio.to_thread(_chat_behind_disk_read, folder)
        for name in torn:
            await asyncio.to_thread(_chat_behind_disk_remove, name)
        if state.get("on") is True:
            _chat_behind.learn(True, str(state.get("why") or "kept from before the start"))
        for entry in sorted(found, key=lambda e: e["file"]):
            if _chat_behind.held(entry["write_id"]) is not None:
                continue
            sent = float(entry.get("sent_at") or 0)
            entry["hold_until"] = sent + chat_live.SETTLE_S if sent else 0.0
            _chat_behind.add(entry, restored=True)
            _chat_behind_said["restored"] += 1
            if _chat_cache is not None:
                people = (entry["from_person"], entry["to_person"])
                _chat_cache.forget(keys=(entry["thread_key"],), people=people)
                _chat_cache.pin(keys=(entry["thread_key"],), people=people)
        for person in _chat_behind.senders():
            _chat_behind_wake(person)
    except Exception as exc:  # noqa: BLE001 - nothing is kept here first until the folder can be read
        _chat_behind_where.update(folder=None, disk="unreadable")
        _chat_behind_said["disk_last_failed"] = type(exc).__name__


# -------------------------------------------------------------------------- CHAT PUSH (server/chat_push.py): a chat…
_chat_push_hub = chat_push.HubLive() if chat_push is not None else None
_chat_push_rate = chat_push.RateLimit() if chat_push is not None else None
_CHAT_PUSH_SAID: dict[str, float] = {"no_key": 0.0}


def _chat_push_seen(ids: Any) -> None:
    """The hub redeemed a ticket or ran an exec for this person: a live chat connection is theirs now."""
    if _chat_push_hub is not None and isinstance(ids, (list, tuple)):
        _chat_push_hub.touched(str(i) for i in ids if i)


def _chat_push_listed(refs: Any, verdict: Any) -> None:
    """The hub's list of the refs its connections hold: those still sessions here are live, as their ids."""
    if _chat_push_hub is None or _chat_refs is None or not isinstance(refs, list):
        return
    try:
        closed = {r for key in ("unknown", "revoked") for r in ((verdict or {}).get(key) or ()) if isinstance(r, str)}
        groups: list[list[str]] = []
        for ref in refs[: chat_live.MAX_CHECK]:
            if not isinstance(ref, str) or ref in closed:
                continue
            ident = (_chat_refs.peek(ref) or {}).get("ident") or {}
            groups.append([str(i) for i in (ident.get("fold_ids") or [ident.get("account_id")]) if i])
        _chat_push_hub.listed(groups)
    except Exception:  # noqa: BLE001 - the door answers regardless; the last list stands until it ages out
        return


def _chat_push_live(ids: list[str]) -> bool:
    """Any of these accounts with a chat stream open (a Be Another tab is not them) or a live chat connection."""
    for uid in ids:
        if any(not getattr(q, "acting", False) for q in list(_chat_subs.get(uid) or ())):
            return True
    return bool(_chat_push_hub is not None and _chat_push_hub.live(ids))


def _chat_push_observed(raw: bytes, content: bytes, ident: dict[str, Any] | None = None) -> None:
    """A chatSend that landed (a /gas answer, a ledger delivery, the hub's exec)."""
    if chat_push is None or web_push is None or b"chatSend" not in raw[:4096]:
        return
    try:
        got = chat_push.landed_send(raw, content)
        if got is None:
            return
        if got["message_id"]:
            _chat_push_start(got, ident, 0.0)
        else:
            _chat_push_unconfirmed(got, chat_push.AFTER_SILENCE_S)
    except Exception:  # noqa: BLE001 - observation, never a failure mode
        return


def _chat_push_unanswered(raw: bytes, *, echo: bool) -> None:
    """A /gas send answered without its receipt: looked for once Apps Script has had the time to file it."""
    if chat_push is None or web_push is None or b"chatSend" not in raw[:4096]:
        return
    try:
        got = chat_push.unanswered_send(raw)
        if got is not None:
            _chat_push_unconfirmed(got, chat_push.AFTER_ECHO_S if echo else chat_push.AFTER_SILENCE_S)
    except Exception:  # noqa: BLE001 - observation, never a failure mode
        return


def _chat_push_unconfirmed(got: dict[str, str], delay: float) -> None:
    """A send with no receipt: nothing for a client's or a guardian's session, one the relay cannot name, or…"""
    token = got.get("token") or ""
    hit = _auth_cache.get(token) if token else None
    role = str(hit[2] or "") if hit and hit[1] else ""
    if not role or chat_live is None or chat_live.narrowed(role) or got.get("tenant"):
        return
    _chat_push_start({**got, "since": chat_push.row_since()}, None, delay, confirm=True)


def _chat_push_start(got: dict[str, str], ident: dict[str, Any] | None, delay: float, *,
                     confirm: bool = False) -> None:
    """The sender named now, from memory; the token dropped here unless the row is still to be read as them."""
    token = got.pop("token", "")
    if ident:
        job = {**got, "from_uid": str(ident.get("account_id") or ""),
               "from_person": str(ident.get("person_id") or ""), "from_name": str(ident.get("name") or "")}
    else:
        job = {**got, "from_uid": _token_user_get(token), "from_person": "", "from_name": _token_name_get(token)}
    if confirm:
        job["confirm_as"] = token
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return
    _keep_task(_chat_push_run(job, delay))


async def _chat_push_confirm(job: dict[str, str], plan: dict[str, Any]) -> bool:
    """A send with no receipt: its row, read as its sender (Chat.gs's own circle and place refusals answer), or…"""
    if chat_live is None or _chat_push_rate is None or not _chat_push_rate.open(plan["rate_key"]):
        return False
    if not await asyncio.to_thread(web_push.devices_for, PG_DSN, plan["to_ids"]):
        return False
    raw = chat_live.form(chat_live.envelope(job["confirm_as"], job.get("tenant") or "", "chatMessages",
                                            {"with_user": job["to_user"]}))
    answer = await chat_live.run_exec(_chat_live_post, raw, "chatMessages", unsettled=_chat_unsettled)
    found = chat_push.row_filed(answer, job.get("since") or "")
    if not found:
        return False
    plan["event"] = found
    return True


async def _chat_push_run(job: dict[str, str], delay: float) -> None:
    try:
        if delay > 0:
            await asyncio.sleep(delay)
        plan = await asyncio.to_thread(_chat_push_plan, job)
        if plan is None or not web_push.wants_push(chat_push.copy_of(plan), live=_chat_push_live(plan["to_ids"])):
            return
        if job.get("confirm_as") is not None and not await _chat_push_confirm(job, plan):
            return
        state, took, why = await asyncio.to_thread(_chat_push_deliver, plan)
    except Exception as exc:  # noqa: BLE001 - one message's push, never the relay's
        log.warning("chat push: a message could not be pushed (%s)", type(exc).__name__)
        return
    if state == chat_push.NO_KEY:
        if time.time() - _CHAT_PUSH_SAID["no_key"] > 3600:
            _CHAT_PUSH_SAID["no_key"] = time.time()
            log.warning("chat push: nothing is pushed — %s", why)
    elif state in (web_push.S_SENT, web_push.S_FAILED, chat_push.HELD_TEST, chat_push.QUIET):
        log.info("chat push: %s (%s device(s))%s", state, took, f" — {why}" if why else "")


def _chat_push_plan(job: dict[str, str]) -> dict[str, Any] | None:
    """Worker thread: the recipient's accounts and both names, from the users copy the chat's folds come from."""
    fold, to_user = _chat_fold, job["to_user"]
    to_person, to_ids = fold.identity(to_user) if fold is not None else (to_user, [to_user])
    from_person = job.get("from_person") or ""
    if not from_person and job.get("from_uid"):
        from_person = fold.identity(job["from_uid"])[0] if fold is not None else job["from_uid"]
    if not from_person:
        from_person = chat_push.other_side(job.get("thread_key") or "", to_person or to_user)
    from_name = job.get("from_name") or (fold.name_of(from_person) if fold is not None and from_person else "")
    return chat_push.plan(to_user=to_user, to_person=to_person, to_ids=to_ids,
                          to_name=fold.name_of(to_user) if fold is not None else "", from_person=from_person,
                          from_name=from_name, thread_key=job.get("thread_key") or "",
                          message_id=job.get("message_id") or "")


def _chat_push_deliver(plan: dict[str, Any]) -> tuple[str, int, str]:
    """Worker thread: the devices, the switch, the chat gate and the night as they stand now; then the push, and…"""
    devs = web_push.devices_for(PG_DSN, plan["to_ids"])
    switch = _web_switch()
    try:
        gate = lane_gate.holds(lane_gate.CHAT_FRAME)
    except Exception as exc:  # noqa: BLE001 - a gate that cannot answer holds
        gate = {"held": True, "why": f"the chat gate could not be read ({type(exc).__name__})"}
    now = chat_push.now()
    quiet = web_gate is not None and web_gate.quiet(now)
    keys = web_push.keys()
    state = chat_push.judge(devices=len(devs), rate=_chat_push_rate, key=plan["rate_key"],
                            held=bool(switch.get("on") or gate.get("held")), quiet=quiet,
                            keys_ok=bool(keys.get("ok")))
    took, why = 0, ""
    if state == chat_push.SEND:
        state, took, why = web_push.push_chat(PG_DSN, devs, chat_push.payload(plan, now), vapid=keys,
                                              ttl=web_push.chat_ttl(now))
    elif state == chat_push.NO_KEY:
        why = str(keys.get("why") or "no VAPID keys")
    rows = _chat_push_rows(plan, state, switch, gate, why)
    if rows:
        try:
            web_gate.record(rows)
        except Exception as exc:  # noqa: BLE001 - the push stands; its row is what is missing
            log.warning("chat push: its mock row could not be kept (%s)", type(exc).__name__)
    return state, took, why


def _chat_push_rows(plan: dict[str, Any], state: str, switch: dict[str, Any], gate: dict[str, Any],
                    why: str) -> list[dict[str, Any]]:
    """Sent, failed, held by test mode, or not sent in the quiet window: one mock row, on the push channel."""
    if web_gate is None:
        return []
    if state == chat_push.HELD_TEST:
        held_by = web_gate.held_by_test(switch) if switch.get("on") else str(gate.get("why") or "the chat gate")
        how = ("held", held_by, "test mode is on — no push left the platform, and none will: this row is its "
                                "only delivery")
    elif state == chat_push.QUIET:
        how = ("quiet", f"held: the quiet window ({web_gate.quiet_words()})",
               "not pushed in the quiet window, and not afterwards: the unread count in My Inbox still shows it")
    elif state == web_push.S_SENT:
        how = ("sent", "", "pushed to the person's device(s)")
    elif state == web_push.S_FAILED:
        how = ("failed", "the push service", f"no device took it, and it is not tried again ({why})"[:300])
    else:
        return []
    notice = {"key": f"{chat_push.KIND}:{plan['event']}", "kind": chat_push.KIND,
              "facts": {"person": plan["from_name"]}}
    return web_gate.mock_rows(web_gate.CH_PUSH, notice, [(plan["to_name"], chat_push.copy_of(plan))],
                              result=how[0], held_by=how[1], reason=how[2], switch=switch)


_CHAT_PUSH_PLAN_TEXT = ("to_person", "to_name", "from_person", "from_name", "thread", "rate_key", "tag", "event")


@app.post("/chat/push")
async def chat_push_door(request: Request, x_hub_chat_key: str = Header(default="")) -> Response:
    """asa-hub-app's: one chat message's push, planned there (app/chat_doors.py) and delivered here, where the
    devices, the switch, the chat gate, the night and the keys are read (_chat_push_deliver)."""
    if chat_live is None or chat_push is None or web_push is None:
        return _chat_live_answer(dict(_CHAT_LIVE_DOWN), http=200)
    if not chat_live.key_ok(x_hub_chat_key, _CHAT_KEY):
        return _chat_live_answer(chat_live.refusal(401, "key", "This door is asa-hub-app's."))
    body = await _chat_live_body(request)
    plan = (body or {}).get("plan")
    if (not isinstance(plan, dict) or not all(isinstance(plan.get(k), str) for k in _CHAT_PUSH_PLAN_TEXT)
            or not isinstance(plan.get("to_ids"), list) or not all(isinstance(i, str) for i in plan["to_ids"])):
        return _chat_live_answer(chat_live.refusal(400, "plan", "The plan could not be read."))
    plan = {**{k: plan[k] for k in _CHAT_PUSH_PLAN_TEXT}, "to_ids": list(plan["to_ids"])}
    try:
        state, took, why = await asyncio.to_thread(_chat_push_deliver, plan)
    except Exception as exc:  # noqa: BLE001 - one message's push, never the relay's
        log.warning("chat push: a message could not be pushed (%s)", type(exc).__name__)
        return _chat_live_answer(chat_live.refusal(503, "unavailable", "The push could not be made."), http=200)
    if state == chat_push.NO_KEY:
        if time.time() - _CHAT_PUSH_SAID["no_key"] > 3600:
            _CHAT_PUSH_SAID["no_key"] = time.time()
            log.warning("chat push: nothing is pushed — %s", why)
    elif state in (web_push.S_SENT, web_push.S_FAILED, chat_push.HELD_TEST, chat_push.QUIET):
        log.info("chat push: %s (%s device(s))%s", state, took, f" — {why}" if why else "")
    return _chat_live_answer({"status": 200, "data": {"state": state, "took": took, "why": why}})


# -------------------------------------------------------------------------- TIME OFF (server/time_off.py): App…
_TIME_OFF_DOWN = {"status": 503, "reason": "unreadable",
                  "message": "Time off is not available on this server right now."}
_TIME_OFF_ROLES_REFUSED = ("client", "guardian", "onboarding", "interviewer")
_TIME_OFF_STATUS = {"not_minted": 503, "unwritable": 503, "unreadable": 503, "missing": 404,
                    "not_allowed": 403, "invalid": 400, "words_needed": 400, "word": 400,
                    "action": 400, "into": 400, "dates": 400, "person": 400, "empty": 400,
                    "unresolved": 400}


# the screens that file, withdraw or decide through these doors: one open to the session opens the door it calls,
# though App Control keeps the Time Off app itself shut (who reaches which request stays time_off's own rule)
_TIME_OFF_FILERS = (("my-calendar", "My Calendar"),)
_TIME_OFF_DECIDERS = (("my-work", "My Work"),)


async def _time_off_gate(authorization: str, hosts: tuple[tuple[str, str], ...] = (), *,
                         floor: bool = True) -> tuple[str, str] | dict[str, Any]:
    """(role, uid) when Time Off's own gate, or a screen in `hosts`, opens to the session; else Time Off's refusal."""
    actor = await _hotline_actor(authorization, app_id="timeoff", refuse_roles=_TIME_OFF_ROLES_REFUSED,
                                 app_label="Time Off", floor=floor)
    if not isinstance(actor, dict) or actor.get("status") != 403:
        return actor
    for app_id, label in hosts:
        via = await _hotline_actor(authorization, app_id=app_id, refuse_roles=_TIME_OFF_ROLES_REFUSED,
                                   app_label=label, floor=floor)
        if not isinstance(via, dict):
            return via
    return actor


async def _time_off_reader(authorization: str, hosts: tuple[tuple[str, str], ...] = ()
                           ) -> tuple[dict[str, Any], tuple[str, str]] | dict[str, Any]:
    if time_off is None or not PG_DSN:
        return dict(_TIME_OFF_DOWN)
    actor = await _time_off_gate(authorization, hosts)
    if isinstance(actor, dict):
        return _daily_refusal(actor)
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return {**got, "reason": got.get("reason") or "unreadable"}
    who, session = got
    if time_off.refused_reader(who):
        return {"status": 403, "reason": "badge", "message": "Time Off is the staff's screen."}
    return who, session


def _time_off_answer(exc: Exception, what: str) -> dict[str, Any]:
    if time_off is not None and isinstance(exc, time_off.Refused):
        data = {k: v for k, v in (exc.extra or {}).items() if k in ("refusals", "preview", "names")}
        return {"status": _TIME_OFF_STATUS.get(exc.code, 409), "reason": exc.code, "message": exc.why,
                "data": data}
    if time_off is not None and isinstance(exc, time_off.Unreadable):
        return {"status": 503, "reason": "unreadable", "message": f"{str(exc)} — {what}."}
    log.warning("time off: %s failed (%s)", what, type(exc).__name__)
    return {"status": 503, "reason": "unreadable", "message": f"{what} could not be done ({type(exc).__name__})."}


def _time_off_changed() -> None:
    """A write owes the Builder's Requests slice, the bell and the calendars a look now."""
    try:
        asyncio.get_running_loop().create_task(build_all(only={"calendarRequests"}))
    except Exception as exc:  # noqa: BLE001 — the next full build carries it
        log.info("time off: calendarRequests will follow the next build (%s)", type(exc).__name__)
    _notices_wake()
    _housecal_rang()


async def _time_off_body(request: Request) -> dict[str, Any] | None:
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return None
    return body if isinstance(body, dict) else None


@app.get("/hub-lanes/time-off")
async def lane_time_off(response: Response, house: str = "",
                       authorization: str = Header(default="")) -> dict[str, Any]:
    """The app's feed: the black band, the rows and the reader's own reach, cut per reader."""
    response.headers["Cache-Control"] = "no-store"
    got = await _time_off_reader(authorization)
    if isinstance(got, dict):
        return got
    who, _session = got
    try:
        data = await asyncio.to_thread(time_off.feed, PG_DSN, who, house=str(house or "")[:40])
    except Exception as exc:  # noqa: BLE001
        return _time_off_answer(exc, "time off could not be shown")
    return {"status": 200, "data": data}


@app.get("/hub-lanes/time-off/detail")
async def lane_time_off_detail(response: Response, ref: str = "",
                              authorization: str = Header(default="")) -> dict[str, Any]:
    """One request, opened: the timeline, the legs, what approving does; the reason only to its readers."""
    response.headers["Cache-Control"] = "no-store"
    got = await _time_off_reader(authorization)
    if isinstance(got, dict):
        return got
    who, _session = got
    ref = str(ref or "").strip().upper()
    if not time_off.REF_RE.fullmatch(ref):
        return {"status": 400, "reason": "request", "message": "ref is required (TO…)"}
    try:
        data = await asyncio.to_thread(time_off.detail, PG_DSN, who, ref)
    except Exception as exc:  # noqa: BLE001
        return _time_off_answer(exc, "this request could not be read")
    return {"status": 200, "data": data}


@app.post("/hub-lanes/time-off/request")
async def lane_time_off_request(request: Request, response: Response,
                               authorization: str = Header(default="")) -> dict[str, Any]:
    """File time off (or preview it with dry_run); every refusal is said before anything is written."""
    response.headers["Cache-Control"] = "no-store"
    got = await _time_off_reader(authorization, _TIME_OFF_FILERS)
    if isinstance(got, dict):
        return got
    who, session = got
    body = await _time_off_body(request)
    if body is None:
        return {"status": 400, "reason": "request", "message": "invalid body"}
    try:
        if body.get("dry_run"):
            data = await asyncio.to_thread(time_off.preview, PG_DSN, who, body)
            return {"status": 200, "data": data}
        filed = await asyncio.to_thread(time_off.request, PG_DSN, who, body)
    except Exception as exc:  # noqa: BLE001
        return _time_off_answer(exc, "the request could not be filed")
    log.info("time off: %s filed by %s", filed["ref"], session[1])
    _time_off_changed()
    return {"status": 200, "data": {"ref": filed["ref"], "asked": filed["asked"],
                                    "row": time_off.shape(filed["row"], who, [], None)}}


async def _time_off_act(authorization: str, request: Request, what: str,
                        run: Any, hosts: tuple[tuple[str, str], ...] = ()) -> dict[str, Any]:
    got = await _time_off_reader(authorization, hosts)
    if isinstance(got, dict):
        return got
    who, session = got
    body = await _time_off_body(request)
    if body is None:
        return {"status": 400, "reason": "request", "message": "invalid body"}
    ref = str(body.get("ref") or "").strip().upper()
    if not time_off.REF_RE.fullmatch(ref):
        return {"status": 400, "reason": "request", "message": "ref is required (TO…)"}
    try:
        row = await asyncio.to_thread(run, who, ref, body)
    except Exception as exc:  # noqa: BLE001
        return _time_off_answer(exc, what)
    log.info("time off: %s %s by %s → %s", ref, what, session[1], row.get("status"))
    _time_off_changed()
    return {"status": 200, "data": time_off.shape(row, who, [], None)}


