@app.post("/hub-lanes/time-off/away")
async def lane_time_off_away(request: Request) -> dict[str, Any]:
    """Who is on scheduled time off in a range — the URGENT blast's one question; service identity only."""
    body = await _time_off_body(request) or {}
    if not _mail_auth_ok(body):
        return {"status": 401, "message": "service identity required"}
    if time_off is None or not PG_DSN:
        return {"status": 502, "message": "the Time Off lane is not loaded on this server"}
    lo = time_off.day_of(body.get("from"))
    hi = time_off.day_of(body.get("to")) or lo
    if lo is None or hi is None or hi < lo:
        return {"status": 400, "message": "from and to (YYYY-MM-DD) are required"}
    try:
        away = await asyncio.to_thread(time_off.away, PG_DSN)
    except Exception as exc:  # noqa: BLE001
        return {"status": 502, "message": f"who is on approved time off could not be read ({type(exc).__name__})"}
    keys, names = [], []
    for key, spans in away.items():
        for i in spans:
            a, b = time_off.day_of(i["col_iso"]), time_off.day_of(i["until"])
            if a and b and a <= hi and lo <= b:
                keys.append(key)
                names.append(i["employee"])
                break
    return {"status": 200, "data": {"readable": True, "keys": sorted(set(keys)), "names": sorted(set(names))}}


def _time_off_keeper(loop: asyncio.AbstractEventLoop) -> Any:
    """time_off's door to the app, called from a worker thread: the write waits on this loop for the app's answer
    (None when it gave none; never from the loop's own thread, which would wait on itself)."""
    def call(door: str, payload: dict[str, Any]) -> dict[str, Any] | None:
        try:
            asyncio.get_running_loop()
            return None
        except RuntimeError:
            pass
        # the upload carries the whole house; a request kept waits as long as any write does
        wait = HUB_APP_PACK_TIMEOUT_S if door == "timeOffUpload" else HUB_APP_TIMEOUT_S
        write_id = "W" + hashlib.sha256(f"{door}|{time.time_ns()}".encode()).hexdigest()[:24]
        try:
            got = asyncio.run_coroutine_threadsafe(
                _backend_call(TIME_OFF_APP, door, payload, {"is_service": True}, extra={"write_id": write_id},
                              timeout=wait), loop).result(wait * 2 + BACKEND_RETRY_S)
        except Exception as exc:  # noqa: BLE001 - unanswered: the caller says nothing was written
            log.warning("time off: %s not answered by the app (%s)", door, type(exc).__name__)
            return None
        return got[2] if got is not None else None
    return call


async def _time_off_boot() -> None:
    """Whether the relay can write the house, said once at start."""
    time_off.KEEPER[0] = _time_off_keeper(asyncio.get_running_loop())
    try:
        state = await asyncio.to_thread(time_off.settings_state, PG_DSN, probe=True)
    except Exception as exc:  # noqa: BLE001
        log.warning("time off: the house could not be read at start (%s)", type(exc).__name__)
        return
    if not state.get("minted"):
        log.warning("time off: the house is not minted yet — nothing is filed or enforced")
        return
    house = state.get("house") or {}
    log.info("time-off house writable: %s (%s rows)%s", "yes" if house.get("writable") else "no",
             house.get("rows"), f" — {house.get('writable_why')}" if house.get("writable_why") else "")
    if state.get("directors_why"):
        log.warning("time off: %s", state["directors_why"])


# The form sync's last held reason, said again only when it changes.
_TIME_OFF_FORM_HELD: list[str] = [""]


async def _time_off_sweep() -> None:
    """The minute's pass: effects owed, expiries, approvers owed a read, and new Google Form rows."""
    if time_off is None or not PG_DSN:
        return
    try:
        said = await asyncio.to_thread(time_off.settle, PG_DSN)
        if said.get("settled") or said.get("expired") or said.get("recomputed"):
            log.info("time off: %s settled, %s expired, %s approvers read again", said.get("settled"),
                     said.get("expired"), said.get("recomputed"))
            _time_off_changed()
    except Exception as exc:  # noqa: BLE001
        log.warning("time off: the pass failed (%s)", type(exc).__name__)
    try:
        synced = await asyncio.to_thread(time_off.form_sync, PG_DSN)
        if synced.get("added"):
            log.info("time off: %s Google Form row(s) added as requests", synced["added"])
            _time_off_changed()
        held_why = str(synced.get("why") or "") if synced.get("skipped") == "directors unreadable" else ""
        if held_why and held_why != _TIME_OFF_FORM_HELD[0]:
            log.warning("time off: the form sync waits — %s", held_why)
        _TIME_OFF_FORM_HELD[0] = held_why
    except Exception as exc:  # noqa: BLE001
        log.warning("time off: the form sync failed (%s)", type(exc).__name__)


async def _time_off_post() -> None:
    """Time off's asks and answers through staffShiftReminder; only a real outcome closes one."""
    if time_off is None or not PG_DSN:
        return
    credential = ({"service_secret": SERVICE_SECRET} if SERVICE_SECRET else {"token": SERVICE_TOKEN})
    try:
        rows = await asyncio.to_thread(time_off.owed, PG_DSN)
    except Exception as exc:  # noqa: BLE001
        log.warning("time off: the owed rows could not be read (%s)", type(exc).__name__)
        return
    if not rows:
        return
    try:
        env = await _staff_door("staffShiftReminder", {"rows": rows}, credential)
    except Exception as exc:  # noqa: BLE001
        log.warning("time off: the door could not be reached (%s) — the rows stay owed", type(exc).__name__)
        return
    if (env or {}).get("status") != 200:
        log.warning("time off refused: %s — the rows stay owed", str((env or {}).get("message") or env)[:160])
        return
    said = (env or {}).get("data") or {}
    try:
        wrote = await asyncio.to_thread(time_off.mark_said, PG_DSN, [str(r["id"]) for r in rows], said, rows)
    except Exception as exc:  # noqa: BLE001
        log.warning("time off: the ledger could not be written (%s)", type(exc).__name__)
        return
    log.info("time off: %s row(s) offered, %s written down", len(rows), wrote)


async def _punch_pairs_post() -> None:
    """The pair rule's messages and its warnings, on the one shift door."""
    if not PG_DSN:
        return
    credential = ({"service_secret": SERVICE_SECRET} if SERVICE_SECRET else {"token": SERVICE_TOKEN})
    try:
        import punch_pairs  # noqa: PLC0415 — lazy, so the in-container suites need no new module
        rows = await asyncio.to_thread(punch_pairs.owed, PG_DSN)
    except Exception as exc:  # noqa: BLE001
        log.warning("punch pairs: the owed rows could not be read (%s)", type(exc).__name__)
        return
    if not rows:
        return
    try:
        env = await _staff_door("staffShiftReminder", {"rows": rows}, credential)
    except Exception as exc:  # noqa: BLE001
        log.warning("punch pairs: the door could not be reached (%s) — the rows stay owed",
                    type(exc).__name__)
        return
    if (env or {}).get("status") != 200:
        log.warning("punch pairs refused: %s — the rows stay owed",
                    str((env or {}).get("message") or env)[:160])
        return
    said = (env or {}).get("data") or {}
    try:
        wrote = await asyncio.to_thread(punch_pairs.mark_said, PG_DSN,
                                        [str(r["id"]) for r in rows], said)
    except Exception as exc:  # noqa: BLE001
        log.warning("punch pairs: the ledger could not be written (%s)", type(exc).__name__)
        return
    log.info("punch pairs: %s row(s) offered, %s written down", len(rows), wrote)


# rung after a Support Requests write the engine answered 200, and after a Scheduling write (its rows are listed…
SUPPORT_DESK_EVENT = "support-desk"
_SUPPORT_DESK_WRITES = frozenset({"supportDeskDecide", "supportDeskAdp", "supportDeskSettingsSet", "supportInboxAnswer",
                                  "myCalendarVacationFile"})
# these two write Scheduling's own flows behind the door, so Scheduling's screens are told as well
_SUPPORT_DESK_SCHED_WRITES = frozenset({"supportDeskDecide", "myCalendarVacationFile"})


def _relay_observe_support_desk(action: str, content: bytes) -> None:
    try:
        ours = action in _SUPPORT_DESK_WRITES
        sched = action.startswith("scheduling") and _resolver_lane(action) not in ("read", "")
        if not ours and not sched:
            return
        env = json.loads(content)
        if not isinstance(env, dict) or env.get("status") != 200:
            return
        _publish_slice(SUPPORT_DESK_EVENT)
        if action in _SUPPORT_DESK_SCHED_WRITES:
            try:
                _publish_slice("scheduling")
            finally:
                _app_pack_swept[SCHEDULING_EVENT] = time.time()
    except Exception:  # noqa: BLE001 — telling nobody must never fail a write
        pass


def _support_desk_rang(action: str, content: bytes) -> None:
    """After a Support Requests write landed 200 (Python's or Apps Script's), Python's copy read before it is behind;
    never raises."""
    try:
        if action not in _SUPPORT_DESK_WRITES:
            return
        env = json.loads(content)
        if isinstance(env, dict) and env.get("status") == 200:
            _app_pack_swept[SUPPORT_DESK_EVENT] = time.time()
    except Exception:  # noqa: BLE001 — telling nobody must never fail a write
        pass


