# THE DEFAULT LANE — every other read the resolver manifest declares is kept the same way, per viewer, unless it…
VIEWER_CACHE_DEFAULT = os.getenv("HUB_VIEWER_CACHE_DEFAULT", "1").strip().lower() not in ("0", "false", "no", "off")
_VIEWER_CACHE_FILE_RING = "gs:"
_VIEWER_CACHE_OPT_OUT = frozenset({"hubBoot", "list", "get"})
_VIEWER_CACHE_OPT_OUT_RE = re.compile(r"(DocFile|DocRead|File|Bytes|Transcripts?|Texts|Resume|Pack|Config|ConfigGet"
                                      r"|Secrets?|Tokens?|Credentials?|Passwords?)$|^(auth|chat)")
_viewer_cache_default_held: dict[str, Any] = {"mtime": None, "reads": {}, "rings": {}, "files": {}, "by_resource": {}}


def _viewer_cache_default_table() -> dict[str, Any]:
    """read -> its ring, ring -> its reads, write -> its file's ring and resource -> the rings of its writers'…"""
    table = _resolver_table()
    held = _viewer_cache_default_held
    if held["mtime"] == _resolver_cache["mtime"]:
        return held
    sessions = {str((table.get(a) or {}).get("file") or "") for a in RELAY_NO_RECEIPT_ACTIONS
                if a not in RELAY_BYTE_READS and (table.get(a) or {}).get("lane") not in (None, "read")}
    reads: dict[str, str] = {}
    files: dict[str, str] = {}
    by_resource: dict[str, set[str]] = {}
    for name, entry in table.items():
        file = str((entry or {}).get("file") or "") if isinstance(entry, dict) else ""
        if not file.endswith(".gs"):
            continue
        ring = _VIEWER_CACHE_FILE_RING + file[:-3]
        files[name] = ring
        if entry.get("lane") in ("write", "tool"):
            for resource in entry.get("invalidates") or ():
                by_resource.setdefault(str(resource), set()).add(ring)
        if (entry.get("lane") != "read" or entry.get("router") or entry.get("service") or entry.get("cache") is False
                or not entry.get("idempotent") or entry.get("cost") == "minutes" or file in sessions
                or name in _VIEWER_CACHE_OPT_OUT or _VIEWER_CACHE_OPT_OUT_RE.search(name)):
            continue
        reads[name] = ring
    rings: dict[str, tuple[str, ...]] = {}
    for name, ring in sorted(reads.items()):
        rings[ring] = rings.get(ring, ()) + (name,)
    held.update({"mtime": _resolver_cache["mtime"], "reads": reads, "rings": rings, "files": files,
                 "by_resource": by_resource})
    return held


def _viewer_cache_ring_of(read: str) -> str | None:
    """The name a kept read's screens re-read on; None for a read never kept."""
    ring = _VIEWER_CACHE_READS.get(read)
    if ring is not None or not VIEWER_CACHE_DEFAULT:
        return ring
    return _viewer_cache_default_table()["reads"].get(read)


def _viewer_cache_reads_of(name: str) -> tuple[str, ...]:
    """The kept reads a ring of `name` makes stale."""
    explicit = tuple(_VIEWER_CACHE_RINGS.get(name, ()))
    if not VIEWER_CACHE_DEFAULT or not name.startswith(_VIEWER_CACHE_FILE_RING):
        return explicit
    return explicit + tuple(_viewer_cache_default_table()["rings"].get(name, ()))


def _viewer_cache_write_rings(action: str, raw: bytes = b"") -> set[str]:
    """The default lane's names a write rings: its own file's, and the files of every writer of a resource it (or…"""
    if not VIEWER_CACHE_DEFAULT or not action or _resolver_touches(action) is not None:
        return set()
    held = _viewer_cache_default_table()
    rings: set[str] = set()
    resources: set[str] = set()
    if action in _APP_PACK_VERBS:
        resource = str((_relay_envelope(raw) or {}).get("resource") or "")
        if resource:
            resources.add(resource)
    elif _resolver_lane(action) in ("write", "tool"):
        if action in held["files"]:
            rings.add(held["files"][action])
        resources.update(_resolver_invalidates(action))
    for resource in resources:
        rings |= held["by_resource"].get(resource, set())
    return {ring for ring in rings if ring in held["rings"]}
