_VIEWER_CACHE_TEMP_RE = r"\.(?:[0-9a-f]{64}|marks)\.viewer\.json\.[A-Za-z0-9_]+\.tmp"
_VIEWER_CACHE_FORM = "application/x-www-form-urlencoded;charset=UTF-8"
# the boards that carry the words about an absence (a time off's or a call-off's reason, the notes beside it, the…
_VIEWER_CACHE_PRIVATE_READS = frozenset({"schedulingBoard", "schedulingStaffShifts", "schedulingTimeOffList",
                                         "supportDeskList", *_VIEWER_CACHE_LANES})
_VIEWER_CACHE_PRIVATE_KEYS = frozenset({"reason", "note", "body"})
# keys whose file the next beat writes again, or removes
_VIEWER_CACHE_DIRTY: set[str] = set()
# files removed at once since the beat being written took its jobs: one of them that beat writes is removed again
_VIEWER_CACHE_GONE: set[str] = set()
