_VIEWER_CACHE_PREFILLING: set[str] = set()
_VIEWER_CACHE_PREFILLS = asyncio.Semaphore(VIEWER_CACHE_PREFILL_SLOTS)
_VIEWER_CACHE_DISK: dict[str, Any] = {"state": "not started", "taken": 0, "written": 0, "removed": 0, "failed": 0,
                                      "ahead": 0}
# the folder in use once the start has judged it and taken its copies up; None: memory alone
_VIEWER_CACHE_FOLDER: "Path | None" = None


def _viewer_cache_drop(key: str) -> dict[str, Any] | None:
    """A copy let go; its file goes at the next beat."""
    _VIEWER_CACHE_DIRTY.add(key)
    return _VIEWER_CACHE.pop(key, None)


def _viewer_cache_drop_session(th: str, reads: Any = None) -> list[str]:
    """Every copy of one session (of these boards only, when named); returns their keys."""
    keys = [k for k, e in _VIEWER_CACHE.items() if e["th"] == th and (reads is None or e["read"] in reads)]
    for key in keys:
        _viewer_cache_drop(key)
    return keys


def _viewer_cache_unlink_now(keys: Any) -> None:
    """The files of copies a write, a sign-out or a refusal outdates, removed before it leaves rather than at the…"""
    folder = _VIEWER_CACHE_FOLDER
    if folder is None:
        return
    for key in keys:
        name = f"{key}.viewer.json"
        _VIEWER_CACHE_GONE.add(name)
        try:
            (folder / name).unlink(missing_ok=True)
        except OSError:
            _VIEWER_CACHE_DISK["failed"] += 1


def _viewer_cache_marks_keep() -> None:
    """The write marks written beside the copies (wall clock, each within the age), before the write leaves…"""
    folder = _VIEWER_CACHE_FOLDER
    if folder is None:
        return
    wall_now, now = time.time(), time.monotonic()
    marks = {k: wall_now - (now - at) for k, at in _VIEWER_CACHE_WROTE.items() if now - at <= VIEWER_CACHE_MAX_AGE_S}
    try:
        if not marks:
            (folder / _VIEWER_CACHE_MARKS).unlink(missing_ok=True)
        elif not _app_pack_write_file(folder, _VIEWER_CACHE_MARKS, {"v": 1, "marks": marks}):
            _VIEWER_CACHE_DISK["failed"] += 1
    except OSError:
        _VIEWER_CACHE_DISK["failed"] += 1


def _viewer_cache_withhold(read: str, data: Any) -> tuple[Any, int]:
    """A board's data as it may rest on disk, and how many cells that withholds: every object through the…"""
    import redaction  # noqa: PLC0415 - the one withholding rule of every copy
    private = read in _VIEWER_CACHE_PRIVATE_READS
    withheld = 0

    def words(row: dict, k: Any) -> bool:
        return k in _VIEWER_CACHE_PRIVATE_KEYS or (k == "value" and str(row.get("label") or "").lower() == "reason")

    def walk(node: Any, depth: int) -> Any:
        nonlocal withheld
        if isinstance(node, list):
            return [walk(v, depth + 1) for v in node]
        if not isinstance(node, dict):
            return node
        row, n = redaction.redact_row(node)
        withheld += n
        out: dict = {}
        for k, v in row.items():
            if (private and depth > 0 and isinstance(v, str) and v.strip() and not redaction.is_marker_value(v)
                    and words(row, k)):
                out[k] = redaction.MARKER_PRIVATE
                withheld += 1
            else:
                out[k] = walk(v, depth + 1)
        return out

    return walk(data, 0), withheld


def _viewer_cache_envelope(content: bytes) -> dict[str, Any] | None:
    try:
        env = json.loads(content)
    except (ValueError, TypeError, RecursionError):
        return None
    return env if isinstance(env, dict) else None


_VIEWER_CACHE_RECEIPT_KEYS = frozenset({"accepted", "queued", "confirmed", "deduplicated", "running", "message"})


def _viewer_cache_receipt(data: Any) -> bool:
    """A receipt standing where a read's answer belongs ({accepted:true} and its notes, nothing else): doPost's…"""
    return isinstance(data, dict) and data.get("accepted") is True and set(data) <= _VIEWER_CACHE_RECEIPT_KEYS


def _viewer_cache_unclocked(content: bytes) -> Any:
    """An answer without the read's own clock (`now`, `stamp`, `read_at`, each source's `as_of`), which moves on…"""
    env = _viewer_cache_envelope(content)
    data = (env or {}).get("data")
    if env is None or not isinstance(data, dict):
        return env if env is not None else content
    data = {k: v for k, v in data.items() if k not in ("now", "stamp", "read_at", "kept")}
    if isinstance(data.get("sources"), list):
        data["sources"] = [{k: v for k, v in s.items() if k != "as_of"} if isinstance(s, dict) else s
                           for s in data["sources"]]
    return {**env, "data": data}


def _viewer_cache_touched(action: str, raw: bytes = b"") -> set[str]:
    """The boards a write changes, by the names its landing rings; only those it names when it names them."""
    touches = _resolver_touches(action)
    if touches is not None:
        return {read for read in touches if _viewer_cache_ring_of(read) is not None}
    names = _viewer_cache_write_rings(action, raw)
    for named in _VIEWER_CACHE_TOUCHERS:
        names |= named(action, raw)
    if action.startswith("scheduling") and action not in _SCHEDULING_READS and _resolver_lane(action) != "read":
        names.add(SCHEDULING_EVENT)
    if action in _SUPPORT_DESK_WRITES:
        names.add(SUPPORT_DESK_EVENT)
    if action in _SUPPORT_DESK_SCHED_WRITES:
        names.add(SCHEDULING_EVENT)
    if action in VEHICLE_CALENDAR_WRITES:
        names.add(VEHICLE_CALENDAR_EVENT)
    if action in STAFF_PROFILES_WRITES:
        names.add(STAFF_PROFILES_EVENT)
    names.update(name for name, actions in _VIEWER_CACHE_LANE_WRITES.items() if action in actions)
    return {read for name in names for read in _viewer_cache_reads_of(name)}


def _viewer_cache_rang(resource: str) -> None:
    reads = _viewer_cache_reads_of(resource)
    for read in reads:
        _VIEWER_CACHE_VERSION[read] = _VIEWER_CACHE_VERSION.get(read, 0) + 1
    loop = _event_loop
    if reads and loop is not None:
        # the bell may ring from a builder thread: the reads ahead start on the loop
        try:
            loop.call_soon_threadsafe(lambda: _viewer_cache_prefill_for(reads))
        except RuntimeError:
            pass


def _viewer_cache_predates(th: str, read: str, at: float) -> bool:
    """Whether a read that began at `at` began before a write it must not hide."""
    return at <= max(_VIEWER_CACHE_WROTE.get(f"{th}|{read}", float("-inf")),
                     _VIEWER_CACHE_WROTE.get(f"{th}|*", float("-inf")),
                     _VIEWER_CACHE_WROTE.get("*", float("-inf")))


def _viewer_cache_written(action: str, raw: bytes, content: bytes | None = None) -> None:
    """A write leaving (no content) or landed 200: its sender's copies of the boards it changes are read again…"""
    try:
        if action == "authLogout":
            token = (_relay_envelope(raw) or {}).get("token")
            if isinstance(token, str) and token:
                th = hashlib.sha256(token.encode()).hexdigest()
                # nothing of the session read before this is kept or taken up again, from memory or disk
                for read in (*_VIEWER_CACHE_READS, "*"):
                    _VIEWER_CACHE_WROTE[f"{th}|{read}"] = time.monotonic()
                _viewer_cache_marks_keep()
                _viewer_cache_unlink_now(_viewer_cache_drop_session(th))
            return
        access = action in _RELAY_APP_ACCESS_ACTIONS
        reads = set() if access else _viewer_cache_touched(action, raw)
        if not access and not reads:
            return
        if content is not None and (_viewer_cache_envelope(content) or {}).get("status") != 200:
            return
        now = time.monotonic()
        for k, at in list(_VIEWER_CACHE_WROTE.items()):
            if now - at > VIEWER_CACHE_MAX_AGE_S:
                _VIEWER_CACHE_WROTE.pop(k, None)
        if access:
            _VIEWER_CACHE_WROTE["*"] = now
            _viewer_cache_marks_keep()
            _VIEWER_CACHE_DIRTY.update(_VIEWER_CACHE)
            _viewer_cache_unlink_now(sorted(_VIEWER_CACHE_DIRTY))
            _VIEWER_CACHE.clear()
            return
        token = (_relay_envelope(raw) or {}).get("token")
        if isinstance(token, str) and token:
            th = hashlib.sha256(token.encode()).hexdigest()
            for read in reads:
                _VIEWER_CACHE_WROTE[f"{th}|{read}"] = now
            # the writer's own copies go with it, their files too: a restart never answers it from before its write
            _viewer_cache_marks_keep()
            _viewer_cache_unlink_now(_viewer_cache_drop_session(th, reads))
        if content is not None:
            for read in reads:
                _VIEWER_CACHE_VERSION[read] = _VIEWER_CACHE_VERSION.get(read, 0) + 1
            # each My app whose rows the write changed: its copies read again at once, its screens told
            for name, actions in _VIEWER_CACHE_LANE_WRITES.items():
                if action in actions:
                    _publish_slice(name)
            # and each file the default lane keeps reads of
            for name in sorted(_viewer_cache_write_rings(action, raw)):
                _publish_slice(name)
    except Exception:  # noqa: BLE001 — a kept copy never fails a write
        pass


def _viewer_cache_key(action: str, raw: bytes, request: Any = None) -> dict[str, Any] | None:
    """The ask a board read is kept under, or None: a kept read (a board's, or the default lane's), asked with a…"""
    if _viewer_cache_ring_of(action) is None or action in _VIEWER_CACHE_LANES:
        return None
    env = _relay_envelope(raw) or {}
    token = env.get("token")
    if not isinstance(token, str) or not token or "service_secret" in env or env.get("action") != action:
        return None
    # an edit panel's read is the witness its save is checked against: always the engine's
    if isinstance(env.get("payload"), dict) and env["payload"].get("edit"):
        return None
    try:
        asked = json.dumps({k: v for k, v in env.items() if k not in ("token", "write_id")},
                           sort_keys=True, separators=(",", ":"))
    except (TypeError, ValueError):
        return None
    th = hashlib.sha256(token.encode()).hexdigest()
    return {"key": hashlib.sha256(f"{th}\n{asked}".encode()).hexdigest(), "th": th, "read": action, "asked": asked,
            "token": token, "version": _VIEWER_CACHE_VERSION.get(action, 0), "at": time.monotonic(),
            "refresh": getattr(request, "viewer_cache_refresh", False) is True}


def _viewer_cache_take(ask: dict[str, Any], content: bytes) -> None:
    """Keeps a board's clean 200; a refusal takes what it no longer earns, its files at once (401: the session's…"""
    try:
        env = _viewer_cache_envelope(content) or {}
        status = env.get("status")
        if status == 401:
            now = time.monotonic()
            for read in (*_VIEWER_CACHE_READS, "*"):
                _VIEWER_CACHE_WROTE[f"{ask['th']}|{read}"] = now
            _viewer_cache_marks_keep()
            _viewer_cache_unlink_now(_viewer_cache_drop_session(ask["th"]))
        if status in (401, 403, 404):
            _viewer_cache_drop(ask["key"])
            _viewer_cache_unlink_now([ask["key"]])
        if status != 200:
            return
        if _viewer_cache_receipt(env.get("data")):
            # no answer at all: the copy it would replace stands, and is answered as before
            return
        if not isinstance(env.get("data"), dict) or len(content) > VIEWER_CACHE_MAX_BYTES // 8:
            # a 200 that cannot be kept outdates the copy it would replace: that copy is never answered again
            _viewer_cache_drop(ask["key"])
            _viewer_cache_unlink_now([ask["key"]])
            return
        if _viewer_cache_predates(ask["th"], ask["read"], ask["at"]):
            return
        held = _VIEWER_CACHE.pop(ask["key"], None)
        if held is not None and held["at"] > ask["at"]:
            _VIEWER_CACHE[ask["key"]] = held
            return
        # a person's read is a look; a refresh carries the last look over
        used = ask["at"] if not ask.get("refresh") else (held or {}).get("used", float("-inf"))
        _VIEWER_CACHE[ask["key"]] = {"body": bytes(content), "th": ask["th"], "read": ask["read"],
                                     "asked": ask.get("asked"), "version": ask["version"], "at": ask["at"],
                                     "wall": time.time() - (time.monotonic() - ask["at"]), "used": used}
        _VIEWER_CACHE_DIRTY.add(ask["key"])
        size = sum(len(e["body"]) for e in _VIEWER_CACHE.values())
        while len(_VIEWER_CACHE) > VIEWER_CACHE_MAX_KEYS or size > VIEWER_CACHE_MAX_BYTES:
            size -= len(_viewer_cache_drop(next(iter(_VIEWER_CACHE)))["body"])
    except Exception:  # noqa: BLE001 — a copy not kept is a read asked again
        pass


async def _viewer_cache_hit(ask: dict[str, Any], raw: bytes, content_type: str) -> bytes | None:
    """This viewer's kept answer, or None for the normal path; one past fresh is read again behind it, once."""
    if ask["refresh"]:
        return None

    def usable() -> dict[str, Any] | None:
        got = _VIEWER_CACHE.get(ask["key"])
        if got is not None and (time.monotonic() - got["at"] >= VIEWER_CACHE_MAX_AGE_S
                                or _viewer_cache_predates(ask["th"], ask["read"], got["at"])):
            _viewer_cache_drop(ask["key"])
            got = None
        return got

    entry = usable()
    if entry is not None:
        try:
            stands = await _session_actor("Bearer " + ask["token"]) is not None
        except Exception:  # noqa: BLE001 — a session nobody can vouch for goes to Apps Script
            stands = False
        entry = usable() if stands else None
    if entry is None:
        _VIEWER_CACHE_SAID["miss"] += 1
        return None
    _VIEWER_CACHE[ask["key"]] = _VIEWER_CACHE.pop(ask["key"])
    entry["used"] = time.monotonic()
    if entry["version"] == _VIEWER_CACHE_VERSION.get(ask["read"], 0) \
            and time.monotonic() - entry["at"] < VIEWER_CACHE_FRESH_S:
        _VIEWER_CACHE_SAID["fresh"] += 1
        return _viewer_cache_aged(entry)
    _VIEWER_CACHE_SAID["stale"] += 1
    if ask["read"] in _VIEWER_CACHE_LANES:
        _VIEWER_CACHE_LANE_SHOWN.add(ask["key"])
    out = _VIEWER_CACHE_INFLIGHT.get(ask["key"])
    if out is None:
        _VIEWER_CACHE_INFLIGHT[ask["key"]] = _VIEWER_CACHE_VERSION.get(ask["read"], 0)
        _keep_task(_viewer_cache_refresh(ask, raw, content_type, entry["body"]))
    elif out != _VIEWER_CACHE_VERSION.get(ask["read"], 0):
        # the refresh out left before this ring's write, and may not carry it
        _VIEWER_CACHE_AGAIN.add(ask["key"])
    return _viewer_cache_aged(entry)


def _viewer_cache_aged(entry: dict[str, Any]) -> bytes:
    """A kept copy as answered: a profile app's says when it was read (`kept_at`), so a screen never draws it as…"""
    if entry["read"] not in _VIEWER_CACHE_AGED:
        return entry["body"]
    env = _viewer_cache_envelope(entry["body"])
    if env is None or not isinstance(env.get("data"), dict):
        return entry["body"]
    wall = entry.get("wall") or time.time() - (time.monotonic() - entry["at"])
    kept_at = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(wall))
    return json.dumps({**env, "data": {**env["data"], "kept_at": kept_at}}, separators=(",", ":")).encode()


class _ViewerCacheRefresh:
    """What a refresh hands gas_relay: the same body, asked past the kept copy."""
    viewer_cache_refresh = True

    def __init__(self, raw: bytes, content_type: str) -> None:
        self._raw = raw
        self.headers = {"content-type": content_type}

    async def body(self) -> bytes:
        return self._raw


class _ViewerCacheHeld:
    """The gate of a read ahead, already held by it (a housekeeping ticket and a read-ahead slot)."""

    async def __aenter__(self) -> "_ViewerCacheHeld":
        return self

    async def __aexit__(self, *_exc: Any) -> bool:
        return False


async def _viewer_cache_refresh(ask: dict[str, Any], raw: bytes, content_type: str, served: bytes,
                                ahead: bool = False) -> None:
    """One read behind a served copy, through the proxy; a changed answer rings the board's name, once."""
    key = ask["key"]
    lane = ask["read"] in _VIEWER_CACHE_LANES
    try:
        while True:
            outcome, body, unanswered = "failed", None, True
            try:
                if await _session_actor("Bearer " + ask["token"]) is None:
                    outcome, unanswered = "not asked, the session no longer stands", False
                else:
                    async with (_ViewerCacheHeld() if ahead else _VIEWER_CACHE_REFRESHES):
                        _VIEWER_CACHE_AGAIN.discard(key)
                        _VIEWER_CACHE_INFLIGHT[key] = _VIEWER_CACHE_VERSION.get(ask["read"], 0)
                        if lane:
                            got = await _lane_keep_fetch(ask)
                        else:
                            res = await gas_relay(_ViewerCacheRefresh(raw, content_type))
                            got = bytes(getattr(res, "body", b"") or b"")
                    env_got = _viewer_cache_envelope(got) or {}
                    status = env_got.get("status")
                    if status == 200 and _viewer_cache_receipt(env_got.get("data")):
                        status = None   # a receipt is no answer: the copy stays, as for a read that failed
                    if status != 200:
                        unanswered = status not in (401, 403, 404)
                        if not unanswered:
                            _VIEWER_CACHE_LANE_SHOWN.discard(key)
                        outcome = (f"answered {status if status is not None else 'unreadably'}, the copy "
                                   + ("kept" if unanswered else "taken"))
                    else:
                        body = got
                        told = lane and key in _VIEWER_CACHE_LANE_SHOWN
                        _VIEWER_CACHE_LANE_SHOWN.discard(key)
                        if _viewer_cache_unclocked(got) == _viewer_cache_unclocked(served) and not told:
                            outcome = "unchanged"
                        else:
                            _publish_slice(_viewer_cache_ring_of(ask["read"]) or ask["read"], kept_copy=True)
                            outcome = "changed, rung" if not told else "read again, rung"
            except Exception as exc:  # noqa: BLE001 — the copy stays as it was
                outcome = f"failed ({type(exc).__name__})"
            if lane and ahead and body is None and unanswered and key in _VIEWER_CACHE \
                    and key not in _VIEWER_CACHE_LANE_SHOWN:
                _VIEWER_CACHE_LANE_SHOWN.add(key)
                _publish_slice(_viewer_cache_ring_of(ask["read"]) or ask["read"], kept_copy=True)
                outcome += "; rung, so its screens say its age"
            again = body is not None and key in _VIEWER_CACHE_AGAIN
            log.info("viewer cache: %s read again %s — %s%s (%d kept; %d fresh, %d stale, %d missed)",
                     ask["read"], "ahead of its viewer" if ahead else "behind a kept copy", outcome,
                     "; a ring came while it was out, read once more" if again else "",
                     len(_VIEWER_CACHE), _VIEWER_CACHE_SAID["fresh"], _VIEWER_CACHE_SAID["stale"],
                     _VIEWER_CACHE_SAID["miss"])
            if not again:
                return
            served = body
    finally:
        _VIEWER_CACHE_INFLIGHT.pop(key, None)
        _VIEWER_CACHE_AGAIN.discard(key)


def _viewer_cache_due(entry: dict[str, Any], now: float, recent_s: float = VIEWER_CACHE_PREFILL_RECENT_S,
                      age: float = VIEWER_CACHE_FRESH_S) -> bool:
    """A copy worth reading before its viewer looks: within its age, after its viewer's last write, answered to…"""
    return (now - entry["at"] < VIEWER_CACHE_MAX_AGE_S and isinstance(entry.get("asked"), str)
            and not _viewer_cache_predates(entry["th"], entry["read"], entry["at"])
            and now - entry.get("used", entry["at"]) < recent_s
            and (entry["version"] != _VIEWER_CACHE_VERSION.get(entry["read"], 0)
                 or now - entry["at"] >= age))


def _viewer_cache_prefill_for(reads: Any = None, th: str | None = None,
                              recent_s: float = VIEWER_CACHE_PREFILL_RECENT_S, age: float = VIEWER_CACHE_FRESH_S) -> int:
    """The stale copies of viewers whose stream is open (of these boards, of this session), read again before…"""
    try:
        tokens: dict[str, str] = {}
        for q in list(_event_subs):
            token = getattr(q, "token", "")
            if isinstance(token, str) and token:
                h = hashlib.sha256(token.encode()).hexdigest()
                if th is None or h == th:
                    tokens[h] = token
        if not tokens:
            return 0
        now = time.monotonic()
        due: list[tuple[float, str, str]] = []
        for key, e in _VIEWER_CACHE.items():
            if e["th"] not in tokens or (reads is not None and e["read"] not in reads):
                continue
            out = _VIEWER_CACHE_INFLIGHT.get(key)
            if out is not None:
                if out != _VIEWER_CACHE_VERSION.get(e["read"], 0):
                    _VIEWER_CACHE_AGAIN.add(key)
                continue
            if key not in _VIEWER_CACHE_PREFILLING and _viewer_cache_due(e, now, recent_s, age):
                due.append((e.get("used", e["at"]), key, e["th"]))
        room = max(0, VIEWER_CACHE_PREFILL_MAX - len(_VIEWER_CACHE_PREFILLING))
        due.sort(reverse=True)
        for _used, key, h in due[:room]:
            _VIEWER_CACHE_PREFILLING.add(key)
            _keep_task(_viewer_cache_prefill(key, tokens[h], age))
        return min(len(due), room)
    except Exception:  # noqa: BLE001 — a read ahead is never anybody's failure
        return 0


def _viewer_cache_online(token: str) -> None:
    """A stream (re)opened: its viewer's stale copies are read again before they look — after a restart, every…"""
    if token:
        _viewer_cache_prefill_for(None, hashlib.sha256(token.encode()).hexdigest())


async def _viewer_cache_prefill(key: str, token: str, age: float = VIEWER_CACHE_FRESH_S) -> None:
    """One copy read again ahead of its viewer, on a slot of its own and then the housekeeping lane (so the reads…"""
    try:
        async with _VIEWER_CACHE_PREFILLS, _housekeeping_slots:
            entry = _VIEWER_CACHE.get(key)
            if entry is None or key in _VIEWER_CACHE_INFLIGHT or not _viewer_cache_due(entry, time.monotonic(), age):
                return
            if entry["read"] in _VIEWER_CACHE_LANES:
                raw = b""
                ask = (_lane_keep_ask(entry["read"], token, _lane_keep_params(entry["asked"]), True,
                                      json.loads(entry["asked"]).get("mode", ""))
                       if hashlib.sha256(token.encode()).hexdigest() == entry["th"] else None)
            else:
                raw = urllib.parse.urlencode({"body": json.dumps({**json.loads(entry["asked"]),
                                                                  "token": token})}).encode()
                ask = _viewer_cache_key(entry["read"], raw, _ViewerCacheRefresh(raw, _VIEWER_CACHE_FORM))
            if ask is None or ask["key"] != key:
                return
            _VIEWER_CACHE_INFLIGHT[key] = _VIEWER_CACHE_VERSION.get(entry["read"], 0)
            _VIEWER_CACHE_DISK["ahead"] += 1
            await _viewer_cache_refresh(ask, raw, _VIEWER_CACHE_FORM, entry["body"], ahead=True)
    except Exception:  # noqa: BLE001 — the copy stays as it was, and is read again when it is asked for
        pass
    finally:
        _VIEWER_CACHE_PREFILLING.discard(key)


def _viewer_cache_file(key: str) -> str:
    return f"{key}.viewer.json"


def _viewer_cache_take_dirty() -> list[tuple[str, dict[str, Any] | None]]:
    """What the next beat writes: each changed copy, or None for a file to remove."""
    jobs: list[tuple[str, dict[str, Any] | None]] = []
    wall_now, now = time.time(), time.monotonic()
    _VIEWER_CACHE_GONE.clear()
    for key in sorted(_VIEWER_CACHE_DIRTY):
        e = _VIEWER_CACHE.get(key)
        body = None
        if e is not None and isinstance(e.get("asked"), str):
            try:
                used = float(e.get("used", e["at"]))
                body = {"v": 1, "key": key, "th": e["th"], "read": e["read"], "asked": e["asked"],
                        "wall": float(e["wall"]), "used": wall_now - (now - used) if used > float("-inf") else 0.0,
                        "body": bytes(e["body"])}
            except (KeyError, TypeError, ValueError):
                body = None
        jobs.append((_viewer_cache_file(key), body))
    _VIEWER_CACHE_DIRTY.clear()
    return jobs


def _viewer_cache_at_rest(job: dict[str, Any]) -> dict[str, Any] | None:
    """Off the loop: a copy as its file holds it, its answer with what may not rest on disk withheld…"""
    try:
        env = json.loads(job["body"])
        data, withheld = _viewer_cache_withhold(job["read"], env["data"])
        text = json.dumps({**env, "data": data}, ensure_ascii=False, separators=(",", ":"))
    except Exception:  # noqa: BLE001 - not written, and its file goes
        return None
    return {**{k: v for k, v in job.items() if k != "body"}, "withheld": withheld, "body": text}


def _viewer_cache_disk_write(folder: Path, jobs: list[tuple[str, dict[str, Any] | None]]) -> list[str]:
    """Off the loop: each copy written beside itself and renamed over it (_app_pack_write_file: 0600 in a 0700…"""
    failed: list[str] = []
    for name, body in jobs:
        try:
            rest = None if body is None else _viewer_cache_at_rest(body)
            if rest is None:
                (folder / name).unlink(missing_ok=True)
                _VIEWER_CACHE_DISK["removed"] += 1
            elif _app_pack_write_file(folder, name, rest):
                _VIEWER_CACHE_DISK["written"] += 1
                if name in _VIEWER_CACHE_GONE:
                    (folder / name).unlink(missing_ok=True)
            else:
                _VIEWER_CACHE_DISK["failed"] += 1
        except OSError:
            _VIEWER_CACHE_DISK["failed"] += 1
            failed.append(name)
    return failed


def _viewer_cache_disk_read(folder: Path) -> tuple[list[tuple[str, Any]], list[str], dict[str, float] | None]:
    """Off the loop: (each kept file's name and body, the names to remove: a write torn by a stop, a file that…"""
    found: list[tuple[str, Any]] = []
    drop: list[str] = []
    marks: dict[str, float] | None = {}
    for path in sorted(folder.iterdir()):
        if re.fullmatch(_VIEWER_CACHE_TEMP_RE, path.name):
            drop.append(path.name)
        elif path.name == _VIEWER_CACHE_MARKS:
            try:
                kept = json.loads(path.read_text(encoding="utf-8"))
                if kept.get("v") != 1:
                    raise ValueError("shape")
                marks = {str(k): float(at) for k, at in kept["marks"].items()}
            except Exception:  # noqa: BLE001 - marks nobody can read: no copy is taken up
                marks = None
        elif re.fullmatch(_VIEWER_CACHE_FILE_RE, path.name):
            try:
                found.append((path.name, json.loads(path.read_text(encoding="utf-8"))))
            except Exception:  # noqa: BLE001 - not taken up, and removed
                drop.append(path.name)
    return found, drop, marks


def _viewer_cache_marks_take(marks: dict[str, float]) -> None:
    """The marks kept by the last run, each as a moment of this one, never later than now; a mark of no session…"""
    wall_now, now = time.time(), time.monotonic()
    for k, wall in marks.items():
        th, _bar, read = k.partition("|")
        if k != "*" and not (re.fullmatch(r"[0-9a-f]{64}", th)
                             and (read == "*" or _viewer_cache_ring_of(read) is not None)):
            continue
        wall = min(wall, wall_now)
        if wall_now - wall <= VIEWER_CACHE_MAX_AGE_S:
            _VIEWER_CACHE_WROTE[k] = max(_VIEWER_CACHE_WROTE.get(k, float("-inf")), now - (wall_now - wall))


def _viewer_cache_purge_unused() -> int:
    """The copies and marks the default folder still holds while it is not the folder set — keeping turned off…"""
    default = _app_pack_dir_state(os.path.join(APP_PACK_DEFAULT_DIR, "viewer"))[0]
    if default is None or (VIEWER_CACHE_DIR and Path(VIEWER_CACHE_DIR).resolve() == default):
        return 0
    gone = 0
    for path in default.iterdir():
        if (path.name == _VIEWER_CACHE_MARKS or re.fullmatch(_VIEWER_CACHE_FILE_RE, path.name)
                or re.fullmatch(_VIEWER_CACHE_TEMP_RE, path.name)):
            path.unlink(missing_ok=True)
            gone += 1
    return gone


def _viewer_cache_from_disk(name: str, body: Any, now: float) -> tuple[str, dict[str, Any]]:
    """A kept file as a copy, stale."""
    if not isinstance(body, dict) or body.get("v") != 1:
        raise ValueError("shape")
    key, th, read, asked = (body.get(k) for k in ("key", "th", "read", "asked"))
    if (not isinstance(read, str) or _viewer_cache_ring_of(read) is None
            or not all(isinstance(v, str) for v in (key, th, asked))
            or not re.fullmatch(r"[0-9a-f]{64}", th) or name != _viewer_cache_file(key)
            or hashlib.sha256(f"{th}\n{asked}".encode()).hexdigest() != key):
        raise ValueError("key")
    env = json.loads(asked)
    if not isinstance(env, dict) or env.get("action") != read or "token" in env or "service_secret" in env:
        raise ValueError("envelope")
    wall = float(body["wall"])
    text = body.get("body")
    content = text.encode("utf-8") if isinstance(text, str) else b""
    got = _viewer_cache_envelope(content) or {}
    if (not now - VIEWER_CACHE_MAX_AGE_S < wall <= now + 60 or got.get("status") != 200
            or not isinstance(got.get("data"), dict) or len(content) > VIEWER_CACHE_MAX_BYTES // 8):
        raise ValueError("copy")
    used = float(body.get("used") or 0.0)
    return key, {"body": content, "th": th, "read": read, "asked": asked, "version": -1, "wall": wall,
                 "used_wall": used if 0 < used <= now + 60 else 0.0}


def _viewer_cache_adopt(found: list[tuple[str, Any]]) -> tuple[int, list[str]]:
    """The kept files taken up after a start, oldest first and behind any copy filled since: each stale (version…"""
    wall_now, now = time.time(), time.monotonic()
    good: list[tuple[float, str, dict[str, Any]]] = []
    drop: list[str] = []
    for name, body in found:
        try:
            key, entry = _viewer_cache_from_disk(name, body, wall_now)
        except Exception:  # noqa: BLE001 - not taken up, and removed
            drop.append(name)
            continue
        if key in _VIEWER_CACHE:
            # filled since the start: its own file is written over this one
            continue
        if key in _VIEWER_CACHE_DIRTY:
            # let go since the start (refused, outgrown): never taken up again
            drop.append(name)
            continue
        entry["at"] = now - (wall_now - entry["wall"])
        used_wall = entry.pop("used_wall")
        entry["used"] = now - (wall_now - used_wall) if used_wall else float("-inf")
        if _viewer_cache_predates(entry["th"], entry["read"], entry["at"]):
            drop.append(name)
            continue
        good.append((entry["wall"], key, entry))
    since = list(_VIEWER_CACHE.items())
    _VIEWER_CACHE.clear()
    for _wall, key, entry in sorted(good, key=lambda g: (g[0], g[1])):
        _VIEWER_CACHE[key] = entry
    _VIEWER_CACHE.update(since)
    size = sum(len(e["body"]) for e in _VIEWER_CACHE.values())
    while _VIEWER_CACHE and (len(_VIEWER_CACHE) > VIEWER_CACHE_MAX_KEYS or size > VIEWER_CACHE_MAX_BYTES):
        size -= len(_viewer_cache_drop(next(iter(_VIEWER_CACHE)))["body"])
    return sum(1 for _w, key, _e in good if key in _VIEWER_CACHE), drop


def _viewer_cache_expire() -> int:
    """Every copy past its age let go with its file, and the write marks no copy can predate any more."""
    now = time.monotonic()
    gone = [k for k, e in _VIEWER_CACHE.items() if now - e["at"] >= VIEWER_CACHE_MAX_AGE_S]
    for key in gone:
        _viewer_cache_drop(key)
    _VIEWER_CACHE_LANE_SHOWN.intersection_update(_VIEWER_CACHE)
    for k, at in list(_VIEWER_CACHE_WROTE.items()):
        if now - at > VIEWER_CACHE_MAX_AGE_S:
            _VIEWER_CACHE_WROTE.pop(k, None)
    return len(gone)


async def _viewer_cache_open() -> "Path | None":
    """The folder judged (_chat_cache_dir_state: never the served tree, the bundle deposit or the packs' own…"""
    global _VIEWER_CACHE_FOLDER
    try:
        try:
            gone = await asyncio.to_thread(_viewer_cache_purge_unused)
        except Exception as exc:  # noqa: BLE001
            log.warning("viewer cache: the default folder could not be swept (%s)", type(exc).__name__)
            gone = 0
        if gone:
            log.warning("viewer cache: %d file(s) left in a folder not in use, removed", gone)
        folder, why = await asyncio.to_thread(_chat_cache_dir_state, VIEWER_CACHE_DIR)
        _VIEWER_CACHE_DISK["state"] = why or "kept"
        if folder is None:
            if why != "unset":
                log.warning("viewer cache: no folder to keep the copies in (%s); they are held in memory alone", why)
            return None
        found, drop, marks = await asyncio.to_thread(_viewer_cache_disk_read, folder)
        if marks is None:
            drop += [name for name, _body in found]
            found = []
        else:
            _viewer_cache_marks_take(marks)
        taken, more = _viewer_cache_adopt(found)
        drop += more
        _VIEWER_CACHE_DISK["taken"] = taken
        _VIEWER_CACHE_FOLDER = folder
        _viewer_cache_marks_keep()
        if drop:
            failed = await asyncio.to_thread(_viewer_cache_disk_write, folder, [(name, None) for name in drop])
            _VIEWER_CACHE_DIRTY.update(name.split(".", 1)[0] for name in failed
                                       if re.fullmatch(_VIEWER_CACHE_FILE_RE, name))
        ahead = _viewer_cache_prefill_for()
        log.info("viewer cache: %d kept copies taken up from disk, %d files removed, %d read ahead", taken, len(drop),
                 ahead)
        return folder
    except Exception as exc:  # noqa: BLE001 - a folder that cannot be read starts cold, in memory
        _VIEWER_CACHE_DISK["state"] = f"unreadable ({type(exc).__name__})"
        return None


async def _viewer_cache_flush(folder: "Path | None") -> None:
    jobs = _viewer_cache_take_dirty()
    if folder is not None and jobs:
        failed = await asyncio.to_thread(_viewer_cache_disk_write, folder, jobs)
        # a file that could not be removed is removed at the next beat, or written over by a copy filled since
        _VIEWER_CACHE_DIRTY.update(name.split(".", 1)[0] for name in failed
                                   if re.fullmatch(_VIEWER_CACHE_FILE_RE, name))


async def _viewer_cache_start() -> None:
    """After a start the kept copies are taken up; from then on what changed is written every second, the copies…"""
    folder = await _viewer_cache_open()
    beat = 0
    refill_every = max(1, round(VIEWER_CACHE_REFILL_S / VIEWER_CACHE_FLUSH_S))
    while True:
        await asyncio.sleep(VIEWER_CACHE_FLUSH_S)
        beat += 1
        try:
            if beat % VIEWER_CACHE_EXPIRE_EVERY == 0:
                _viewer_cache_expire()
            # the bounded refill: copies answered lately to a viewer whose stream is open, read again past fresh
            if beat % refill_every == 0:
                _viewer_cache_prefill_for(recent_s=VIEWER_CACHE_REFILL_RECENT_S,
                                          age=min(VIEWER_CACHE_FRESH_S, max(0.0, VIEWER_CACHE_REFILL_S - 30.0)))
            # the My apps' lanes, on their own cadence
            if beat % VIEWER_CACHE_LANE_REFILL_S == 0:
                _viewer_cache_prefill_for(_VIEWER_CACHE_LANES, None, age=max(0.0, VIEWER_CACHE_LANE_REFILL_S - 30.0))
            await _viewer_cache_flush(folder)
        except Exception:  # noqa: BLE001 - memory still holds every copy
            _VIEWER_CACHE_DISK["failed"] += 1


# --------------------------------------------------------------------------- THE LANE KEEP's doors (see the top of…
def _lane_keep_params(asked: str) -> dict[str, str]:
    """A kept copy's request as its door takes it again."""
    return {k: str(v) for k, v in json.loads(asked).items() if k not in ("action", "mode")}


def _lane_keep_ask(read: str, token: str, params: dict[str, Any], refresh: bool = False,
                   mode: str = "") -> dict[str, Any] | None:
    """The ask a My app's answer is kept under, or None: a person's token, never a switched session or a visit."""
    if not token or read not in _VIEWER_CACHE_LANES or str(params.get("member") or "").strip() or _my_work_acting(token):
        return None
    try:
        asked = json.dumps({**{k: str(v) for k, v in params.items() if k != "member"}, "action": read, "mode": mode},
                           sort_keys=True, separators=(",", ":"))
    except (TypeError, ValueError):
        return None
    th = hashlib.sha256(token.encode()).hexdigest()
    return {"key": hashlib.sha256(f"{th}\n{asked}".encode()).hexdigest(), "th": th, "read": read, "asked": asked,
            "token": token, "version": _VIEWER_CACHE_VERSION.get(read, 0), "at": time.monotonic(),
            "refresh": refresh}


def _lane_keep_body(out: dict[str, Any]) -> bytes | None:
    from fastapi.encoders import jsonable_encoder  # noqa: PLC0415 - the bytes FastAPI itself would send
    try:
        return json.dumps(jsonable_encoder(out), ensure_ascii=False, separators=(",", ":")).encode()
    except Exception:  # noqa: BLE001 - not kept
        return None


def _lane_keep_said(ask: dict[str, Any], body: bytes) -> Response:
    """A kept answer, saying when it was read and whether it is still current."""
    entry = _VIEWER_CACHE.get(ask["key"]) or {}
    env = json.loads(body)
    now = time.monotonic()
    at = float(entry.get("at", now))
    fresh = entry.get("version") == _VIEWER_CACHE_VERSION.get(ask["read"], 0) and now - at < VIEWER_CACHE_FRESH_S
    wall = float(entry.get("wall") or time.time())
    env["data"]["kept"] = {"at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(wall)),
                           "age_s": int(max(0.0, now - at)), "fresh": bool(fresh)}
    return Response(json.dumps(env, ensure_ascii=False, separators=(",", ":")), media_type="application/json",
                    headers={"Cache-Control": "no-store"})


def _lane_keep_drop(th: str, reads: Any) -> None:
    """A session's copies of these reads let go, their files at once, and none read before now kept again."""
    now = time.monotonic()
    for read in reads:
        _VIEWER_CACHE_WROTE[f"{th}|{read}"] = now
    _viewer_cache_marks_keep()
    _viewer_cache_unlink_now(_viewer_cache_drop_session(th, set(reads)))


def _lane_keep_sure(authorization: str, actor: Any) -> bool:
    """Whether the answer may be kept: never one judged on a master flag not learned yet."""
    role = str((actor or ("",))[0] or "").strip().lower()
    return role != "admin" or _auth_master.get(_hotline_token(authorization)) is not None


def _lane_keep_refused(out: Any) -> int:
    """401 or 403 when an answer takes away what a copy earned; 0 otherwise (a mirror too old or unreadable is not)."""
    if not isinstance(out, dict) or out.get("status") not in (401, 403, 404):
        return 0
    return 0 if out.get("reason") in ("stale", "unreadable") else int(out["status"])


async def _lane_kept(read: str, authorization: str, params: dict[str, Any], mode: str, actor: Any, build: Any) -> Any:
    """A My app's answer past its door's gate: this viewer's kept copy (session checked again) or the built…"""
    token = _hotline_token(authorization)
    refresh = _LANE_KEEP_REFRESHING.get()
    if read == "lane:my-calendar" and my_calendar is not None:
        # "this week" is kept for the day it was read on
        mode = f"{mode}|{my_calendar.today().isoformat()}"
    ask = _lane_keep_ask(read, token, params, refresh, mode) if _lane_keep_sure(authorization, actor) else None
    if ask is None:
        return await build()
    if not refresh:
        hit = await _viewer_cache_hit(ask, b"", "")
        if hit is not None:
            try:
                return _lane_keep_said(ask, hit)
            except Exception:  # noqa: BLE001 - a copy that cannot be said is read again
                pass
    out = await build()
    if isinstance(out, dict) and (out.get("status") == 200 or _lane_keep_refused(out)):
        body = _lane_keep_body(out)
        if body is not None:
            _viewer_cache_take(ask, body)
    return out


async def _lane_keep_fetch(ask: dict[str, Any]) -> bytes:
    """A kept copy read again through its own door, as its viewer: the bytes it answered."""
    door = globals()[_LANE_KEEP_ROUTES[ask["read"]]]
    flag = _LANE_KEEP_REFRESHING.set(True)
    try:
        out = await door(Response(), authorization="Bearer " + ask["token"], **_lane_keep_params(ask["asked"]))
    finally:
        _LANE_KEEP_REFRESHING.reset(flag)
    refused = _lane_keep_refused(out)
    if refused:
        _lane_keep_drop(ask["th"], tuple(_VIEWER_CACHE_READS) if refused == 401 else (ask["read"],))
    if isinstance(out, Response):
        return bytes(out.body)
    return (_lane_keep_body(out) if isinstance(out, dict) else None) or b""


def _lane_keep_path_names(scope: Any) -> tuple[str, ...]:
    if scope.get("type") != "http" or scope.get("method") not in ("POST", "PUT", "PATCH", "DELETE"):
        return ()
    path = str(scope.get("path") or "")
    return tuple(dict.fromkeys(n for prefix, names in _LANE_KEEP_PATH_WRITES if path.startswith(prefix)
                               for n in names))


class _LaneKeepWrites:
    """A relay write door of the My apps' rows (_LANE_KEEP_PATH_WRITES): the writer's copies go before it runs…"""

    def __init__(self, app: Any) -> None:
        self.app = app

    async def __call__(self, scope: Any, receive: Any, send: Any) -> None:
        names = _lane_keep_path_names(scope)
        if not names:
            await self.app(scope, receive, send)
            return
        th, reads = "", tuple(r for r, n in _VIEWER_CACHE_LANES.items() if n in names)
        try:
            for k, v in scope.get("headers") or []:
                if k == b"authorization":
                    token = _hotline_token(v.decode("latin-1"))
                    th = hashlib.sha256(token.encode()).hexdigest() if token else ""
            if th:
                _lane_keep_drop(th, reads)
        except Exception:  # noqa: BLE001 - a kept copy never fails a write
            pass
        said: dict[str, Any] = {"status": 0, "body": b""}

        async def watch(message: Any) -> None:
            if message.get("type") == "http.response.start":
                said["status"] = int(message.get("status") or 0)
            elif message.get("type") == "http.response.body" and len(said["body"]) < 65536:
                said["body"] += bytes(message.get("body") or b"")
            await send(message)

        try:
            await self.app(scope, receive, watch)
        finally:
            try:
                env = _viewer_cache_envelope(said["body"]) or {}
                if said["status"] == 200 and env.get("status", 200) == 200:
                    if th:
                        _lane_keep_drop(th, reads)
                    for name in names:
                        _publish_slice(name)
            except Exception:  # noqa: BLE001 - telling nobody must never fail a write
                pass


app.add_middleware(_LaneKeepWrites)


# SUPPORT REQUESTS' MISSING PUNCHES: the set of faults the door last took, so a beat posts only when it changes.
_SUPPORT_PUNCH: dict[str, Any] = {"digest": "", "off_digest": "", "off_at": 0.0}
SUPPORT_PUNCH_MAX = 200
SUPPORT_PUNCH_OFF_RETRY_S = 600.0


def _support_punch_digest(rows: list[dict]) -> str:
    """One word for a set of faults: its shifts and each one's verdict, so a shift that turns from no entry to an…"""
    return hashlib.sha256("\n".join(sorted(f"{r.get('id')}|{r.get('verdict')}" for r in rows)).encode()).hexdigest()


async def _support_punch_passes(rows: list[dict]) -> dict[str, Any]:
    """supportDeskPunch on Python, pass after pass while it hands faults back: the counts together, and not ok while a
    fault is left unjudged, so the beat offers them all again."""
    said: dict[str, Any] = {"ok": True, "raised": 0, "already": 0, "off": False, "why": ""}
    left = rows
    for _ in range(BACKEND_ROW_PASSES):
        env = await _backend_pass(SUPPORT_PUNCH_APP, "supportDeskPunch", {"rows": left})
        if env.get("status") != 200:
            return env
        data = env.get("data") or {}
        for k in ("raised", "already"):
            said[k] += int(data.get(k) or 0)
        said["off"], said["why"] = bool(data.get("off")), str(data.get("why") or "")
        if data.get("ok") is not True:
            said["ok"] = False
            return {"status": 200, "data": said}
        left = data.get("left") or []
        if not left:
            return {"status": 200, "data": said}
    said.update(ok=False, why=f"{len(left)} fault(s) unjudged after {BACKEND_ROW_PASSES} passes")
    return {"status": 200, "data": said}


async def _support_punch_post() -> None:
    """The punch board's faults, handed to Support Requests (supportDeskPunch), which decides what is a first…"""
    from datetime import datetime, timezone  # noqa: PLC0415
    try:
        import punch_pairs  # noqa: PLC0415 — lazy, as the post above
        if punch_pairs.stale(datetime.now(timezone.utc)):
            return
        rows = punch_pairs.first_faults()
    except Exception as exc:  # noqa: BLE001
        log.warning("support punch: the faults could not be read (%s)", type(exc).__name__)
        return
    if not rows:
        _SUPPORT_PUNCH["digest"] = ""
        return
    rows = sorted(rows, key=lambda r: (str(r.get("shift_at") or ""), str(r.get("id") or "")),
                  reverse=True)[:SUPPORT_PUNCH_MAX]
    digest = _support_punch_digest(rows)
    if digest == _SUPPORT_PUNCH["digest"]:
        return
    if digest == _SUPPORT_PUNCH["off_digest"] and time.time() - _SUPPORT_PUNCH["off_at"] < SUPPORT_PUNCH_OFF_RETRY_S:
        return
    try:
        env = await _support_punch_passes(rows)
    except Exception as exc:  # noqa: BLE001
        log.warning("support punch: the door could not be reached (%s) — offered again", type(exc).__name__)
        return
    if (env or {}).get("status") != 200:
        log.warning("support punch refused: %s — offered again", str((env or {}).get("message") or env)[:160])
        return
    said = (env or {}).get("data") or {}
    if not isinstance(said, dict) or said.get("ok") is not True:
        log.warning("support punch: the door did not take the faults — offered again")
        return
    if said.get("off"):
        _SUPPORT_PUNCH.update(off_digest=digest, off_at=time.time())
        log.info("support punch: %s fault(s) offered, the switch is off", len(rows))
        return
    _SUPPORT_PUNCH.update(digest=digest, off_digest="", off_at=0.0)

    def count(v: Any) -> int:
        return len(v) if isinstance(v, (list, tuple)) else v if isinstance(v, int) and not isinstance(v, bool) else 0

    log.info("support punch: %s fault(s) offered, %s raised, %s already raised", len(rows),
             count(said.get("raised")), count(said.get("already")))
    if count(said.get("raised")):
        _publish_slice(SUPPORT_DESK_EVENT)


_PUNCH_RECEIVED_STATUS = {"no_name": 403, "not_a_director": 403, "own_shift": 403,
                          "no_such_warning": 404, "not_waiting": 409, "several": 409,
                          "never_delivered": 409, "stood_down": 409, "already": 409}


@app.post("/hub-lanes/punch-warnings/received")
async def lane_punch_warning_received(request: Request,
                                     authorization: str = Header(default="")) -> dict[str, Any]:
    """A director's RECEIVED on one punch warning, by its ref — the Hub's half of the text reply, through the…"""
    if not PG_DSN:
        return {"status": 503, "reason": "unreadable",
                "message": "Punch warnings are not available on this server right now."}
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return got
    who, session = got
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        body = None
    if not isinstance(body, dict):
        return {"status": 400, "reason": "request", "message": "invalid body"}
    import punch_pairs  # noqa: PLC0415 — lazy, as the post above
    ref = str(body.get("ref") or "").strip().upper()
    if not punch_pairs.REF_RE.fullmatch(ref):
        return {"status": 400, "reason": "request", "message": "ref is required (PW…)"}
    try:
        master = who.get("is_master") is True
        done = await asyncio.to_thread(punch_pairs.acknowledge, PG_DSN,
                                       by=str(who.get("name") or (f"account {session[1]}" if master else "")),
                                       ref=ref, via="hub", master=master)
    except punch_pairs.Refused as exc:
        return {"status": _PUNCH_RECEIVED_STATUS.get(exc.code, 409), "reason": exc.code,
                "message": exc.why}
    except punch_pairs.Unreadable as exc:
        return {"status": 503, "reason": "unreadable",
                "message": f"{exc} — nothing was done, and the warning still waits for an answer."}
    except Exception as exc:  # noqa: BLE001
        log.warning("punch pairs: a RECEIVED from the Hub failed (%s)", type(exc).__name__)
        return {"status": 503, "reason": "unreadable",
                "message": f"the RECEIVED could not be recorded ({type(exc).__name__}) — nothing was done."}
    log.info("punch pairs: %s answered RECEIVED on the Hub by %s → %s", ref, session[1],
             done.get("state"))
    return {"status": 200, "data": {"ref": done.get("ref") or ref, "state": done.get("state") or "",
                                    "call_off_ref": done.get("call_off_ref") or "",
                                    "words": punch_pairs.received_words(done)}}


# -------------------------------------------------------------------------- PRODUCTION ACTIONS — the go-live…
_PA_REFUSED = {"status": 404, "reason": "unknown", "message": "Unknown lane."}


async def _production_actions_actor(authorization: str) -> tuple[tuple[str, str] | None, str]:
    """((role, uid), "") for the master's own session; (None, why) when the check itself could not be made."""
    actor = await _session_actor(authorization)
    if not actor or str(actor[0] or "").strip().lower() != "admin":
        return None, ""
    if production_actions is None:
        return None, "the runbook is not available on this server right now"
    token = _hotline_token(authorization)
    flag = _auth_master.get(token)
    if flag is None:
        try:
            env = await _auth_me(token)
        except Exception as exc:  # noqa: BLE001 - FAIL-CLOSED: an unknown flag keeps the door shut
            return None, f"the master check could not be made ({type(exc).__name__})"
        user = ((env.get("data") or {}).get("user") or {}) if env.get("status") == 200 else {}
        if "is_master" not in user:
            return None, "the master check could not be made"
        _note_session_answer(token, env)
        flag = bool(user.get("is_master"))
        _auth_master[token] = flag
    return (actor if production_actions.master_verdict(actor[0], flag) else None), ""


@app.get("/hub-lanes/production-actions")
async def lane_production_actions(response: Response, authorization: str = Header(default="")) -> dict[str, Any]:
    """Both runbook houses out of the master JSON, and the relay's own test-mode switch."""
    response.headers["Cache-Control"] = "no-store"
    actor, unsure = await _production_actions_actor(authorization)
    if unsure:
        return {"status": 503, "reason": "unavailable", "message": f"The runbook could not open: {unsure}. Try again."}
    if not actor:
        return dict(_PA_REFUSED)
    if await _backend_wanted(PRODUCTION_ACTIONS_APP):
        # on Python the runbook is Postgres': its view is Python's, never the master JSON's older copy
        got = await _backend_call(PRODUCTION_ACTIONS_APP, "productionActionsView", {},
                                  {"uid": str(actor[1] or ""), "role": "admin", "is_master": True})
        env = got[2] if got is not None else None
        if not env or env.get("status") != 200 or not isinstance(env.get("data"), dict):
            log.warning("production actions: the view was not answered by Python (%s)",
                        _BACKEND_UNANSWERED.get() if env is None else env.get("status"))
            return {"status": 503, "reason": "unavailable",
                    "message": "The runbook could not be read just now. Try again in a moment."}
        data = env["data"]
        data["test_mode"] = _web_switch()
        return {"status": 200, "data": data}
    try:
        data = await asyncio.to_thread(production_actions.view, master_json.ROOT, time.time())
    except Exception as exc:  # noqa: BLE001
        log.warning("production actions: the view failed (%s)", type(exc).__name__)
        return {"status": 503, "reason": "unreadable",
                "message": f"The runbook could not be read ({type(exc).__name__})."}
    data["test_mode"] = _web_switch()
    return {"status": 200, "data": data}


def _code_stamp(folder: Path) -> str:
    """The fingerprint of the code this process runs: sha256 over every top-level *.py, by name (as app/main.py and
    vite.config.ts make theirs)."""
    h = hashlib.sha256()
    try:
        for p in sorted(folder.glob("*.py"), key=lambda x: x.name):
            h.update((p.name + "\n").encode())
            h.update(p.read_bytes())
            h.update(b"\n")
    except OSError:
        return ""
    return h.hexdigest()[:12]


RELAY_CODE_STAMP = _code_stamp(Path(__file__).resolve().parent)
RELAY_STARTED_AT = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


@app.get("/hub-lanes/versions")
async def lane_versions(response: Response, authorization: str = Header(default="")) -> dict[str, Any]:
    """The master's versions box (Settings › Profile): the code the relay and asa-hub-app run and since when, and the
    Apps Script build that last answered. The master's own session alone; everyone else the unknown lane."""
    response.headers["Cache-Control"] = "no-store"
    master, unsure = await _app_pack_master(authorization)
    if unsure:
        return {"status": 503, "reason": "unavailable", "message": f"The versions could not open: {unsure}."}
    if not master:
        return dict(_PA_REFUSED)
    python: dict[str, Any] = {"code": "", "started_at": "", "why": ""}
    try:
        async with httpx.AsyncClient(timeout=3.0) as client:
            res = await client.get(f"{HUB_APP_URL}/healthz")
        body = res.json() if res.status_code == 200 else {}
        python.update(code=str(body.get("code") or ""), started_at=str(body.get("started_at") or ""),
                      why="" if body.get("ok") else "asa-hub-app answered without its health")
    except Exception as exc:  # noqa: BLE001 - said in the box
        python["why"] = f"asa-hub-app did not answer ({type(exc).__name__})"
    return {"status": 200, "data": {"relay": {"code": RELAY_CODE_STAMP, "started_at": RELAY_STARTED_AT},
                                    "python": python, "engine_build": _ENGINE_BUILD or ""}}


# -------------------------------------------------------------------------- APP PACKS — what an app's screen still…
APP_PACK_WARM_START_S = 120.0
# under the proxy's 30-second read timeout on /hub-lanes/, counted from the request's arrival (the sign-in check…
APP_PACK_WAIT_S = 25.0
# a read that waits less than this starts its fill in the background: it stops waiting long before an execution…
APP_PACK_PERSON_WAIT_S = 10.0
# fills on a person's lane at once, every app together; past it a read starts a background fill and answers `filling`
APP_PACK_PERSON_FILLS = 2
# a client's pack runs every Clients section's door in one execution; it stops starting parts at 240 s itself.
APP_PACK_CLIENT_FILL_TIMEOUT_S = 300
APP_PACK_MAX_KEYS = 160
# packs held at once, every app together, the oldest let go past it: every app's warm keys and the keys a person…
APP_PACK_MAX_HELD = 400
_APP_PACK_FILE_RE = r"[0-9a-f]{64}\.json"
# an app's mark: no copy of its packs read before the moment it holds is taken up (`<app>.void`)
_APP_PACK_MARK_RE = r"([a-z][a-z0-9\-]{0,40})\.void"
# a kept file's or a mark's temporary neighbour while it is written: `.<its name>.<random>.tmp`
_APP_PACK_TEMP_RE = r"\.(?:[0-9a-f]{64}\.json|[a-z][a-z0-9\-]{0,40}\.void)\.[A-Za-z0-9_]+\.tmp"
# how long ago a session's own write may be named on its read (?written_ms=, ?sent_ms=); older is not asked about
APP_PACK_WRITTEN_MAX_MS = 15 * 60 * 1000
# a prefetch (?peek=1) that finds nothing held starts a background fill only while fewer than this many are waiting…
APP_PACK_PEEK_QUEUE = 2
# an engine that does not know the pack's action yet is not asked again until it changes, or for this long
APP_PACK_UNPUBLISHED_S = 1800.0
# an upload past what the relay parses names its action and its house in these first bytes
APP_PACK_HEAD_BYTES = 4096
_APP_PACK_REFUSED = {"status": 404, "reason": "unknown", "message": "Unknown lane."}
_APP_PACK_VERBS = frozenset({"create", "update", "delete", "remove"})
# The Locations doors that file or edit an estate row through the estate's own write: the resource each writes, so…
_APP_PACK_DOOR_RESOURCES = {"locationIncidentFile": "uiIncidents", "locationIncidentEdit": "uiIncidents",
                            "locationRepairFile": "workOrders", "locationRepairEdit": "workOrders"}
_APP_PACK_DOOR_RESOURCES.update({_door: "workOrders" for _door in WORK_ORDERS_WRITES})
# and the generic verbs Python answers under their door's name (app/ops_stragglers_writes.py): the packs reading each
# resource rung as the generic verb rang them
_APP_PACK_DOOR_RESOURCES.update({"uiIncidentsUpdate": "uiIncidents", "uiIncidentsDelete": "uiIncidents",
                                 "callOffsDelete": "callOffs",
                                 "docsDelete": "documents", "helpfulContactsCreate": "helpfulContacts",
                                 "helpfulContactsDelete": "helpfulContacts", "peopleUpdate": "people"})
# and the last of route()'s own resources (GENERIC_ROUTES)
_APP_PACK_DOOR_RESOURCES.update({_pre + _v: _res for _res, (_app, _pre) in GENERIC_ROUTES.items()
                                 if _res not in GENERIC_READ_ONLY for _v in ("Create", "Update", "Delete")})

# (app, key) -> {data, built_at, read_at, filled_at, dirty, stale, lane, engine}
_app_pack_held: dict[tuple[str, str], dict[str, Any]] = {}
_app_pack_inflight: dict[tuple[str, str], asyncio.Task] = {}
# set when a person comes to wait on a background fill: one still queued for its turn runs on the person's lane
_app_pack_promote: dict[tuple[str, str], asyncio.Event] = {}
# the promote events of the fills holding a person's lane, APP_PACK_PERSON_FILLS at most: taken by the kick that…
_app_pack_person_lane: set[asyncio.Event] = set()
# bumped by every write that names the key: a fill whose execution began before the write lands dirty
_app_pack_gen: dict[tuple[str, str], int] = {}
# bumped by every sweep: a fill whose execution began before it lands stale
_app_pack_stale_gen: dict[tuple[str, str], int] = {}
# when the relay last saw a write that names the key land: a writer's read is answered by a copy read after it
_app_pack_touched: dict[tuple[str, str], float] = {}
# (app, key) -> the moment no copy of that pack read before may be kept or taken up again: a write that makes it…
_app_pack_void: dict[tuple[str, str], float] = {}
# (app, key) -> when the engine last refused that pack (its whole app: key ""): no copy read before is kept or taken up,
# as _app_pack_void — but a refusal is no write, so Python's reads never take it for one (_backend_copy_at)
_app_pack_refused: dict[tuple[str, str], float] = {}
# the fill executing now for a key, and when it began reading
_app_pack_began: dict[tuple[str, str], tuple[Any, float]] = {}
# app -> (when, the engine build then): the rest ends when the engine changes, or after APP_PACK_UNPUBLISHED_S
_app_pack_unpublished: dict[str, tuple[float, str]] = {}
_app_pack_warm_sem = asyncio.Semaphore(1)
# one background fill at a time across every app, so the packs never hold more than one housekeeping ticket
_app_pack_bg_sem = asyncio.Semaphore(1)
_app_pack_warm_wake = asyncio.Event()


class _AppPackRefused(Exception):
    """The engine answered the pack with a refusal: its status and its own words."""

    def __init__(self, status: int, message: str) -> None:
        super().__init__(message)
        self.status = status
        self.message = message


def _app_pack_house_keys() -> list[str]:
    """The active house codes of the relay's own houses slice; [] when it cannot be read."""
    try:
        body = json.loads((OUT_DIR / "houses.json").read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001 - no slice, no warm pass; a person's read still fills its own key
        return []
    rows = body.get("rows") if isinstance(body, dict) else body
    out: list[str] = []
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            continue
        code = str(row.get("code") or "").strip().upper()
        if row.get("active") is True and re.fullmatch(r"[A-Z]{2,4}\d{3,6}", code) and code not in out:
            out.append(code)
    return out[:APP_PACK_MAX_KEYS]


async def _app_pack_exec_locations(key: str) -> dict:
    """One locationPack fill: Python fills it, refuses it or says 503; the housekeeping ticket, when there is one, is
    already held by the fill."""
    return await _backend_pack("locations", "locationPack", key)


def _app_pack_house_of(body: dict[str, Any], env: Any) -> str:
    """The house a Locations write names: in its request, or in the note or entry it answers with; '' for none."""
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    data = env.get("data") if isinstance(env, dict) and isinstance(env.get("data"), dict) else {}
    said = [payload.get("house")] + [(data.get(k) or {}).get("house") for k in ("note", "entry")
                                     if isinstance(data.get(k), dict)]
    for value in said:
        code = str(value or "").strip().upper()
        if re.fullmatch(_APP_PACK_HOUSE_RE, code):
            return code
    return ""


def _app_pack_client_houses_of(body: dict[str, Any], env: Any) -> list[str]:
    """The houses a client's record edit touches: the house its clients slice row names for each client it names…"""
    out: list[str] = []
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    said = [c.get(f) for c in payload.get("changes") or [] if isinstance(c, dict)
            and "house" in str(c.get("field") or "").lower() for f in ("value", "expected")]
    clients = set(_app_pack_clients_of(body, env))
    if clients:
        try:
            rows = json.loads((OUT_DIR / "clients.json").read_text(encoding="utf-8"))
            rows = rows.get("rows") if isinstance(rows, dict) else rows
        except Exception:  # noqa: BLE001 - no slice: the houses' own age refreshes them
            rows = []
        for row in rows if isinstance(rows, list) else []:
            if isinstance(row, dict) and (str(row.get("client_key") or "").strip()
                                          or _app_pack_fold_name(row.get("name"))) in clients:
                said.append(row.get("house"))
    for value in said:
        code = str(value or "").strip().upper()
        if re.fullmatch(_APP_PACK_HOUSE_RE, code) and code not in out:
            out.append(code)
    return out


_APP_PACK_HOUSE_RE = r"[A-Z]{2,4}\d{3,6}"
_APP_PACK_CLIENT_RE = r"[A-Za-z0-9_.\-]{1,80}"
_APP_PACK_CLIENTS = "client-profiles"


def _app_pack_fold_name(value: Any) -> str:
    """A name folded the way the platform folds it (clientNameKey_): lower case, letters and digits only."""
    return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())


def _app_pack_client_index() -> dict[str, Any]:
    """From the relay's own clients slice, identity only: every client key, the active ones in order (the warm…"""
    out: dict[str, Any] = {"active": [], "keys": set(), "names": {}}
    try:
        body = json.loads((OUT_DIR / "clients.json").read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001 - no slice, no warm pass and no name match; a person's read still fills its key
        return out
    rows = body.get("rows") if isinstance(body, dict) else body
    names: dict[str, str] = {}
    twice: set[str] = set()
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            continue
        fold = _app_pack_fold_name(row.get("name"))
        key = str(row.get("client_key") or "").strip() or fold
        if not key or not re.fullmatch(_APP_PACK_CLIENT_RE, key):
            continue
        out["keys"].add(key)
        if fold:
            if names.get(fold, key) != key:
                twice.add(fold)
            names.setdefault(fold, key)
        if client_status.live(row) and key not in out["active"]:
            out["active"].append(key)
    out["names"] = {f: k for f, k in names.items() if f not in twice}
    out["active"] = out["active"][:APP_PACK_MAX_KEYS]
    return out


def _app_pack_client_keys() -> list[str]:
    """The active clients of the relay's own clients slice; [] when it cannot be read."""
    return list(_app_pack_client_index()["active"])


async def _app_pack_exec_clients(key: str) -> dict:
    """One clientPack fill: Python fills it, refuses it or says 503; the housekeeping ticket, when there is one, is
    already held by the fill."""
    return await _backend_pack("clients", "clientPack", key)


def _app_pack_client_of(body: dict[str, Any], env: Any) -> str:
    """The client a write names, read the way the platform reads a client-bearing row (hubRowIsClients_): any…"""
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    data = env.get("data") if isinstance(env, dict) and isinstance(env.get("data"), dict) else {}
    sources = [payload, data] + [data[k] for k in ("row", "note", "entry", "record") if isinstance(data.get(k), dict)]
    said = [str(v).strip() for src in sources for k, v in src.items()
            if "client" in str(k).lower() and isinstance(v, (str, int)) and str(v).strip()]
    if not said:
        return ""
    index = _app_pack_client_index()
    known = index["keys"] | {k for (a, k) in list(_app_pack_held) + list(_app_pack_inflight) if a == _APP_PACK_CLIENTS}
    for value in said:
        key = value[4:] if value.startswith("CLI_") else value
        if key in known:
            return key
    for value in said:
        hit = index["names"].get(_app_pack_fold_name(value))
        if hit:
            return hit
    return ""


_APP_PACK_SSA_RE = r"ssa_[a-z0-9]{1,80}"
_APP_PACK_SSAS = "ssa-profiles"


def _app_pack_ssa_index() -> dict[str, Any]:
    """From the relay's own clients slice, identity only: every SSA key (ssa_ and the folded name a client's…"""
    out: dict[str, Any] = {"active": [], "keys": set(), "of_client": {}}
    try:
        body = json.loads((OUT_DIR / "clients.json").read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001 - no slice, no warm pass and no client match; a person's read still fills its key
        return out
    rows = body.get("rows") if isinstance(body, dict) else body
    unnamed: list[str] = []
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            continue
        client = str(row.get("client_key") or "").strip() or _app_pack_fold_name(row.get("name"))
        live = client_status.live(row)
        if not str(row.get("ssa_name") or "").strip():
            if client and live:
                unnamed.append(client)
            continue
        key = "ssa_" + _app_pack_fold_name(row.get("ssa_name"))
        if not re.fullmatch(_APP_PACK_SSA_RE, key):
            continue
        out["keys"].add(key)
        if client:
            out["of_client"][client] = key
        if live and key not in out["active"]:
            out["active"].append(key)
    if unnamed:
        for (app, key), entry in list(_app_pack_held.items()):
            if app != _APP_PACK_SSAS:
                continue
            parts = (entry.get("data") or {}).get("parts") if isinstance(entry.get("data"), dict) else None
            overview = parts.get("overview") if isinstance(parts, dict) else None
            listed = overview.get("clients") if isinstance(overview, dict) else None
            current = {str(c.get("client_key") or "").strip() for c in (listed if isinstance(listed, list) else [])
                       if client_status.live(c)}
            for client in unnamed:
                if client in current and client not in out["of_client"]:
                    out["of_client"][client] = key
                    out["keys"].add(key)
                    if key not in out["active"]:
                        out["active"].append(key)
    out["active"] = out["active"][:APP_PACK_MAX_KEYS]
    return out


def _app_pack_ssa_keys() -> list[str]:
    """The SSAs the current clients of the relay's own clients slice name; [] when it cannot be read."""
    return list(_app_pack_ssa_index()["active"])


async def _app_pack_exec_ssas(key: str) -> dict:
    """One ssaPack fill: Python fills it, refuses it or says 503; the housekeeping ticket, when there is one, is already
    held by the fill."""
    return await _backend_pack("ssa", "ssaPack", key)


def _app_pack_ssa_of(body: dict[str, Any], env: Any) -> str:
    """The SSA a write names: its key (the SSA app's own write, or the note it answers with), else the SSA a…"""
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    data = env.get("data") if isinstance(env, dict) and isinstance(env.get("data"), dict) else {}
    index = _app_pack_ssa_index()
    known = index["keys"] | {k for (a, k) in list(_app_pack_held) + list(_app_pack_inflight) if a == _APP_PACK_SSAS}
    note = data.get("note") if isinstance(data.get("note"), dict) else {}
    for value in (payload.get("ssa"), note.get("ssa")):
        key = value.strip() if isinstance(value, str) else ""
        if key in known:
            return key
    fields = payload.get("fields") if isinstance(payload.get("fields"), dict) else {}
    for src in (fields, payload):
        key = "ssa_" + _app_pack_fold_name(src.get("ssa_name"))
        if key in known:
            return key
    client = _app_pack_client_of(body, env)
    return index["of_client"].get(client, "") if client else ""


def _app_pack_written_clients(env: Any) -> list[str] | None:
    """The client records a family member's edit wrote (its answer's client_keys); None for any other answer."""
    data = env.get("data") if isinstance(env, dict) and isinstance(env.get("data"), dict) else {}
    keys = data.get("client_keys")
    if not isinstance(keys, list):
        return None
    return [k.strip() for k in keys if isinstance(k, str) and k.strip()]


def _app_pack_clients_of(body: dict[str, Any], env: Any) -> list[str]:
    """Every client a write names: each record a family member's edit wrote, else the one _app_pack_client_of finds."""
    written = _app_pack_written_clients(env)
    if written is not None:
        return written
    key = _app_pack_client_of(body, env)
    return [key] if key else []


def _app_pack_ssas_of(body: dict[str, Any], env: Any) -> list[str]:
    """Every SSA a write names: the SSA of each record a family member's edit wrote, else the one…"""
    written = _app_pack_written_clients(env)
    if written is None:
        key = _app_pack_ssa_of(body, env)
        return [key] if key else []
    of_client = _app_pack_ssa_index()["of_client"]
    return sorted({of_client[k] for k in written if of_client.get(k)})


_APP_PACK_FAMILIES = "family-profiles"
_APP_PACK_FAMILY_RE = r"fam_[a-z0-9]{3,120}"
# a key the engine says is no family member, or answers under another key (one person, two spellings), is not warmed…
APP_PACK_FAMILY_REST_S = 6 * 3600.0
# family key -> (when, the engine build then)
_app_pack_family_refused: dict[str, tuple[float, str]] = {}


def _app_pack_slice_rows(name: str) -> list[dict[str, Any]]:
    """The rows of one of the relay's own slices; [] when it cannot be read."""
    try:
        body = json.loads((OUT_DIR / name).read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001 - no slice, no key from it; a person's read still fills its own key
        return []
    rows = body.get("rows") if isinstance(body, dict) else body
    return [row for row in rows if isinstance(row, dict)] if isinstance(rows, list) else []


def _app_pack_family_index() -> dict[str, Any]:
    """From the families index Python builds off asa-hub-db (the familyIndexPack held here), identity only: every
    family member's key, the active first, and the family member each client's own record names. Nothing until that
    index is held: the relay's own slices never name a family member Families does not have."""
    held = _app_pack_held.get((_APP_PACK_FAMILY_INDEX, _APP_PACK_FAMILY_INDEX_KEY)) or {}
    parts = (held.get("data") or {}).get("parts") or {}
    families = (parts.get("roster") or {}).get("families") or []
    keys = [str(f.get("key") or "") for f in sorted((f for f in families if isinstance(f, dict)),
                                                     key=lambda f: f.get("status") != "active")]
    records = parts.get("records") if isinstance(parts.get("records"), dict) else {}
    return {"keys": list(dict.fromkeys(k for k in keys if re.fullmatch(_APP_PACK_FAMILY_RE, k))),
            "clients": {str(c): str(k) for c, k in records.items() if re.fullmatch(_APP_PACK_FAMILY_RE, str(k))}}


def _app_pack_family_keys() -> list[str]:
    """The family members the relay's own slices name, less the ones the engine said are none while that word…"""
    engine = _app_pack_engine()
    now = time.time()
    out: list[str] = []
    for key in _app_pack_family_index()["keys"]:
        rest = _app_pack_family_refused.get(key)
        if rest is not None and rest[1] == engine and now - rest[0] < APP_PACK_FAMILY_REST_S:
            continue
        out.append(key)
    return out[:APP_PACK_MAX_KEYS]


async def _app_pack_exec_families(key: str) -> dict:
    """One familyPack fill: Python fills it, refuses it or says 503; the housekeeping ticket, when there is one, is
    already held by the fill."""
    env = await _backend_pack("family", "familyPack", key)
    try:
        status = int(env.get("status") or 0) if isinstance(env, dict) else 0
    except (TypeError, ValueError):
        status = 0
    data = env.get("data") if status == 200 and isinstance(env.get("data"), dict) else {}
    if status == 200 and str(data.get("family") or key) == key:
        _app_pack_family_refused.pop(key, None)
    elif status == 200 or (status in (400, 404) and not _app_pack_not_served(status, str(env.get("message") or ""))):
        _app_pack_family_refused[key] = (time.time(), _app_pack_engine())
    return env


def _app_pack_family_of(body: dict[str, Any], env: Any) -> str:
    """The family member a write names: the family key of the request, or of the note, call or row it answers…"""
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    data = env.get("data") if isinstance(env, dict) and isinstance(env.get("data"), dict) else {}
    sources = [payload, data] + [data[k] for k in ("note", "call", "entry", "row", "record")
                                 if isinstance(data.get(k), dict)]
    for src in sources:
        key = str(src.get("family") or src.get("family_key") or "").strip()
        if re.fullmatch(_APP_PACK_FAMILY_RE, key):
            return key
    for src in sources:
        said = str(src.get("id") or "").strip()
        if said.startswith("PPL_guardian_"):
            key = "fam_" + _app_pack_fold_name(said[len("PPL_guardian_"):])
            if re.fullmatch(_APP_PACK_FAMILY_RE, key):
                return key
    client = _app_pack_client_of(body, env)
    return _app_pack_family_index()["clients"].get(client, "") if client else ""


# THE FAMILIES INDEX — what every open of Families starts on, for every family member at once (FamilyProfiles.gs…
_APP_PACK_FAMILY_INDEX = "family-index"
_APP_PACK_FAMILY_INDEX_KEY = "all"


def _app_pack_family_index_keys() -> list[str]:
    """The index's one key, always: it is what names every family member the warm pass fills."""
    return [_APP_PACK_FAMILY_INDEX_KEY]


async def _app_pack_exec_family_index(key: str) -> dict:
    """One familyIndexPack fill, Python's; the housekeeping ticket, when there is one, is already held by the fill."""
    return await _backend_pack("family", "familyIndexPack", key, pack=_APP_PACK_FAMILY_INDEX)


def _app_pack_view_told(answer: dict[str, Any], master: bool) -> dict[str, Any]:
    """An answered pack that says which view its reader reads, in the roster's own words (famViewWords_…"""
    data = answer.get("data") if isinstance(answer, dict) else None
    if not isinstance(data, dict) or answer.get("status") != 200:
        return answer
    return {**answer, "data": {**data, "view": {"kind": "master" if master else "all", "notes": True}}}


_APP_PACK_CANDIDATE_RE = r"CAN_[A-Za-z0-9]{6,80}"
_APP_PACK_CANDIDATES = "staff-candidates"


def _app_pack_candidate_keys() -> list[str]:
    """The candidates on the hiring board (the relay's own candidates slice, which holds no archived one), in its…"""
    try:
        body = json.loads((OUT_DIR / "candidates.json").read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001 - no slice, no warm pass; a person's read still fills its own key
        return []
    rows = body.get("rows") if isinstance(body, dict) else body
    out: list[str] = []
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict) or not str(row.get("stage") or "").strip():
            continue
        key = str(row.get("id") or "").strip()
        if re.fullmatch(_APP_PACK_CANDIDATE_RE, key) and key not in out:
            out.append(key)
    return out[:APP_PACK_MAX_KEYS]


async def _app_pack_exec_candidates(key: str) -> dict:
    """One candidatePack fill: Python fills it, refuses it or says 503; the housekeeping ticket, when there is one, is
    already held by the fill."""
    return await _backend_pack("candidates", "candidatePack", key)


def _app_pack_candidate_of(body: dict[str, Any], env: Any) -> str:
    """The candidate a write names: a field of the request, or of the candidate, row, note or entry it answers…"""
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    data = env.get("data") if isinstance(env, dict) and isinstance(env.get("data"), dict) else {}
    sources = [payload, data] + [data[k] for k in ("candidate", "row", "note", "entry")
                                 if isinstance(data.get(k), dict)]
    for src in sources:
        for name, value in src.items():
            if "candidate" not in str(name).lower():
                continue
            if isinstance(value, list) and len(value) == 1:
                value = value[0]
            key = value.strip() if isinstance(value, str) else ""
            if re.fullmatch(_APP_PACK_CANDIDATE_RE, key):
                return key
    return ""


# a referral's row id as clientCandidatePack reads it: the scraper's LEAD_<referral number>, or a hand-added row's id
_APP_PACK_LEAD_RE = r"[A-Za-z0-9_\-]{3,80}"
_APP_PACK_LEADS = "client-candidates"
# the stages a referral leaves the intake in, and the ones a hand moved it into — the intake's six (Client…
_APP_PACK_LEAD_CLOSED = frozenset({"converted", "lost", "on-hold", "closed", "ready-for-intake"})
_APP_PACK_LEAD_MOVED = frozenset({"contacted", "assessment", "intake", "isp-drafting", "discovery", "placement-review"})


def _app_pack_lead_stage(value: Any) -> str:
    """A referral's stage folded as ClientCandidates.gs folds it: 'Placement Review' -> placement-review."""
    return re.sub(r"[\s_\-]+", "-", str(value or "").strip().lower())


def _app_pack_lead_day(value: Any) -> str:
    """A referral's expiry as YYYY-MM-DD (the portal's MM/DD/YY, or ISO); '' when it names no day."""
    said = str(value or "").strip()
    iso = re.match(r"(\d{4})-(\d{2})-(\d{2})", said)
    if iso:
        return "-".join(iso.groups())
    us = re.match(r"(\d{1,2})/(\d{1,2})/(\d{4}|\d{2})(?!\d)", said)
    if not us or not 1 <= int(us.group(1)) <= 12 or not 1 <= int(us.group(2)) <= 31:
        return ""
    year = int(us.group(3))
    if year < 100:
        year += 2000 if year < 69 else 1900
    return f"{year:04d}-{int(us.group(1)):02d}-{int(us.group(2)):02d}"


def _app_pack_lead_keys() -> list[str]:
    """The referrals still in the intake, in the relay's own potentialClients slice's order: a named row never…"""
    try:
        body = json.loads((OUT_DIR / "potentialClients.json").read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001 - no slice, no warm pass; a person's read still fills its own key
        return []
    rows = body.get("rows") if isinstance(body, dict) else body
    today = time.strftime("%Y-%m-%d", time.gmtime())
    out: list[str] = []
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            continue
        key = str(row.get("id") or "").strip()
        stage = _app_pack_lead_stage(row.get("stage"))
        if (not re.fullmatch(_APP_PACK_LEAD_RE, key) or key in out or stage in _APP_PACK_LEAD_CLOSED
                or not str(row.get("client_name") or "").strip()):
            continue
        expires = _app_pack_lead_day(row.get("expiration_date"))
        if stage in _APP_PACK_LEAD_MOVED or not expires or expires >= today:
            out.append(key)
    return out[:APP_PACK_MAX_KEYS]


async def _app_pack_exec_leads(key: str) -> dict:
    """One clientCandidatePack fill: Python fills it, refuses it or says 503; the housekeeping ticket, when there is
    one, is already held by the fill."""
    return await _backend_pack("client-candidates", "clientCandidatePack", key)


def _app_pack_lead_of(body: dict[str, Any], env: Any) -> str:
    """The referral a write names: the row id of a potentialClients write (its request, or the row it answers…"""
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    data = env.get("data") if isinstance(env, dict) and isinstance(env.get("data"), dict) else {}
    sources = [payload, data] + [data[k] for k in ("row", "note", "entry", "candidate", "lead")
                                 if isinstance(data.get(k), dict)]
    for src in sources:
        for name, value in src.items():
            said = str(name).lower()
            if said not in ("id", "ids") and "candidate" not in said and "lead" not in said:
                continue
            if isinstance(value, list) and len(value) == 1:
                value = value[0]
            key = value.strip() if isinstance(value, str) else ""
            if re.fullmatch(_APP_PACK_LEAD_RE, key):
                return key
    return ""


def _app_pack_leads_of(body: dict[str, Any], env: Any) -> list[str]:
    """Every referral a write names."""
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    ids = payload.get("ids")
    if isinstance(ids, list) and len(ids) > 1:
        data = env.get("data") if isinstance(env, dict) and isinstance(env.get("data"), dict) else None
        results = data.get("results") if isinstance(data, dict) else None
        named = ([r.get("id") for r in results if isinstance(r, dict) and not r.get("unchanged") and not r.get("error")]
                 if isinstance(results, list) else ids)
        out: list[str] = []
        for value in named:
            key = value.strip() if isinstance(value, str) else ""
            if re.fullmatch(_APP_PACK_LEAD_RE, key) and key not in out:
                out.append(key)
        return out
    key = _app_pack_lead_of(body, env)
    return [key] if key else []


_APP_PACK_STAFF = "staff-profiles"
# the client keys of the accounts whose own views the warm pass keeps warm, read from the Core users copy off the…
_app_pack_client_accounts: list[str] = []
_APP_PACK_OWN_INACTIVE = frozenset({"false", "0", "no"})


def _app_pack_row_cell(row: dict[str, Any], name: str) -> str:
    """A users row's cell by its header, whatever the header's case or punctuation; '' when it has none."""
    want = _app_pack_fold_name(name)
    for head, value in row.items():
        if _app_pack_fold_name(head) == want:
            return str(value if value is not None else "").strip()
    return ""


def _app_pack_own_key(row: Any) -> str:
    """FAIL-CLOSED: the client key a users row links, for an active client-role account, not merged, that wears…"""
    if not isinstance(row, dict) or _app_pack_row_cell(row, "role").lower() != "client":
        return ""
    if _app_pack_row_cell(row, "active").lower() in _APP_PACK_OWN_INACTIVE or _app_pack_row_cell(row, "merged_into"):
        return ""
    types = _app_pack_row_cell(row, "types").upper()
    worn = {w.strip() for w in re.split(r"[,;|\n]+", types) if w.strip()} | {"CLIENT"}
    follows = globals().get("badge_follows")
    if follows is not None:
        worn = follows.with_followed(worn)
    # a cell in any other shape that names GUARDIAN at all is read as wearing it
    if "GUARDIAN" in worn or "GUARDIAN" in types:
        return ""
    key = _app_pack_row_cell(row, "client_key")
    return key if re.fullmatch(_APP_PACK_CLIENT_RE, key) else ""


def _app_pack_client_account_rows() -> list[dict[str, Any]]:
    """Blocking: the Core users copy's rows."""
    with psycopg2.connect(PG_DSN, connect_timeout=5) as conn, conn.cursor() as cur:
        cur.execute("select data from asa_drive_sheets_rows where sheet_id = %s and tab_name = 'users'",
                    (HUB_DB_SHEET_ID,))
        return [r[0] for r in cur.fetchall() if isinstance(r[0], dict)]


def _app_pack_client_accounts_refresh() -> int:
    """Blocking: the client keys of the accounts a client's own view is kept warm for (_app_pack_own_key), from…"""
    if not globals().get("PG_DSN"):
        return len(_app_pack_client_accounts)
    keys: list[str] = []
    for row in _app_pack_client_account_rows():
        key = _app_pack_own_key(row)
        if key and key not in keys:
            keys.append(key)
    _app_pack_client_accounts[:] = keys[:APP_PACK_MAX_KEYS]
    return len(_app_pack_client_accounts)


def _app_pack_staff_keys() -> list[str]:
    """The client accounts whose own view of Staff the warm pass keeps."""
    return list(_app_pack_client_accounts)


async def _app_pack_exec_staff(key: str) -> dict:
    """One staffClientPack fill, Python's; the housekeeping ticket, when there is one, is already held by the fill."""
    return await _backend_pack("staff", "staffClientPack", key, pack=_APP_PACK_STAFF, named="client")


# THE TEAM'S STAFF PACK — one staff member's whole sections (StaffProfiles.gs staffPack), asked through the Staff…
_APP_PACK_STAFF_TEAM = "staff-team"
_APP_PACK_STAFF_KEY_RE = r"[a-z0-9]{3,80}"
_APP_PACK_MASTER_PART = re.compile(r"edit_[a-z]+")
# an app's door -> the pack it reads, where the app's own view is another pack's
_APP_PACK_DOORS = {_APP_PACK_STAFF: _APP_PACK_STAFF_TEAM}
# a door of its own -> the app whose App Control row opens it, and whose screens its fills ring
_APP_PACK_GATES = {_APP_PACK_FAMILY_INDEX: _APP_PACK_FAMILIES}


def _app_pack_staff_team_keys() -> list[str]:
    """The active staff of the relay's own people slice, keyed the way the platform keys them (clientNameKey_)…"""
    clients = {_app_pack_fold_name(r.get("name")) for r in _app_pack_slice_rows("clients.json")}
    out: list[str] = []
    for row in _app_pack_slice_rows("people.json"):
        if str(row.get("status") or "").strip().lower() != "active":
            continue
        if str(row.get("role") or "").strip().lower() in ("guardian", "entity", "client"):
            continue
        name = str(row.get("name") or "").strip() or f"{row.get('first_name') or ''} {row.get('last_name') or ''}"
        key = _app_pack_fold_name(name)
        if key and key not in clients and re.fullmatch(_APP_PACK_STAFF_KEY_RE, key) and key not in out:
            out.append(key)
    return out[:APP_PACK_MAX_KEYS]


async def _app_pack_exec_staff_team(key: str) -> dict:
    """One staffPack fill: Python fills it, refuses it or says 503; the housekeeping ticket, when there is one, is
    already held by the fill."""
    return await _backend_pack("staff", "staffPack", key)


def _app_pack_staff_key_of(body: dict[str, Any], env: Any) -> str:
    """The staff member a write names: its staff, key or person (a roster name, folded), the note it answers…"""
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    data = env.get("data") if isinstance(env, dict) and isinstance(env.get("data"), dict) else {}
    note = data.get("note") if isinstance(data.get("note"), dict) else {}
    for value in (payload.get("staff"), payload.get("key"), payload.get("person"), note.get("staff_key"),
                  data.get("staff_key")):
        key = _app_pack_fold_name(value)
        if re.fullmatch(_APP_PACK_STAFF_KEY_RE, key):
            return key
    return ""


def _app_pack_master_parts_out(answer: dict[str, Any]) -> dict[str, Any]:
    """A pack as anyone but the master's own session is handed it: without the edit panels' raw values."""
    data = answer.get("data") if isinstance(answer, dict) else None
    parts = data.get("parts") if isinstance(data, dict) else None
    if not isinstance(parts, dict) or not any(_APP_PACK_MASTER_PART.fullmatch(str(p)) for p in parts):
        return answer
    status = data.get("part_status") if isinstance(data.get("part_status"), dict) else {}
    return {**answer, "data": {**data,
                               "parts": {k: v for k, v in parts.items() if not _APP_PACK_MASTER_PART.fullmatch(str(k))},
                               "part_status": {k: v for k, v in status.items()
                                               if not _APP_PACK_MASTER_PART.fullmatch(str(k))}}}


def _app_pack_parts_out(answer: dict[str, Any], names: tuple[str, ...] | frozenset[str]) -> dict[str, Any]:
    """A pack without these parts: each part, its state, and each client's own view of it."""
    data = answer.get("data") if isinstance(answer, dict) else None
    parts = data.get("parts") if isinstance(data, dict) else None
    if not isinstance(parts, dict) or not names:
        return answer
    status = data.get("part_status") if isinstance(data.get("part_status"), dict) else {}
    kept = {k: v for k, v in parts.items() if k not in names}
    views = kept.get("client_views")
    if isinstance(views, dict):
        kept["client_views"] = {c: ({k: v for k, v in view.items() if k not in names} if isinstance(view, dict)
                                    else view) for c, view in views.items()}
    said = {k: v for k, v in status.items() if k not in names}
    return {**answer, "data": {**data, "parts": kept, "part_status": said}}


def _app_pack_ssa_docs_out(answer: dict[str, Any]) -> dict[str, Any]:
    """An SSA pack without its Documents: the part, its state, and each client's own view of it."""
    return _app_pack_parts_out(answer, ("documents",))


def _app_pack_this_week() -> str:
    """This week's Monday in New York, on the relay's clock (MyFamily.gs myFamilyWeek_)."""
    from datetime import datetime, timedelta
    from zoneinfo import ZoneInfo
    day = datetime.fromtimestamp(time.time(), ZoneInfo("America/New_York")).date()
    return (day - timedelta(days=day.weekday())).isoformat()


def _app_pack_past_week(app: str, held: dict[str, Any] | None) -> bool:
    """A client's own Staff pack gathered for a week that is over: the people on it are that week's."""
    if app != _APP_PACK_STAFF or not isinstance(held, dict):
        return False
    data = held.get("data") if isinstance(held.get("data"), dict) else {}
    return str(data.get("week") or "") != _app_pack_this_week()


