# Python's alone, whatever Settings › Back-end says, and never Apps Script: a Google Form's import (app/forms_import.py)
# and a signed packet form attached (app/onboarding_packet.py) — each one's prepare read first, as the caller, then its
# write kept under its own id — and the hiring walk (app/hiring_walk.py, _hiring_walk). Python not answering, or a
# session whose master flag cannot be read, is a 503 to try again: door → (app, prepare read, the payload's bytes field)
PYTHON_TOOL_DOORS = {"formImportGoogle": (FORMS_APP, "formImportGooglePrepare", ""),
                     "packetUpload": (ONBOARDING_APP, "packetUploadPrepare", "base64"),
                     "hiringWalkRun": (HIRING_APP, "", "")}
PYTHON_TOOL_UNANSWERED = {"status": 503, "message": "This could not be done just now — nothing was saved. Try again "
                                                    "in a moment."}
# the walk's budget is this relay's own wait, under nginx's 120 s; each turn is one look and at most one press
HIRING_WALK_BUDGET_S = 100.0
HIRING_WALK_TURNS = 40


async def _python_tool_door(action: str, raw: bytes) -> Response:
    """formImportGoogle, packetUpload and hiringWalkRun answered by asa-hub-app with the session the relay verified:
    the prepare read, then the write; the walk pressed step by step (_hiring_walk)."""
    def said(env: dict[str, Any]) -> Response:
        return Response(json.dumps(env, default=str), media_type="application/json")

    if _relay_is_service(raw):
        return said({"status": 404, "message": "Unknown action."})
    env = _cert_papers_envelope(raw) if action == "packetUpload" else _relay_envelope(raw)
    if not isinstance(env, dict):
        return said({"status": 400, "message": "The request could not be read."})
    token = str(env.get("token") or "")
    actor = await _session_actor(f"Bearer {token}") if token else None
    if not actor:
        return said({"status": 401, "message": "Authentication required."})
    if any(env.get(k) for k in ("world", "tenant", "member")):
        return said(LOCATION_MEDS_AWAY)
    master, unsure = await _app_pack_master(f"Bearer {token}")
    if unsure:
        return said(PYTHON_TOOL_UNANSWERED)
    user = {"uid": str(actor[1] or ""), "role": str(actor[0] or "").strip().lower(), "is_master": bool(master)}
    sent = env.get("payload") if isinstance(env.get("payload"), dict) else {}
    # what the relay alone hands Python is never taken from the browser
    payload = {k: v for k, v in sent.items() if k not in ("prepared", "walk")}
    app_id, prepare, field = PYTHON_TOOL_DOORS[action]
    if action == "hiringWalkRun":
        _traffic_note("backend_python")
        return said(await _hiring_walk(payload, user))
    if prepare and (not field or payload.get(field)):
        got = await _backend_call(app_id, prepare, payload, user, timeout=BACKEND_PREPARE_TIMEOUT_S)
        if got is None:
            log.warning("%s: its prepare not answered by Python (%s) — said 503", action, _BACKEND_UNANSWERED.get())
            return said(PYTHON_TOOL_UNANSWERED)
        ready = got[2]
        if ready.get("status") != 200 or not isinstance(ready.get("data"), dict):
            return said({k: v for k, v in ready.items() if k in ("status", "message", "data")})
        payload = {**{k: v for k, v in payload.items() if k != field}, "prepared": ready["data"]}
        if field:
            payload[field] = "kept"
    write_id = str(env.get("write_id") or "")
    if not re.fullmatch(r"[A-Za-z0-9_.:\-]{8,80}", write_id):
        write_id = "W" + hashlib.sha256(raw[:4096] + str(time.time_ns()).encode()).hexdigest()[:24]
    got = await _backend_call(app_id, action, payload, user, extra={"write_id": write_id})
    if got is None:
        log.warning("%s: not answered by Python (%s) — said 503", action, _BACKEND_UNANSWERED.get())
        return said(PYTHON_TOOL_UNANSWERED)
    answer = got[2]
    answer.pop("_write", None)
    if answer.get("status") == 200:
        _backend_final_landed(action, raw, json.dumps(answer).encode())
    _traffic_note("backend_python")
    return said(answer)


async def _hiring_walk(opts: dict[str, Any], user: dict[str, Any]) -> dict[str, Any]:
    """HiringWalk.gs hiringWalkRun on Python: asa-hub-app checks each step's answer and names the next press
    (hiringWalkNext), each press made here through its own door as the caller (_hiring_walk_press), and the report
    raised to Smart Comms by hiringWalkRun; the walk's envelope."""
    walk: dict[str, Any] = {"budget_ms": int(HIRING_WALK_BUDGET_S * 1000)}
    data: dict[str, Any] = {}
    for _ in range(HIRING_WALK_TURNS):
        got = await _backend_call(HIRING_APP, "hiringWalkNext", {**opts, "walk": walk}, user,
                                  timeout=HUB_APP_PACK_TIMEOUT_S)
        if got is None:
            log.warning("hiring walk: not answered by Python (%s) — said 503", _BACKEND_UNANSWERED.get())
            return dict(PYTHON_TOOL_UNANSWERED)
        env = got[2]
        data = env.get("data") if env.get("status") == 200 and isinstance(env.get("data"), dict) else {}
        if not isinstance(data.get("walk"), dict):
            return {k: v for k, v in env.items() if k in ("status", "message", "data")}
        walk = data["walk"]
        if not isinstance(data.get("press"), dict):
            break
        walk["last"] = await _hiring_walk_press(data["press"], user)
    else:
        return dict(PYTHON_TOOL_UNANSWERED)
    out = data.get("out") if isinstance(data.get("out"), dict) else {}
    if data.get("report") is not True:
        return {"status": 200, "data": out}
    write_id = "W" + hashlib.sha256(f"hiringWalkRun|{time.time_ns()}".encode()).hexdigest()[:24]
    got = await _backend_call(HIRING_APP, "hiringWalkRun", {**opts, "prepared": out}, user,
                              extra={"write_id": write_id})
    told = dict(got[2]) if got is not None else {}
    told.pop("_write", None)
    if told.get("status") != 200:
        # the walk stands as it ran; its report did not leave
        log.warning("hiring walk: the report was not raised (%s)",
                    str(told.get("message") or _BACKEND_UNANSWERED.get())[:160])
        return {"status": 200, "data": {**out, "reported_to": ""}}
    return told


async def _hiring_walk_press(press: dict[str, Any], user: dict[str, Any]) -> dict[str, Any]:
    """One step of the walk pressed through its own Python door as the caller, its prepare read first: what the door
    answered ({status, message, data}), else why nothing answered (error), and how long it took (ms)."""
    action = str(press.get("action") or "")
    payload = press.get("payload") if isinstance(press.get("payload"), dict) else {}
    started = time.monotonic()

    def took(env: dict[str, Any]) -> dict[str, Any]:
        return {**env, "ms": int((time.monotonic() - started) * 1000)}

    read = action in BACKEND_APPS[HIRING_APP]["reads"]
    try:
        if read:
            got = await _backend_call(HIRING_APP, action, payload, user, timeout=BACKEND_PREPARE_TIMEOUT_S)
        else:
            prepare = BACKEND_WRITE_PREPARE.get(action)
            if prepare is not None and (not prepare[1] or payload.get(prepare[1])):
                got = await _backend_call(HIRING_APP, prepare[0], payload, user, timeout=BACKEND_PREPARE_TIMEOUT_S)
                ready = got[2] if got is not None else None
                if ready is None:
                    return took({"error": f"its preparation was not done ({_BACKEND_UNANSWERED.get() or 'unsaid'})"})
                if ready.get("status") != 200 or not isinstance(ready.get("data"), dict):
                    return took({k: ready.get(k) for k in ("status", "message", "data")})
                payload = {**{k: v for k, v in payload.items() if k != prepare[1]}, "prepared": ready["data"]}
            write_id = "W" + hashlib.sha256(f"walk|{action}|{time.time_ns()}".encode()).hexdigest()[:24]
            got = await _backend_call(HIRING_APP, action, payload, user, extra={"write_id": write_id},
                                      timeout=HUB_APP_PACK_TIMEOUT_S)
        if got is None:
            return took({"error": f"Python did not answer ({_BACKEND_UNANSWERED.get() or 'unsaid'})"})
        env = dict(got[2])
        env.pop("_write", None)
        if env.get("status") == 200 and not read:
            asked = urllib.parse.urlencode({"body": json.dumps({"action": action, "payload": press.get("payload")})})
            _backend_final_landed(action, asked.encode(), json.dumps(env).encode())
        return took({k: env.get(k) for k in ("status", "message", "data")})
    except Exception as exc:  # noqa: BLE001 - said as this step's own failure
        return took({"error": type(exc).__name__})


# The MARS papers the relay's lane finds and reads (mar_papers.py) and their OCR text live only in asa-hub-db: Apps
# Script holds neither, so neither the switch, nor a restart's settle window, nor an unsure master flag hands them there
MAR_PAPERS_ACTIONS = frozenset({"clientSourceMar", "clientSourceMarDocFile"})
MAR_PAPERS_APP = "clients"


async def _mar_papers(action: str, raw: bytes) -> Response:
    """A client's MARS papers, and one paper's bytes or kept OCR text, answered by asa-hub-app with the session the
    relay verified; never Apps Script."""
    def said(env: dict[str, Any]) -> Response:
        return Response(json.dumps(env), media_type="application/json")

    env = _relay_envelope(raw)
    if not isinstance(env, dict):
        return said({"status": 400, "message": "The request could not be read."})
    token = str(env.get("token") or "")
    actor = await _session_actor(f"Bearer {token}") if token else None
    if not actor:
        return said({"status": 401, "message": "Authentication required."})
    # a visit, a world or a place away from home reads another account's rows: never answered as this session's own
    if any(env.get(k) for k in ("world", "tenant", "member")):
        return said(LOCATION_MEDS_AWAY)
    master, unsure = await _app_pack_master(f"Bearer {token}")
    payload = env.get("payload") if isinstance(env.get("payload"), dict) else {}
    # an unknown master flag reads as not the master: the Clients door then decides on the account's own reach
    user = {"uid": str(actor[1] or ""), "role": str(actor[0] or "").strip().lower(),
            "is_master": bool(master) and not unsure}
    # nobody else answers these, so Python is waited for as long as a pack: a cold or busy read ran 9–12 s
    got = await _backend_call(MAR_PAPERS_APP, action, payload, user, timeout=HUB_APP_PACK_TIMEOUT_S)
    if got is None:
        log.warning("mar papers: %s not answered by Python — said 503, never handed to Apps Script", action)
        return said(LOCATION_MEDS_UNREAD)
    answer = got[2]
    answer.pop("_write", None)
    _traffic_note("backend_python")
    return said(answer)


