    token = str(env.get("token") or "")
    actor = await _session_actor(f"Bearer {token}") if token else None
    if not actor:
        return said({"status": 401, "message": "Authentication required."})
    # a visit, a world or a place away from home reads another account's rows: never answered as this session's own
    if any(env.get(k) for k in ("world", "tenant", "member")):
        return said(LOCATION_MEDS_AWAY)
    master, unsure = await _app_pack_master(f"Bearer {token}")
    payload = env.get("payload") if isinstance(env.get("payload"), dict) else {}
