# Settings › Back-end per app › My Profile: asa-hub-app builds the profile off asa-hub-db for the scope decided here
MY_PROFILE_APP = "my-profile"
MY_PROFILE_PYTHON_READ = "myProfileView"
# past this the relay's own builder answers
MY_PROFILE_PYTHON_TIMEOUT_S = min(60.0, max(HUB_APP_TIMEOUT_S, float(os.getenv("HUB_MY_PROFILE_TIMEOUT_S", "15"))))
_MY_PROFILE_KEYS = ("scope", "person", "details", "requirements", "read_at")


async def _my_profile_python(session: tuple[str, str], scope: dict[str, str], person: str,
                             client: str) -> dict[str, Any] | None:
    """The profile as asa-hub-app builds it for the scope and subject decided here; None: the relay's own builder."""
    try:
        # an App Control change the copy may not hold yet stays the relay's to answer
        if not await _backend_wanted(MY_PROFILE_APP) or _backend_settling():
            return None
    except Exception:  # noqa: BLE001 - FAIL-SAFE: the relay's own builder
        return None
    mass = scope["mode"] == my_work.MODE_MASS
    payload: dict[str, Any] = {"mode": scope["mode"], "why": scope["why"], "person": person, "client": client}
    user = {"uid": str(session[1] or ""), "role": str(session[0] or "").strip().lower(), "is_master": mass}
    got = await _backend_call(MY_PROFILE_APP, MY_PROFILE_PYTHON_READ, payload, user,
                              timeout=MY_PROFILE_PYTHON_TIMEOUT_S)
    if got is None:
        return None
    env = got[2]
    data = env.get("data") if env.get("status") == 200 else None
    said = data.get("scope") if isinstance(data, dict) else None
    whose = data.get("person") if isinstance(data, dict) else None
    # own: the caller's own profile alone; mass: exactly the person or client the master chose
    if (not isinstance(said, dict) or not isinstance(whose, dict) or any(k not in data for k in _MY_PROFILE_KEYS)
            or said.get("mode") != scope["mode"] or said.get("person") != (person if mass else "")
            or (mass and said.get("client") != ("" if person else client))
            or (not mass and whose.get("own") is not True)):
        log.warning("my profile: Python's answer did not keep the relay's scope or shape — the relay's builder answers")
        return None
    _traffic_note("backend_python")
    return data


@app.get("/hub-lanes/my-profile")
async def lane_my_profile(response: Response, member: str = "", person: str = "", client: str = "",
                         authorization: str = Header(default="")) -> Any:
    """One person's details and requirements — whose, decided here, never by the screen; past the gate, this…"""
    response.headers["Cache-Control"] = "no-store"
    kept = globals().get("_lane_kept")
    # the profile is the SESSION's account, never a visit: answering one would draw the visitor's record
    if str(member or "").strip():
        return {"status": 403, "reason": "visit", "message": _MY_PROFILE_VISIT}
    if my_profile is None or my_work is None or not PG_DSN:
        return dict(_MY_PROFILE_DOWN)
    unsure = await _my_work_learn_master(authorization)
    # no admin floor: a flag the check could not learn is judged as not the master
    actor = await _hotline_actor(authorization, app_id="my-profile", refuse_roles=_MY_PROFILE_ROLES_REFUSED,
                                 app_label="My Profile", floor=False)
    if isinstance(actor, dict):
        if unsure:
            # FAIL-CLOSED: the refusal may be only the unknown flag, so it is said as that, never as a badge
            return {"status": 503, "reason": "unavailable",
                    "message": f"My Profile could not open: the master check could not be made ({unsure}). Try again."}
        return _daily_refusal(actor)
    scope = _my_profile_scope(authorization, actor, unsure)
    person = str(person or "").strip()
    client = str(client or "").strip()
    if (person or client) and scope["mode"] != my_work.MODE_MASS:
        return {"status": 403, "reason": "scope", "message": _MY_PROFILE_OWN_ONLY}
    if person and client:
        return {"status": 400, "reason": "person", "message": "Choose a person or a client, not both."}
    if person and not my_profile.PERSON_RE.fullmatch(person):
        return {"status": 400, "reason": "person", "message": "That person cannot be read."}
    if client and not my_profile.CLIENT_RE.fullmatch(client):
        return {"status": 400, "reason": "person", "message": "That client cannot be read."}
    role = str(actor[0] or "").strip().lower()

    async def build():  # noqa: ANN202 - lifted by name into the doors' tests, where no annotation is in scope
        # on Python (Settings › Back-end per app) asa-hub-app builds it for this scope; any failure: the builder below
        python = globals().get("_my_profile_python")
        data = await python(actor, scope, person, client) if python is not None else None
        if data is not None:
            return {"status": 200, "data": data}
        if role == "client" and scope["mode"] != my_work.MODE_MASS:
            # the client is found on the server from the account's own row; no roster identity is drawn
            me, uid = {}, str(actor[1] or "")
        else:
            got = await _requests_viewer(authorization)
            if isinstance(got, dict):
                return {**got, "reason": got.get("reason") or "unreadable"}
            who, session = got
            uid = session[1]
            try:
                me = await asyncio.to_thread(my_work.identity, PG_DSN, HUB_DB_SHEET_ID, uid,
                                             roster_name=str(who.get("name") or ""))
            except Exception as exc:  # noqa: BLE001 - FAIL-CLOSED: nobody's profile is drawn for an unread account
                log.warning("my profile: the account row could not be read (%s)", type(exc).__name__)
                return {"status": 502, "reason": "unreadable",
                        "message": f"Who you are could not be read ({type(exc).__name__}), so nothing is shown."}
        try:
            data = await asyncio.to_thread(my_profile.profile, PG_DSN, HUB_DB_SHEET_ID, mode=scope["mode"], me=me,
                                           uid=uid, person=person, client=client, role=role,
                                           scope_why=scope["why"], clients=_my_profile_clients,
                                           fresh_s=MIRROR_TRUST_MAX_S)
        except my_profile.NoSuchPerson as exc:
            return {"status": 404, "reason": "person", "message": str(exc)}
        except Exception as exc:  # noqa: BLE001
            log.warning("my profile: the profile failed (%s)", type(exc).__name__)
            return {"status": 503, "reason": "unreadable",
                    "message": f"My Profile could not be put together ({type(exc).__name__})."}
        return {"status": 200, "data": data}

    return await (build() if kept is None else kept("lane:my-profile", authorization,
                                                    {"person": person, "client": client}, scope["mode"], actor, build))


# -------------------------------------------------------------------------- MY CALENDAR (server/my_calendar.py)…
_MY_CALENDAR_DOWN = {"status": 503, "reason": "unreadable",
                     "message": "My Calendar is not available on this server right now."}
# a client-role account (a client or a guardian) is forwarded, not refused; no account has the role `guardian`
_MY_CALENDAR_ROLES_REFUSED = ("onboarding", "interviewer")
_MY_CALENDAR_NO_REQUESTS = {"status": 403, "reason": "restricted",
                            "message": "Time off requests are the staff's; this account files none."}
_MY_CALENDAR_VISIT = "My Calendar reads the signed-in account's own record; it is not drawn inside a visit."
_MY_CALENDAR_OWN_ONLY = "My Calendar shows only your own calendar."
_MY_CALENDAR_DAY = r"\d{4}-\d{2}-\d{2}"
# how long a read waits on the sign-in check it joined; a check still running answers the next read
_MY_CALENDAR_SESSION_WAIT_S = 20.0


def _my_calendar_scope(authorization: str, actor: tuple[str, str], unsure: str = "") -> dict[str, str]:
    """{mode, why}. `mass` only for the master's own session; an unknown flag is `own`, and says why."""
    token = _hotline_token(authorization)
    acting = _my_work_acting(token)
    role = str(actor[0] or "").strip().lower()
    flag = _auth_master.get(token)
    if not (flag is None and role == "admin" and not acting):
        unsure = ""
    elif not unsure:
        unsure = "the sign-in check was not made"
    mode = my_work.scope_verdict(role, flag, acting)
    if mode == my_work.MODE_MASS:
        why = ("Signed in as the master account: your own calendar, or any person's you choose; a request you add "
               "there is filed for them, by you.")
    elif unsure:
        why = f"The master check could not be made ({unsure}), so only your own calendar is shown."
    else:
        # an acting session is told exactly what the person is told
        why = ""
    return {"mode": mode, "why": why}


async def _my_calendar_session(authorization: str) -> str:
    """'' once the gate can judge this session; else why the sign-in check could not be made."""
    token = _hotline_token(authorization)
    if not token:
        return ""

    def held() -> tuple[float, bool, str, str] | None:
        got = _auth_cache.get(token)
        return got if got and time.time() - got[0] < AUTH_TTL_SECONDS else None

    hit = held()
    if hit is None:
        verdict = await asyncio.to_thread(_session_verdict, token)
        if verdict is not None:
            _auth_cache_put(token, *verdict)
            return ""
        # a check already running may have answered meanwhile
        hit = held()
    if hit is None:
        if token not in _auth_pending and len(_auth_pending) < 256:
            _auth_pending.add(token)
            _auth_tasks[token] = asyncio.create_task(_validate(token))
        task = _auth_tasks.get(token)
        if task is None:
            return "too many sign-in checks are waiting"
        try:
            await asyncio.wait_for(asyncio.shield(task), timeout=_MY_CALENDAR_SESSION_WAIT_S)
        except Exception:  # noqa: BLE001 - judged below by what the check left
            pass
        hit = held()
        if hit is None:
            return "it did not answer in time"
    # the brief refusal a check leaves when the backend could not answer is no verdict
    if not hit[1] and _auth_unsure.get(token) == hit[0]:
        return "the backend could not answer"
    return ""


async def _my_calendar_gate(authorization: str, member: str, person: str
                            ) -> tuple[dict[str, str], tuple[str, str]] | dict[str, Any]:
    """(scope, actor) for a session My Calendar serves, or the refusal: a visit before anything, then the…"""
    # the calendar is the SESSION's account, never a visit: answering one would draw the visitor's week
    if str(member or "").strip():
        return {"status": 403, "reason": "visit", "message": _MY_CALENDAR_VISIT}
    if my_calendar is None or my_work is None or my_profile is None or time_off is None or not PG_DSN:
        return dict(_MY_CALENDAR_DOWN)
    unchecked = await _my_calendar_session(authorization)
    if unchecked:
        return {"status": 503, "reason": "unavailable",
                "message": f"My Calendar could not open: the sign-in check could not be made ({unchecked}). Try again."}
    unsure = await _my_work_learn_master(authorization)
    # no admin floor: a flag the check could not learn is judged as not the master
    actor = await _hotline_actor(authorization, app_id="my-calendar", refuse_roles=_MY_CALENDAR_ROLES_REFUSED,
                                 app_label="My Calendar", floor=False)
    if isinstance(actor, dict):
        if unsure:
            # FAIL-CLOSED: the refusal may be only the unknown flag, so it is said as that, never as a badge
            return {"status": 503, "reason": "unavailable",
                    "message": f"My Calendar could not open: the master check could not be made ({unsure}). "
                               f"Try again."}
        return _daily_refusal(actor)
    scope = _my_calendar_scope(authorization, actor, unsure)
    # another person's calendar outside the master's scope: only My Calendar's edition opens it, on Python
    on_python = globals().get("_my_calendar_on")
    if person and scope["mode"] != my_work.MODE_MASS and (_my_family_session(actor) or on_python is None
                                                          or not await on_python()):
        return {"status": 403, "reason": "scope", "message": _MY_CALENDAR_OWN_ONLY}
    if person and not my_profile.PERSON_RE.fullmatch(person):
        return {"status": 400, "reason": "person", "message": "That person cannot be read."}
    return scope, actor


async def _my_calendar_who(authorization: str
                           ) -> tuple[dict[str, Any], tuple[str, str], dict[str, Any]] | dict[str, Any]:
    """(who, session, me): the calendars' viewer, and the account's own keys read STRICTLY."""
    got = await _requests_viewer(authorization)
    if isinstance(got, dict):
        return {**got, "reason": got.get("reason") or "unreadable"}
    who, session = got
    try:
        me = await asyncio.to_thread(my_work.identity, PG_DSN, HUB_DB_SHEET_ID, session[1],
                                     roster_name=str(who.get("name") or ""))
    except Exception as exc:  # noqa: BLE001 - FAIL-CLOSED: nobody's calendar is drawn for an unread account
        log.warning("my calendar: the account row could not be read (%s)", type(exc).__name__)
        return {"status": 502, "reason": "unreadable",
                "message": f"Who you are could not be read ({type(exc).__name__}), so nothing is shown."}
    return who, session, me


async def _my_calendar_time_off_open(authorization: str, who: dict[str, Any]) -> dict[str, Any]:
    """{open, why}: whether the Time Off doors this screen files through would take this session — their own gate…"""
    gate = await _time_off_gate(authorization, _TIME_OFF_FILERS, floor=False)
    if isinstance(gate, dict):
        return {"open": False, "why": str(gate.get("message") or "Time Off is not open to you.")}
    if time_off.refused_reader(who):
        return {"open": False, "why": "Time Off is the staff's screen."}
    return {"open": True, "why": ""}


# Settings › Back-end per app › My Calendar: asa-hub-app builds the week off asa-hub-db for the scope decided here
MY_CALENDAR_APP = "my-calendar"
MY_CALENDAR_PYTHON_READ = "myCalendarView"
MY_CALENDAR_PYTHON_CHECK = "myCalendarCheck"
# on: the relay hands its state tables in with each call (no grant); off: asa-hub-app reads HUB_RELAY_RO_DSN or defers
MY_CALENDAR_SEND_STATE = os.getenv("HUB_MY_CALENDAR_SEND_STATE", "").strip().lower() in ("1", "yes", "on", "true")
# past this the relay's own builder answers
MY_CALENDAR_PYTHON_TIMEOUT_S = min(60.0, max(HUB_APP_TIMEOUT_S,
                                             float(os.getenv("HUB_MY_CALENDAR_TIMEOUT_S", "15"))))
_MY_CALENDAR_KEYS = ("scope", "person", "today", "week", "requests", "form", "test_mode", "read_at")
_MY_CALENDAR_CHECK_KEYS = ("ref", "start", "end", "days", "dates", "ok", "refusals")
# the edition (app/editions.py) that opens any person's calendar to a session outside the master's scope
_MY_CALENDAR_EDITIONS = frozenset({"myCalendar.anyone"})
# Python's own word on an edition's ask: a refusal, or a person or a ref it cannot read
_MY_CALENDAR_EDITION_REFUSALS = (400, 403, 404)
_MY_CALENDAR_UNCHECKED = {"status": 503, "reason": "unavailable",
                          "message": "Whether you may open another person's calendar could not be checked just now. "
                                     "Try again."}


async def _my_calendar_on() -> bool:
    """My Calendar runs on Python here and App Control is not settling; anything unknown is the relay's builder."""
    try:
        return await _backend_wanted(MY_CALENDAR_APP) and not _backend_settling()
    except Exception:  # noqa: BLE001 - FAIL-SAFE: the relay's own builder
        return False


def _my_calendar_published() -> list[dict[str, Any]]:
    """Blocking, read-only: every house's cells just published or held by test mode (the estate lays them, the week
    marks them; an unflagged cell does neither), each stamp as ISO text."""
    from datetime import date, datetime
    conn = psycopg2.connect(PG_DSN, connect_timeout=5)
    try:
        conn.set_session(readonly=True, autocommit=True)
        with conn.cursor() as cur:
            rows = [r for r in effective_roster.published(cur) if r.get("pending") or r.get("test_mode")]
    finally:
        conn.close()
    return [{k: (v.isoformat() if isinstance(v, (date, datetime)) else v) for k, v in r.items()} for r in rows]


# the cells as last read, held a few seconds (the builder's own estate is held ESTATE_TTL_S)
_MY_CALENDAR_PUBLISHED_HELD: dict[str, Any] = {"at": 0.0, "rows": None}
MY_CALENDAR_PUBLISHED_HOLD_S = 5.0


async def _my_calendar_handed() -> dict[str, Any]:
    """What the relay hands Python with each read: its test mode switch, and the published cells its own edits table
    holds, which asa-hub-app is not granted."""
    out: dict[str, Any] = {"test_mode": effective_roster.test_mode_said()}
    held = _MY_CALENDAR_PUBLISHED_HELD
    if held["rows"] is not None and time.time() - float(held["at"]) < MY_CALENDAR_PUBLISHED_HOLD_S:
        out["published"] = held["rows"]
        return out
    try:
        rows = await asyncio.to_thread(_my_calendar_published)
        held.update(at=time.time(), rows=rows)
        out["published"] = rows
    except Exception as exc:  # noqa: BLE001 - Python reads none, defers, and the relay's builder answers
        log.info("my calendar: the published cells were not handed to Python (%s)", type(exc).__name__)
    return out


async def _my_calendar_python(session: tuple[str, str], scope: dict[str, str], action: str,
                              ask: dict[str, Any]) -> dict[str, Any] | None:
    """asa-hub-app's envelope for the scope and subject decided here; None: the relay's own builder answers."""
    if not await _my_calendar_on():
        return None
    mass = scope["mode"] == my_work.MODE_MASS
    person = str(ask.get("person") or "")
    # a person outside the master's scope: the edition Python alone holds decides, never this relay
    edition = bool(person) and not mass
    payload: dict[str, Any] = {"mode": scope["mode"], "why": scope["why"], **ask}
    if MY_CALENDAR_SEND_STATE:
        try:
            payload["relay_state"] = await asyncio.to_thread(_my_work_state_read)
        except Exception as exc:  # noqa: BLE001 - asa-hub-app reads them itself, or defers
            log.info("my calendar: the state tables were not handed to Python (%s)", type(exc).__name__)
    user = {"uid": str(session[1] or ""), "role": str(session[0] or "").strip().lower(), "is_master": mass}
    got = await _backend_call(MY_CALENDAR_APP, action, payload, user, timeout=MY_CALENDAR_PYTHON_TIMEOUT_S)
    if got is None:
        return None
    env = got[2]
    if env.get("status") != 200:
        if edition and env.get("status") in _MY_CALENDAR_EDITION_REFUSALS:
            return {k: env[k] for k in ("status", "reason", "message") if k in env}
        return None
    data = env.get("data")
    if not isinstance(data, dict):
        data = None
    elif action == MY_CALENDAR_PYTHON_CHECK:
        if any(k not in data for k in _MY_CALENDAR_CHECK_KEYS) or data.get("ref") != ask.get("ref"):
            data = None
    else:
        said, whose = data.get("scope"), data.get("person")
        said = said if isinstance(said, dict) else {}
        # an edition's holder is answered as Python widened the scope: any person, said under the edition
        widened = (not mass and said.get("mode") == my_work.MODE_MASS
                   and str(said.get("edition") or "") in _MY_CALENDAR_EDITIONS)
        # own: the caller's own week alone; mass: exactly the person the master chose; widened: the person asked
        if (not said or not isinstance(whose, dict) or any(k not in data for k in _MY_CALENDAR_KEYS)
                or (said.get("mode") != scope["mode"] and not widened)
                or said.get("person") != (person if mass or widened else "")
                or (not mass and not widened and whose.get("own") is not True)
                or (edition and not widened)):
            data = None
    if data is None:
        log.warning("my calendar: Python's answer did not keep the relay's scope or shape — the relay answers")
        return None
    _traffic_note("backend_python")
    return {"status": 200, "data": data}


@app.get("/hub-lanes/my-calendar")
async def lane_my_calendar(response: Response, member: str = "", person: str = "", week: str = "",
                          authorization: str = Header(default="")) -> Any:
    """One person's week of shifts and their own time off requests — whose, decided here, never by the screen…"""
    response.headers["Cache-Control"] = "no-store"
    kept = globals().get("_lane_kept")
    person = str(person or "").strip()
    got = await _my_calendar_gate(authorization, member, person)
    if isinstance(got, dict):
        return got
    scope, _actor = got
    if _my_family_session(_actor):
        week = str(week or "").strip()
        if week and not re.fullmatch(_MY_CALENDAR_DAY, week):
            return {"status": 400, "reason": "week", "message": "A week is asked for by a day written YYYY-MM-DD."}
        # returned before any staff source is read: none of them is computed for a client-role session
        def forward():  # noqa: ANN202
            return _my_family_forward(authorization, "calendar", week)
        return await (forward() if kept is None else kept("lane:my-calendar", authorization,
                                                          {"person": person, "week": week}, scope["mode"], _actor,
                                                          forward))
    on = my_calendar.today()
    try:
        mon = my_calendar.parse_week(week, on)
    except my_calendar.BadWeek as exc:
        return {"status": 400, "reason": "week", "message": str(exc)}
    # past the gate, a person outside the master's scope is an edition's ask: Python alone answers it
    edition = bool(person) and scope["mode"] != my_work.MODE_MASS

    async def build():  # noqa: ANN202 - lifted by name into the doors' tests, where no annotation is in scope
        # on Python (Settings › Back-end per app) asa-hub-app builds it for this scope; any failure: the builder below
        python = globals().get("_my_calendar_python")
        if python is not None and await _my_calendar_on():
            ask: dict[str, Any] = {"person": person, "week": mon.isoformat(), "today": on.isoformat(),
                                   **await _my_calendar_handed()}
            # the filing doors' gate as this relay judges it; Python adds whether the reader is staff
            gate = await _time_off_gate(authorization, _TIME_OFF_FILERS, floor=False)
            ask["time_off_open"] = ({"open": False, "why": str(gate.get("message") or "Time Off is not open to you.")}
                                    if isinstance(gate, dict) else {"open": True, "why": ""})
            env = await python(_actor, scope, MY_CALENDAR_PYTHON_READ, ask)
            if env is not None:
                return env
        if edition:
            return dict(_MY_CALENDAR_UNCHECKED)
        got = await _my_calendar_who(authorization)
        if isinstance(got, dict):
            return got
        who, _session, me = got
        time_off_open = await _my_calendar_time_off_open(authorization, who)
        try:
            data = await asyncio.to_thread(my_calendar.answer, PG_DSN, HUB_DB_SHEET_ID, mode=scope["mode"], me=me,
                                           who=who, person=person, week=mon, on=on, scope_why=scope["why"],
                                           time_off_open=time_off_open)
        except my_profile.NoSuchPerson as exc:
            return {"status": 404, "reason": "person", "message": str(exc)}
        except Exception as exc:  # noqa: BLE001
            log.warning("my calendar: the calendar failed (%s)", type(exc).__name__)
            return {"status": 503, "reason": "unreadable",
                    "message": f"My Calendar could not be put together ({type(exc).__name__})."}
        return {"status": 200, "data": data}

    # an edition's ask is never kept: a key turned off or a person taken off its list closes it at once
    return await (build() if kept is None or edition else kept("lane:my-calendar", authorization,
                                                               {"person": person, "week": week}, scope["mode"],
                                                               _actor, build))


@app.get("/hub-lanes/my-calendar/check")
async def lane_my_calendar_check(response: Response, member: str = "", person: str = "", ref: str = "",
                                start: str = "", end: str = "",
                                authorization: str = Header(default="")) -> dict[str, Any]:
    """Would new dates for one of the reader's requests file?"""
    response.headers["Cache-Control"] = "no-store"
    person = str(person or "").strip()
    got = await _my_calendar_gate(authorization, member, person)
    if isinstance(got, dict):
        return got
    scope, _actor = got
    if _my_family_session(_actor):
        return dict(_MY_CALENDAR_NO_REQUESTS)
    ref = str(ref or "").strip().upper()
    if not time_off.REF_RE.fullmatch(ref):
        return {"status": 400, "reason": "request", "message": "ref is required (TO…)"}
    # no reason is taken here: a query string is written to access logs
    start, end = str(start or "").strip(), str(end or "").strip()
    if any(d and not re.fullmatch(_MY_CALENDAR_DAY, d) for d in (start, end)):
        return {"status": 400, "reason": "dates", "message": "A day is written YYYY-MM-DD."}
    # on Python asa-hub-app checks it for this scope; a person outside the master's scope is Python's alone
    python = globals().get("_my_calendar_python")
    if python is not None and await _my_calendar_on():
        env = await python(_actor, scope, MY_CALENDAR_PYTHON_CHECK,
                           {"person": person, "ref": ref, "start": start, "end": end,
                            "today": my_calendar.today().isoformat(), **await _my_calendar_handed()})
        if env is not None:
            return env
    if person and scope["mode"] != my_work.MODE_MASS:
        return dict(_MY_CALENDAR_UNCHECKED)
    got = await _my_calendar_who(authorization)
    if isinstance(got, dict):
        return got
    who, _session, me = got
    try:
        data = await asyncio.to_thread(my_calendar.check, PG_DSN, who, ref, start, end, keys=me.get("keys") or [],
                                       person=person, mode=scope["mode"], core_sheet_id=HUB_DB_SHEET_ID)
    except Exception as exc:  # noqa: BLE001
        if isinstance(exc, my_profile.NoSuchPerson):
            return {"status": 404, "reason": "person", "message": str(exc)}
        if isinstance(exc, time_off.Unreadable):
            return {"status": 503, "reason": "unreadable", "message": f"{exc} — the new dates were not checked."}
        log.warning("my calendar: the check failed (%s)", type(exc).__name__)
        return {"status": 503, "reason": "unreadable",
                "message": f"The new dates could not be checked ({type(exc).__name__})."}
    return {"status": 200, "data": data}


# -------------------------------------------------------------------------- MY INBOX (server/my_inbox.py): App…
_MY_INBOX_DOWN = {"status": 503, "reason": "unreadable",
                  "message": "My Inbox is not available on this server right now."}
# a client-role account (a client or a guardian) is forwarded, not refused; no account has the role `guardian`
_MY_INBOX_ROLES_REFUSED = ("onboarding", "interviewer")
_MY_INBOX_LANES = ("supportQueue", "callOffs", "uiIncidents")
_MY_INBOX_VISIT = "My Inbox reads the signed-in account's own alerts; it is not drawn inside a visit."
_MY_INBOX_OWN_ONLY = "My Inbox shows only your own alerts."
_MY_INBOX_ACTING = {"status": 409, "code": "be_another_refused", "reason": "acting",
                    "message": "Not in a switched session: read marks are not kept. "
                               "Press Be Back to do this as yourself."}
# under the proxy's 30-second read timeout on /hub-lanes/, counted from the request's arrival: past it the browser…
_MY_INBOX_BUDGET_S = 24.0
# a client-role account's last backend answer, by account: served at once while fresh, and while a newer one is read…
_MY_INBOX_FAMILY_HELD: dict[str, tuple[float, dict[str, Any]]] = {}
_MY_INBOX_FAMILY_ASKING: dict[str, asyncio.Task] = {}
_MY_INBOX_FAMILY_FRESH_S = 300.0
_MY_INBOX_FAMILY_CEILING_S = 1800.0
_MY_INBOX_FAMILY_HELD_MAX = 500
_MY_INBOX_FAMILY_REFUSED = (400, 401, 403, 404)
_MY_INBOX_FAMILY_SLOW = "the backend is still reading this account's alerts; they are listed on the next read"


def _my_inbox_scope(authorization: str, actor: tuple[str, str], unsure: str = "") -> dict[str, str]:
    """{mode, why}. `mass` only for the master's own session; an unknown flag is `own`, and says why."""
    token = _hotline_token(authorization)
    acting = _my_work_acting(token)
    role = str(actor[0] or "").strip().lower()
    flag = _auth_master.get(token)
    if not (flag is None and role == "admin" and not acting):
        unsure = ""
    elif not unsure:
        unsure = "the sign-in check was not made"
    mode = my_work.scope_verdict(role, flag, acting)
    if mode == my_work.MODE_MASS:
        why = "Signed in as the master account: your own alerts, or any person's you choose, read-only."
    elif unsure:
        why = f"The master check could not be made ({unsure}), so only your own alerts are shown."
    else:
        # an acting session is told exactly what the person is told
        why = ""
    return {"mode": mode, "why": why}


async def _my_inbox_gate(authorization: str, member: str
                         ) -> tuple[dict[str, str], tuple[str, str]] | dict[str, Any]:
    """(scope, actor) for a session My Inbox serves, or the refusal: a visit before anything, then the session…"""
    # the inbox is the SESSION's account, never a visit: answering one would draw the visitor's alerts
    if str(member or "").strip():
        return {"status": 403, "reason": "visit", "message": _MY_INBOX_VISIT}
    if my_inbox is None or my_work is None or not PG_DSN:
        return dict(_MY_INBOX_DOWN)
    # My Calendar's session check: a switched session's verdict leaves memory minutes after the backend last spoke…
    unchecked = await _my_calendar_session(authorization)
    if unchecked:
        return {"status": 503, "reason": "unavailable",
                "message": f"My Inbox could not open: the sign-in check could not be made ({unchecked}). Try again."}
    unsure = await _my_work_learn_master(authorization)
    # no admin floor: a flag the check could not learn is judged as not the master
    actor = await _hotline_actor(authorization, app_id="my-inbox", refuse_roles=_MY_INBOX_ROLES_REFUSED,
                                 app_label="My Inbox", floor=False)
    if isinstance(actor, dict):
        if unsure:
            # FAIL-CLOSED: the refusal may be only the unknown flag, so it is said as that, never as a badge
            return {"status": 503, "reason": "unavailable",
                    "message": f"My Inbox could not open: the master check could not be made ({unsure}). Try again."}
        return _daily_refusal(actor)
    return _my_inbox_scope(authorization, actor, unsure), actor


async def _my_inbox_access(uid: str, role: str, is_master: bool,
                           extra: list[str] | tuple[str, ...] = (),
                           base: tuple[str, ...] | None = None) -> dict[str, dict[str, Any]]:
    """{app: {open, why}} for every app a source is judged by (`base`, the staff sources' by default), and the…"""
    apps = tuple(dict.fromkeys((*(my_inbox.APPS if base is None else base), *extra)))
    if hotline_desk is None:
        return {a: {"open": False, "why": "The access checks are not loaded on this server."} for a in apps}

    async def one(app_id: str) -> dict[str, Any]:
        try:
            verdict = await hotline_desk.run_gate(hotline_desk.app_access, PG_DSN, HUB_DB_SHEET_ID, uid, role,
                                                  app_id, MIRROR_TRUST_MAX_S, is_master=is_master)
        except Exception as exc:  # noqa: BLE001 - FAIL-CLOSED: a check that throws stays shut
            log.warning("my inbox: an access check failed (%s)", type(exc).__name__)
            return {"open": False, "why": f"The access check failed ({type(exc).__name__})."}
        return {"open": verdict.get("open") is True, "why": str(verdict.get("why") or "")}

    got = await asyncio.gather(*(one(a) for a in apps))
    return dict(zip(apps, got))


async def _my_inbox_family_fill(authorization: str, uid: str) -> dict[str, Any]:
    """The backend's myFamily inbox answer for this account: held on a 200, and a refusal lets the held one go."""
    env = await _my_family_forward(authorization, "inbox")
    status = env.get("status")
    if status == 200:
        _MY_INBOX_FAMILY_HELD.pop(uid, None)
        _MY_INBOX_FAMILY_HELD[uid] = (time.time(), env["data"])
        while len(_MY_INBOX_FAMILY_HELD) > _MY_INBOX_FAMILY_HELD_MAX:
            _MY_INBOX_FAMILY_HELD.pop(next(iter(_MY_INBOX_FAMILY_HELD)))
    elif status in _MY_INBOX_FAMILY_REFUSED:
        _MY_INBOX_FAMILY_HELD.pop(uid, None)
    return env


async def _my_inbox_family_read(authorization: str, uid: str, arrived: float
                                ) -> tuple[dict[str, Any] | None, dict[str, Any] | None, str]:
    """(the backend's answer, its refusal, why neither came)."""
    held = _MY_INBOX_FAMILY_HELD.get(uid)
    age = time.time() - held[0] if held else 0.0
    if held and age < _MY_INBOX_FAMILY_FRESH_S:
        return held[1], None, ""
    task = _MY_INBOX_FAMILY_ASKING.get(uid)
    if task is None:
        task = asyncio.create_task(_my_inbox_family_fill(authorization, uid))
        _MY_INBOX_FAMILY_ASKING[uid] = task

        def done(t: asyncio.Task, u: str = uid) -> None:
            if _MY_INBOX_FAMILY_ASKING.get(u) is t:
                _MY_INBOX_FAMILY_ASKING.pop(u, None)

        task.add_done_callback(done)
    if held and age < _MY_INBOX_FAMILY_CEILING_S:
        return held[1], None, ""
    try:
        env = await asyncio.wait_for(asyncio.shield(task),
                                     timeout=max(0.0, _MY_INBOX_BUDGET_S - (time.monotonic() - arrived)))
    except asyncio.TimeoutError:
        return None, None, _MY_INBOX_FAMILY_SLOW
    except Exception as exc:  # noqa: BLE001 - said on the heads, never an empty list
        return None, None, f"the backend could not be asked ({type(exc).__name__})"
    if env.get("status") == 200:
        return env["data"], None, ""
    if env.get("status") in _MY_INBOX_FAMILY_REFUSED:
        return None, env, ""
    return None, None, str(env.get("message") or "the backend did not answer")


async def _my_inbox_family(authorization: str, actor: tuple[str, str], scope: dict[str, str],
                           arrived: float) -> dict[str, Any]:
    """A client-role session's alerts: New staff from the backend, the company notices at the houses it names…"""
    uid = str(actor[1] or "")
    family, refused, family_why = await _my_inbox_family_read(authorization, uid, arrived)
    if refused is not None:
        return refused
    acting = _my_work_acting(_hotline_token(authorization))
    subject = {"uid": uid, "role": str(actor[0] or ""), "types": "", "is_master": False, "label": ""}
    access = await _my_inbox_access(subject["uid"], subject["role"], False, base=my_inbox.FAMILY_APPS)
    # test mode holds the company notices, as for everybody
    switch = _web_switch()
    held = ("test mode" + ("" if switch.get("readable") else " (unreadable, so treated as on)")
            if switch["on"] else "")
    notices = ((lambda houses: web_notices.house_news(PG_DSN, houses=houses, uid=uid, held=held))
               if web_notices is not None else None)
    try:
        data = await asyncio.to_thread(my_inbox.family_board, PG_DSN, subject=subject, family=family,
                                       family_why=family_why, access=access, notices=notices, held=held,
                                       readonly=acting, readonly_why=my_inbox.KEPT_WHY_ACTING)
    except Exception as exc:  # noqa: BLE001
        log.warning("my inbox: the family board failed (%s)", type(exc).__name__)
        return {"status": 503, "reason": "unreadable",
                "message": f"My Inbox could not be put together ({type(exc).__name__})."}
    my_inbox.apply_display(data, _my_work_display(scope["mode"]))
    data["scope"] = {"mode": scope["mode"], "why": scope["why"], "person": "", "readonly": acting}
    return {"status": 200, "data": data}


def _my_inbox_people(accounts: list[dict[str, str]]) -> list[dict[str, str]]:
    """The master's chooser: every active account, by its label."""
    return sorted(({"uid": a["uid"], "label": a["label"], "role": a["role"]}
                   for a in accounts if not a.get("unlisted")),
                  key=lambda p: (p["label"].lower(), p["uid"]))


# Settings › Back-end per app › My Inbox: asa-hub-app builds the alerts off asa-hub-db for the scope decided here, and
# keeps the session's own read and cleared marks (app.inbox_reads) and the first sightings (app.inbox_seen)
MY_INBOX_APP = "my-inbox"
MY_INBOX_PYTHON_READ = "myInboxView"
MY_INBOX_PYTHON_MARK = "myInboxRead"
# on: the relay hands its state tables in with each call (no grant); off: asa-hub-app reads HUB_RELAY_RO_DSN or defers
MY_INBOX_SEND_STATE = os.getenv("HUB_MY_INBOX_SEND_STATE", "").strip().lower() in ("1", "yes", "on", "true")
# past this the relay's own builder answers
MY_INBOX_PYTHON_TIMEOUT_S = min(60.0, max(HUB_APP_TIMEOUT_S, float(os.getenv("HUB_MY_INBOX_TIMEOUT_S", "15"))))
_MY_INBOX_KEYS = ("subject", "heads", "items", "unread", "capped", "marks", "read_at", "scope")
# the edition (app/editions.py) that opens any person's alerts, read-only, to a session outside the master's scope
_MY_INBOX_EDITIONS = frozenset({"myInbox.anyone"})
# Python's own word on an edition's ask: a refusal, or a person it cannot read
_MY_INBOX_EDITION_REFUSALS = (400, 403, 404)
_MY_INBOX_UNCHECKED = {"status": 503, "reason": "unavailable",
                       "message": "Whether you may open another person's alerts could not be checked just now. "
                                  "Try again."}
# a mark Python did not keep is said, never kept here instead
_MY_INBOX_UNMARKED = {"status": 503, "reason": "unavailable", "message": BACKEND_FINAL_UNWRITTEN}


async def _my_inbox_on() -> bool:
    """My Inbox runs on Python here and App Control is not settling; anything unknown is the relay's builder."""
    try:
        return await _backend_wanted(MY_INBOX_APP) and not _backend_settling()
    except Exception:  # noqa: BLE001 - FAIL-SAFE: the relay's own builder and marks
        return False


def _my_inbox_marks_read(uid: str) -> dict[str, Any]:
    """Blocking, read-only: this account's rows of asa_hub_inbox_reads and every asa_hub_inbox_seen row, each stamp as
    ISO text; a table not made yet holds none."""
    from datetime import datetime

    def iso(v: Any) -> Any:
        return v.isoformat() if isinstance(v, datetime) else v

    out: dict[str, Any] = {"user_id": uid, "reads": [], "seen": []}
    conn = hub_db.connect(PG_DSN, connect_timeout=5)
    try:
        if not hub_db.on():
            conn.set_session(readonly=True, autocommit=True)
        with conn.cursor() as cur:
            cur.execute("SELECT to_regclass('asa_hub_inbox_reads') IS NOT NULL, "
                        "to_regclass('asa_hub_inbox_seen') IS NOT NULL")
            reads_here, seen_here = cur.fetchone() or (False, False)
            if reads_here and uid:
                cur.execute("SELECT user_id, alert_key, read_at, dismissed_at FROM asa_hub_inbox_reads "
                            "WHERE user_id = %s", (uid,))
                out["reads"] = [{"user_id": u, "alert_key": k, "read_at": iso(r), "dismissed_at": iso(d)}
                                for u, k, r, d in cur.fetchall()]
            if seen_here:
                cur.execute("SELECT kind, key, first_seen FROM asa_hub_inbox_seen")
                out["seen"] = [{"kind": k, "key": key, "first_seen": iso(f)} for k, key, f in cur.fetchall()]
    finally:
        conn.close()
    return out


def _my_inbox_punch_board() -> dict[str, Any]:
    """The punch board the attendance lane wrote here, as handed: {punch_board} or {punch_board_error} ("missing")."""
    try:
        return {"punch_board": json.loads(punch_board_slices.BOARD_FILE.read_text(encoding="utf-8") or "null")}
    except FileNotFoundError:
        return {"punch_board_error": "missing"}
    except Exception as exc:  # noqa: BLE001 - said on the punch head, as the builder says it
        return {"punch_board_error": type(exc).__name__}


async def _my_inbox_handed(authorization: str, actor: tuple[str, str], person: str) -> dict[str, Any] | None:
    """What only this relay holds, handed to Python with each read: the subject's read marks and every first sighting
    (inbox_marks), its test mode switch, the punch board and the bell's notices for the subject (none while test mode
    holds them); None when the subject cannot be read here (the builder, or the edition's door, says so)."""
    known = True
    if person:
        try:
            accounts = await asyncio.to_thread(_notice_accounts)
        except Exception as exc:  # noqa: BLE001 - a chosen person is the builder's to refuse
            log.info("my inbox: the accounts were not read for Python (%s)", type(exc).__name__)
            return None
        acc = next((a for a in accounts if a.get("uid") == person), None)
        # a person who is no active account is Python's to refuse, before any notice is read
        known = acc is not None
        subject = {"uid": person, "role": (acc or {}).get("role") or "", "types": (acc or {}).get("types") or "",
                   "is_master": False}
    else:
        subject = {"uid": str(actor[1] or ""), "role": str(actor[0] or ""), "types": None,
                   "is_master": _auth_master.get(_hotline_token(authorization)) is True}
    switch = _web_switch()
    out: dict[str, Any] = {"test_mode": switch, **await asyncio.to_thread(_my_inbox_punch_board)}
    try:
        out["inbox_marks"] = await asyncio.to_thread(_my_inbox_marks_read, subject["uid"])
        if switch.get("on") or not known or web_notices is None:
            return out
        name = await asyncio.to_thread(_roster_name_of, subject["uid"], strict=True)
        if subject["types"] is None:
            subject["types"] = await asyncio.to_thread(_user_badges, subject["uid"])
        who = await asyncio.to_thread(shift_requests.viewer, PG_DSN, name=name, role=subject["role"],
                                      types=subject["types"], is_master=subject["is_master"])
    except Exception as exc:  # noqa: BLE001 - the relay's builder answers, and says what it could not read
        log.info("my inbox: what the relay holds was not handed to Python (%s)", type(exc).__name__)
        return None
    try:
        got = await asyncio.to_thread(web_notices.inbox, PG_DSN,
                                      who={**who, "alerts_off": _lane_alerts_off(subject["uid"])},
                                      uid=subject["uid"], limit=200, held="")
        out["notices"] = json.loads(json.dumps(got, default=str))
    except Exception as exc:  # noqa: BLE001 - said on the notices head, as the builder says it
        out["notices_error"] = type(exc).__name__
    return out


async def _my_inbox_python(authorization: str, actor: tuple[str, str], scope: dict[str, str],
                           person: str) -> dict[str, Any] | None:
    """asa-hub-app's envelope for the scope and subject decided here; None: the relay's own builder answers."""
    if not await _my_inbox_on():
        return None
    mass = scope["mode"] == my_work.MODE_MASS
    # a person outside the master's scope: the edition Python alone holds decides, never this relay
    edition = bool(person) and not mass
    handed = await _my_inbox_handed(authorization, actor, person)
    if handed is None:
        return None
    payload: dict[str, Any] = {"mode": scope["mode"], "why": scope["why"], "person": person, **handed}
    if MY_INBOX_SEND_STATE:
        try:
            payload["relay_state"] = await asyncio.to_thread(_my_work_state_read)
        except Exception as exc:  # noqa: BLE001 - asa-hub-app reads them itself, or defers
            log.info("my inbox: the state tables were not handed to Python (%s)", type(exc).__name__)
    user = {"uid": str(actor[1] or ""), "role": str(actor[0] or "").strip().lower(), "is_master": mass}
    got = await _backend_call(MY_INBOX_APP, MY_INBOX_PYTHON_READ, payload, user, timeout=MY_INBOX_PYTHON_TIMEOUT_S)
    if got is None:
        return None
    env = got[2]
    if env.get("status") != 200:
        if edition and env.get("status") in _MY_INBOX_EDITION_REFUSALS:
            return {k: env[k] for k in ("status", "reason", "message") if k in env}
        return None
    data = env.get("data")
    said = data.get("scope") if isinstance(data, dict) else None
    said = said if isinstance(said, dict) else {}
    # an edition's holder is answered as Python widened the scope: any person, said under the edition
    widened = (not mass and said.get("mode") == my_work.MODE_MASS
               and str(said.get("edition") or "") in _MY_INBOX_EDITIONS)
    # own: the caller's own alerts, marks kept; mass or widened: exactly the person chosen, read-only
    if (not said or any(k not in data for k in _MY_INBOX_KEYS)
            or (said.get("mode") != scope["mode"] and not widened)
            or said.get("person") != person or said.get("readonly") is not bool(person)
            or (edition and not widened)):
        log.warning("my inbox: Python's answer did not keep the relay's scope or shape — the relay's builder answers")
        return None
    if not isinstance(data.get("display"), dict):
        my_inbox.apply_display(data, _my_work_display(scope["mode"]))
    _traffic_note("backend_python")
    return {"status": 200, "data": data}


async def _my_inbox_mark_python(actor: tuple[str, str], scope: dict[str, str], keys: list[str],
                                dismiss: bool) -> dict[str, Any]:
    """The session's own alert marks, kept final by asa-hub-app (app.inbox_reads): its answer, or 503 when it gave
    none — never kept here instead."""
    uid = str(actor[1] or "")
    write_id = "W" + hashlib.sha256(f"{uid}|{dismiss}|{','.join(keys)}|{time.time_ns()}".encode()).hexdigest()[:24]
    user = {"uid": uid, "role": str(actor[0] or "").strip().lower(), "is_master": scope["mode"] == my_work.MODE_MASS}
    got = await _backend_call(MY_INBOX_APP, MY_INBOX_PYTHON_MARK, {"keys": list(keys), "dismiss": dismiss}, user,
                              extra={"write_id": write_id})
    if got is None:
        # whatever Python may have kept under this id is let go: the answer says nothing was written
        _backend_settle_soon(MY_INBOX_APP, write_id, "void")
        log.warning("my inbox: the marks were not kept by Python — said 503, never kept here instead")
        return dict(_MY_INBOX_UNMARKED)
    answer = got[2]
    answer.pop("_write", None)
    if answer.get("status") == 200 and not isinstance((answer.get("data") or {}).get("marked"), int):
        log.warning("my inbox: Python's mark answer carried no count — said 503")
        return dict(_MY_INBOX_UNMARKED)
    _traffic_note("backend_python")
    return answer


@app.get("/hub-lanes/my-inbox")
async def lane_my_inbox(response: Response, member: str = "", person: str = "",
                       authorization: str = Header(default="")) -> Any:
    """One person's alerts — whose, decided here, never by the screen."""
    arrived = time.monotonic()
    response.headers["Cache-Control"] = "no-store"
    kept = globals().get("_lane_kept")
    gate = await _my_inbox_gate(authorization, member)
    if isinstance(gate, dict):
        return gate
    scope, actor = gate
    mass = scope["mode"] == my_work.MODE_MASS
    person = str(person or "").strip()
    # another person's alerts outside the master's scope: only My Inbox's edition opens them, on Python
    if person and not mass and (_my_family_session(actor) or not await _my_inbox_on()):
        return {"status": 403, "reason": "scope", "message": _MY_INBOX_OWN_ONLY}
    if person and not my_inbox.PERSON_RE.fullmatch(person):
        return {"status": 400, "reason": "person", "message": "That person cannot be read."}
    if _my_family_session(actor):
        # returned before any staff source is read: none of them is computed for a client-role session
        return await _my_inbox_family(authorization, actor, scope, arrived)
    # past the gate, a person outside the master's scope is an edition's ask: Python alone answers it
    edition = bool(person) and not mass

    async def build():  # noqa: ANN202 - lifted by name into the doors' tests, where no annotation is in scope
        token = _hotline_token(authorization)
        acting = _my_work_acting(token)
        # on Python (Settings › Back-end per app) asa-hub-app builds it for this scope; a session whose marks are not
        # kept, or any failure: the builder below
        python = globals().get("_my_inbox_python")
        if python is not None and not acting:
            env = await python(authorization, actor, scope, person)
            if env is not None:
                return env
        if edition:
            return ({"status": 403, "reason": "scope", "message": _MY_INBOX_OWN_ONLY} if acting
                    else dict(_MY_INBOX_UNCHECKED))
        accounts: list[dict[str, str]] | None = None
        people_why = ""
        if mass:
            try:
                accounts = await asyncio.to_thread(_notice_accounts)
            except Exception as exc:  # noqa: BLE001 - the chooser says so; the master's own alerts still answer
                people_why = f"The accounts could not be read ({type(exc).__name__})."
        if person:
            if accounts is None:
                return {"status": 502, "reason": "unreadable", "message": f"{people_why} Nobody can be chosen."}
            acc = next((a for a in accounts if a.get("uid") == person), None)
            if acc is None:
                return {"status": 403, "reason": "scope", "message": "That person is not an active account."}
            # judged as that account — its own role and badges, never the master's flag
            subject = {"uid": acc["uid"], "role": acc["role"], "types": acc.get("types") or "", "is_master": False,
                       "label": acc.get("label") or ""}
        else:
            subject = {"uid": str(actor[1] or ""), "role": str(actor[0] or ""), "types": None,
                       "is_master": _auth_master.get(token) is True and not acting, "label": ""}
        try:
            name = await asyncio.to_thread(_roster_name_of, subject["uid"], strict=True)
            if subject["types"] is None:
                subject["types"] = await asyncio.to_thread(_user_badges, subject["uid"])
            who = await asyncio.to_thread(shift_requests.viewer, PG_DSN, name=name, role=subject["role"],
                                          types=subject["types"], is_master=subject["is_master"])
            me = await asyncio.to_thread(my_work.identity, PG_DSN, HUB_DB_SHEET_ID, subject["uid"], roster_name=name)
        except Exception as exc:  # noqa: BLE001 - FAIL-CLOSED: nobody's alerts are drawn for an unread account
            log.warning("my inbox: the account could not be read (%s)", type(exc).__name__)
            return {"status": 502, "reason": "unreadable",
                    "message": f"Whose alerts these are could not be read ({type(exc).__name__}), so nothing is "
                               f"shown."}
        lanes, lanes_why = None, ""
        if hotline_lanes is None or hotline_desk is None:
            lanes_why = "the hotline lanes are not loaded on this server"
        else:
            try:
                lanes = (await hotline_lanes.current_lanes(hotline_desk.sheets_client, _MY_INBOX_LANES,
                                                           PG_DSN))["lanes"]
            except Exception as exc:  # noqa: BLE001 - each source that reads a lane says so; the others answer
                lanes_why = f"the hotline lanes could not be read ({type(exc).__name__})"
        # the release notes first: access is asked only for the apps their Live lines name
        updates = await asyncio.to_thread(my_inbox.read_updates, PG_DSN)
        access = await _my_inbox_access(subject["uid"], subject["role"], subject["is_master"],
                                        my_inbox.updates_apps(updates))
        # test mode holds the company notices, which are messages; every other source is a read
        switch = _web_switch()
        held = ("test mode" + ("" if switch.get("readable") else " (unreadable, so treated as on)")
                if switch["on"] else "")
        # the alerts the subject turned off for itself in Settings, obeyed by the bell and the directors' copy alike
        alerts_off = _lane_alerts_off(subject["uid"])
        notices = ((lambda: web_notices.inbox(PG_DSN, who={**who, "alerts_off": alerts_off}, uid=subject["uid"],
                                              limit=200, held=held))
                   if web_notices is not None else None)
        readonly = bool(person) or acting
        try:
            data = await asyncio.to_thread(
                my_inbox.board, PG_DSN, subject=subject, me=me, access=access,
                requests=lambda: my_work.requests_for(PG_DSN, me=me, who=who, lanes=lanes, lanes_why=lanes_why),
                lanes=lanes, lanes_why=lanes_why, notices=notices, held=held, snapshot_dir=OUT_DIR,
                board_file=punch_board_slices.BOARD_FILE, readonly=readonly,
                readonly_why=my_inbox.KEPT_WHY_CHOSEN if person else my_inbox.KEPT_WHY_ACTING, updates=updates,
                alerts_off=alerts_off)
        except Exception as exc:  # noqa: BLE001
            log.warning("my inbox: the board failed (%s)", type(exc).__name__)
            return {"status": 503, "reason": "unreadable",
                    "message": f"My Inbox could not be put together ({type(exc).__name__})."}
        # Settings > My Work's Sources switch, judged by the session exactly as My Work's door judges its parts
        my_inbox.apply_display(data, _my_work_display(scope["mode"]))
        data["scope"] = {"mode": scope["mode"], "why": scope["why"], "person": person, "readonly": readonly}
        if mass:
            data["scope"]["people"] = _my_inbox_people(accounts) if accounts is not None else None
            data["scope"]["people_why"] = people_why
        return {"status": 200, "data": data}

    # an edition's ask is never kept: a key turned off or a person taken off its list closes it at once
    return await (build() if kept is None or edition else kept("lane:my-inbox", authorization, {"person": person},
                                                               scope["mode"], actor, build))


@app.post("/hub-lanes/my-inbox/read")
async def lane_my_inbox_read(request: Request, member: str = "",
                            authorization: str = Header(default="")) -> dict[str, Any]:
    """Mark the SESSION's own alerts read, or cleared."""
    gate = await _my_inbox_gate(authorization, member)
    if isinstance(gate, dict):
        return gate
    scope, actor = gate
    if _my_work_acting(_hotline_token(authorization)):
        return dict(_MY_INBOX_ACTING)
    uid = str(actor[1] or "").strip()
    if not uid:
        return {"status": 403, "reason": "session", "message": "This session carries no account to keep the reads for."}
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        return {"status": 400, "reason": "body", "message": "The body could not be read."}
    if not isinstance(body, dict):
        return {"status": 400, "reason": "body", "message": "The body could not be read."}
    if str(body.get("member") or "").strip():
        return {"status": 403, "reason": "visit", "message": _MY_INBOX_VISIT}
    keys = body.get("keys")
    if not isinstance(keys, list) or not keys:
        return {"status": 400, "reason": "keys", "message": "keys is required."}
    if len(keys) > my_inbox.READ_MAX:
        return {"status": 400, "reason": "keys", "message": f"At most {my_inbox.READ_MAX} keys at once."}
    notice_ids, alert_keys, ignored = my_inbox.split_keys(keys)
    if not notice_ids and not alert_keys:
        return {"status": 400, "reason": "keys", "message": "None of those keys is an alert."}
    if notice_ids and web_notices is None:
        return {"status": 503, "reason": "unreadable", "message": "The notices lane is not on this server."}
    dismiss = body.get("dismiss") is True
    marked = 0
    # on Python the alert marks are kept final by asa-hub-app; a notice's stay the bell's, a client-role board's here
    python = bool(alert_keys) and not _my_family_session(actor) and await _my_inbox_on()
    if python:
        got = await _my_inbox_mark_python(actor, scope, alert_keys, dismiss)
        if got.get("status") != 200:
            return got
        marked += int(got["data"]["marked"])
    try:
        if notice_ids:
            marked += await asyncio.to_thread(web_notices.mark_read, PG_DSN, uid=uid, ids=notice_ids,
                                              dismiss=dismiss)
        if alert_keys and not python:
            marked += await asyncio.to_thread(my_inbox.mark_read, PG_DSN, uid=uid, keys=alert_keys,
                                              dismiss=dismiss)
    except Exception as exc:  # noqa: BLE001
        log.warning("my inbox: the read marks could not be written (%s)", type(exc).__name__)
        return {"status": 502, "reason": "unreadable", "message": f"Not marked ({type(exc).__name__})."}
    return {"status": 200, "data": {"marked": marked, "ignored": ignored}}


# asa-hub-app's own front door asks this relay to finish what it answered (server/front_door_finish.py)
import front_door_finish  # noqa: E402

front_door_finish.install(app, globals())
